{
  "message": "Recrop reverse parking with adjusted coordinates",
  "input": {
    "command": "cd /home/claude && python3 << 'EOF'
from PIL import Image, ImageDraw
img = Image.open('/mnt/user-data/uploads/科目二.jpg')

# Adjusted coords (shift Y up by ~30px)
crops_dao = {
    'dao_1': (440, 220, 720, 380),
    'dao_2': (440, 380, 720, 530),
    'dao_3': (440, 530, 720, 675),
    'dao_4': (440, 675, 720, 820),
    'dao_5': (440, 820, 720, 965),
    'dao_6': (50, 1100, 320, 1265),
}

for name, (x1, y1, x2, y2) in crops_dao.items():
    img.crop((x1, y1, x2, y2)).save(f'step_images/{name}.png')

verify = img.crop((0, 200, 767, 1300)).copy()
draw = ImageDraw.Draw(verify)
for name, (x1, y1, x2, y2) in crops_dao.items():
    draw.rectangle([x1, y1-200, x2, y2-200], outline='red', width=3)
verify.save('sections/verify_dao2.png')
EOF",
    "description": "Recrop reverse parking with adjusted coordinates"
  },
