                's3_images/img09_step01.png', 's3_images/img16_step02.png',
                's3_images/img01_step01.png', 's3_images/img03_step03.png']

for f in sample_files:
    img = Image.open(f).convert('RGB')
    arr = np.array(img)
    H, W, _ = arr.shape

    # Find columns that are mostly non-white (content columns)
    col_dark = np.mean(np.min(arr, axis=(0,2))) < 230  # True = has content
    col_has_content = np.min(arr, axis=(0,2)) < 220    # per column, min across rows+channels

    # Find leftmost and rightmost content column
    for x in range(W):
        if np.min(arr[:, x, :]) < 220:
            x_left = x; break
    else:
        x_left = 0
    for x in range(W-1, -1, -1):
        if np.min(arr[:, x, :]) < 220:
            x_right = x; break
    else:
        x_right = W-1

    print(f"{f}: W={W} H={H} | content x: {x_left}–{x_right} | "
          f"left_pad={x_left} right_pad={W-1-x_right} content_w={x_right-x_left+1}")
EOF",
