.lp .bk-toc::-webkit-scrollbar{width:5px}
.lp .bk-toc::-webkit-scrollbar-thumb{background:rgba(28,25,22,.16);border-radius:3px}
.lp .bk-brand{font-family:var(--serif);font-size:1rem;font-weight:700;letter-spacing:.04em;line-height:1.5}
.lp .bk-brand-sub{margin-top:4px;font-family:var(--mono);font-size:.68rem;letter-spacing:.05em;
