footer.site-foot{background:var(--ink);color:rgba(250,249,245,.72);margin-top:20px}
.foot-in{padding:64px 24px 36px;max-width:1180px;margin:0 auto}
.foot-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr 1fr;gap:32px}
.foot-brand{font-family:var(--serif);font-weight:700;font-size:21px;color:var(--paper)}
.foot-brand .dot{color:var(--coral)}
