  if (cfg.showUnit && (!unit || !inOpts(unit, cfg.unitOptions))) return bad(res, '请选择“座”')
  if (cfg.showRoom && (!room || !inOpts(room, cfg.roomOptions))) return bad(res, '请选择“房”')
