  }
  rec = {
    id: uid(), editToken: editToken || uid(),
    name, building, unit, room, roomFull, phone, area: +area.toFixed(2),
    certFile, idFrontFile, idBackFile, signFile,
    status: 'pending', reviewNote: '', reviewedAt: null, submittedAt: now
