  if (!cfg.showBuilding) building = ''
  if (!cfg.showUnit) unit = ''
  if (!cfg.showRoom) room = ''
  // 后端兜底校验（前端已逐项校验并就地提示）
  if (!/^[\u4e00-\u9fa5]{2,4}$/.test(name)) return bad(res, '业主姓名应为 2-4 个中文字')
