:root{
  --bg:#f4f5f7; --card:#fff; --ink:#1f2328; --ink-2:#5b6470; --ink-3:#9aa0a6;
  --line:#e8eaed; --brand:#1f6feb; --brand-soft:#e8f0fe; --ok:#1a7f37; --ok-soft:#e6f4ea;
  --warn:#b35900; --warn-soft:#fdf0e3; --danger:#cf222e; --danger-soft:#fbeaec;
  --maxw:560px;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;padding:0}
body{
  background:var(--bg); color:var(--ink);
  font:16px/1.55 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei","Helvetica Neue",sans-serif;
}
#app{max-width:var(--maxw);margin:0 auto;min-height:100vh;background:var(--bg);position:relative}

/* 顶栏 */
#topbar{
  position:sticky;top:0;z-index:20;height:48px;display:flex;align-items:center;justify-content:space-between;
  padding:0 16px;background:#fff;border-bottom:1px solid var(--line);font-weight:600;
  padding-top:env(safe-area-inset-top);
}
#topRight{font-size:13px;color:var(--brand);font-weight:500}

/* 视图区 + 给底栏留白 */
#view{padding:14px 14px calc(78px + env(safe-area-inset-bottom))}

/* 底部标签栏 */
#tabbar{
  position:fixed;left:50%;transform:translateX(-50%);bottom:0;width:100%;max-width:var(--maxw);
  display:flex;background:#fff;border-top:1px solid var(--line);z-index:20;
  padding-bottom:env(safe-area-inset-bottom);
}
.tab{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;padding:8px 0;color:var(--ink-3);font-size:11px;text-decoration:none;cursor:pointer}
.tab .t-ic{font-size:18px;line-height:1}
.tab.on{color:var(--brand)}

/* 卡片与基础排版 */
.card{background:var(--card);border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:0 1px 0 var(--line)}
.h1{font-size:21px;font-weight:600}
.h2{font-size:17px;font-weight:600;margin-bottom:8px}
.muted{color:var(--ink-2)} .dim{color:var(--ink-3);font-size:13px}
.row{display:flex;align-items:center}.between{justify-content:space-between}
.mt8{margin-top:8px}.mt16{margin-top:16px}.mt24{margin-top:24px}
.hidden{display:none!important}
.empty{text-align:center;color:var(--ink-3);padding:40px 0}
.foot{margin-top:12px;padding:0 4px;line-height:1.5}

/* 进度条 */
.bar{height:9px;background:var(--line);border-radius:999px;overflow:hidden}
.bar>i{display:block;height:100%;background:var(--brand);border-radius:999px;transition:width .4s}
.bar.ok>i{background:var(--ok)}
.pct{font-size:18px;font-weight:600;color:var(--brand)} .pct.ok{color:var(--ok)}

/* 徽标 */
.badge{display:inline-block;padding:2px 11px;border-radius:999px;font-size:12px}
.badge.ok{background:var(--ok-soft);color:var(--ok)}
.badge.wait{background:var(--warn-soft);color:var(--warn)}
.badge.no{background:var(--danger-soft);color:var(--danger)}

/* 按钮 */
.btn{display:block;width:100%;background:var(--brand);color:#fff;border:none;border-radius:11px;padding:13px;font-size:16px;font-weight:500;cursor:pointer}
.btn:disabled{background:#c9d3e0}
.btn.ghost{background:var(--brand-soft);color:var(--brand)}
.btn.line{background:#fff;color:var(--ink);border:1px solid var(--line)}
.btn.danger{background:#fff;color:var(--danger);border:1px solid #f3c0c5}
.btn.sm{display:inline-block;width:auto;padding:7px 14px;font-size:14px}

/* 表单 */
.field{margin-bottom:15px}
.label{font-size:14px;color:var(--ink-2);margin-bottom:7px}
.label .req{color:var(--danger);margin-left:4px}
.input,.textarea,select{width:100%;background:#f7f8fa;border:1px solid var(--line);border-radius:10px;padding:11px;font-size:16px;color:var(--ink);font-family:inherit}
.textarea{min-height:72px;resize:vertical}
.three{display:flex;gap:8px}.three .input{flex:1;min-width:0}
.kv{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--line)}
.kv:last-child{border-bottom:none}.kv .k{color:var(--ink-2)}.kv .v{font-weight:500;text-align:right}

/* 提示块 */
.notice{background:var(--brand-soft);color:#1a4f9c;padding:10px 12px;border-radius:10px;font-size:13px}
.warnbox{background:var(--warn-soft);color:var(--warn);padding:10px 12px;border-radius:10px;font-size:13px}
.tip{padding:9px 12px;border-radius:10px;font-size:13px}
.tip.ok{background:var(--ok-soft);color:var(--ok)}
.tip.no{background:var(--danger-soft);color:var(--danger)}
.tipcard{background:var(--brand-soft);color:#1a4f9c;font-size:13px;line-height:1.7}

/* 计数三列 */
.counts{display:flex}.counts .cell{flex:1;text-align:center}
.counts .num{font-size:26px;font-weight:700}.counts .num.warn{color:var(--warn)}

/* 迷你路线图 */
.roadmap{display:flex;align-items:flex-start}
.rm-node{display:flex;flex-direction:column;align-items:center;width:40px;flex:none}
.rm-dot{width:26px;height:26px;border-radius:50%;background:var(--line);color:var(--ink-3);text-align:center;line-height:26px;font-size:13px;font-weight:700}
.rm-node.cur .rm-dot{background:var(--brand);color:#fff}
.rm-node.done .rm-dot{background:var(--ok-soft);color:var(--ok)}
.rm-label{font-size:11px;color:var(--ink-3);margin-top:5px}
.rm-node.cur .rm-label{color:var(--brand);font-weight:600}
.rm-line{flex:1;height:2px;background:var(--line);margin-top:12px}
.rm-line.done{background:var(--ok)}

/* 指南步骤 */
.entries{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}
.entry{width:calc(50% - 4px);background:var(--card);border-radius:12px;padding:13px;box-shadow:0 1px 0 var(--line);cursor:pointer}
.entry .e-t{font-weight:600}.entry .e-d{font-size:12px;color:var(--ink-3);margin-top:3px}
.step{background:var(--card);border-radius:12px;margin-bottom:10px;box-shadow:0 1px 0 var(--line);overflow:hidden}
.step.cur{border:1.5px solid var(--brand)}
.step-head{display:flex;align-items:flex-start;padding:14px;gap:11px;cursor:pointer}
.step-no{flex:none;width:30px;height:30px;border-radius:50%;background:var(--line);color:var(--ink-2);text-align:center;line-height:30px;font-weight:700}
.step.cur .step-no{background:var(--brand);color:#fff}.step.past .step-no{background:var(--ok-soft);color:var(--ok)}
.step-main{flex:1}.step-title{font-weight:600}
.curtag{font-size:11px;color:var(--brand);background:var(--brand-soft);padding:1px 8px;border-radius:999px;margin-left:6px}
.step-sum{font-size:13px;color:var(--ink-2);margin-top:4px}.step-arrow{flex:none;font-size:12px;color:var(--ink-3);align-self:center}
.step-body{padding:0 14px 14px 55px}
.pt{font-size:13px;color:var(--ink-2);line-height:1.7;margin-bottom:7px}
.docs{margin-top:4px}.docs-label{font-size:12px;color:var(--ink-3)}
.doc-chip{display:inline-block;font-size:12px;color:var(--brand);background:var(--brand-soft);padding:2px 9px;border-radius:7px;margin:5px 5px 0 0}

/* 资格自测选项 */
.opt{display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);cursor:pointer}
.opt:last-child{border-bottom:none}
.box{flex:none;width:22px;height:22px;border:1.5px solid #c9d0d8;border-radius:6px;text-align:center;line-height:22px;color:#fff;font-size:14px;margin-top:2px}
.opt.on.red .box{background:var(--danger);border-color:var(--danger)} .opt.on.green .box{background:var(--ok);border-color:var(--ok)}
.opt-t{flex:1;font-size:14px;line-height:1.5}.opt.on.red .opt-t{color:var(--danger)}
.redt{color:var(--danger)}.greent{color:var(--ok)}

/* 证件上传 */
.certs{display:flex;gap:12px}.cert-cell{flex:1}
.cert-img{width:100%;height:100px;object-fit:cover;border-radius:10px;display:block}
.cert-add{width:100%;height:100px;border:1px dashed #c9d0d8;border-radius:10px;display:flex;align-items:center;justify-content:center;color:var(--ink-3);background:#f7f8fa;font-size:14px;cursor:pointer}
.cert-cap{text-align:center;font-size:12px;color:var(--ink-3);margin-top:6px}

/* 签名画板 */
.sig-box{position:relative}
.sig-canvas{width:100%;height:150px;background:#f7f8fa;border:1px dashed #c9d0d8;border-radius:10px;touch-action:none;display:block}
.sig-hint{position:absolute;left:0;right:0;top:60px;text-align:center;color:#b6bcc4;font-size:14px;pointer-events:none}
.sig-tools{display:flex;justify-content:flex-end;margin-top:6px}.sig-clear{color:var(--brand);font-size:13px;cursor:pointer}

/* 审核列表 */
.tabs{display:flex;background:#fff;border-radius:11px;padding:4px;margin-bottom:10px}
.tabs .t{flex:1;text-align:center;padding:8px 0;font-size:14px;color:var(--ink-2);border-radius:8px;cursor:pointer}
.tabs .t.on{background:var(--brand-soft);color:var(--brand);font-weight:600}
.item{padding:14px;cursor:pointer}.item .name{font-weight:600}.item .room{color:var(--ink-2);margin-left:8px}
.ops{display:flex;gap:8px;justify-content:flex-end}.loadmore{text-align:center;color:var(--brand);padding:12px;cursor:pointer}
.big{width:100%;border-radius:10px;margin-top:8px}
.sig-show{width:100%;border:1px solid var(--line);border-radius:10px;margin-top:8px;background:#fff}

/* 导出 */
.letter{white-space:pre-wrap;background:#fbfbfc;border:1px solid var(--line);border-radius:10px;padding:14px;font-size:13px;line-height:1.85}
.thead,.trow{display:flex;padding:8px 0;border-bottom:1px solid var(--line);font-size:13px}
.thead{color:var(--ink-2);font-weight:600}
.c-no{width:42px}.c-name{width:72px}.c-room{flex:1}.c-area{width:64px;text-align:right}
.note{font-size:12px;color:var(--ink-2)}
.signs{display:flex;flex-wrap:wrap;gap:8px}
.sign-cell{width:calc(50% - 4px);border:1px solid var(--line);border-radius:10px;padding:6px}
.sign-img{width:100%;height:60px;object-fit:contain;background:#fff}.sign-cap{font-size:11px;color:var(--ink-3);text-align:center;margin-top:4px}

/* 名词/换物业 */
.term .t-h{font-size:16px;font-weight:700;color:var(--brand);margin-bottom:5px}.term .t-b{font-size:14px;color:var(--ink-2);line-height:1.75}
.lane{display:flex;flex-direction:column;gap:6px}
.lane-i{background:#f7f8fa;border-radius:10px;padding:9px 11px;display:flex;justify-content:space-between;align-items:center}
