.pstep{display:flex;gap:10px;padding:8px 0}.pn{flex:none;width:24px;height:24px;border-radius:50%;background:var(--brand-soft);color:var(--brand);text-align:center;line-height:24px;font-weight:700;font-size:13px}
.pt2{font-weight:600;font-size:14px}.pd{font-size:13px;color:var(--ink-2);line-height:1.7;margin-top:4px}
.vrow{display:flex;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}.vrow:last-of-type{border-bottom:none}
.vk{flex:none;width:64px;color:var(--ink-3);font-size:13px}.vv{flex:1;font-size:14px;line-height:1.6}

/* 文书库 */
.grp{padding:0;overflow:hidden}
.grp-h{display:flex;justify-content:space-between;align-items:center;padding:14px;cursor:pointer}
.grp-t{font-weight:600}.grp-a{font-size:20px;color:var(--ink-3)}
.grp-b{padding:0 14px 10px}
.doc{display:flex;gap:9px;padding:8px 0;border-top:1px solid var(--line)}
.doc-no{flex:none;width:90px;font-size:12px;color:var(--brand);font-weight:600}
.doc-name{font-size:14px;font-weight:500}.doc-use{font-size:12px;color:var(--ink-2);line-height:1.6;margin-top:3px}

.seg{display:flex;gap:8px}.seg-i{flex:1;text-align:center;padding:9px 0;border:1px solid var(--line);border-radius:10px;color:var(--ink-2);font-size:14px;cursor:pointer}
.seg-i.on{background:var(--brand-soft);color:var(--brand);border-color:var(--brand-soft);font-weight:600}
.matter{display:inline-block;background:var(--brand-soft);color:var(--brand);padding:4px 10px;border-radius:8px;font-size:13px;font-weight:600}

/* 返回链接 */
.back{display:inline-block;color:var(--brand);font-size:14px;margin-bottom:8px;cursor:pointer}

/* toast / modal */
.toast{position:fixed;left:50%;bottom:96px;transform:translateX(-50%);background:rgba(0,0,0,.82);color:#fff;padding:9px 16px;border-radius:8px;font-size:14px;z-index:50;opacity:0;transition:opacity .2s;pointer-events:none;max-width:80%;text-align:center}
.toast.show{opacity:1}
.modal-mask{position:fixed;inset:0;background:rgba(0,0,0,.4);display:flex;align-items:center;justify-content:center;z-index:60;padding:24px}
.modal{background:#fff;border-radius:14px;padding:18px;width:100%;max-width:340px}
.modal-title{font-weight:600;font-size:17px;margin-bottom:8px}
.modal-body{font-size:14px;color:var(--ink-2);line-height:1.6}
.modal-input{margin-top:12px}
.modal-actions{display:flex;gap:10px;margin-top:16px}.modal-actions .btn{flex:1}

/* 顶部 banner（预览模式提示） */
.banner{background:#fff8e1;color:#8a5a1a;font-size:12px;padding:8px 12px;border-radius:10px;margin-bottom:12px;line-height:1.5}

/* 打印（导出申请书时） */
@media print{
  #topbar,#tabbar,.no-print{display:none!important}
  #view{padding:0}
  .card{box-shadow:none;border:none}
}

