#app{max-width:var(--maxw);margin:0 auto;min-height:100vh;background:var(--bg);position:relative}

/* 顶栏 */
#topbar{
  position:sticky;top:0;z-index:20;height:48px;display:flex;align-items:center;justify-content:space-between;
  padding:0 16px;background:#fff;border-bottom:1px solid var(--line);font-weight:600;
  padding-top:env(safe-area-inset-top);
}
#topRight{font-size:13px;color:var(--brand);font-weight:500}

/* 视图区 + 给底栏留白 */
#view{padding:14px 14px calc(78px + env(safe-area-inset-bottom))}

/* 底部标签栏 */
#tabbar{
  position:fixed;left:50%;transform:translateX(-50%);bottom:0;width:100%;max-width:var(--maxw);
  display:flex;background:#fff;border-top:1px solid var(--line);z-index:20;
  padding-bottom:env(safe-area-inset-bottom);
}
.tab{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;padding:8px 0;color:var(--ink-3);font-size:11px;text-decoration:none;cursor:pointer}
.tab .t-ic{font-size:18px;line-height:1}
.tab.on{color:var(--brand)}

/* 卡片与基础排版 */
.card{background:var(--card);border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:0 1px 0 var(--line)}
.h1{font-size:21px;font-weight:600}
.h2{font-size:17px;font-weight:600;margin-bottom:8px}
.muted{color:var(--ink-2)} .dim{color:var(--ink-3);font-size:13px}
.row{display:flex;align-items:center}.between{justify-content:space-between}
.mt8{margin-top:8px}.mt16{margin-top:16px}.mt24{margin-top:24px}
.hidden{display:none!important}
.empty{text-align:center;color:var(--ink-3);padding:40px 0}
.foot{margin-top:12px;padding:0 4px;line-height:1.5}

/* 进度条 */
.bar{height:9px;background:var(--line);border-radius:999px;overflow:hidden}
.bar>i{display:block;height:100%;background:var(--brand);border-radius:999px;transition:width .4s}
.bar.ok>i{background:var(--ok)}
.pct{font-size:18px;font-weight:600;color:var(--brand)} .pct.ok{color:var(--ok)}

/* 徽标 */
.badge{display:inline-block;padding:2px 11px;border-radius:999px;font-size:12px}
.badge.ok{background:var(--ok-soft);color:var(--ok)}
.badge.wait{background:var(--warn-soft);color:var(--warn)}
.badge.no{background:var(--danger-soft);color:var(--danger)}

/* 按钮 */
.btn{display:block;width:100%;background:var(--brand);color:#fff;border:none;border-radius:11px;padding:13px;font-size:16px;font-weight:500;cursor:pointer}
.btn:disabled{background:#c9d3e0}
.btn.ghost{background:var(--brand-soft);color:var(--brand)}
.btn.line{background:#fff;color:var(--ink);border:1px solid var(--line)}
.btn.danger{background:#fff;color:var(--danger);border:1px solid #f3c0c5}
.btn.sm{display:inline-block;width:auto;padding:7px 14px;font-size:14px}

/* 表单 */
.field{margin-bottom:15px}
.label{font-size:14px;color:var(--ink-2);margin-bottom:7px}
.label .req{color:var(--danger);margin-left:4px}
.input,.textarea,select{width:100%;background:#f7f8fa;border:1px solid var(--line);border-radius:10px;padding:11px;font-size:16px;color:var(--ink);font-family:inherit}
.textarea{min-height:72px;resize:vertical}
.three{display:flex;gap:8px}.three .input{flex:1;min-width:0}
.kv{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--line)}
.kv:last-child{border-bottom:none}.kv .k{color:var(--ink-2)}.kv .v{font-weight:500;text-align:right}

/* 提示块 */
.notice{background:var(--brand-soft);color:#1a4f9c;padding:10px 12px;border-radius:10px;font-size:13px}
.warnbox{background:var(--warn-soft);color:var(--warn);padding:10px 12px;border-radius:10px;font-size:13px}
.tip{padding:9px 12px;border-radius:10px;font-size:13px}
.tip.ok{background:var(--ok-soft);color:var(--ok)}
.tip.no{background:var(--danger-soft);color:var(--danger)}
.tipcard{background:var(--brand-soft);color:#1a4f9c;font-size:13px;line-height:1.7}

/* 计数三列 */
.counts{display:flex}.counts .cell{flex:1;text-align:center}
.counts .num{font-size:26px;font-weight:700}.counts .num.warn{color:var(--warn)}

/* 迷你路线图 */
.roadmap{display:flex;align-items:flex-start}
.rm-node{display:flex;flex-direction:column;align-items:center;width:40px;flex:none}
.rm-dot{width:26px;height:26px;border-radius:50%;background:var(--line);color:var(--ink-3);text-align:center;line-height:26px;font-size:13px;font-weight:700}
