    v.innerHTML = bannerHtml() + `
      <div class="card">
        <div class="h1">在${esc(cmName)}成立业主委员会</div>
        <div class="muted mt8">从联名到选出业委会、再到换物业的完整路线。每步可展开看要点和对应官方文书。</div>
