/* watermark.js —— 证件图片的双层水印与取证
 *
 * 设计思路（threat model：内部人员截图/下载后外泄）：
 *   第一层 · 可见水印：把「查看人代号 + 时间 + 记录号」以低透明度斜向平铺打进图片像素。
 *            截图、转发、二次压缩、甚至翻拍屏幕都带着 → 这是主要的震慑与追溯手段。
 *   第二层 · 隐形水印（LSB）：把完整信息（查看人真实姓名、记录号、时间戳、用途）
 *            写进像素最低位，肉眼不可见、不影响观感。原图直接外泄时可用「取证」功能还原。
 *            注意：LSB 无法抵抗微信等平台的二次有损压缩 —— 这是数学上的固有限制，不夸大。
 *
 * 每位查看者拿到的都是「独一无二的一张」，因此外泄图片能反查到具体是谁调阅的。
 */
let Jimp = null
try { Jimp = require('jimp') } catch (e) { /* 未安装则降级为不打水印 */ }

const MAGIC = 'KXWM1'          // 隐形水印起始标记
const MAX_W = 1400             // 输出最大宽度（控制体积，同时保住 LSB）

function available () { return !!Jimp }

/* ---------- LSB 隐形水印：写入 ---------- */
function lsbEmbed (bitmap, text) {
  const payload = Buffer.from(MAGIC + text, 'utf8')
  const header = Buffer.alloc(4)
  header.writeUInt32BE(payload.length, 0)
  const bytes = Buffer.concat([header, payload])
  const bits = bytes.length * 8
  const data = bitmap.data
  // 每 4 字节一个像素(RGBA)，只用 R、G、B 三个通道的最低位，跳过 A
  const capacity = Math.floor(data.length / 4) * 3
  if (bits > capacity) return false
  let bi = 0
  for (let px = 0; px < data.length && bi < bits; px += 4) {
    for (let ch = 0; ch < 3 && bi < bits; ch++) {
      const byte = bytes[bi >> 3]
      const bit = (byte >> (7 - (bi & 7))) & 1
      const idx = px + ch
      data[idx] = (data[idx] & 0xFE) | bit
      bi++
    }
  }
  return true
}

/* ---------- LSB 隐形水印：读取 ---------- */
function lsbExtract (bitmap) {
  const data = bitmap.data
  const readBits = (start, count) => {
    const out = Buffer.alloc(Math.ceil(count / 8))
    let bi = 0, got = 0
    for (let px = 0; px < data.length && got < count; px += 4) {
      for (let ch = 0; ch < 3 && got < count; ch++) {
        if (bi >= start) {
          const bit = data[px + ch] & 1
          out[got >> 3] |= bit << (7 - (got & 7))
          got++
        }
        bi++
      }
    }
    return out
  }
  try {
    const head = readBits(0, 32)
    const len = head.readUInt32BE(0)
    if (!len || len > 4096) return null
    const body = readBits(32, len * 8)
    const txt = body.toString('utf8')
    if (txt.indexOf(MAGIC) !== 0) return null
    return txt.slice(MAGIC.length)
  } catch (e) { return null }
}

/* ---------- 主函数：给一张图片打上双层水印 ---------- */
/* opts: { viewerCode, viewerName, recordLabel, kind, at } */
async function stamp (filePath, opts) {
  if (!Jimp) return null
  const img = await Jimp.read(filePath)
  if (img.bitmap.width > MAX_W) img.resize(MAX_W, Jimp.AUTO)

  const W = img.bitmap.width, H = img.bitmap.height
  const d = new Date(opts.at || Date.now())
  const p2 = n => String(n).padStart(2, '0')
  const tsShort = d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate()) + ' ' + p2(d.getHours()) + ':' + p2(d.getMinutes())

  // —— 第一层：可见平铺水印（ASCII，保证内置位图字体可渲染）——
  const line = 'KXTXMT ' + (opts.viewerCode || 'UNKNOWN') + '  ' + tsShort
  try {
    const font = await Jimp.loadFont(Jimp.FONT_SANS_16_WHITE)
    // 先把文字画到透明图层，再整体降透明度斜贴，避免逐字调透明度
    const tile = new Jimp(460, 90, 0x00000000)
    tile.print(font, 0, 0, line)
    tile.print(font, 0, 34, 'FOR ID CHECK ONLY / ' + (opts.recordLabel || ''))
    tile.rotate(-28, false)
    tile.opacity(0.30)
    const stepX = Math.max(300, Math.floor(W / 2.1))
    const stepY = Math.max(210, Math.floor(H / 3.2))
    for (let y = -stepY; y < H + stepY; y += stepY) {
      for (let x = -stepX; x < W + stepX; x += stepX) {
        img.composite(tile, x, y, { mode: Jimp.BLEND_SOURCE_OVER, opacitySource: 0.55 })
      }
    }
    // 底部信息条，便于人眼快速识别
    const bar = new Jimp(W, 34, 0x00000088)
    img.composite(bar, 0, H - 34)
    const fontS = await Jimp.loadFont(Jimp.FONT_SANS_16_WHITE)
    img.print(fontS, 8, H - 30, line + '  ' + (opts.recordLabel || ''))
  } catch (e) { /* 字体不可用则仅保留隐形层 */ }

  // —— 第二层：LSB 隐形水印（承载完整中文信息）——
  const secret = JSON.stringify({
    v: opts.viewerName || '', c: opts.viewerCode || '',
    r: opts.recordLabel || '', k: opts.kind || '',
    t: opts.at || Date.now(), u: '仅核验业主身份用'
  })
  lsbEmbed(img.bitmap, secret)

  // 必须输出 PNG：JPEG 有损压缩会摧毁 LSB
  return await img.getBufferAsync(Jimp.MIME_PNG)
}

/* ---------- 取证：从可疑图片中还原隐形水印 ---------- */
async function forensic (bufOrPath) {
  if (!Jimp) return { ok: false, msg: '服务器未安装图像处理组件' }
  try {
    const img = await Jimp.read(bufOrPath)
    const txt = lsbExtract(img.bitmap)
    if (!txt) return { ok: false, msg: '未能提取到隐形水印：图片可能经过二次压缩/截图/裁剪，或本就不含水印。请改用图片上肉眼可见的水印进行追溯。' }
    let info = null
    try { info = JSON.parse(txt) } catch (e) { return { ok: false, msg: '水印数据损坏' } }
    return { ok: true, info }
  } catch (e) { return { ok: false, msg: '图片无法解析：' + e.message } }
}

module.exports = { available, stamp, forensic, lsbEmbed, lsbExtract }

