const fs = require('fs')
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle,
  Header, Footer, PageNumber, LevelFormat, convertInchesToTwip
} = require('docx')

const FONT = 'SimSun'
const FONT_H = 'SimHei'

const A4 = { width: 11906, height: 16838 } // A4 in DXA

function p (text, opts = {}) {
  const { bold, size = 24, align, indentFirstLine, spacingBefore = 0, spacingAfter = 120, italics, color, font = FONT, lineSpacing } = opts
  return new Paragraph({
    alignment: align || AlignmentType.JUSTIFIED,
    spacing: { before: spacingBefore, after: spacingAfter, line: lineSpacing || 360 },
    indent: indentFirstLine ? { firstLine: 480 } : undefined,
    children: [new TextRun({ text, bold, italics, size, color, font })]
  })
}

function heading1 (text, num) {
  return new Paragraph({
    spacing: { before: 320, after: 160 },
    children: [new TextRun({ text: (num ? num + '、' : '') + text, bold: true, size: 28, font: FONT_H })]
  })
}

function heading2 (text) {
  return new Paragraph({
    spacing: { before: 200, after: 120 },
    children: [new TextRun({ text, bold: true, size: 26, font: FONT_H })]
  })
}

function bullet (text, opts = {}) {
  return new Paragraph({
    numbering: { reference: 'main-bullets', level: 0 },
    spacing: { after: 100, line: 360 },
    alignment: AlignmentType.JUSTIFIED,
    children: [new TextRun({ text, size: 24, font: FONT, bold: opts.bold })]
  })
}

function numbered (text, level = 0) {
  return new Paragraph({
    numbering: { reference: 'main-numbers', level },
    spacing: { after: 100, line: 360 },
    alignment: AlignmentType.JUSTIFIED,
    children: [new TextRun({ text, size: 24, font: FONT })]
  })
}

function hr () {
  return new Paragraph({
    spacing: { before: 60, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: 'B0B0B0' } },
    children: [new TextRun({ text: '' })]
  })
}

// ---- 表格：分工与权责 ----
function cell (text, opts = {}) {
  const { bold, shade, align = AlignmentType.LEFT, width } = opts
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: shade ? { type: ShadingType.CLEAR, color: 'auto', fill: shade } : undefined,
    margins: { top: 80, bottom: 80, left: 100, right: 100 },
    verticalAlign: 'center',
    children: [new Paragraph({
      alignment: align,
      spacing: { line: 300 },
      children: [new TextRun({ text, bold, size: 22, font: FONT })]
    })]
  })
}

const colW = [1500, 3200, 2600, 2600] // 角色/职责/权/责，合计 9900

const tableHeader = new TableRow({
  tableHeader: true,
  children: [
    cell('角色', { bold: true, shade: 'D9D9D9', align: AlignmentType.CENTER, width: colW[0] }),
    cell('职责', { bold: true, shade: 'D9D9D9', align: AlignmentType.CENTER, width: colW[1] }),
    cell('权', { bold: true, shade: 'D9D9D9', align: AlignmentType.CENTER, width: colW[2] }),
    cell('责', { bold: true, shade: 'D9D9D9', align: AlignmentType.CENTER, width: colW[3] })
  ]
})

const roleRows = [
  ['总协调人（1人）', '统筹节奏、对外沟通街道办/社区工作站、主持会议、日常事务拍板', '日常事务决定权；对外代表发起小组', '进度总责；重大事项须集体表决，不得独断'],
  ['法务文书（1人）', '起草申请书、公告、答疑内容、信息公开申请，把关法律表述，对接手册与街道办口径', '文书内容建议权', '对外文字的合规性（不造谣、不越权、表述准确）'],
  ['技术运维（1人）', '网站部署更新、后台配置、数据备份、账号口令保管', '后台管理权限', '数据安全、限期删除的执行，不得私自导出滥用'],
  ['数据审核（1–2人）', '后台核验证件、电话回访核实、汇总名单、维护进度数字', '审核通过/驳回权', '核验真实性、信息保密，不得对外泄露名单'],
  ['楼栋联络员（每栋1人）', '本栋扫楼、贴海报、答疑、代收纸质件、催办', '本栋动员组织权', '如实传达、不夸大承诺、材料及时上交'],
  ['宣传（1人）', '海报设计、群/朋友圈文案、里程碑播报、舆情应对', '宣传口径建议权', '不发布未经核实的信息，口径与法务一致']
]

const bodyRows = roleRows.map(r => new TableRow({
  children: [
    cell(r[0], { bold: true, width: colW[0] }),
    cell(r[1], { width: colW[1] }),
    cell(r[2], { width: colW[2] }),
    cell(r[3], { width: colW[3] })
  ]
}))

const roleTable = new Table({
  width: { size: 9900, type: WidthType.DXA },
  columnWidths: colW,
  rows: [tableHeader, ...bodyRows]
})

// ---- 文档主体 ----
const children = []

// 标题
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 80 },
  children: [new TextRun({ text: '关于组建业委会发起人小组、开展联名推广工作的方案', bold: true, size: 36, font: FONT_H })]
}))
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 300 },
  children: [new TextRun({ text: '——潜在困难研判、发起人小组组建、分工权责与推进节奏', size: 22, font: FONT, color: '595959' })]
}))
children.push(hr())

// 引言
children.push(p('发起阶段的成败，七成不在技术手段，而在组织动员。业主联名成立业委会推广过程中的最大阻力，往往并非来自物业的对抗，而是来自“搭便车”心理与“信任赤字”——多数业主并非反对成立业委会，而是持“我支持，但让别人去做”的态度。因此，本方案的组织设计以“降低信任成本、制造社会认同压力”为核心原则，而非单纯以“把网站推广出去”为目标。', { indentFirstLine: true }))

// 一、潜在困难
children.push(heading1('潜在困难研判及应对', '一'))
children.push(p('结合本次联名推广的实际情况，梳理以下九项潜在困难，按可能造成的影响程度排序，并逐项给出应对思路：', { indentFirstLine: true }))

const issues = [
  ['信任赤字：业主质疑发起人动机，担忧“是否为骗局或受物业操纵”',
   '这是隐私顾虑背后的真正根源，也是最能瘫痪联名工作的因素。应对不依赖话术，而依赖机制：发起人小组成员实名公开（姓名、房号及合影），成员覆盖不同楼栋，公示分工与承诺书。核心原则是：发起人越透明，业主越敢签署。'],
  ['搭便车困境：业主普遍持“我支持，等别人先签够20%”的心态',
   '人人皆如此设想，联名比例便永远无法凑齐。应对之策是将“进度”与“社会认同”予以可视化：设置按楼栋、单元统计的完成度榜，激发楼栋内部的攀比与熟人催促。社区动员的最小有效单位是“单元楼道”，而非“整个小区”。'],
  ['触达断层：业主群覆盖有限、老年业主不熟悉网络操作、部分房屋为租户占用',
   '业主群通常仅能覆盖三至六成业主，且多数成员对群消息保持沉默。应采取线上、线下双轨并行：线上依托业主群、朋友圈及公共区域二维码海报；线下由each楼栋联络员扫楼、上门张贴及代收纸质材料。触达率决定联名工作的上限，而触达依靠的是“每栋皆有熟人”，并非“群内反复转发”。'],
  ['物业方面的软性对抗：撕除海报、在业主群中散布不实言论、宣称“签字需承担责任”“信息将被泄露”“系少数人挑动”等',
   '此类情形大概率发生，且较正面对抗更为常见。应对措施：海报张贴于业主自有区域或业主共有区域，而非物业管理范围内的墙面，以减少被强行撕除的正当理由，并对撕除行为留存证据；已建立的常见问题解答（FAQ）板块，即为回应不实言论的信息储备，物业散布何种说法，即在相应问题上予以置顶回应；全程对现场情况予以拍照、录像留证，阻挠行为本身亦可作为投诉依据。'],
  ['隐私顾虑达到临界点：要求提交身份证、产权证明等材料，导致部分中间立场业主放弃参与',
   '此为转化流程中流失最为严重的环节。应对措施：以书面形式公示《发起人自律承诺书》，明确资料仅用于本次联名、限期删除、仅发起人可查阅；同时可采取“先行意向登记、后续补交材料”的两段式方式——先以较低门槛（仅需姓名、房号、联系方式）征集支持意向，形成整体声势后，待与街道办确认材料形式要求后再统一补交证件，从而将“提交隐私信息”这一环节后置，并与“即将达标”的信心形成叠加效应。'],
  ['法律形式风险：材料收集完毕后，因电子签名或材料形式不符要求而被街道办退回',
   '此为最可能导致工作前功尽弃的技术性风险。应对措施：在全面推广之前，先以数十户为试点，完整走一遍流程并提交至社区工作站进行预先审核，待材料形式与受理口径确认后，再行全面推广，遵循“先行探路、再行推广”的工作顺序。'],
  ['发起人小组内部的意见分歧、精力消耗与人员中途退出',
   '此为纯志愿性组织较为常见的问题。应对措施：小组成员保持五人以上规模以形成容错空间；日常事务由总协调人决定，重大事项以简单多数表决；将任务拆解至“何人于何时交付何事”的具体颗粒度，而非笼统认领；每周召开十五分钟左右的简短会议以同步进度。'],
  ['数据与账号管理集中于单一人员，一旦出现意外将导致数据与进度中断',
   '应对措施：后台登录口令由总协调人与技术负责人各自留存一份备份，并定期导出数据备份；此举亦与前述“限期删除”承诺相互配合。'],
  ['推广工作周期较长，单纯依靠热情启动的动员方式难以持续',
   '应对措施：设定阶段性目标（如“每周新增若干户”），并以可见的里程碑进行播报，借助进度的紧迫感维持参与热度，而非依赖情绪化的宣传维持动力；网站首页已设置六步进度时间轴，使参与者能够直观看到工作进展。']
]

issues.forEach((it, i) => {
  children.push(new Paragraph({
    spacing: { before: 160, after: 60 },
    children: [new TextRun({ text: `${i + 1}. ${it[0]}`, bold: true, size: 24, font: FONT })]
  }))
  children.push(p(it[1], { indentFirstLine: true, spacingAfter: 160 }))
})

// 二、组建
children.push(heading1('发起人小组的组建', '二'))

children.push(heading2('（一）规模'))
children.push(p('建议发起人小组规模为五至九人。人数过少（少于五人）容错空间不足，人数过多（多于九人）则协调难度增加；采用奇数便于必要时进行表决。', { indentFirstLine: true }))

children.push(heading2('（二）构成原则'))
children.push(p('小组构成应刻意追求“代表性”，其重要程度不亚于个人能力，因为代表性直接关系到业主对小组的信任程度：', { indentFirstLine: true }))
children.push(bullet('楼栋覆盖：尽量做到每栋或每个片区至少有一名代表，使各楼栋均有本栋熟悉的联系人负责扫楼动员；'))
children.push(bullet('能力互补：宜包含熟悉法律文书者、熟悉技术运维者、在业主群中具有一定影响力者、时间较为灵活愿意跑腿者，以及细致耐心适合数据管理者；'))
children.push(bullet('口碑门槛：小组成员本人在小区内的口碑应良好，若个别成员存在明显负面评价，将直接影响联名工作的整体信任基础。'))

children.push(heading2('（三）法律地位与对外表述'))
children.push(p('发起人小组本身不具有法律主体地位，业主委员会与筹备组均须经法定程序设立后方具有相应地位。发起人小组的性质是“联名工作的组织者”。因此，对外一切表述均应使用“发起业主（联名）”，落款亦同，不应自称“业主委员会”或“筹备组”，以避免授人以“非法组织”之口实。', { indentFirstLine: true }))

children.push(heading2('（四）入组方式'))
children.push(p('采取公开招募（业主群及海报）与定向邀请相结合的方式。加入小组前，成员应签署《发起人自律承诺书》，承诺事项包括：实名公示、不谋求私利、信息保密、材料限期删除、不代表任何一方在物业费缴纳问题上的立场。小组名单应予以公示，接受全体业主监督。', { indentFirstLine: true }))

// 三、分工与权责
children.push(heading1('分工与权责', '三'))
children.push(p('发起人小组设六类角色，可由一人兼任多项职责，具体分工及权责如下表：', { indentFirstLine: true, spacingAfter: 200 }))
children.push(roleTable)
children.push(p('', { spacingAfter: 120 }))

children.push(heading2('权责红线（四项基本原则）'))
children.push(numbered('重大事项集体表决。是否推进下一阶段工作、材料提交方式、对外正式发文、是否与物业进行和解等事项，均须经小组集体表决（以简单多数通过）并留存会议记录；日常事务性工作由总协调人决定即可。'))
children.push(numbered('发起阶段不收取任何费用。即使为印制海报等所需的工本费，亦应由个人垫付或采取均摊方式，并公开账目。一旦涉及收费，业主对发起人动机的质疑将难以消除。'))
children.push(numbered('数据接触遵循最小化原则。能够接触身份证、产权证明等原始证件的人员，限于数据审核角色（一至二人），其余角色仅接触人数、进度等汇总性信息，权限与相应责任严格对应。'))
children.push(numbered('对外表述保持统一口径。所有正式表述均以法务文书角色的定稿为准，任何个人不得擅自代表小组作出承诺，尤其“必定能够更换物业”“必定降至某一价格”等无法兑现的表述，一律不得使用。'))

// 四、推进节奏
children.push(heading1('推进节奏', '四'))

children.push(heading2('第一阶段：筹备（第一至二周）'))
children.push(p('完成小组组建、签署承诺书并公示名单；网站上线并完成小区参数配置（楼栋、单元、房号、面积选项、公告文案、常见问题解答等）。此阶段的关键前置工作是：选取数十户业主先行试点，完整走一遍流程并提交社区工作站进行预先审核，待受理口径确认后，方可进入全面推广阶段。在口径尚未确定之前，不应开展大规模推广，此为工作纪律。', { indentFirstLine: true }))

children.push(heading2('第二阶段：启动（第一周）'))
children.push(p('由在业主群中具有一定影响力的成员率先发布联名倡议及网站入口；发起人小组成员带头完成签署，以起到示范作用；在电梯、大堂等公共区域张贴海报；当日播报已完成签署的户数。此阶段的目标是营造“已有较多业主参与”的社会认同氛围，以带动后续跟进。', { indentFirstLine: true }))

children.push(heading2('第三阶段：扫楼动员（第二至四周）'))
children.push(p('由楼栋联络员按楼栋分片包干，逐户上门或投递说明材料、电话联系，重点覆盖持中间立场的业主及不熟悉网络操作的老年业主，可由联络员代为填报及代收材料；上线按楼栋统计的完成度排名，以激发楼栋内部的相互催促；每周播报进度及距离达标尚差的户数或面积数。此阶段是获取联名签署数量的主要来源，也是投入精力最多的阶段，主要依靠熟人之间的一对一沟通。', { indentFirstLine: true }))

children.push(heading2('第四阶段：冲刺与材料完善（接近20%比例时）'))
children.push(p('集中力量推进进度落后的楼栋；组织线下集中签署及补充证件的活动，便于解决老年业主操作不便及证件提交方面的顾虑；达到法定比例后，锁定名单，导出《申请书（附件2）》及《业主联名表（附件2-1）》，进入向街道办提交的程序。', { indentFirstLine: true }))

children.push(heading2('贯穿全程的工作事项'))
children.push(bullet('根据舆情变化及时更新常见问题解答内容；'))
children.push(bullet('随时拍照留存关于物业服务问题的现场证据（此类证据具有时效性，新物业进场整改后，原有问题现场即难以取证）；'))
children.push(bullet('持续公示进度时间轴；'))
children.push(bullet('每周召开简短会议，同步各项工作进展。'))

// 结语/提醒
children.push(heading1('工作提醒', '五'))
children.push(numbered('应先行完成预先审核，再行全面推广。在与街道办、社区工作站确认材料形式及受理口径之前，不宜进行大规模推广，这是防止此前工作前功尽弃的关键环节。'))
children.push(numbered('发起人小组的透明程度，直接决定联名工作的转化比例。实名公示、零收费、书面承诺书，其效果优于任何宣传文案。'))
children.push(numbered('动员工作真正的推动力在于“每一楼栋均有一名熟人负责”及“可见的进度”，而非单纯依靠在业主群中反复转发链接。建议将有限的精力优先投入楼栋联络员网络的建设。'))

children.push(new Paragraph({ spacing: { before: 400 }, alignment: AlignmentType.RIGHT, children: [new TextRun({ text: '发起业主（联名）', size: 24, font: FONT })] }))
children.push(new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: '　　年　　月　　日', size: 24, font: FONT })] }))

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 24 } } }
  },
  numbering: {
    config: [
      {
        reference: 'main-bullets',
        levels: [{ level: 0, format: LevelFormat.BULLET, text: '●', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 480, hanging: 240 } } } }]
      },
      {
        reference: 'main-numbers',
        levels: [
          { level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 480, hanging: 240 } } } },
          { level: 1, format: LevelFormat.DECIMAL, text: '（%2）', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 240 } } } }
        ]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: A4,
        margin: { top: 1440, bottom: 1440, left: 1440, right: 1440 }
      }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: 'BFBFBF' } },
          children: [new TextRun({ text: '业委会成立联名工作 · 发起人小组组建方案', size: 18, color: '808080', font: FONT })]
        })]
      })
    },
    footers: {
      default: new Footer({
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [
            new TextRun({ text: '第 ', size: 18, color: '808080', font: FONT }),
            new TextRun({ children: [PageNumber.CURRENT], size: 18, color: '808080', font: FONT }),
            new TextRun({ text: ' 页  共 ', size: 18, color: '808080', font: FONT }),
            new TextRun({ children: [PageNumber.TOTAL_PAGES], size: 18, color: '808080', font: FONT }),
            new TextRun({ text: ' 页', size: 18, color: '808080', font: FONT })
          ]
        })]
      })
    },
    children
  }]
})

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/doc1/发起人小组组建方案.docx', buf)
  console.log('已生成')
})

