      initiatorName: '', initiatorPhone: '',
      buildingStr: '', unitStr: '', roomStr: '', areaStr: '',
      showBuilding: false, showUnit: true, showRoom: true,
      noticeTitle: '', noticeText: ''
    },
    noticePreview: null,
    hasExCert: false, hasExIdFront: false, hasExIdBack: false,
    // FAQ
    faqList: [], faqEdit: null, faqGroup: '', faqQ: '', faqA: '', faqPinned: false
  },

  onShow () {
    if (!app.globalData.adminToken) { toast('请先登录'); setTimeout(() => wx.navigateBack(), 500); return }
    this.load()
  },
  switchTab (e) { this.setData({ tab: e.currentTarget.dataset.t }) },

  load () {
    API.getConfig().then(r => {
      const c = r.config || {}
      const stageIdx = Math.max(0, STAGES.indexOf(c.currentStage || 'collecting'))
      const dates = c.stageDates || {}
      const f = {
        communityName: c.communityName === '（未设置小区名称）' ? '' : c.communityName,
        streetOffice: c.streetOffice === '（未设置街道办）' ? '' : c.streetOffice,
        community: c.community || '', headcountLabel: c.headcountLabel || '业主总人数',
        lianmingMatter: c.lianmingMatter || '', totalHouseholds: c.totalHouseholds || '', totalArea: c.totalArea || '',
        stageIdx, initiatorName: c.initiatorName || '', initiatorPhone: c.initiatorPhone || '',
        buildingStr: (c.buildingOptions || []).join('\n'), unitStr: (c.unitOptions || []).join('\n'),
        roomStr: (c.roomOptions || []).join('\n'), areaStr: (c.areaOptions || []).join('\n'),
        showBuilding: !!c.showBuilding, showUnit: !!c.showUnit, showRoom: !!c.showRoom,
        noticeTitle: c.noticeTitle || '', noticeText: c.noticeText || ''
      }
      this.setData({
        loaded: true, f,
        stageDateItems: STAGES.map((k, i) => ({ key: k, label: STAGE_DATE_LABELS[i], date: dates[k] || '' })),
        hasExCert: !!c.hasExampleCert, hasExIdFront: !!c.hasExampleIdFront, hasExIdBack: !!c.hasExampleIdBack
      })
