  onFaqA (e) { this.setData({ faqA: e.detail.value }) },
  onFaqPin (e) { this.setData({ faqPinned: e.detail.value }) },
  faqSave () {
    const item = { group: (this.data.faqGroup || '').trim() || '其他', q: (this.data.faqQ || '').trim(), a: (this.data.faqA || '').trim(), pinned: this.data.faqPinned }
    if (!item.q || !item.a) return toast('问题与回答均不能为空')
    loading(true, '保存中')
    const p = this.data.faqEdit && this.data.faqEdit.id ? API.updateFaq(this.data.faqEdit.id, item) : API.addFaq(item)
    p.then(() => { loading(false); toast('已保存'); this.setData({ faqEdit: null }); this.loadFaq() }).catch(e => { loading(false); toast(e.message) })
  },
  faqDel (e) {
    const id = e.currentTarget.dataset.id
    wx.showModal({ title: '删除问题', content: '确定删除该条问答？', confirmColor: '#d1543a', success: res => {
      if (!res.confirm) return
      loading(true); API.deleteFaq(id).then(() => { loading(false); toast('已删除'); this.loadFaq() }).catch(err => { loading(false); toast(err.message) })
    } })
  }
})

function splitLines (t) {
  const seen = {}
  return String(t || '').split(/[\n,，、;；]+/).map(x => x.trim()).filter(x => x && !seen[x] && (seen[x] = 1))
}

