// pages/faq/faq.js
const API = require('../../utils/api.js')
const { toast } = require('../../utils/util.js')

Page({
  data: { loaded: false, isMock: false, groups: [] },
  onShow () { this.load() },
  onPullDownRefresh () { this.load(() => wx.stopPullDownRefresh()) },
  load (done) {
    const isMock = (API.BASE || '').indexOf('your-domain') >= 0
    API.getFaq().then(r => {
      const list = (r && r.list) || []
      const order = []
      const map = {}
      list.forEach(x => {
        const g = x.group || '其他'
        if (!map[g]) { map[g] = []; order.push(g) }
        map[g].push({ id: x.id, q: x.q, a: x.a, pinned: !!x.pinned, open: false })
      })
      this.setData({ loaded: true, isMock, groups: order.map(g => ({ name: g, items: map[g] })) })
      done && done()
    }).catch(e => { this.setData({ loaded: true, isMock }); toast(e.message); done && done() })
  },
  toggle (e) {
    const { g, i } = e.currentTarget.dataset
    const groups = this.data.groups
    groups[g].items[i].open = !groups[g].items[i].open
    this.setData({ groups })
  }
})

