    const isMock = (API.BASE || '').indexOf('your-domain') >= 0
    Promise.all([API.getStats(), API.getFaq().catch(() => ({ list: [] }))])
      .then(([s, fq]) => {
        const c = s.community || {}
        const curIdx = Math.max(0, STAGES.indexOf(c.currentStage || 'collecting'))
        const curNo = curIdx + 1
        const dates = c.stageDates || {}
        const timeline = CONTENT.stages.map((st, i) => {
          const done = curNo > i + 1
          const cur = curNo === i + 1
          const d = dates[STAGES[i]]
          return {
            no: st.no, short: st.short, summary: st.summary,
            cls: done ? 'done' : (cur ? 'cur' : 'todo'),
            badge: done ? '已完成' : (cur ? '进行中' : '待定'),
            date: d ? d.replace(/-/g, '.') : '',
            dot: done ? '✓' : String(i + 1),
            isLast: i === CONTENT.stages.length - 1
          }
        })
        const list = (fq && fq.list) || []
        const faqPinned = list.find(x => x.pinned) || list[0] || null
        this.setData({
          loaded: true, isMock, c, s,
          curNo, timeline,
          notice: parseNotice(c.noticeTitle, c.noticeText),
          faqPinned,
          hcWidth: Math.min(100, s.headcountPct || 0),
          areaWidth: Math.min(100, s.areaPct || 0)
        })
        done && done()
      })
      .catch(e => { this.setData({ loaded: true, isMock }); toast(e.message); done && done() })
  },
  goGuide () { wx.navigateTo({ url: '/pages/guide/guide' }) },
  goFaq () { wx.switchTab({ url: '/pages/faq/faq' }) },
  goRegister () { wx.switchTab({ url: '/pages/register/register' }) }
})

