/* pages/index/index.wxss */
.pct { font-size: 34rpx; font-weight: 800; color: var(--ink-3); }
.pct.ok { color: var(--brand); }
.bar { height: 20rpx; background: #eef1f4; border-radius: 10rpx; overflow: hidden; }
.bar-i { height: 100%; background: linear-gradient(90deg, #2f7bb5, #1f5c8b); border-radius: 10rpx; }
.bar.ok .bar-i { background: linear-gradient(90deg, #37a06a, #2b8a5b); }

.gap-callout { background: #fff7ed; border: 2rpx solid #f5c98a; border-left: 10rpx solid #e8862e; border-radius: 16rpx; padding: 26rpx; }
.gap-t { font-size: 26rpx; color: #9a5b13; font-weight: 600; }
.gap-nums { margin-top: 10rpx; font-size: 30rpx; color: #7c4a0e; }
.gap-n { font-size: 52rpx; font-weight: 800; color: #d96f1a; }
.gap-or { margin: 0 16rpx; color: #b58448; font-size: 26rpx; }
.gap-d { margin-top: 10rpx; font-size: 25rpx; color: #9a6a2f; }

/* 时间轴 */
.tl-item { display: flex; }
.tl-rail { width: 52rpx; flex: none; display: flex; flex-direction: column; align-items: center; }
.tl-dot { width: 52rpx; height: 52rpx; border-radius: 50%; background: #e6e8eb; color: var(--ink-3); font-size: 26rpx; font-weight: 800; display: flex; align-items: center; justify-content: center; }
.tl-line { flex: 1; width: 4rpx; background: #e6e8eb; margin: 4rpx 0; min-height: 30rpx; }
.tl-item.done .tl-dot { background: var(--brand); color: #fff; }
.tl-item.done .tl-line { background: var(--brand); }
.tl-item.cur .tl-dot { background: var(--brand); color: #fff; box-shadow: 0 0 0 8rpx var(--brand-soft); }
.tl-body { flex: 1; padding: 0 0 32rpx 20rpx; }
.tl-item:last-child .tl-body { padding-bottom: 0; }
.tl-row { display: flex; align-items: center; justify-content: space-between; }
.tl-title { font-size: 30rpx; font-weight: 600; }
.tl-badge { font-size: 22rpx; padding: 4rpx 14rpx; border-radius: 20rpx; background: #eef0f3; color: var(--ink-3); }
.tl-badge.done { background: var(--brand-soft); color: var(--brand); }
.tl-badge.cur { background: #fff3e0; color: #b26a00; }
.tl-date { font-size: 25rpx; color: var(--ink-2); margin-top: 4rpx; }
.tl-sum { font-size: 24rpx; color: var(--ink-3); line-height: 1.6; margin-top: 6rpx; }

/* 公告文章 */
.notice-art { background: #fffdf5; border: 2rpx solid #f0e6c8; border-radius: 16rpx; padding: 28rpx; font-size: 29rpx; line-height: 1.9; color: var(--ink); }
.nt-title { text-align: center; font-weight: 800; font-size: 34rpx; margin-bottom: 20rpx; }
.nt-p { margin-bottom: 18rpx; }
.notice-art.with-title .nt-p { text-indent: 2em; }
.nt-right { text-align: right; text-indent: 0; }
.nt-b { font-weight: 700; }
.nt-hr { border-top: 2rpx dashed #dfd3ac; margin: 20rpx 0; }

/* 首页 FAQ */
.fq-home { background: #f4f7fb; }
.fq-home-t { font-size: 26rpx; font-weight: 700; color: var(--brand); }
.fq-more { color: var(--brand); font-size: 26rpx; }
.fq-home-q { font-size: 29rpx; font-weight: 700; }
.fq-home-a { font-size: 26rpx; color: var(--ink-2); line-height: 1.8; }

