// pages/mine/mine.js
const API = require('../../utils/api.js')
const { toast } = require('../../utils/util.js')
const app = getApp()
const STATUS = { pending: '待审核', approved: '已通过', rejected: '已驳回' }

Page({
  data: { loaded: false, isMock: false, isAdmin: false, mine: null, statusText: '', statusCls: '' },
  onShow () {
    this.setData({ isAdmin: !!app.globalData.adminToken })
    this.load()
  },
  onPullDownRefresh () { this.load(() => wx.stopPullDownRefresh()) },
  load (done) {
    const isMock = (API.BASE || '').indexOf('your-domain') >= 0
    const et = app.globalData.editToken
    if (!et) { this.setData({ loaded: true, isMock, mine: null }); done && done(); return }
    API.getMine(et).then(r => {
      const m = r.mine
      this.setData({
        loaded: true, isMock, mine: m,
        statusText: m ? (STATUS[m.status] || m.status) : '',
        statusCls: m ? (m.status === 'approved' ? 'ok' : (m.status === 'rejected' ? 'no' : 'wait')) : ''
      })
      done && done()
    }).catch(e => { this.setData({ loaded: true, isMock }); toast(e.message); done && done() })
  },
  editMine () { wx.switchTab({ url: '/pages/register/register' }) },
  goRegister () { wx.switchTab({ url: '/pages/register/register' }) },
  goLogin () { wx.navigateTo({ url: '/pages/admin-login/admin-login' }) },
  goReview () { wx.navigateTo({ url: '/pages/admin-review/admin-review' }) },
  goConfig () { wx.navigateTo({ url: '/pages/admin-config/admin-config' }) },
  goPropAdmin () { wx.navigateTo({ url: '/pages/property-admin/property-admin' }) },
  logout () {
    wx.showModal({
      title: '退出登录', content: '确认退出发起人后台？', success: res => {
        if (res.confirm) { app.setAdminToken(''); this.setData({ isAdmin: false }); toast('已退出') }
      }
    })
  }
})

