// pages/property-admin/property-admin.js
const API = require('../../utils/api.js')
const { toast, loading, fmtDate } = require('../../utils/util.js')
const app = getApp()
const STATUS = { pending: '待审核', approved: '已通过', rejected: '已驳回' }

Page({
  data: { tab: 'review', loaded: false, list: [], pending: 0, cats: [] },
  onShow () {
    if (!app.globalData.adminToken) { toast('请先登录'); setTimeout(() => wx.navigateBack(), 500); return }
    this.load()
  },
  onPullDownRefresh () { this.load(() => wx.stopPullDownRefresh()) },
  switchTab (e) { this.setData({ tab: e.currentTarget.dataset.t }); this.load() },
  load (done) {
    if (this.data.tab === 'review') {
      API.adminProperty().then(r => {
        const list = (r.list || []).map(f => ({
          id: f.id, catName: f.catName, tags: f.tags || [], text: f.text,
          who: f.anon ? '匿名' : ('实名：' + (f.room || '未填')), votes: f.votes,
          status: f.status, statusText: STATUS[f.status] || f.status,
          statusCls: f.status === 'approved' ? 'ok' : (f.status === 'rejected' ? 'no' : 'wait'),
          hasPhoto: f.hasPhoto, photo: f.hasPhoto ? API.adminPropPhotoUrl(f.id) : '',
          date: fmtDate(f.createdAt)
        }))
        this.setData({ loaded: true, list, pending: r.pending })
        done && done()
      }).catch(e => { this.setData({ loaded: true }); toast(e.message); done && done() })
    } else {
      API.getPropCats().then(r => {
        this.setData({ loaded: true, cats: (r.cats || []).map(c => ({ id: c.id, name: c.name, tagsStr: (c.tags || []).join('，'), std: c.std || '', level: c.level || '' })) })
        done && done()
      }).catch(e => { this.setData({ loaded: true }); toast(e.message); done && done() })
    }
  },
  previewPhoto (e) { const u = e.currentTarget.dataset.u; if (u) wx.previewImage({ urls: [u] }) },
  review (e) {
    const { id, action } = e.currentTarget.dataset
    loading(true)
    API.reviewFeedback(id, action, '').then(() => { loading(false); toast(action === 'approve' ? '已通过' : '已驳回'); this.load() }).catch(err => { loading(false); toast(err.message) })
  },
  del (e) {
    const id = e.currentTarget.dataset.id
    wx.showModal({ title: '删除反馈', content: '确定删除该条反馈？', confirmColor: '#d1543a', success: res => {
      if (!res.confirm) return
      loading(true)
      API.deleteFeedback(id).then(() => { loading(false); toast('已删除'); this.load() }).catch(err => { loading(false); toast(err.message) })
    } })
  },
  // 分类维护输入
  onTag (e) { this.updateCat(+e.currentTarget.dataset.i, 'tagsStr', e.detail.value) },
  onStd (e) { this.updateCat(+e.currentTarget.dataset.i, 'std', e.detail.value) },
  onLevel (e) { this.updateCat(+e.currentTarget.dataset.i, 'level', e.detail.value) },
  updateCat (i, key, val) { const cats = this.data.cats.slice(); cats[i] = Object.assign({}, cats[i], { [key]: val }); this.setData({ cats }) },
  saveCats () {
    const payload = this.data.cats.map(c => ({ id: c.id, tags: c.tagsStr, std: c.std, level: c.level }))
    loading(true, '保存中')
    API.savePropCats(payload).then(() => { loading(false); toast('已保存') }).catch(e => { loading(false); toast(e.message) })
  }
})

