  toggleTag (e) {
    const t = e.currentTarget.dataset.t
    const picked = Object.assign({}, this.data.picked)
    if (picked[t]) delete picked[t]
    else {
      if (Object.keys(picked).length >= 3) return toast('最多选 3 个标签')
      picked[t] = 1
    }
    const tags = this.data.tags.map(x => ({ t: x.t, on: !!picked[x.t] }))
    this.setData({ picked, tags })
  },
  onText (e) { this.setData({ text: e.detail.value }) },
  setAnon (e) { this.setData({ anon: e.currentTarget.dataset.v === '1' }) },
  onRoom (e) { this.setData({ room: e.detail.value }) },
  pickPhoto () {
    wx.chooseMedia({ count: 1, mediaType: ['image'], sizeType: ['compressed'], success: res => this.setData({ photoPath: res.tempFiles[0].tempFilePath }) })
  },
  removePhoto () { this.setData({ photoPath: '' }) },

  submit () {
    if (this.data.submitting) return
    const d = this.data
    const c = d.cats[d.catIdx]
    if (!c) return toast('请选择问题类别')
    const text = (d.text || '').trim()
    if (text.length < 4) return toast('请描述具体问题（至少 4 个字）')
    const tags = Object.keys(d.picked)
    this.setData({ submitting: true })
    loading(true, '提交中')
    API.submitFeedback({ catId: c.id, text, tags, anon: d.anon, room: d.room }, d.photoPath || '')
      .then(() => {
        loading(false); this.setData({ submitting: false })
        wx.showModal({ title: '已提交', content: '反馈已提交，经发起人审核通过后计入统计。', showCancel: false, success: () => wx.navigateBack() })
      })
      .catch(e => { loading(false); this.setData({ submitting: false }); toast(e.message) })
  }
})

