// pages/property/property.js
const API = require('../../utils/api.js')
const { toast, fmtDate } = require('../../utils/util.js')
const app = getApp()

Page({
  data: {
    loaded: false, isMock: false, isAdmin: false,
    stat: {}, cats: [], perCat: [], maxCount: 0,
    curCat: '', curCatObj: null,
    items: [], chips: [], dist: []
  },
  onShow () {
    this.setData({ isAdmin: !!app.globalData.adminToken })
    this.load()
  },
  onPullDownRefresh () { this.load(() => wx.stopPullDownRefresh()) },

  load (done) {
    const isMock = (API.BASE || '').indexOf('your-domain') >= 0
    API.getProperty().then(P => {
      const cat = this.data.curCat
      const chips = [{ id: '', name: '综合 Top5', count: 0, on: cat === '' }].concat(
        (P.cats || []).map(c => {
          const pc = (P.perCat || []).find(x => x.id === c.id) || { count: 0 }
          return { id: c.id, name: c.name, count: pc.count, on: cat === c.id }
        })
      )
      const dist = (P.cats || []).map(c => {
        const pc = (P.perCat || []).find(x => x.id === c.id) || { count: 0 }
        return { id: c.id, name: c.name, count: pc.count, w: P.maxCount ? Math.round(pc.count / P.maxCount * 100) : 0 }
      })
      const finish = (items) => {
        const voted = app.globalData.voted || {}
        const rows = items.map((f, i) => ({
          id: f.id, catName: f.catName, tags: f.tags || [], text: f.text,
          room: f.room || '', date: fmtDate(f.createdAt),
          reflect: f.reflect, hasPhoto: f.hasPhoto, photo: f.hasPhoto ? API.propPhotoUrl(f.id) : '',
          voted: !!voted[f.id], rank: cat ? 0 : (i + 1)
        }))
        this.setData({
          loaded: true, isMock, stat: { totalReports: P.totalReports, totalReflect: P.totalReflect, participants: P.participants },
          cats: P.cats, perCat: P.perCat, maxCount: P.maxCount, chips, dist,
          curCat: cat, curCatObj: cat ? (P.cats || []).find(c => c.id === cat) : null,
          items: rows
        })
        done && done()
      }
      if (cat) API.getPropertyList(cat).then(r => finish(r.list || [])).catch(() => finish([]))
      else finish(P.top5 || [])
    }).catch(e => { this.setData({ loaded: true, isMock }); toast(e.message); done && done() })
  },

  pickCat (e) { this.setData({ curCat: e.currentTarget.dataset.c }); this.load() },
  previewPhoto (e) { const u = e.currentTarget.dataset.u; if (u) wx.previewImage({ urls: [u] }) },
  goForm () { wx.navigateTo({ url: '/pages/property-form/property-form' }) },
  goAdmin () { wx.navigateTo({ url: '/pages/property-admin/property-admin' }) },

  vote (e) {
    const id = e.currentTarget.dataset.id
    if ((app.globalData.voted || {})[id]) return
    API.voteFeedback(id, true, '').then(r => {
      app.markVoted(id)
      const items = this.data.items.map(it => it.id === id ? Object.assign({}, it, { voted: true, reflect: r.reflect }) : it)
      this.setData({ items })
      toast('已 +1，感谢反映')
    }).catch(err => toast(err.message))
  }
})

