// pages/register/register.js
const API = require('../../utils/api.js')
const { toast, loading } = require('../../utils/util.js')
const app = getApp()

Page({
  data: {
    loaded: false, isMock: false,
    c: {}, matter: '',
    showBuilding: false, showUnit: false, showRoom: true,
    buildingOptions: [], unitOptions: [], roomOptions: [], areaOptions: [],
    // 表单
    name: '', phone: '',
    bIdx: -1, uIdx: -1, rIdx: -1, aIdx: -1,
    // 文件（临时路径）与预览
    certPath: '', idFrontPath: '', idBackPath: '', signPath: '',
    // 错误
    eName: '', eAddr: '', eArea: '', ePhone: '',
    editing: false,
    hasExCert: false, hasExIdFront: false, hasExIdBack: false,
    submitting: false
  },

  onShow () { this.load() },
  onPullDownRefresh () { this.load(() => wx.stopPullDownRefresh()) },

  load (done) {
    const isMock = (API.BASE || '').indexOf('your-domain') >= 0
    API.getConfig().then(r => {
      const c = r.config || {}
      this.setData({
        loaded: true, isMock, c,
        matter: c.lianmingMatter || '',
        showBuilding: !!c.showBuilding, showUnit: !!c.showUnit, showRoom: !!c.showRoom,
        buildingOptions: c.buildingOptions || [], unitOptions: c.unitOptions || [],
        roomOptions: c.roomOptions || [], areaOptions: c.areaOptions || [],
        hasExCert: !!c.hasExampleCert, hasExIdFront: !!c.hasExampleIdFront, hasExIdBack: !!c.hasExampleIdBack
      })
      done && done()
    }).catch(e => { this.setData({ loaded: true, isMock }); toast(e.message); done && done() })
  },

  // ------- 表单输入 -------
  onName (e) { this.setData({ name: e.detail.value, eName: '' }) },
  onPhone (e) { this.setData({ phone: e.detail.value.replace(/\D/g, '').slice(0, 11), ePhone: '' }) },
  onBuilding (e) { this.setData({ bIdx: +e.detail.value, eAddr: '' }) },
  onUnit (e) { this.setData({ uIdx: +e.detail.value, eAddr: '' }) },
  onRoom (e) { this.setData({ rIdx: +e.detail.value, eAddr: '' }) },
  onArea (e) { this.setData({ aIdx: +e.detail.value, eArea: '' }) },

  // ------- 查看示例（下载后用系统程序打开，兼容图片/PDF）-------
  viewExample (e) {
    const kind = e.currentTarget.dataset.kind
    loading(true, '加载中')
    wx.downloadFile({
      url: API.exampleUrl(kind),
      success (res) {
        loading(false)
        if (res.statusCode !== 200) return toast('示例暂不可用')
        wx.openDocument({ filePath: res.tempFilePath, showMenu: true, fail () { toast('无法打开该示例') } })
      },
      fail () { loading(false); toast('加载失败') }
    })
  },

  // ------- 产权证明：拍照/相册（图片）-------
  pickCert () {
    wx.chooseMedia({
      count: 1, mediaType: ['image'], sizeType: ['compressed'],
      success: res => { this.setData({ certPath: res.tempFiles[0].tempFilePath }) }
    })
  },

  // ------- 身份证：选图后加水印 -------
  pickId (e) {
    const which = e.currentTarget.dataset.which // 'front' | 'back'
    wx.chooseMedia({
      count: 1, mediaType: ['image'], sizeType: ['compressed'],
      success: res => {
        loading(true, '处理中')
        this.watermark(res.tempFiles[0].tempFilePath, out => {
          loading(false)
          if (which === 'front') this.setData({ idFrontPath: out })
          else this.setData({ idBackPath: out })
        })
      }
    })
  },

  // 用离屏 canvas 给身份证平铺水印“仅核验业主身份用”
  watermark (src, cb) {
    wx.getImageInfo({
      src,
      success: info => {
        const maxW = 1000
        const scale = info.width > maxW ? maxW / info.width : 1
        const w = Math.round(info.width * scale)
        const h = Math.round(info.height * scale)
        wx.createSelectorQuery().in(this).select('#wm').fields({ node: true }).exec(res => {
          if (!res[0] || !res[0].node) { cb(src); return }
          const canvas = res[0].node
          canvas.width = w; canvas.height = h
          const ctx = canvas.getContext('2d')
          const img = canvas.createImage()
          img.onload = () => {
            ctx.clearRect(0, 0, w, h)
            ctx.drawImage(img, 0, 0, w, h)
            ctx.save()
            ctx.translate(w / 2, h / 2)
            ctx.rotate(-Math.PI / 7)
            ctx.font = Math.round(w / 16) + 'px sans-serif'
            ctx.fillStyle = 'rgba(0,0,0,0.22)'
            ctx.textAlign = 'center'
            const step = Math.round(w / 3.2)
            for (let y = -h; y < h; y += step) {
              for (let x = -w; x < w; x += step * 2) {
                ctx.fillText('仅核验业主身份用', x, y)
              }
            }
            ctx.restore()
            wx.canvasToTempFilePath({
              canvas,
              success: r => cb(r.tempFilePath),
              fail: () => cb(src)
            })
          }
          img.onerror = () => cb(src)
          img.src = src
        })
      },
      fail: () => cb(src)
    })
  },

  // ------- 手写签名 canvas -------
  onReady () { this.initSign() },
  initSign () {
    wx.createSelectorQuery().in(this).select('#sign').fields({ node: true, size: true }).exec(res => {
      if (!res[0] || !res[0].node) return
      const canvas = res[0].node
      const dpr = (wx.getWindowInfo && wx.getWindowInfo().pixelRatio) || 2
      canvas.width = res[0].width * dpr
      canvas.height = res[0].height * dpr
      const ctx = canvas.getContext('2d')
      ctx.scale(dpr, dpr)
      ctx.lineWidth = 3
      ctx.lineCap = 'round'
      ctx.lineJoin = 'round'
      ctx.strokeStyle = '#111'
      this._sign = { canvas, ctx, drawing: false, dirty: false, w: res[0].width, h: res[0].height }
    })
  },
  signStart (e) { const s = this._sign; if (!s) return; s.drawing = true; const p = e.touches[0]; s.ctx.beginPath(); s.ctx.moveTo(p.x, p.y) },
  signMove (e) { const s = this._sign; if (!s || !s.drawing) return; const p = e.touches[0]; s.ctx.lineTo(p.x, p.y); s.ctx.stroke(); s.dirty = true },
  signEnd () { const s = this._sign; if (s) s.drawing = false },
  clearSign () {
    const s = this._sign; if (!s) return
    s.ctx.clearRect(0, 0, s.canvas.width, s.canvas.height)
    s.dirty = false
    this.setData({ signPath: '' })
  },

  // ------- 提交 -------
  submit () {
    if (this.data.submitting) return
    const d = this.data
    const name = (d.name || '').trim()
    const building = d.showBuilding ? (d.buildingOptions[d.bIdx] || '') : ''
    const unit = d.showUnit ? (d.unitOptions[d.uIdx] || '') : ''
    const room = d.showRoom ? (d.roomOptions[d.rIdx] || '') : ''
    const area = d.areaOptions[d.aIdx] || ''
    const phone = (d.phone || '').trim()
    let bad = false
    const err = {}
    if (!name) { err.eName = '请填写业主姓名'; bad = true }
    else if (!/^[\u4e00-\u9fa5]{2,4}$/.test(name)) { err.eName = '业主姓名应为 2-4 个中文字'; bad = true }
    const miss = []
    if (d.showBuilding && !building) miss.push('栋')
    if (d.showUnit && !unit) miss.push('座')
    if (d.showRoom && !room) miss.push('房')
    if (miss.length) { err.eAddr = '请选择“' + miss.join('”、“') + '”'; bad = true }
    if (!area) { err.eArea = '请选择房屋建筑面积'; bad = true }
    if (!/^1\d{10}$/.test(phone)) { err.ePhone = '请填写 11 位手机号（以 1 开头）'; bad = true }
    this.setData(err)
    if (bad) return
    if (!d.certPath) return toast('请上传产权证明')
    if (!d.idFrontPath) return toast('请上传身份证人像面')
    if (!d.idBackPath) return toast('请上传身份证国徽面')

    const doSubmit = (signPath) => {
      this.setData({ submitting: true })
      loading(true, '提交中')
      API.submitSignature(
        { name, building, unit, room, area, phone },
        { cert: d.certPath, idFront: d.idFrontPath, idBack: d.idBackPath, sign: signPath },
        app.globalData.editToken
      ).then(() => {
        loading(false); this.setData({ submitting: false })
        wx.showModal({ title: '提交成功', content: '已提交，等待发起人核验证件后计入联名。可在「我的」查看状态。', showCancel: false, success: () => wx.switchTab({ url: '/pages/mine/mine' }) })
      }).catch(e => { loading(false); this.setData({ submitting: false }); toast(e.message) })
    }

    // 导出签名图再提交
    const s = this._sign
    if (!s || !s.dirty) return toast('请在签名区手写签名')
    wx.canvasToTempFilePath({
      canvas: s.canvas,
      success: r => doSubmit(r.tempFilePath),
      fail: () => toast('签名导出失败，请重试')
    }, this)
  }
})

