}

/* ---------------- 导出汇总（管理员） ---------------- */
async function getExportData (openid) {
  requireAdminGuard(await isAdmin(openid))
  const cfg = await getConfigDoc()

  // 取全部已通过记录（联名清单）
  const out = []
  const MAX = 1000
  let skip = 0
