const app = getApp()

Page({
  data: { id: '', rec: null, loading: true },

  onLoad (q) {
    this.setData({ id: q.id })
    this.load()
  },

  load () {
    // 复用列表接口取单条（也可单独写 getOne；此处用 listSignatures 后筛选不便，改为直接查全部小数据）
    app.api('listSignatures', { status: undefined, page: 0, size: 50 }).then(res => {
      // 若数据量大，建议后端加 getOne；此处兼顾简单
      let rec = res.list.find(x => x._id === this.data.id)
      if (rec) {
        this.setData({ rec, loading: false })
      } else {
        this.searchAll(0)
      }
    }).catch(e => {
      this.setData({ loading: false })
      wx.showToast({ title: e.message, icon: 'none' })
    })
  },

  searchAll (page) {
    app.api('listSignatures', { page, size: 50 }).then(res => {
      const rec = res.list.find(x => x._id === this.data.id)
      if (rec) { this.setData({ rec, loading: false }); return }
      if (res.list.length < 50) { this.setData({ loading: false }); return }
      this.searchAll(page + 1)
    })
  },

  preview (e) {
    const url = e.currentTarget.dataset.url
    if (url) wx.previewImage({ urls: [url], current: url })
  },

