const app = getApp()

Page({
  data: { loading: true, data: null, letter: '', today: '' },

  onLoad () {
    const d = new Date()
    this.setData({ today: `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日` })
  },

  onShow () { this.load() },

  load () {
    app.api('getExportData').then(res => {
      this.setData({ data: res, loading: false, letter: this.buildLetter(res) })
    }).catch(e => {
      this.setData({ loading: false })
      wx.showModal({ title: '无法导出', content: e.message || '仅管理员可用', showCancel: false, success: () => wx.navigateBack() })
    })
  },

  buildLetter (res) {
    const c = res.config
    const hc = c.headcountLabel || '业主总人数'
    return (
`关于要求成立${c.communityName}首次业主大会会议筹备组的申请

${c.streetOffice}：

  我们是${c.communityName}的业主。根据《深圳经济特区物业管理条例》及《龙岗区业主大会及业主委员会工作指导手册》的有关规定，占物业管理区域业主总人数百分之二十以上的业主，或者占全体业主所持投票权数百分之二十以上的业主，可联名向街道办事处书面要求成立首次业主大会会议筹备组。

  截至${this.data.today}，本小区已有 ${res.count} 名业主联名要求成立筹备组，占${hc}（${c.totalHouseholds}）的 ${res.headcountPct}%；上述业主所拥有专有部分建筑面积合计 ${res.totalSignArea} ㎡，占全体业主专有部分建筑面积总数（${c.totalArea} ㎡）的 ${res.areaPct}%。${res.qualified ? '已达到法定联名比例。' : '（尚未达到法定比例，仅供核对。）'}

  现联名向贵办书面提出申请，请求依法组织、指导成立本小区首次业主大会会议筹备组，推进业主大会的成立与业主委员会的选举工作。

  附：业主联名清单（含姓名、房号、专有部分建筑面积、签名）共 ${res.count} 人。

  联系人：${c.initiatorName || '＿＿＿＿'}　　电话：${c.initiatorPhone || '＿＿＿＿＿＿'}

                                        ${c.communityName}全体联名业主
                                          ${this.data.today}`
    )
  },

  copyLetter () {
    wx.setClipboardData({ data: this.data.letter, success: () => {
      wx.showToast({ title: '申请书已复制', icon: 'none' })
    }})
  },

  copyList () {
    const rows = this.data.data.list.map((d, i) =>
      `${i + 1}\t${d.name}\t${d.roomFull}\t${d.area}㎡\t${d.phone || ''}`
    )
    const head = '序号\t姓名\t房号\t建筑面积\t手机号'
    wx.setClipboardData({ data: [head, ...rows].join('\n'), success: () => {
      wx.showToast({ title: '清单已复制(可粘贴到表格)', icon: 'none' })
    }})
  }
})

