const app = getApp()

// 成立业委会全流程（业主视角），依据《龙岗区业主大会及业主委员会工作指导手册》一、(一)~(六)
const STAGES = [
  {
    key: 'collecting', no: 1, title: '满足启动条件 · 业主联名',
    summary: '征集到法定比例的业主联名，是我们自己能发起的启动方式。',
    points: [
      '三种启动方式满足其一即可：① 业主书面联名（占业主总人数 20% 或占全体业主投票权 20%）；② 建设单位书面报告；③ 街道办事处主动成立。我们走的是第①种。',
      '每位联名业主须提供：联名的具体事项、本人签名、联系电话、房号、投票权数（即房屋建筑面积）、产权证明复印件、身份证复印件。',
      '本小程序的「联名」就是完成这一步——线上登记、手写签名、上传证件，实时统计是否达标。'
    ],
    docs: ['附件2 成立筹备组申请书', '附件2-1 业主联名申请表']
  },
  {
    key: 'submitted', no: 2, title: '提交申请 · 街道办受理',
    summary: '达标后把联名材料交给街道办，由街道办受理并发布公告。',
    points: [
      '达到法定比例后，由联名业主向所属街道办事处提交书面联名申请（申请书 + 联名表 + 各业主身份证、产权证复印件）。',
      '街道办事处根据小区党组织成立情况和物业管理区域实际情况发布公告。',
      '在「我的 → 导出」里可一键生成符合官方模板的申请书与联名清单。'
    ],
    docs: ['附件2 / 附件2-1']
  },
  {
    key: 'group', no: 3, title: '成立筹备组',
    summary: '街道办牵头组建 7–10 人的筹备组，业主代表占 3–5 名。',
    points: [
      '筹备组由 7 至 10 名成员组成：街道办事处代表 1 名（担任组长）、社区党委或基层党组织代表 1 名、业主代表 3 至 5 名、辖区公安派出所代表 1 名、社区居委会代表 1 名、建设单位代表 1 名。',
      '业主代表具体人数由街道办根据小区实际确定，多数小区建议为 3 人。',
      '建设单位未派员参加，不影响筹备组成立。'
    ],
    docs: []
  },
  {
    key: 'enroll', no: 4, title: '业主代表 / 委员报名与遴选',
    summary: '热心业主报名当代表、委员，经资格审查与公示产生名单。',
    points: [
      '筹备组业主代表在全体业主中遴选，其资格与业主委员会委员候选人资格条件一致。',
      '业委会委员、候补委员候选人报名后，需经资格审查（对照正面清单 / 负面清单）、征求社区党委意见。',
      '候选人名单需在小区显著位置公示，公示时间不少于十日。',
      '想报名的业主，可先用「资格自测」对照清单看看自己是否符合。'
    ],
    docs: ['附件3 报名通知', '附件3-1 简历表', '附件3-2 推荐表', '附件3-3 承诺书', '附件7 名单公示']
  },
  {
    key: 'meeting', no: 5, title: '召开首次业主大会 · 选举业委会',
    summary: '全体业主表决选举出业主委员会。',
    points: [
      '筹备组确定首次业主大会会议的时间、地点、方式与议题，并发布召开会议通知。',
      '业主参与表决，选举产生业主委员会委员与候补委员；表决结果在小区公示。',
      '选举办法、表决比例等以筹备组发布的会议文件为准。'
    ],
    docs: ['附件18 召开会议通知', '附件11 首届业委会选举办法', '附件20 表决结果公告']
  },
  {
    key: 'done', no: 6, title: '备案 · 刻章 · 开始运作',
    summary: '业委会成立后备案刻章，就能代表业主开展工作——包括换物业。',
    points: [
      '业主大会、业主委员会依规向街道办事处 / 区主管部门备案，并办理刻章。',
      '业委会成立后，即可依法发起「续聘 / 选聘物业服务企业」等业主大会表决事项——这就是更换物业的法定路径。',
      '具体怎么换物业，见「换物业指南」。'
    ],
    docs: []
  }
]

Page({
  data: {
    stages: STAGES,
    currentKey: 'collecting',
    currentNo: 1,
    expanded: -1,
    communityName: ''
  },

  onShow () {
    app.api('getStats').then(s => {
      const key = s.community.currentStage || 'collecting'
      const idx = STAGES.findIndex(x => x.key === key)
      this.setData({
        currentKey: key,
        currentNo: idx >= 0 ? STAGES[idx].no : 1,
        communityName: s.community.communityName,
        // 默认展开当前阶段
        expanded: idx >= 0 ? idx : 0
      })
    }).catch(() => {})
  },

  toggle (e) {
    const i = e.currentTarget.dataset.i
    this.setData({ expanded: this.data.expanded === i ? -1 : i })
  },

  go (e) {
    const url = e.currentTarget.dataset.url
    wx.navigateTo({ url })
  }
})

