  {
    g: '一、启动联名（我们现在这一步）',
    items: [
      { no: '附件2', name: '成立首次业主大会会议筹备组申请书', use: '联名达标后交给街道办的正式申请书。小程序「导出」会按此模板生成。' },
      { no: '附件2-1', name: '业主联名申请表', use: '随申请书一起的联名清单（姓名/楼栋房号/建筑面积/联系方式/签名）。' },
      { no: '附件1', name: '物业出售及交付使用情况书面报告', use: '建设单位启动方式用，与业主联名无关。' }
    ]
  },
  {
    g: '二、筹备组业主代表',
    items: [
      { no: '附件3', name: '筹备组业主代表报名通知', use: '街道办发布，号召业主报名当代表。' },
      { no: '附件3-1', name: '筹备组业主代表简历表', use: '报名时填写。' },
      { no: '附件3-2', name: '筹备组业主代表推荐表', use: '被推荐报名时用。' },
      { no: '附件3-3', name: '筹备组业主代表承诺书', use: '报名时签署。' },
      { no: '附件4', name: '报名人资料清单', use: '报名需提交的材料一览。' },
      { no: '附件5', name: '延长代表报名期限通知', use: '报名人数不足时延期用。' },
      { no: '附件7', name: '筹备组业主代表名单公示', use: '名单确定后公示（≥10日）。' }
    ]
  },
  {
    g: '三、首次业主大会与选举业委会',
    items: [
      { no: '附件9 / 9-1~9-3', name: '管理规约（含平面图、物业构成、共有设施明细）', use: '小区的"基本法"，首次业主大会表决通过。' },
      { no: '附件10 / 10-1', name: '议事规则 / 印章使用登记表', use: '业主大会、业委会的议事程序与用章规范。' },
