      { no: '附件16 / 16-1', name: '征询候选人名单的函 / 候选人名单', use: '征求社区党委意见环节。' },
      { no: '附件17', name: '候选人名单公示', use: '候选人名单公示（≥10日）。' },
      { no: '附件18', name: '召开首次业主大会会议通知', use: '正式召开与投票的通知。' },
      { no: '附件8 / 12', name: '会议通知 / 延长投票期限通知', use: '通用会议通知、投票延期。' },
      { no: '附件19', name: '第二轮选举通知', use: '首轮未选足时启用。' },
      { no: '附件20 / 20-1 / 20-2', name: '表决结果公告 / 得票明细 / 表决汇总', use: '选举与表决结果公示。' }
    ]
  },
  {
    g: '四、日常运作与各类表决',
    items: [
      { no: '附件21', name: '换届小组业主代表报名通知', use: '业委会换届时用。' },
      { no: '附件22~26', name: '第X次业主大会通知 / 告知书 / 开箱唱票 / 决定公告', use: '日后任何一次业主大会表决（含换物业）的通用文书。' },
      { no: '附件27 / 27-1 / 28', name: '居委会代行业委会职责 征求意见 / 反馈 / 公告', use: '未成立或不启动业委会时的过渡安排。' },
      { no: '附件29 / 29-1 / 30', name: '方案征集意见通知 / 反馈表 / 采纳情况公示', use: '任何重大方案（如选聘物业）征集业主意见用。' }
    ]
  }
]

