if(!reFired&&st.E>=70){reFired=true;phi+=26;S.re.push(i);S.log.push([ys[i],'再进入：E≥70，系统开始运算自身（脉冲 +26）','re']);}
phi=Math.max(0,phi-P.S*0.1*dy);
st.T=Math.max(2,st.T+phi*(1-p.a)*P.R-p.d*st.T*dy);
st.Vs=Math.min(100,st.Vs+0.05*dy+p.c*p.a*phi);
st.E=Math.min(100,st.E+0.014*st.Vs*dy/10);

versions.new:
st.Ve=Math.min(160,st.Ve*Math.pow(1+P.g/100,dy));
let phi=0.06*Math.max(0,st.Ve-st.Vs)*dy;
if(!reFired&&st.E>=70){reFired=true;phi+=26;S.re.push(i);S.log.push([ys[i],'再进入：E≥70，系统开始运算自身（脉冲 +26）','re']);}
phi=Math.max(0,phi-P.S*dy);
st.T=Math.max(2,st.T+phi*(1-p.a)*P.R-p.d*st.T*dy);
st.Vs=Math.min(100,st.Vs+0.05*dy+p.c*p.a*phi);
st.E=Math.min(100,st.E+0.006*st.Vs*dy);

