def gens_table(gens):
    rows = "".join(
        f'<tr><td class="g">{E(g)}</td><td class="f">{E(f)}</td><td>{E(d)}</td></tr>'
        for g, f, d in gens)
    return ('<table class="gens"><thead><tr><th>代际</th><th>形态</th><th>机制与凭证</th></tr></thead>'
            f'<tbody>{rows}</tbody></table>')

def case_html(c):
    h = [f'<div class="case" id="c{c["id"]}">']
    h.append(f'<h2><span class="cn">第 {c["id"]:02d} 案</span>{E(c["title"])}</h2>')
    h.append(f'<div class="verdict"><div class="lab">判 词</div><p>{E(c["verdict"])}</p></div>')
    h.append(f'<div class="mother"><span class="lab">母悖论</span>{E(c["mother"])}</div>')
    h.append('<h3 class="sec">四代诊断</h3>')
    h.append(gens_table(c["gens"]))
    h.append('<h3 class="sec">独门结构</h3>')
    h.append(f'<p>{E(c["signature"])}</p>')
    if c.get("settle"):
        h.append('<h3 class="sec">步五收账</h3>')
        h.append(f'<p>{E(c["settle"])}</p>')
    h.append(f'<div class="remainder"><div class="lab">诚实的残余</div><p>{E(c["remainder"])}</p></div>')
    h.append('</div>')
    return "".join(h)

def vol_html(v):
    h = [f'<div class="voldiv"><div class="no">{E(v["no"])}</div>'
         f'<h1>{E(v["title"])}</h1><div class="sub">{E(v["sub"])}</div><div class="rule"></div>']
    if v["intro"]:
        h.append(f'<div class="intro">{E(v["intro"])}</div>')
    h.append('</div>')
    for c in v["cases"]:
        h.append(case_html(c))
    return "".join(h)

# ── TOC ──
toc = ['<div class="front toc"><h1 class="fm">目　录</h1>']
toc.append('<div class="c"><span class="num"></span><a href="#intro">导论 · 框架说明与阅读须知</a></div>')
for v in VOLS:
    toc.append(f'<div class="v">{E(v["no"])}　{E(v["title"])}<span class="vs">{E(v["sub"])}</span></div>')
    for c in v["cases"]:
        toc.append(f'<div class="c"><span class="num">第 {c["id"]:02d} 案</span>'
                   f'<a href="#c{c["id"]}">{E(c["title"])}</a></div>')
toc.append('<div class="v">附　录</div>')
for aid, at in [("apxA", "附录一　跨案韵脚清单"), ("apxB", "附录二　框架欠账清单"),
                ("apxC", "附录三　全案诊断索引表")]:
    toc.append(f'<div class="c"><span class="num"></span><a href="#{aid}">{E(at)}</a></div>')
toc.append('</div>')

# ── 导论 ──
INTRO = """<div class="front fm-body" id="intro"><h1 class="fm">导论 · 框架说明与阅读须知</h1>
<h2>一、这台机器是什么</h2>
<p class="noind">「认知操作系统」把一切系统读作一台<b>矛盾处理机</b>。它不问系统「是什么」,只问一件事:<b>当系统遇到一个它的架构无法消化的输入时,它做了什么?</b>——这个动作,就是它的代际。</p>
<p>由此得到四个大版本:<b>1.0 封闭</b>——拒收(划界、立 A=A、把异物判为噪声;唯一失败模式是脆断,因为它没有降级模式);<b>2.0 耗散</b>——燃烧(把矛盾接上传动轴当燃料,远离平衡态自组织;代价是没有刹车);<b>3.0 分层</b>——位移(把矛盾搬到另一个层级,对象语言/元语言之塔;解悖=位移而非消除,盲点不可消除只可上移);<b>4.0 生态</b>——共存(多方案并存,有效性环境相对,悬置从终点变成引擎舱)。</p>
<p>轴的两端另有两个<b>边界条件</b>,它们不是版本:<b>序</b>——「划下第一刀」这个打开整个版本空间的动作(道家拒绝的正是它);<b>∞</b>——镜厅,即「这架梯子没有顶格」的声明。把 ∞ 编号为 5.0,等于把哥德尔句登记成一条普通定理。</p>
<h2>二、体例</h2>
<p class="noind">全书 26 案 ＋ 1 问,分七编,按<b>观察者与对象的距离</b>由远及近排列:自然系统(观察者不在场)→ 思想传统 → 政治与制度 → 金融系统 → 形式与元学科 → 文本 · 个体 · 主体(观察者就是对象)→ 元理论。每案固定五栏:<b>判词</b>(结论先行)、<b>母悖论</b>(地基里那枚不可解的 p∧¬p)、<b>四代诊断</b>(表)、<b>独门结构</b>(本案区别于全谱的那一手)、<b>步五收账</b>(约束集 / 形态分布 / 可证伪条件)、<b>诚实的残余</b>(框架在本案上撞到的自身极限)。</p>
<p>收账栏遵守两条纪律:<b>形态可断言,时点须悬置</b>——只给形态分布,不给时间表;<b>可证伪条件挂牌</b>——每案明写「什么能证伪本案判词」。这两条不是学术修辞,是期权交易者的认识论:不预测时点,只定价分布;把「我不知道」本身做成头寸。</p>
<h2>三、如何读这本书</h2>
<p class="noind">如果只读贴合处,这本书会显得像一把万能钥匙——那正是它最危险的读法。<b>真正的产出物是附录二那张欠账清单</b>:框架每一案都赢了叙事,却在残余里持续失血,而那些失血记录攒成了一张越来越长的单子。走到第十九案时结论已经清楚:<b>这台框架最好的用法不是解释一切,是当一块磨刀石——每一段正史在它上面磨过,磨出的偏差比贴合更值钱。</b></p>
<p>因此建议的读法是:先读附录二,再读正文;每读完一案的判词,先去看它的残余。判词是这台机器能说的话,残余是它说不出的话——而后者才是这本书的边界所在。</p>
<h2>四、一条必须前置的声明</h2>
<p class="noind">本书全部判词都是<b>「Q 世界的期望值」</b>——四代阶梯是一次测度变换,把杂乱的历史换算进一个虚构的「逻辑演化空间」里计价;而历史在 P 世界成交。框架与现实之间的落差,就是每一份判词自带的风险溢价,而每案末尾的悬置戳,就是这笔溢价的会计确认。</p>
<p>凡涉及当代议题(美国政治、中国政治、金融、加密),本书采取<b>在场者悬置</b>:账本尚未合上,分析者本人在系统内部——判词没有验尸报告的效力,只有工作票的效力:它标记问题,不裁决结局。凡涉及金融与市场的分析,均为结构分析与情景映射,<b>不构成任何投资建议</b>。</p>
</div>"""

# ── 附录 ──
apxA = ['<div class="appx" id="apxA"><h1>附录一　跨案韵脚清单</h1>',
        '<p class="lead">同一个机制在不同案例中反复现身,是本系列最主要的发现方式。以下十四条韵脚,每一条都至少横跨三案——它们既是框架的解释力所在,也正是「万能溶剂」嫌疑的证据来源:能溶解一切的溶剂,装不进任何容器。</p>',
        '<table class="appx-t"><thead><tr><th>韵脚</th><th>跨案现身</th></tr></thead><tbody>']
for k, v in RHYMES:
    apxA.append(f'<tr><td class="k">{E(k)}</td><td>{E(v)}</td></tr>')
apxA.append('</tbody></table></div>')

apxB = ['<div class="appx" id="apxB"><h1>附录二　框架欠账清单</h1>',
        '<p class="lead">本清单是全书<b>真正的产出物</b>。每一条都是框架在某一案上被对象顶回来的地方——不是修辞性的谦辞,是可被后续工作接手的具体裂缝。清单只增不减:一条被结清(如「致死性 vs 增殖性脆断」由生命案结清),即在备注中标明。</p>',
        '<table class="appx-t"><thead><tr><th>欠账</th><th>立案</th><th>内容</th></tr></thead><tbody>']
for k, src, v in DEBTS:
    apxB.append(f'<tr><td class="k">{E(k)}</td><td class="src">{E(src)}</td><td>{E(v)}</td></tr>')
apxB.append('</tbody></table></div>')

apxC = ['<div class="appx" id="apxC"><h1>附录三　全案诊断索引表</h1>',
        '<p class="lead">全案一览。「代际判定」为该系统的当前形态判定,「独门」为本案区别于全谱的那一手。此表可作为查阅入口,亦可作为跨案比对的工作面。</p>',
        '<table class="idx"><thead><tr><th>№</th><th>案名</th><th>母悖论</th><th>独门 / 判定</th></tr></thead><tbody>']
IDX = {
 1:("对称 ↔ 结构","四代升级线的物理原产地;超新星把脆断改写成分发机制"),
