def gens_table(gens):
    rows = "".join(
        f'<tr><td class="g">{E(g)}</td><td class="f">{E(f)}</td><td>{E(d)}</td></tr>'
        for g, f, d in gens)
    return ('<table class="gens"><thead><tr><th>代际</th><th>形态</th><th>机制与凭证</th></tr></thead>'
            f'<tbody>{rows}</tbody></table>')

def case_html(c):
    h = [f'<div class="case" id="c{c["id"]}">']
    h.append(f'<h2><span class="cn">第 {c["id"]:02d} 案</span>{E(c["title"])}</h2>')
    h.append(f'<div class="verdict"><div class="lab">判 词</div><p>{E(c["verdict"])}</p></div>')
    h.append(f'<div class="mother"><span class="lab">母悖论</span>{E(c["mother"])}</div>')
    h.append('<h3 class="sec">四代诊断</h3>')
    h.append(gens_table(c["gens"]))
    h.append('<h3 class="sec">独门结构</h3>')
    h.append(f'<p>{E(c["signature"])}</p>')
    if c.get("settle"):
        h.append('<h3 class="sec">步五收账</h3>')
        h.append(f'<p>{E(c["settle"])}</p>')
    h.append(f'<div class="remainder"><div class="lab">诚实的残余</div><p>{E(c["remainder"])}</p></div>')
    h.append('</div>')
    return "".join(h)

def vol_html(v):
    h = [f'<div class="voldiv"><div class="no">{E(v["no"])}</div>'
         f'<h1>{E(v["title"])}</h1><div class="sub">{E(v["sub"])}</div><div class="rule"></div>']
    if v["intro"]:
        h.append(f'<div class="intro">{E(v["intro"])}</div>')
    h.append('</div>')
    for c in v["cases"]:
        h.append(case_html(c))
    return "".join(h)

