const fs = require('fs');
const { JSDOM, VirtualConsole } = require('jsdom');

const errors = [];
const vc = new VirtualConsole();
vc.on('jsdomError', e => errors.push('jsdomError: ' + e.message));
vc.on('error', (...a) => errors.push('console.error: ' + a.join(' ')));

const html = fs.readFileSync('认知操作系统-逻辑演化实验室.html', 'utf-8');
const dom = new JSDOM(html, { runScripts: 'dangerously', pretendToBeVisual: true, virtualConsole: vc, resources: undefined });
const { window } = dom;
const doc = window.document;

const sleep = ms => new Promise(r => setTimeout(r, ms));
function btns() { return [...doc.querySelectorAll('#actions button')].map(b => b.textContent); }
function click(substr) {
  const b = [...doc.querySelectorAll('#actions button')].find(b => b.textContent.includes(substr));
  if (!b) throw new Error('button not found: "' + substr + '" | available: ' + JSON.stringify(btns()));
  b.click(); return true;
}
function phase() { return doc.querySelector('#hud').textContent; }
function logTail(n=3){ return [...doc.querySelectorAll('#syslog .ln')].slice(-n).map(x=>x.textContent); }

(async () => {
  try {
    await sleep(300);
    console.log('[0]', phase(), '| actions:', btns());

    // 序 · 划下一刀
    click('划下一刀'); await sleep(4300);
    console.log('[序完成]', 'kernel:', doc.querySelector('#law-sr .lst').textContent, '| actions:', btns());
    click('启动 1.0'); await sleep(300);
    console.log('[1.0]', phase());

    // 1.0 投喂 + 三次悖论 + 脆断
    click('投喂清晰命题'); await sleep(2100);
    console.log('  定理计数:', doc.querySelector('#c-thm').textContent);
    for (let i = 0; i < 3; i++) { click('注入'); await sleep(1600); }
    console.log('  拒收:', doc.querySelector('#c-rej').textContent, '| log:', logTail(2));
    click('脆断'); await sleep(1300);
    console.log('[2.0]', phase(), '| actions:', btns());

    // 2.0 三轮扬弃
    for (let i = 0; i < 3; i++) {
      click('异化'); await sleep(400);
      click('扬弃'); await sleep(2200);
    }
    console.log('  扬弃计数:', doc.querySelector('#c-auf').textContent, '| actions:', btns());
    click('梦想闭合'); await sleep(300);
    console.log('[3.0]', phase());

    // 3.0 自证 → Ashby → 三联
    click('执行 PROVE'); await sleep(4600);
    console.log('  actions:', btns());
    click('扩充'); await sleep(200); click('扩充'); await sleep(2800);
    console.log('  三联后 actions:', btns(), '| log:', logTail(2));
    click('分层解悖'); await sleep(300);
    console.log('[3.0+]', phase());

    // 分层塔 ×4
    click('加盖'); await sleep(500);
    for (let i = 0; i < 3; i++) { click('再加一层'); await sleep(500); }
    console.log('  位移:', doc.querySelector('#c-shift').textContent, '| actions:', btns());
    click('放弃'); await sleep(300);
    console.log('[4.0]', phase());

    // 4.0 滑杆 + 气泡点击 + 注入
    const slide = doc.querySelector('#tslide');
    slide.value = '80'; slide.dispatchEvent(new window.Event('input', { bubbles: true }));
    console.log('  真值显示:', doc.querySelector('#tval').textContent);
    // 点击一个气泡（第二个 circle.clickable）
    const bub = doc.querySelectorAll('#gSys circle.clickable')[1];
    bub.dispatchEvent(new window.MouseEvent('click', { bubbles: true }));
    console.log('  局部内核视图:', doc.querySelector('#kview').textContent.slice(0, 30), '| 排中律:', doc.querySelector('#law-em .lst').textContent);
    doc.querySelector('#kback').onclick && doc.querySelector('#kback').click();
    click('注入一枚悖论'); await sleep(1600);
    console.log('  注入后 actions:', btns(), '| log:', logTail(2));
    click('尾声'); await sleep(300);
    console.log('[∞]', phase());

    // 镜厅 ×2 + final
    click('再划一刀'); await sleep(2200);
    console.log('  深度:', doc.querySelector('#c-depth').textContent, '| actions:', btns());
    click('再划一刀'); await sleep(2400);
    console.log('  final actions:', btns());
    console.log('  嵌套层数(g.nest):', doc.querySelectorAll('#gWorld g.nest').length);

    // 回跳测试：rail 全解锁后跳回 2.0
    const rail = [...doc.querySelectorAll('#rail .rstop')];
    console.log('  rail 解锁数:', rail.filter(b => !b.disabled).length, '/', rail.length);
    rail[2].click(); await sleep(300);
    console.log('  回跳后:', phase(), '| actions:', btns());

    // 重新推演
    rail[6].click(); await sleep(300);
    // 静态区块测试
    doc.querySelectorAll('#mtabs .mtab')[2].click();
    console.log('  档案切换到:', doc.querySelector('#mpanel .mv').textContent, doc.querySelector('#mpanel .mera').textContent);
    for (let i = 0; i < 5; i++) doc.querySelector('#wbbtns .wbtn').click();
    console.log('  工作台链条点亮:', doc.querySelector('#wbchain').className, '| 按钮区:', doc.querySelector('#wbbtns').textContent.slice(0, 20));
    doc.querySelectorAll('#wbtabs .mtab')[2].click();
    console.log('  切换数学域, 步骤重置:', doc.querySelectorAll('#wbsteps .step.done').length, 'done');
    doc.querySelector('.acard').click();
    console.log('  武器库展开:', doc.querySelector('.acard').className);

    console.log('\n== SMOKE PASS ==');
  } catch (e) {
    console.log('\n== SMOKE FAIL ==\n' + e.stack);
  }
  if (errors.length) { console.log('\n-- captured errors --'); errors.slice(0, 10).forEach(e => console.log(e)); }
  else console.log('-- no console/jsdom errors --');
  window.close(); process.exit(0);
})();

