const html=fs.readFileSync('./五步法推演引擎.html','utf-8');
let errors=[];
const dom=new JSDOM(html,{runScripts:'dangerously',pretendToBeVisual:true,
 virtualConsole:new (require('jsdom').VirtualConsole)().on('jsdomError',e=>errors.push(String(e))).on('error',(...a)=>errors.push(a.join(' ')))});
const w=dom.window,d=w.document;
const ok=(c,m)=>{console.log((c?'✅':'❌')+' '+m);if(!c)process.exitCode=1;};

setTimeout(()=>{
 ok(errors.length===0,'加载零错误 '+(errors[0]||''));
 ok(!!w.APP&&w.APP.SYSTEMS.length===3,'APP 钩子与三系统');

 const anchors=[[1781,1901,1975],[1665,1872,1963],[1933,1971,2008]];
 const tol=[[25,12,10],[20,12,10],[3,3,3]];
 for(let i=0;i<3;i++){
  w.APP.go(i);
  const s=w.APP.SYSTEMS[i];
  ok(d.querySelectorAll('#axioms .axcard').length===4,s.name+' 公理卡×4');
  ok(d.querySelectorAll('#faults .fault').length===6,s.name+' 断层线×6');
  ok(d.querySelectorAll('#matrix tr').length===5,s.name+' 矩阵 5 行');
  ok(d.querySelectorAll('#genchips .genchip').length===4,s.name+' 代际×4');
  ok(d.querySelectorAll('#evlist .ev').length>=15,s.name+' 事件≥15 ('+d.querySelectorAll('#evlist .ev').length+')');
  const S=w.APP.series;
  ok(S.trans.length===3,s.name+' 相变×3 ('+S.trans.length+')');
  const yrs=S.trans.map(t=>Math.round(S.years[t]));
  let hit=true;yrs.forEach((y,k)=>{if(Math.abs(y-anchors[i][k])>tol[i][k])hit=false;});
  ok(hit,s.name+' 相变锚点 '+JSON.stringify(yrs)+' ≈ '+JSON.stringify(anchors[i]));
  ok(S.gen[719]===3,s.name+' 终局 G4');
  // T 轨迹健全性：不粘地板、锚点前不越脆断线
  let maxPre=0,floor2=0;
  for(let k=0;k<719;k++){const g=S.gen[k],th=s.gens[g].p.th;
   if(S.T[k]>=th*1.35)maxPre++;
   if(S.T[k]<=2.01)floor2++;}
  ok(maxPre===0,s.name+' 全程未越脆断线（历史模式应存活）');
  ok(floor2<80,s.name+' 张力不长期粘地板 (地板样本 '+floor2+')');
  const tmax=Math.max(...S.T).toFixed(0),tmin=Math.min(...S.T.slice(30)).toFixed(0);
  console.log('   ↳ '+s.name+' T∈['+tmin+','+tmax+'] 相变年 '+yrs.join('/')+' 再进入×'+S.re.length+' 近脆断×'+S.nd.length);
  w.APP.setPlay(719);
  ok(d.querySelector('#readout').children.length===8,s.name+' 实时读数×8');
  ok(d.querySelector('#chart1').querySelectorAll('polyline').length>=3,s.name+' 时空图折线渲染');
  ok(d.querySelector('#phase1').querySelectorAll('line,circle').length>10,s.name+' 相图轨迹渲染');
 }

 // 排序切换
 w.APP.go(2);
 const first=()=>d.querySelector('#faults .fault .fn').textContent;
 const bySilt=first();
 d.querySelector('#sortLoud').click();
 const byLoud=first();
 ok(bySilt!==byLoud,'排序翻转：淤积首位「'+bySilt.slice(3,20)+'」→ 响度首位「'+byLoud.slice(3,20)+'」');
 d.querySelector('#sortSilt').click();

 // 代际切换
 const chips=d.querySelectorAll('#genchips .genchip');
 chips[2].click();
 ok(d.querySelector('#gencard').textContent.includes('分层塔'),'代际卡切换至 G3（金融）');

 // 步五开关平移
 const pct0=d.querySelector('#forms .formbar span:last-child').textContent;
 d.querySelector('#toggles .tgl').click();
 const pct1=d.querySelector('#forms .formbar span:last-child').textContent;
 ok(pct0!==pct1,'假设开关平移分布 '+pct0+'→'+pct1);

 // 沙盘四出口（直接调引擎）
 const B=w.APP.buildSandbox;
 const r1=B({g:.62,R:1,D:12,S:0,reg:0});
 ok(r1.outcome[0]==='out-ok'&&r1.trans.length>=3,'沙盘默认→完整序列 G1→G4 ('+r1.outcome[1].slice(0,14)+') 相变×'+r1.trans.length+' 再进入×'+r1.re.length);
 const r2=B({g:1.1,R:1.6,D:60,S:0,reg:0});
 ok(r2.dead===true,'高压×高刚性×长延迟→脆断死亡 ('+(r2.log.find(l=>l[2]==='dead')||['','?'])[1].slice(0,16)+')');
 const r3=B({g:.62,R:1,D:12,S:2.5,reg:0});
 ok(r3.outcome[0]==='out-frozen'&&r3.gen[719]<3,'高补贴→冻结 (终局 G'+(r3.gen[719]+1)+')');
 const r4=B({g:.62,R:1,D:12,S:0,reg:1});
 ok(r4.regressed===true,'回缩开关→经历反动回缩 ('+r4.outcome[1].slice(0,20)+'…)');
 const r5=B({g:.2,R:1,D:12,S:0,reg:0});
 ok(r5.gen[719]<3&&!r5.dead,'低压→停滞 (终局 G'+(r5.gen[719]+1)+')');
 console.log('   ↳ 沙盘默认相变年:',r1.trans.map(t=>Math.round(r1.years[t])).join('/'),'再进入年:',r1.re.map(t=>Math.round(r1.years[t])).join('/'));

 // 沙盘 DOM 流程
 d.querySelector('#mSand').click();
 setTimeout(()=>{
  ok(d.querySelector('#sandblock').style.display!=='none','模式切换至沙盘');
  ok(d.querySelector('#outbanner').textContent.length>4,'出口判读 banner: '+d.querySelector('#outbanner').textContent.slice(0,26));
  d.querySelector('#ghostBtn').click();
  ok(d.querySelector('#ghostn').textContent.includes('×1'),'叠影保留 ×1');
  ok(d.querySelectorAll('#evlist2 .ev').length>=1,'沙盘事件日志非空');
  console.log('\n==== SMOKE DONE ====');
  w.close();
 },600);
},400);

