const {JSDOM}=require('jsdom');
const fs=require('fs');
const html=fs.readFileSync('./认知操作系统-逻辑演化实验室.html','utf-8');
let errors=[];
const dom=new JSDOM(html,{runScripts:'dangerously',pretendToBeVisual:true,
 virtualConsole:new (require('jsdom').VirtualConsole)().on('jsdomError',e=>errors.push(String(e)))});
const w=dom.window,d=w.document;
const ok=(c,m)=>{console.log((c?'✅':'❌')+' '+m);if(!c)process.exitCode=1;};
setTimeout(()=>{
 ok(errors.length===0,'加载零错误 '+(errors[0]||''));
 const tabs=d.querySelectorAll('#wbtabs .mtab');
 ok(tabs.length===3,'三域标签: '+[...tabs].map(t=>t.textContent).join(' / '));
 ok(tabs[0].textContent==='西方哲学'&&tabs[1].textContent==='基督教思想','域名替换正确');
 const KEY=[['sp','悬置为纪律'],['s4','普世生态']];
 for(let di=0;di<2;di++){
  tabs[di]===d.querySelectorAll('#wbtabs .mtab')[di];
  d.querySelectorAll('#wbtabs .mtab')[di].click();
  const nm=d.querySelectorAll('#wbtabs .mtab')[di].textContent;
  const steps=d.querySelectorAll('#wbsteps .step');
  ok(steps.length===5,nm+' 五步卡片');
  const alltxt=d.querySelector('#wbsteps').textContent;
  const marks=di===0?['响度≠载荷','再进入','形态可断言，时点须悬置']:['圣化围堵','sola scriptura','回缩模块','形态可断言'];
  marks.forEach(k=>ok(alltxt.includes(k),nm+' 含判词「'+k+'」'));
  for(let i=0;i<5;i++){const b=d.querySelector('#wbbtns .wbtn');ok(!!b,nm+' 步骤按钮 '+(i+1));b&&b.click();}
  ok(d.querySelector('#wbchain').classList.contains('lit'),nm+' 链条点亮');
  const nodes=d.querySelectorAll('#wbchain .cnode');
  ok(nodes.length===7,nm+' 链条 7 节点 ('+nodes.length+')');
  ok(d.querySelector('#wbchain').textContent.includes(KEY[di][1]),nm+' 末节点: '+KEY[di][1]);
  ok(!!d.querySelector('#wbchain .tg-'+KEY[di][0]),nm+' 色标 tg-'+KEY[di][0]+' 存在');
  ok(d.querySelector('#wbbtns').textContent.includes('推演完毕'),nm+' 完毕消息');
 }
 d.querySelectorAll('#wbtabs .mtab')[2].click();
 ok(d.querySelector('#wbsteps').textContent.includes('欧几里得'),'数学思想域保持原样');
 ok(d.querySelectorAll('#rail .rstop').length===7,'相位轨道 7 站（回归检查）');
 console.log('==== WB SMOKE DONE ====');
 w.close();
},400);

