const {JSDOM}=require('jsdom');
const fs=require('fs');
const html=fs.readFileSync('./认知操作系统-逻辑演化实验室.html','utf-8');
let errors=[];
const dom=new JSDOM(html,{runScripts:'dangerously',pretendToBeVisual:true,
 virtualConsole:new (require('jsdom').VirtualConsole)().on('jsdomError',e=>errors.push(String(e)))});
const w=dom.window,d=w.document;
const ok=(c,m)=>{console.log((c?'✅':'❌')+' '+m);if(!c)process.exitCode=1;};
const q=s=>d.querySelector(s), qa=s=>d.querySelectorAll(s);
setTimeout(()=>{
 ok(errors.length===0,'加载零错误 '+(errors[0]||''));
 // 精推域回归
 ok(qa('#wbmode .mtab').length===2,'模式切换 ×2: '+[...qa('#wbmode .mtab')].map(x=>x.textContent).join(' | '));
 ok(qa('#wbtabs .mtab').length===3,'精推域 ×3');
 for(let i=0;i<5;i++)q('#wbbtns .wbtn').click();
 ok(q('#wbchain').classList.contains('lit')&&qa('#wbchain .cnode').length===7,'精推域链条点亮 ×7');
 // 切图谱
 qa('#wbmode .mtab')[1].click();
 ok(qa('#wbcats .mtab').length===11,'类别 ×11');
 ok(qa('#wbsys .syschip').length===2&&q('#wbsys .syschip b').textContent==='基督教','默认类·宗教思想 ×2');
 // 经济金融 → 期权系统
 const cats=[...qa('#wbcats .mtab')];
 const fin=cats.find(x=>x.textContent.startsWith('经济金融'));
 ok(!!fin&&fin.textContent.includes('×6'),'经济金融 ×6');
 fin.click();
 const chips=[...qa('#wbsys .syschip')];
 ok(chips.length===6,'金融系统芯片 ×6: '+chips.map(x=>x.querySelector('b').textContent).join('/'));
 const opt=chips.find(x=>x.querySelector('b').textContent==='期权系统');
 ok(!!opt,'找到期权系统');opt.click();
 // 步一母悖论
 q('#wbbtns .wbtn').click();
 const s1=qa('#wbsteps .step')[0];
 ok(s1.classList.contains('done')&&s1.textContent.includes('母悖论')&&s1.textContent.includes('图谱供数'),'步一·母悖论已供数');
 // 星座
 ok(q('#wbchainT').textContent.includes('张力星座'),'右栏切换为张力星座');
 ok(!q('#wbchain').classList.contains('lit2'),'步二前星座未点亮');
 q('#wbbtns .wbtn').click();
 ok(q('#wbchain').classList.contains('lit2'),'步二后星座点亮');
 const tens=qa('#wbsteps .ten');
 ok(tens.length===11&&qa('#wbchain .tpill').length===11,'期权系统断层线 ×11（列表与星座一致）');
 tens[0].click();
 ok(tens[0].classList.contains('open')&&tens[0].querySelector('.tx').textContent.length>20,'张力注文可展开: '+tens[0].querySelector('b').textContent);
 // 步三四五
 q('#wbbtns .wbtn').click();q('#wbbtns .wbtn').click();q('#wbbtns .wbtn').click();
 const txt=q('#wbsteps').textContent;
 ok(txt.includes('四科目会计')&&txt.includes('框架工作单'),'步三·会计工作单');
 ok(txt.includes('五步法推演引擎'),'步四·引擎交接');
 ok(txt.includes('悬置纪律'),'步五·元结论+悬置');
 ok(q('#wbbtns').textContent.includes('图谱燃料推演完毕'),'完毕消息');
 // 回精推域
 const back=[...qa('#wbbtns .wbtn')].find(x=>x.textContent.includes('回精推域'));
 back.click();
 ok(qa('#wbtabs .mtab').length===3&&q('#wbchainT').textContent.includes('演化链条'),'回精推域成功·链条标题还原');
 ok(q('#wblegend').style.display!=='none','图例还原显示');
 // 学科反思抽查
 qa('#wbmode .mtab')[1].click();
 [...qa('#wbcats .mtab')].find(x=>x.textContent.startsWith('学科反思')).click();
 ok(qa('#wbsys .syschip').length===24,'学科反思 ×24');
