files.content:
# -*- coding: utf-8 -*-
import re, json, sys
sys.path.insert(0, '/tmp')
from wb3_data import NEW_DOMAINS, DIAG

p = '认知操作系统-逻辑演化实验室.html'
s = open(p, encoding='utf-8').read()
orig = len(s)

# ============ ① 重建 ATLAS 嵌入（合流诊断字段） ============
c = json.load(open('/tmp/atlas.json'))
data = c['SYSTEMS']; CATS = c['CATEGORIES']
cat_names = [x if isinstance(x, str) else (x.get('name') or x.get('id')) for x in CATS]

def prose(lst, n, cap):
    out = []
    for it in (lst or []):
        if isinstance(it, dict) and it.get('type') == 'prose':
            t = (it.get('text') or '').strip()
            if not t: continue
            out.append(t[:cap] + ('…' if len(t) > cap else ''))
            if len(out) >= n: break
    return out

def norm(x): return re.sub(r'\s+', '', x or '')

trim = []
for d in data:
    m = d['mother_paradox']
    ts = []
    for t in d['tensions']:
        a, b = t.get('pole_a', '').strip(), t.get('pole_b', '').strip()
        l = (t.get('full_label') or '').strip()
        if norm(l) in (norm(a + '↔' + b), norm(a + ' ↔ ' + b)): l = ''
        x = prose(t.get('body'), 1, 170)
        ts.append({'a': a, 'b': b, 'l': l, 'x': x[0] if x else ''})
    dg = DIAG[d['name']]
    ent = {'n': d['name'], 'c': d['category'], 'e': d.get('era', ''),
           'g': dg['g'], 'b': dg['b'], 'mech': dg['mech'], 'v': dg['v'],
           'm': {'a': m.get('pole_a', ''), 'b': m.get('pole_b', ''),
                 'd': prose(m.get('description'), 1, 240)},
           't': ts, 'z': prose(d.get('meta_conclusion'), 1, 200)}
    if 'lk' in dg: ent['lk'] = dg['lk']
    trim.append(ent)
present = [cn for cn in cat_names if any(x['c'] == cn for x in trim)]
js_data = json.dumps(trim, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')
js_cats = json.dumps(present, ensure_ascii=False, separators=(',', ':'))
print('嵌入体积:', len(js_data.encode('utf-8')) // 1024, 'KB')

# ============ ② 插入六个新精推域 ============
anchor = "新范式','s4']]}];"
assert anchor in s
s = s.replace(anchor, "新范式','s4']]},\n" + NEW_DOMAINS + "];", 1)

# ============ ③ 结构：总览容器 ============
s = s.replace('<div id="wbcats"></div>', '<div id="wbov"></div>\n    <div id="wbcats"></div>', 1)

# ============ ④ 导语更新 ============
old_l = '现已接入<a class="alink" href="https://cavno.github.io/Reading_and_Thinking/Philosophy/%E6%82%96%E8%AE%BA%E5%9B%BE%E8%B0%B1/" target="_blank" rel="noopener">《悖论图谱》</a>燃料库：<b>96 系统 · 842 张力 · 11 类</b>——母悖论供步一，断层线供步二，元结论供步五；步三 / 四为框架工作单。'
new_l = '现已接入<a class="alink" href="https://cavno.github.io/Reading_and_Thinking/Philosophy/%E6%82%96%E8%AE%BA%E5%9B%BE%E8%B0%B1/" target="_blank" rel="noopener">《悖论图谱》</a>并完成<b>全谱代际诊断</b>：96 个系统逐一判定所处代际（1.0 封闭 / 2.0 耗散 / 3.0 分层 / 4.0 生态 / 特案），各附机制指认与判词——判定依据只有一条：<b>它上一次遇到矛盾时做了什么</b>。其中 9 个系统入精推域，按同一工艺完成完整五步推演。'
assert old_l in s; s = s.replace(old_l, new_l)

# ============ ⑤ 替换图谱 JS 块（含渲染器） ============
NEWJS = 'const ATLAS=' + js_data + ';\nconst ACATS=' + js_cats + ';\n' + r'''const GBK={1:'1.0',2:'2.0',3:'3.0',4:'4.0',0:'特案'};
const GSTAT={1:0,2:0,3:0,4:0,0:0};ATLAS.forEach(x=>GSTAT[x.b]++);
let wbMode='fine',wbD=0,wbS=0,aC=0,aS=0;
function esc(x){return String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function renderWB(){
  const mb=$('#wbmode');mb.innerHTML='';
  [['fine','精推域 ×'+DOMAINS.length],['atlas','代际诊断 ×'+ATLAS.length]].forEach(pair=>{
    const b=H('button','mtab'+(wbMode===pair[0]?' act':''),pair[1],mb);
    b.onclick=()=>{if(wbMode!==pair[0]){wbMode=pair[0];wbS=0;renderWB();}};});
  const tabs=$('#wbtabs'),cats=$('#wbcats'),sysb=$('#wbsys'),ov=$('#wbov');
  tabs.innerHTML='';cats.innerHTML='';sysb.innerHTML='';ov.innerHTML='';
  if(wbMode==='fine'){
    ov.style.display='none';cats.style.display='none';sysb.style.display='none';tabs.style.display='flex';
    DOMAINS.forEach((d,i)=>{const b=H('button','mtab'+(i===wbD?' act':''),d.name,tabs);
      b.onclick=()=>{wbD=i;wbS=0;renderWB();};});
    renderFine();
  }else{
    tabs.style.display='none';ov.style.display='flex';cats.style.display='flex';sysb.style.display='grid';
    [1,2,3,4,0].forEach(k=>H('span','gpill g'+k,GBK[k]+(k?['',' 封闭',' 耗散',' 分层',' 生态'][k]:'')+' ×'+GSTAT[k],ov));
    H('span','ovnote','判定依据＝上一次遇到矛盾时它做了什么 · 特案含脆断窗口 / 代际错位 / 元批判文本',ov);
    ACATS.forEach((cn,i)=>{const k=ATLAS.filter(x=>x.c===cn).length;
      const b=H('button','mtab'+(i===aC?' act':''),cn+' ×'+k,cats);
      b.onclick=()=>{aC=i;aS=0;renderWB();};});
    const list=ATLAS.filter(x=>x.c===ACATS[aC]);
    if(aS>=list.length)aS=0;
    list.forEach((sy,i)=>{const b=H('button','syschip'+(i===aS?' act':''),
      '<b>'+esc(sy.n)+'</b><span><i class="gb g'+sy.b+'">'+GBK[sy.b]+'</i>'+sy.t.length+' 断层线'+(sy.lk!=null?' · <u>已精推</u>':'')+'</span>',sysb);
      b.onclick=()=>{aS=i;renderWB();};});
    renderAtlas(list[aS]);
  }
}
function wbStepCard(st,i,body){
  H('div','step'+(i<wbS?' done':''),
   '<div class="st"><b>'+(i+1)+'</b>'+WBSTEPS[i]+'</div><div class="sc">'+body+'</div><div class="pend">待执行</div>',st);
}
function renderFine(){
  const d=DOMAINS[wbD];
