// 版本档案 · 四代系统对照
const STAGES = [
  { v:'1.0', era:'古希腊形式逻辑', time:'公元前 5–4 世纪',
    ppl:['巴门尼德','芝诺（压力测试员）','亚里士多德','欧几里得'],
    char:'封闭、线性、确定性——假设前提与结论之间存在绝对刚性传导。',
    mech:'硬边界屏蔽信息熵：A=A 作为基准协议，滤除时间维度与状态流变，把万物锁进离散、静止的坐标点。',
    form:'三段论、几何公理体系；一切知识被要求编入同一张静态之网。',
    lim:'零矛盾容忍。遇到无法划界的边缘输入（连续性、变化、自指）即报错卡死——脆断是唯一失败模式。',
    fp:[95,8,15,10] },
  { v:'2.0', era:'康德 — 黑格尔', time:'18–19 世纪',
    ppl:['康德','黑格尔'],
    char:'远离平衡态的耗散结构——靠吞吐矛盾与熵流维持并升级秩序。',
    mech:'二元悖论从 Bug 翻转为引擎：正题耗散出反题，结构性张力逼迫系统经扬弃自组织跃迁到新层级。',
    form:'二律背反；辩证法；一棵吞噬矛盾、不断自我扩容的动态演化树。',
    lim:'引擎没有刹车：矛盾无阻生成，可能导致系统失控；且它把机制误读成了存在本身（见「结算 · 贰」）。',
    fp:[40,45,55,70] },
  { v:'3.0', era:'现代数理逻辑', time:'1879 – 1936',
    ppl:['弗雷格','罗素','希尔伯特','哥德尔','塔尔斯基','图灵'],
    char:'反身性系统——表达力抵达极致后开始运算自身；分层、递归、元系统嵌套。',
    mech:'自指短路以分层阻断：类型论、对象语言 / 元语言。悖论被位移到更高层级，而非消除。',
    form:'罗素悖论、说谎者振荡、哥德尔不完备、塔尔斯基真值层级、图灵停机。',
    lim:'不存在绝对完备的系统；每个元层级带着新盲点；解悖 = 推迟，塔无穷高。',
    fp:[65,35,70,50] },
  { v:'4.0', era:'多值逻辑 — AI 概率计算', time:'20 世纪中叶至今',
    ppl:['Brouwer','Łukasiewicz','Zadeh','Priest','Pearl 一系'],
    char:'开放、非线性、概率性的复杂适应系统——一个逻辑的生态。',
    mech:'真值连续化 p ∈ [0,1]；在动态环境中拟合与收敛；局部冗余代谢局部矛盾，整体在不完备中持续输出。',
    form:'直觉主义、弗协调、模糊 / 多值、贝叶斯网络、神经网络。',
    lim:'真值不再绝对，解释力依赖模型与数据；有效性彻底环境相对。',
    fp:[25,90,92,88] }
];
const FPL = ['闭合度','开放度','变异度','张力耐受'];

Page({
  data: { stages: STAGES, fpl: FPL, cur: 0, s: STAGES[0] },
  onTab(e) {
    const i = e.currentTarget.dataset.i;
    this.setData({ cur: i, s: STAGES[i] });
    try { wx.vibrateShort({ type: 'light' }); } catch (err) {}
  },
  onSwipe(e) { this.setData({ cur: e.detail.current, s: STAGES[e.detail.current] }); },
  onShareAppMessage() {
    return { title: '逻辑的四份体检报告：1.0 防火墙 → 4.0 自适应生态', path: '/pages/archive/archive' };
  },
  onShareTimeline() { return { title: '版本档案 · 四代系统对照' }; }
});

