// 概念武器库 · 洞察 · 两笔结算 · 诚实的残余
const ARSENAL = [
  { n:'区分 / 再进入', en:'Distinction / Re-entry', by:'G. Spencer-Brown', pos:'序章 · 3.0 危机',
    def:'逻辑的最小动作是划界；当区分重新进入它区分出的空间，产生二值无法消化的「虚值」，在时间中显形为振荡。',
    deep:'说谎者句的真假来回翻转、罗素集、哥德尔「我不可证」、塔尔斯基真谓词——全是再进入事件。Varela 后来用一个自主的第三值把振荡形式化。判词：危机不是内容错了，是几何形状塌了。' },
  { n:'自创生', en:'Autopoiesis', by:'Maturana & Varela', pos:'3.0 · 闭合之梦',
    def:'系统自己生产构成自己的元件、自己为自己奠基、操作上完全闭合。',
    deep:'从 Organon 到 calculemus 到希尔伯特纲领，两千年是同一个梦：让逻辑成为自产自销的自创生系统。坏消息：一旦真的操作闭合、又强到能描述自身，就再也躲不开自指。判词：闭合的完成时，就是崩溃的进行时。' },
  { n:'必要变异度定律', en:'Law of Requisite Variety', by:'W. R. Ashby', pos:'3.0 · 铁律',
    def:'只有变异度能吸收变异度：调节器的变异度必须不小于被控系统。',
    deep:'有限公理系统的变异度有限，而「全部真理 ∋ 关于它自己的真理」变异度更高——控制端永远追不上。谨慎：这是启发性的桥，不是等号；严格定理属于哥德尔、塔尔斯基、图灵。判词：希尔伯特之梦死于必然律，不死于意外。' },
  { n:'盲点 / 二阶控制论', en:'Blind Spot / 2nd-order Cybernetics', by:'H. von Foerster', pos:'3.0 · 尾声',
    def:'每个观察用一个区分看世界，却看不见自己正在用的那个区分——如同眼睛看不见自己的盲点。',
    deep:'「客观性是以为观察可以没有观察者的那种错觉。」1900–1936 的危机，本质是逻辑第一次被迫把观察者放回系统内部。判词：没有无盲点的上帝视角，只有一座观察者观察观察者的塔。' },
  { n:'解悖', en:'Entparadoxierung', by:'N. Luhmann', pos:'3.0 · 分层塔',
    def:'系统奠基于一个悖论，只能把它藏起来、展开、移走——永远不能消除。',
    deep:'类型论、对象语言 / 元语言、亚里士多德「同一时间同一方面」、那句免责脚注「在同一语境下」——全是同一招：把再进入点切开塞进上一层。判词：所有解药都是止痛药，病灶只被推迟。' },
  { n:'耗散结构', en:'Dissipative Structure', by:'I. Prigogine', pos:'2.0 · 引擎',
    def:'远离平衡态的系统靠吞吐熵流维持并升级自身秩序。',
    deep:'黑格尔辩证引擎的物理学近亲：正题耗散出反题，张力驱动扬弃跃迁。区别在于 Luhmann 只让这台引擎在观察系统里转，拒绝装回存在本身（见「结算 · 贰」）。判词：矛盾是燃料，不是故障。' }
];
const INSIGHTS = [
  ['逻辑律是认知的硬约束','不管是理性还是信仰、数学还是艺术，都无法违背四条底层逻辑律——它们是所有认知系统的「操作系统内核」。'],
  ['矛盾是发展的必然动力','任何系统内部都会产生矛盾；处理矛盾的方式，决定了它的发展方向与高度。'],
  ['分层是解决复杂性的唯一途径','从简单到复杂，系统必须通过分层、抽象、元视角来处理自指与无穷回归。'],
  ['开放是高级系统的标志','越高级的系统，越能拥抱不确定性、模糊性与多元性，而不是追求绝对确定。'],
  ['历史是逻辑的展开','过去发生的一切，本质上是逻辑在特定条件下的必然演化，不是偶然的堆积。'],
  ['未来是可推演的','掌握当前系统的状态与矛盾，就能推导它下一步的必然选择与可能形态——推演给出的是相变序列与形态分布，不是事件的时间表。']
];
const NOS = ['①','②','③','④','⑤','⑥'];

Page({
  data: {
    arsenal: ARSENAL.map(a => ({ ...a, open: false })),
    insights: INSIGHTS, nos: NOS
  },
  onCard(e) {
    const i = e.currentTarget.dataset.i;
    const key = 'arsenal[' + i + '].open';
    this.setData({ [key]: !this.data.arsenal[i].open });
    try { wx.vibrateShort({ type: 'light' }); } catch (err) {}
  },
  onShareAppMessage() {
    return { title: '概念武器库：区分、自创生、必要变异度、盲点、解悖、耗散结构', path: '/pages/arsenal/arsenal' };
  },
  onShareTimeline() { return { title: '概念武器库 · 两笔结算' }; }
