// 推演工作台 · 五步法 × 三种文明燃料
const WBSTEPS = ['确定系统边界与原始公理','识别内在矛盾与张力源','分析矛盾的处理机制','推导系统的演化路径','预测未来的发展趋势'];
const DOMAINS = [
  { name:'古希腊理性哲学',
    steps:[
      '论域＝可言说的存在；公理＝逻各斯可把握世界、A=A；环境＝神话叙事与经验流变的高熵输入。',
      '一与多、静与动、连续与离散——公理的静态锁定与经验的流变输入正面冲突；芝诺把冲突推到归谬极限。',
      '分化（自然哲学诸派各执一端）→ 否定（芝诺归谬）→ 分层（可感世界 / 理念世界）→ 整合（亚里士多德：四因说＋三段论收编全域）。',
      '沿右侧链条推演：每一步都是上一步矛盾的必然产物，而非天才的偶然灵感。',
      '事后验证：刚性闭合耗尽变异度后，系统以怀疑与悬置（ἐποχή）自我保护——为 2.0 的矛盾引擎预留了接口。'
    ],
    chain:[
      ['神话解释世界','低级图景 · 混沌初态','init'],['追问本源','充足理由律启动','s1'],
      ['一元本原论','同一律确立','s1'],['芝诺悖论','矛盾律触发','s2'],
      ['理念世界分层','分层架构','s3'],['亚里士多德体系','复杂整合','s3'],
      ['怀疑与悬置','系统自我保护','sp']
    ] },
  { name:'信仰与思想体系',
    steps:[
      '论域＝意义与救赎；公理＝神圣权威不可错；环境＝死亡、苦难与不确定性的持续压力。',
      '启示的绝对性 vs 经验的多样性；文本的同一 vs 解释的分歧——每一次传播都在制造变异。',
      '正统化（同一律：教义定于一尊）→ 排异（异端审判＝矛盾律执法）→ 科层化（教会分层吸收解释权冲突）→ 跃迁（改革与分裂）。',
      '沿右侧链条推演：分层压不住的张力，最终以系统分裂的方式释放。',
      '开放适应：灵性多元化、个体化拟合；权威从中心制转为网络制——与逻辑 4.0 同构。'
    ],
    chain:[
      ['原始敬畏','经验俘获','init'],['神的启示','权威建立 · 划界','s1'],
      ['教义正统化','同一律确立','s1'],['异端冲突','矛盾律触发','s2'],
      ['教会分层体系','组织架构','s3'],['宗教改革 / 分裂','系统跃迁','s2'],
      ['现代灵性多元化','开放适应','s4']
    ] },
  { name:'数学思想',
    steps:[
      '论域＝数与形；公理＝欧几里得 / 皮亚诺；环境＝计数经验与物理直觉。',
      '无穷与有限、连续与离散、可证与为真——表达力每上一个台阶，张力就换一副面孔。',
      '公理化（希尔伯特：终极闭合尝试）→ 自指（集合论悖论）→ 分层（类型论 / ZFC 层级 / 范畴论）→ 外包（机器辅助证明）。',
      '沿右侧链条推演：闭合之梦被变异度铁律击穿——3.0 的完整标本。',
      '推演未来：证明从个体洞见转为人机生态的搜索与验证；真理供给从演绎独占转向概率加权的发现网络——数学正在进入自己的 4.0。'
    ],
    chain:[
      ['算术直觉','具体经验','init'],['公理化体系','形式逻辑闭合','s1'],
      ['集合论基础','自指危机','s3'],['哥德尔不完备','系统盲区','s3'],
      ['类型论 / 范畴论','分层解决','s3'],['计算机科学','复杂适应','s4'],
      ['AI 数学 / 自动化发现','新范式','s4']
    ] }
];

Page({
  data: { wbsteps: WBSTEPS, domains: DOMAINS, di: 0, step: 0, d: DOMAINS[0] },
  onDomain(e) {
    const i = e.currentTarget.dataset.i;
    this.setData({ di: i, step: 0, d: DOMAINS[i] });
    try { wx.vibrateShort({ type: 'light' }); } catch (err) {}
  },
  onStep() {
    if (this.data.step >= 5) return;
    const step = this.data.step + 1;
    this.setData({ step });
    try { wx.vibrateShort({ type: step === 4 ? 'medium' : 'light' }); } catch (err) {}
    if (step === 4) wx.showToast({ title: '链条点亮 · 相变序列显影', icon: 'none' });
  },
  onReset() { this.setData({ step: 0 }); },
  onShareAppMessage() {
    return { title: '五步法推演工作台：同一台方法机，三种文明燃料', path: '/pages/bench/bench' };
  },
  onShareTimeline() { return { title: '推演工作台 · 五步法' }; }
});

