// 认知操作系统 · 演化实验室（七相位状态机 · 小程序原生实现）
const SUP = ['⁰','¹','²','³','⁴'];
const SUB = ['₀','₁','₂','₃','₄','₅'];
const PHM = [
  { k:'void',     no:'序',    name:'划界' },
  { k:'closed',   no:'1.0',   name:'稳态封闭' },
  { k:'dialectic',no:'2.0',   name:'辩证引擎' },
  { k:'reentry',  no:'3.0',   name:'再进入' },
  { k:'tower',    no:'3.0⁺',  name:'分层塔' },
  { k:'ecology',  no:'4.0',   name:'逻辑生态' },
  { k:'mirror',   no:'∞',     name:'镜厅' }
];
const LAWS0 = [
