#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
将 27 案足本 + 韵脚 + 欠账 深度整合进 cavno 现有 app(src_orig.html)。
不新建独立页,而是:
 - 新增「五 · 诊断汇编」章节(原「五 结算」顺延为「六」),复用现有设计令牌
 - 复用现有七相位内核(goPhase):汇编顶部的版本轴脊柱直接驱动〇实验室的活体状态机
 - 双向打通:现有 96 系统 ATLAS 卡片 → 对应足本案(兑现其判词里「完整推演」的承诺);
   足本案 → 回跳 ATLAS 摘要卡片
 - 韵脚(跨案机制)与欠账(自批账本)作为两个全新维度横切全部案例
所有新增 CSS 作用域限定于 #sec-diag,类名统一 dc- 前缀,零冲突。
"""
import json

SRC = '/home/claude/web/src_orig.html'
DATA = '/home/claude/web/data.json'
OUT = '/mnt/user-data/outputs/认知操作系统·逻辑史的系统论重构.html'

# ATLAS 条目名(n) → 足本案号 —— 兑现「完整推演」双向链
NAMEMAP = {
 "物质演化":"01","能量演化":"02","信息演化":"03",
 "基督教":"05","佛教":"06","佛学思想":"06","儒家思想":"07","道家思想":"08","法家思想":"09","哲学进化":"10",
 "中国历代王朝":"11","美国政治文明":"12","新中国政权":"13",
 "现代金融体系":"14","比特币":"15","加密货币":"15","金融微观市场行为":"16","期权系统":"17",
 "数学思想":"18","数学（学科反思）":"18","逻辑学":"19","经济学":"20","管理学":"21","科学":"22",
 "Matrix系统":"23","个体与社会":"25",
}

# ---------------------------------------------------------------------------
CSS = r"""
<style id="dc-styles">
/* ============ 五 · 诊断汇编 —— 作用域限定 #sec-diag ============ */
