#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
将 27 案足本 + 韵脚 + 欠账 深度整合进 cavno 现有 app(src_orig.html)。
不新建独立页,而是:
 - 新增「五 · 诊断汇编」章节(原「五 结算」顺延为「六」),复用现有设计令牌
 - 复用现有七相位内核(goPhase):汇编顶部的版本轴脊柱直接驱动〇实验室的活体状态机
 - 双向打通:现有 96 系统 ATLAS 卡片 → 对应足本案(兑现其判词里「完整推演」的承诺);
   足本案 → 回跳 ATLAS 摘要卡片
 - 韵脚(跨案机制)与欠账(自批账本)作为两个全新维度横切全部案例
所有新增 CSS 作用域限定于 #sec-diag,类名统一 dc- 前缀,零冲突。
"""
import json

SRC = '/home/claude/web/src_orig.html'
DATA = '/home/claude/web/data.json'
OUT = '/mnt/user-data/outputs/认知操作系统·逻辑史的系统论重构.html'

# ATLAS 条目名(n) → 足本案号 —— 兑现「完整推演」双向链
NAMEMAP = {
 "物质演化":"01","能量演化":"02","信息演化":"03",
 "基督教":"05","佛教":"06","佛学思想":"06","儒家思想":"07","道家思想":"08","法家思想":"09","哲学进化":"10",
 "中国历代王朝":"11","美国政治文明":"12","新中国政权":"13",
 "现代金融体系":"14","比特币":"15","加密货币":"15","金融微观市场行为":"16","期权系统":"17",
 "数学思想":"18","数学（学科反思）":"18","逻辑学":"19","经济学":"20","管理学":"21","科学":"22",
 "Matrix系统":"23","个体与社会":"25",
}

# ---------------------------------------------------------------------------
CSS = r"""
<style id="dc-styles">
/* ============ 五 · 诊断汇编 —— 作用域限定 #sec-diag ============ */
#sec-diag .dc-tone-amber{--tc:#7a4a0c;--tb:#F7EDD6;--ts:#B08A2E}
#sec-diag .dc-tone-gray{--tc:#4a463c;--tb:#EFEADD;--ts:#6B6153}
#sec-diag .dc-tone-coral{--tc:#8f3a1c;--tb:#F6E6DD;--ts:#C05B33}
#sec-diag .dc-tone-blue{--tc:#134a80;--tb:#E4EEF7;--ts:#2E6DA4}
#sec-diag .dc-tone-green{--tc:#2b4d12;--tb:#E9F0DC;--ts:#4C6B23}
#sec-diag .dc-tone-purple{--tc:#3f3785;--tb:#ECEAF6;--ts:#5B52A8}

#sec-diag .dc-spinewrap{margin:6px 0 8px}
#sec-diag .dc-spinehint{font-size:12.5px;color:var(--ink2);margin-bottom:10px}
#sec-diag .dc-spinehint b{color:var(--terra)}
#sec-diag .dc-spine{display:flex;gap:8px;align-items:stretch;overflow-x:auto;padding:2px 0 8px}
#sec-diag .dc-gnode{flex:1 1 0;min-width:110px;background:var(--paper2);border:1px solid var(--hair);
  border-top:3px solid var(--ts);border-radius:10px;padding:11px 12px 12px;cursor:pointer;transition:.16s}
#sec-diag .dc-gnode:hover{transform:translateY(-2px);background:var(--tb);box-shadow:0 6px 16px rgba(90,78,56,.14)}
#sec-diag .dc-gnode .dc-gid{font-family:var(--mono,ui-monospace);font-size:17px;font-weight:700;color:var(--ts);line-height:1}
#sec-diag .dc-gnode .dc-gname{font-size:14px;font-weight:700;margin:6px 0 2px;color:var(--ink)}
#sec-diag .dc-gnode .dc-gact{font-size:11px;color:var(--tc)}
#sec-diag .dc-spine .dc-arw{align-self:center;color:var(--ink2);font-size:13px;flex:none;opacity:.6}

#sec-diag .dc-nav{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0 4px;border-bottom:1px solid var(--hair);padding-bottom:12px}
#sec-diag .dc-tab{font-size:14px;padding:7px 16px;border:1px solid var(--hair);border-radius:22px;background:var(--paper2);
  cursor:pointer;color:var(--ink2);transition:.14s;display:flex;align-items:center;gap:7px}
#sec-diag .dc-tab .dc-tk{font-family:var(--mono,ui-monospace);font-size:11px;opacity:.7}
#sec-diag .dc-tab:hover{border-color:var(--teal);color:var(--ink)}
#sec-diag .dc-tab.on{background:var(--teal);color:#F6EFDF;border-color:var(--teal)}
#sec-diag .dc-tab.on .dc-tk{color:#Bfe3d8;opacity:1}

#sec-diag .dc-content{margin-top:18px}
#sec-diag .dc-filters{display:flex;flex-wrap:wrap;gap:7px;margin:2px 0 22px;align-items:center}
#sec-diag .dc-fl{font-size:12px;color:var(--ink2);font-family:var(--mono,ui-monospace);margin-right:2px}
#sec-diag .dc-ftog{font-size:12.5px;padding:4px 12px;border:1px solid var(--hair);border-radius:18px;background:var(--paper2);
  cursor:pointer;color:var(--ink2);transition:.14s}
#sec-diag .dc-ftog:hover{border-color:var(--teal);color:var(--ink)}
#sec-diag .dc-ftog.on{background:var(--teal);color:#F6EFDF;border-color:var(--teal)}

#sec-diag .dc-partblock{margin-bottom:30px}
#sec-diag .dc-ph{display:flex;align-items:baseline;gap:11px;border-bottom:2px solid var(--teal);padding-bottom:6px;margin-bottom:14px}
#sec-diag .dc-ph .dc-pr{font-family:var(--mono,ui-monospace);font-size:14px;font-weight:700;color:var(--terra)}
#sec-diag .dc-ph .dc-pn{font-size:18px;font-weight:700;color:var(--teal-deep)}
#sec-diag .dc-ph .dc-psub{font-size:12px;color:var(--ink2);margin-left:auto}
#sec-diag .dc-partintro{font-size:13.5px;color:var(--ink2);line-height:1.7;margin:-6px 0 16px}
#sec-diag .dc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}
#sec-diag .dc-ccard{background:var(--paper2);border:1px solid var(--hair);border-radius:11px;padding:15px 16px;
  cursor:pointer;transition:.16s;position:relative;overflow:hidden;display:flex;flex-direction:column}
#sec-diag .dc-ccard::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--ts);opacity:.9}
#sec-diag .dc-ccard:hover{transform:translateY(-3px);box-shadow:0 9px 22px rgba(90,78,56,.16);border-color:var(--ts)}
#sec-diag .dc-ccard .dc-ch{display:flex;align-items:baseline;gap:8px;margin-bottom:6px}
#sec-diag .dc-ccard .dc-cn{font-family:var(--mono,ui-monospace);font-size:13.5px;font-weight:700;color:var(--terra)}
#sec-diag .dc-ccard .dc-ct{font-size:16px;font-weight:700;line-height:1.32;color:var(--ink)}
#sec-diag .dc-ccard .dc-cp{font-size:12.5px;color:var(--ink);margin:2px 0 8px;padding:5px 0;
  border-top:1px dotted var(--hair);border-bottom:1px dotted var(--hair)}
#sec-diag .dc-ccard .dc-cp .dc-plab{font-family:var(--mono,ui-monospace);font-size:10px;color:var(--ink2);margin-right:6px}
#sec-diag .dc-ccard .dc-cv{font-size:12px;color:var(--ink2);line-height:1.55;flex:1}
#sec-diag .dc-ccard .dc-cf{display:flex;align-items:center;gap:6px;margin-top:10px;flex-wrap:wrap}
#sec-diag .dc-ccard .dc-rc{font-family:var(--mono,ui-monospace);font-size:10px;color:#6a5fa8}

#sec-diag .dc-gbadge{display:inline-flex;align-items:center;font-family:var(--mono,ui-monospace);font-size:10.5px;font-weight:700;
  color:var(--tc);background:var(--tb);border:1px solid var(--ts);border-radius:5px;padding:2px 7px;white-space:nowrap}
#sec-diag .dc-tbadge{display:inline-flex;align-items:center;font-size:11px;color:var(--ink2);background:rgba(0,0,0,.04);
  border:1px solid var(--hair);border-radius:5px;padding:2px 7px;white-space:nowrap}
#sec-diag .dc-chip{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;border:1px solid var(--hair);
  background:var(--paper2);border-radius:18px;padding:3px 12px 3px 10px;cursor:pointer;transition:.14s;color:var(--ink)}
#sec-diag .dc-chip:hover{border-color:var(--teal);background:#E7F1EE}
#sec-diag .dc-chip .dc-cno{font-family:var(--mono,ui-monospace);font-size:11px;color:var(--terra);font-weight:700}
#sec-diag .dc-chip.dc-m{border-color:#d6cde6;background:#f0ecf8}
#sec-diag .dc-chip.dc-m:hover{border-color:#5B52A8;background:#e9e3f5}
#sec-diag .dc-chip.dc-m .dc-cco{font-family:var(--mono,ui-monospace);font-size:11px;color:#5B52A8;font-weight:700}
#sec-diag .dc-chip.dc-d{border-color:#e5cfc3;background:#f6e9e2}
#sec-diag .dc-chip.dc-d:hover{border-color:var(--terra);background:#f2ddd2}

#sec-diag .dc-motif{background:var(--paper2);border:1px solid var(--hair);border-radius:11px;padding:18px 20px;
  margin-bottom:13px;border-left:4px solid #6a5fa8}
#sec-diag .dc-motif.dc-pulse{animation:dcPulse 1.4s ease}
@keyframes dcPulse{0%{box-shadow:0 0 0 0 rgba(106,95,168,.35)}45%{box-shadow:0 0 0 8px rgba(106,95,168,0)}100%{box-shadow:0 0 0 0 rgba(106,95,168,0)}}
#sec-diag .dc-motif .dc-mh{display:flex;align-items:baseline;gap:11px;margin-bottom:8px;flex-wrap:wrap}
#sec-diag .dc-motif .dc-mc{font-family:var(--mono,ui-monospace);font-size:13px;font-weight:700;color:#5B52A8;
  background:#ece7f7;border:1px solid #d6cde6;border-radius:5px;padding:1px 8px}
#sec-diag .dc-motif .dc-mn{font-size:17px;font-weight:700;color:var(--ink)}
#sec-diag .dc-motif .dc-mcount{font-family:var(--mono,ui-monospace);font-size:11px;color:var(--ink2);margin-left:auto}
#sec-diag .dc-motif .dc-md{font-size:14px;color:var(--ink);margin:0 0 12px;line-height:1.7}
#sec-diag .dc-motif .dc-mcases{display:flex;flex-wrap:wrap;gap:7px}
#sec-diag .dc-univ{font-family:var(--mono,ui-monospace);font-size:12px;color:var(--teal-deep);background:#E7F1EE;
  border:1px solid #bfd8d0;border-radius:18px;padding:4px 13px;display:inline-block}

#sec-diag .dc-debt{background:var(--paper2);border:1px solid var(--hair);border-radius:11px;padding:16px 20px;
  margin-bottom:12px;border-left:4px solid var(--terra)}
#sec-diag .dc-debt.dc-pulse2{animation:dcPulse2 1.4s ease}
@keyframes dcPulse2{0%{box-shadow:0 0 0 0 rgba(192,91,51,.35)}45%{box-shadow:0 0 0 8px rgba(192,91,51,0)}100%{box-shadow:0 0 0 0 rgba(192,91,51,0)}}
#sec-diag .dc-debt .dc-dh{display:flex;align-items:baseline;gap:10px;margin-bottom:6px;flex-wrap:wrap}
#sec-diag .dc-debt .dc-dnum{font-family:var(--mono,ui-monospace);font-size:12px;color:var(--ink2)}
#sec-diag .dc-debt .dc-dn{font-size:16px;font-weight:700;color:var(--ink)}
#sec-diag .dc-debt .dc-dstat{font-family:var(--mono,ui-monospace);font-size:10.5px;padding:1px 9px;border-radius:16px;border:1px solid;margin-left:auto}
#sec-diag .dc-s-jq{color:#2b4d12;background:#E9F0DC;border-color:#4C6B23}
#sec-diag .dc-s-zz{color:#8f3a1c;background:#F6E6DD;border-color:#C05B33}
#sec-diag .dc-s-zj{color:#3f3785;background:#ECEAF6;border-color:#5B52A8}
#sec-diag .dc-debt .dc-dnote{font-size:13.5px;color:var(--ink);margin:0 0 11px;line-height:1.68}
#sec-diag .dc-debt .dc-dcases{display:flex;flex-wrap:wrap;gap:7px;align-items:center}
#sec-diag .dc-debt .dc-dcases .dc-lab,#sec-diag .dc-motif .dc-lab{font-size:12px;color:var(--ink2);margin-right:2px}

/* 案详情 */
#sec-diag .dc-back{font-family:var(--mono,ui-monospace);font-size:13px;color:var(--teal-deep);cursor:pointer;
  display:inline-flex;align-items:center;gap:6px;margin-bottom:16px}
#sec-diag .dc-back:hover{color:var(--teal)}
#sec-diag .dc-casehead{border-bottom:2px solid var(--teal);padding-bottom:14px;margin-bottom:6px}
#sec-diag .dc-cbread{font-family:var(--mono,ui-monospace);font-size:12px;color:var(--terra);letter-spacing:.06em;margin-bottom:7px}
#sec-diag .dc-casehead h1{font-size:clamp(24px,4vw,34px);font-weight:800;margin:0 0 12px;line-height:1.14;color:var(--ink)}
#sec-diag .dc-cmeta{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
#sec-diag .dc-paradox{display:flex;align-items:baseline;gap:10px;background:var(--paper3);border:1px solid var(--hair);
  border-left:4px solid var(--gold);border-radius:9px;padding:11px 17px;margin:15px 0}
#sec-diag .dc-paradox .dc-plab{font-family:var(--mono,ui-monospace);font-size:11px;color:#7a5c15;letter-spacing:.08em;flex:none}
#sec-diag .dc-paradox .dc-pval{font-size:15.5px;font-weight:600;color:var(--ink)}
#sec-diag .dc-cross{background:var(--paper2);border:1px solid var(--hair);border-radius:10px;padding:14px 17px;margin:15px 0 8px}
#sec-diag .dc-cross .dc-cl-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
#sec-diag .dc-cross .dc-cl-row+.dc-cl-row{margin-top:9px}
#sec-diag .dc-cross .dc-cl-lab{font-family:var(--mono,ui-monospace);font-size:11px;color:var(--ink2);flex:none;width:76px}

#sec-diag .dc-body{padding-top:10px}
#sec-diag .dc-body .dc-lbl{font-family:var(--mono,ui-monospace);font-size:12px;font-weight:700;letter-spacing:.06em;
  margin:28px 0 11px;padding-bottom:5px;border-bottom:1px solid var(--hair);display:flex;align-items:center;gap:8px}
#sec-diag .dc-body .dc-lbl::before{content:"■";font-size:9px}
#sec-diag .dc-body .dc-lbl-verdict{color:var(--teal-deep)}
#sec-diag .dc-body .dc-lbl-diag{color:var(--terra)}
#sec-diag .dc-body .dc-lbl-struct{color:#2E6DA4}
#sec-diag .dc-body .dc-lbl-ledger{color:#7a5c15}
#sec-diag .dc-body .dc-lbl-residue{color:var(--terra)}
#sec-diag .dc-body p{margin:0 0 .78em;font-size:16px;line-height:1.86;text-align:justify;color:var(--ink)}
#sec-diag .dc-body p strong{font-weight:700;color:var(--ink)}
#sec-diag .dc-body p.dc-res{color:#5a4a3a}
#sec-diag .dc-body hr{border:none;border-top:1px solid var(--hair);margin:1.25em 0 1.05em}
#sec-diag .dc-body .dc-fig{margin:20px auto;text-align:center}
#sec-diag .dc-body .dc-fig svg{max-width:100%;height:auto;background:var(--paper2);border:1px solid var(--hair);border-radius:9px;padding:10px}
#sec-diag .dc-body .dc-fig figcaption{font-family:var(--mono,ui-monospace);font-size:11px;color:var(--ink2);margin-top:8px}
#sec-diag .dc-residue-band{background:#F6E9E2;border:1px solid #e5cfc3;border-left:4px solid var(--terra);border-radius:10px;
  padding:2px 18px 8px;margin:20px 0}
#sec-diag .dc-casenav{display:flex;justify-content:space-between;gap:12px;margin-top:32px;border-top:1px solid var(--hair);padding-top:18px}
#sec-diag .dc-casenav a{font-size:14px;color:var(--teal-deep);cursor:pointer;max-width:46%}
#sec-diag .dc-casenav a .dc-d{font-family:var(--mono,ui-monospace);font-size:11px;color:var(--ink2);display:block}
#sec-diag .dc-casenav a.dc-nx{text-align:right;margin-left:auto}
#sec-diag .dc-atlaslink{margin:6px 0 2px}
#sec-diag .dc-atlaslink button{font-size:13px}
@media(max-width:720px){#sec-diag .dc-gnode{min-width:98px}#sec-diag .dc-casehead h1{font-size:24px}}
</style>
"""

# ---------------------------------------------------------------------------
SECTION = """
<!-- ================= 五 诊断汇编 ================= -->
<section class="sec wrap" id="sec-diag">
  <div class="sechead"><span class="idx">五</span><h2>诊断汇编 · 二十六案 ＋ 一问</h2><span class="en">DIAGNOSTIC COMPENDIUM</span></div>
  <p class="seclead">把前面那台方法机，逐案实操二十六次的<b>足本档案</b>——每案含判词、四代诊断图、独门结构图与诚实的残余全文（原文一字未改）。它不是平铺的案例列表：顶部<b>版本轴</b>与〇实验室共用同一套七相位内核，点节点即回到实验室复演；每个已在<b>二·工作台</b>登记过的系统，其摘要卡片与此处足本互为表里——正是那些判词里反复承诺的「完整推演」。而<b>韵脚</b>与<b>欠账</b>两栏，横切全部案例，把内核最深的两件事亮出来：同一机制如何跨越不相干的系统复现，以及框架在哪里持续失血。</p>

  <div class="dc-spinewrap">
    <div class="dc-spinehint">版本轴 · 与〇实验室联动：轴上四个大版本是处理矛盾的四种策略，两端是两个边界条件。点任一节点，<b>回到实验室以该相位复演</b>。</div>
    <div class="dc-spine" id="dc-spine"></div>
  </div>

  <div class="dc-nav" id="dc-nav"></div>
  <div class="dc-content" id="dc-content"></div>
</section>
"""

# ---------------------------------------------------------------------------
JS = r"""
<script>
/* ============ 五 · 诊断汇编 —— 深度整合层 ============ */
(function(){
  const DC = __DC_DATA__;
  const NM = __DC_NAMEMAP__;
  window.DC_CASE_BY_NAME = NM;               // 供现有 renderAtlas 挂足本按钮
  const CASE={}; DC.cases.forEach(c=>CASE[c.no]=c);
  const MOTIF={}; DC.motifs.forEach(m=>MOTIF[m.code]=m);
  const GEN={}; DC.generations.forEach(g=>GEN[g.id]=g);
  const NOS=DC.cases.map(c=>c.no);
  const toneOf=g=>(GEN[g]&&GEN[g].tone)||({'双轨':'coral','共时':'blue','序':'amber','元':'purple'}[g])||'green';
  const cont=()=>document.getElementById('dc-content');
  let dcView={mode:'cases',part:'all'};

  /* 相位轴 → 实验室 goPhase 联动 */
  const PHASE_OF={'序':'void','1.0':'closed','2.0':'dialectic','3.0':'reentry','4.0':'ecology','∞':'mirror'};
  function renderSpine(){
    const el=document.getElementById('dc-spine'); if(!el) return;
    let h='';
    DC.generations.forEach((n,i)=>{
      h+='<div class="dc-gnode dc-tone-'+n.tone+'" data-ph="'+(PHASE_OF[n.id]||'')+'">'
        +'<div class="dc-gid">'+n.label+'</div><div class="dc-gname">'+esc(n.name)+'</div>'
        +'<div class="dc-gact">'+esc(n.action)+'</div></div>';
      if(i<DC.generations.length-1) h+='<span class="dc-arw">→</span>';
    });
    el.innerHTML=h;
    el.querySelectorAll('.dc-gnode').forEach(nd=>nd.addEventListener('click',()=>{
      const ph=nd.dataset.ph;
      if(ph && typeof goPhase==='function'){ goPhase(ph);
        var lab=document.getElementById('sec-lab'); if(lab) lab.scrollIntoView({behavior:'smooth'}); }
    }));
  }

  /* 徽章与 chip */
  function genBadge(g){
    const label=g==='双轨'?'双轨 · 4.0∥1.0':g==='共时'?'四代共时':g==='元'?'元 · 轴外':g;
    return '<span class="dc-gbadge dc-tone-'+toneOf(g)+'">代际 '+label+'</span>';
  }
  const topoBadge=t=>'<span class="dc-tbadge">拓扑 '+esc(t)+'</span>';
  function caseChip(no){const c=CASE[no];if(!c)return '';
    return '<span class="dc-chip dc-tone-'+toneOf(c.gen)+'" data-case="'+no+'"><span class="dc-cno">'+no+'</span>'+esc(c.title)+'</span>';}
  function motifChip(code){const m=MOTIF[code];if(!m)return '';
    return '<span class="dc-chip dc-m" data-motif="'+code+'"><span class="dc-cco">'+code+'</span>'+esc(m.name)+'</span>';}
  function debtChip(name){const i=DC.debts.findIndex(d=>d.name===name);
    return '<span class="dc-chip dc-d" data-debt="'+i+'">'+esc(name)+'</span>';}

  /* 子导航 */
  function renderNav(){
    const el=document.getElementById('dc-nav'); if(!el) return;
    const tabs=[['cases','▦','案谱'],['motifs','≈','韵脚'],['debts','⚖','欠账']];
    el.innerHTML=tabs.map(t=>'<span class="dc-tab'+(dcView.mode===t[0]?' on':'')+'" data-tab="'+t[0]+'">'
      +'<span class="dc-tk">'+t[1]+'</span>'+t[2]+'</span>').join('');
    el.querySelectorAll('.dc-tab').forEach(tb=>tb.addEventListener('click',()=>{
      const m=tb.dataset.tab;
      if(m==='cases')renderCases(dcView.part);else if(m==='motifs')renderMotifs();else renderDebts();
    }));
  }

  /* 案谱 */
  function renderCases(part){
    dcView={mode:'cases',part:part||'all'}; renderNav();
    let f='<div class="dc-filters"><span class="dc-fl">编</span>';
    f+='<span class="dc-ftog'+(dcView.part==='all'?' on':'')+'" data-part="all">全部</span>';
    DC.parts.forEach(p=>{f+='<span class="dc-ftog'+(dcView.part===p.roman?' on':'')+'" data-part="'+p.roman+'">'+p.roman+' '+esc(p.name)+'</span>';});
    f+='</div>';
    let body='';
    DC.parts.forEach(p=>{
      if(dcView.part!=='all'&&dcView.part!==p.roman)return;
      body+='<div class="dc-partblock"><div class="dc-ph"><span class="dc-pr">'+p.roman+'</span><span class="dc-pn">'+esc(p.name)+'</span><span class="dc-psub">'+esc(p.sub)+'</span></div>';
      if(dcView.part!=='all')body+='<div class="dc-partintro">'+esc(p.intro)+'</div>';
      body+='<div class="dc-grid">';
      p.nos.forEach(no=>{const c=CASE[no];const rc=c.motifs.length?'<span class="dc-rc">≈'+c.motifs.length+'</span>':'';
        body+='<div class="dc-ccard dc-tone-'+toneOf(c.gen)+'" data-case="'+no+'">'
          +'<div class="dc-ch"><span class="dc-cn">'+no+'</span><span class="dc-ct">'+esc(c.title)+'</span></div>'
          +'<div class="dc-cp"><span class="dc-plab">母悖论</span>'+esc(c.paradox)+'</div>'
          +'<div class="dc-cv">'+esc(c.verdict)+'</div>'
          +'<div class="dc-cf">'+genBadge(c.gen)+' '+topoBadge(c.topo)+' '+rc+'</div></div>';
      });
      body+='</div></div>';
    });
    cont().innerHTML=f+body;
    cont().querySelectorAll('.dc-ftog').forEach(el=>el.addEventListener('click',()=>renderCases(el.dataset.part)));
  }

  /* 韵脚 */
  function renderMotifs(focus){
    dcView={mode:'motifs'}; renderNav();
    let intro='<div class="dc-partintro" style="margin:0 0 18px">同一个结构性动作，在毫不相干的领域里反复现身——迦克墩的四否定、弗协调逻辑、Neo 让 Smith 覆写自己，是同一手「圣化围堵」。这种跨案复现是本系列最主要的发现方式，也是「万能溶剂」嫌疑的证据来源。点任一案跳转。</div>';
    let body='';
    DC.motifs.forEach(m=>{
      const cases=m.universal?'<span class="dc-univ">贯穿全部 '+DC.cases.length+' 案 · 每一案的同一枚落款</span>':m.cases.map(caseChip).join('');
      const cnt=m.universal?'全案':(m.cases.length+' 案');
      body+='<div class="dc-motif" id="dc-m-'+m.code+'"><div class="dc-mh"><span class="dc-mc">'+m.code+'</span><span class="dc-mn">'+esc(m.name)+'</span><span class="dc-mcount">现身 '+cnt+'</span></div>'
        +'<p class="dc-md">'+esc(m.desc)+'</p><div class="dc-mcases">'+cases+'</div></div>';
    });
    cont().innerHTML=intro+body;
    if(focus){const e=document.getElementById('dc-m-'+focus);if(e){e.scrollIntoView({behavior:'smooth',block:'center'});e.classList.add('dc-pulse');setTimeout(()=>e.classList.remove('dc-pulse'),1500);}}
  }

  /* 欠账 */
  function renderDebts(focus){
    dcView={mode:'debts'}; renderNav();
    let intro='<div class="dc-partintro" style="margin:0 0 18px">每条都是框架在某案上被对象顶回来的具体裂缝——不是谦辞，是可被后续工作接手的账目。清单只增不减；一条被结清即标状态。走到第十九案结论已清楚：这台框架最好的用法不是解释一切，是当一块磨刀石。</div>';
    const smap={'结清':'dc-s-jq','最重':'dc-s-zz','自指':'dc-s-zj'};
    let body='';
    DC.debts.forEach((d,i)=>{const stat=d.status?'<span class="dc-dstat '+(smap[d.status.replace('已','')]||'')+'">'+d.status+'</span>':'';
      body+='<div class="dc-debt" id="dc-d-'+i+'"><div class="dc-dh"><span class="dc-dnum">#'+String(i+1).padStart(2,'0')+'</span><span class="dc-dn">'+esc(d.name)+'</span>'+stat+'</div>'
        +'<p class="dc-dnote">'+esc(d.note)+'</p><div class="dc-dcases"><span class="dc-lab">立案于</span>'+d.cases.map(caseChip).join('')+'</div></div>';
    });
    cont().innerHTML=intro+body;
    if(focus!=null){const e=document.getElementById('dc-d-'+focus);if(e){e.scrollIntoView({behavior:'smooth',block:'center'});e.classList.add('dc-pulse2');setTimeout(()=>e.classList.remove('dc-pulse2'),1500);}}
  }

  /* 回跳现有 ATLAS 摘要卡片 */
  function atlasOpen(no){
    if(typeof ATLAS==='undefined'||typeof renderWB!=='function')return;
    let name=null; for(const k in NM){if(NM[k]===no){name=k;break;}}
    if(!name)return;
    const sy=ATLAS.find(x=>x.n===name); if(!sy)return;
    const cat=sy.c, catI=ACATS.indexOf(cat);
    const list=ATLAS.filter(x=>x.c===cat); const sysI=list.indexOf(sy);
    if(catI<0||sysI<0)return;
    wbMode='atlas'; aC=catI; aS=sysI; renderWB();
    var wb=document.getElementById('sec-wb'); if(wb) wb.scrollIntoView({behavior:'smooth'});
  }
  const hasAtlas=no=>{for(const k in NM){if(NM[k]===no)return true;}return false;};

  /* 案详情 */
  function openCase(no){
    const c=CASE[no]; if(!c)return;
    dcView={mode:'case',no:no};
    const idx=NOS.indexOf(no), prev=idx>0?CASE[NOS[idx-1]]:null, next=idx<NOS.length-1?CASE[NOS[idx+1]]:null;
    const motifRow=c.motifs.length?'<div class="dc-cl-row"><span class="dc-cl-lab">≈ 韵脚</span>'+c.motifs.map(motifChip).join('')+'</div>':'';
    const debtRow=c.debts.length?'<div class="dc-cl-row"><span class="dc-cl-lab">⚖ 欠账</span>'+c.debts.map(debtChip).join('')+'</div>':'';
    const cross=(motifRow||debtRow)?'<div class="dc-cross">'+motifRow+debtRow+'</div>':'';
    const atlasBtn=hasAtlas(no)?'<div class="dc-atlaslink"><button class="wbtn ghost" data-atlas="'+no+'">▸ 在二·工作台查看该系统的摘要卡片（代际诊断）</button></div>':'';
    cont().innerHTML='<div class="dc-tone-'+toneOf(c.gen)+'">'
      +'<span class="dc-back" data-back="1">◂ 返回案谱</span>'
      +'<div class="dc-casehead"><div class="dc-cbread">'+c.partRoman+' · '+esc(c.partName)+'　/　第 '+no+' 案</div>'
      +'<h1>'+esc(c.title)+'</h1><div class="dc-cmeta">'+genBadge(c.gen)+' '+topoBadge(c.topo)+'</div></div>'
      +'<div class="dc-paradox"><span class="dc-plab">母悖论</span><span class="dc-pval">'+esc(c.paradox)+'</span></div>'
      +cross+atlasBtn
      +'<div class="dc-body">'+c.html+'</div>'
      +'<div class="dc-casenav">'
      +(prev?'<a data-case="'+prev.no+'"><span class="dc-d">◂ 第 '+prev.no+' 案</span>'+esc(prev.title)+'</a>':'<span></span>')
      +(next?'<a class="dc-nx" data-case="'+next.no+'"><span class="dc-d">第 '+next.no+' 案 ▸</span>'+esc(next.title)+'</a>':'')
      +'</div></div>';
    bandResidue();
    var sec=document.getElementById('sec-diag'); if(sec) sec.scrollIntoView({behavior:'smooth'});
  }
  window.dcOpenCase=openCase;   // 供现有 ATLAS 卡片的足本按钮调用

  function bandResidue(){
    const body=cont().querySelector('.dc-body'); if(!body)return;
    const kids=[...body.children];
    const h=kids.find(el=>el.classList&&el.classList.contains('dc-lbl-residue'));
    if(!h)return;
    const band=document.createElement('div'); band.className='dc-residue-band';
    h.parentNode.insertBefore(band,h);
    let el=h; const grab=[]; while(el){grab.push(el);el=el.nextElementSibling;}
    grab.forEach(k=>band.appendChild(k));
  }

  /* 事件委托 */
  document.getElementById('sec-diag').addEventListener('click',e=>{
    const t=e.target.closest('[data-case],[data-motif],[data-debt],[data-back],[data-atlas]'); if(!t)return;
    if(t.dataset.back!=null){renderCases(dcView.part||'all');return;}
    if(t.dataset.atlas!=null){atlasOpen(t.dataset.atlas);return;}
    if(t.dataset.case!=null){openCase(t.dataset.case);return;}
    if(t.dataset.motif!=null){renderMotifs(t.dataset.motif);return;}
    if(t.dataset.debt!=null){renderDebts(+t.dataset.debt);return;}
  });

  renderSpine(); renderNav(); renderCases('all');
})();
</script>
"""

# ---------------------------------------------------------------------------
def main():
    src = open(SRC, encoding='utf-8').read()
    data = open(DATA, encoding='utf-8').read()
    safe = data.replace('</', '<\\/')  # embed-safe inside <script>

    js = JS.replace('__DC_DATA__', safe).replace('__DC_NAMEMAP__', json.dumps(NAMEMAP, ensure_ascii=False))

    # 1) CSS before </head>
    assert '</head>' in src
    src = src.replace('</head>', CSS + '\n</head>', 1)

    # 2) new section before 五 结算; renumber 五→六
    anchor = '<!-- ================= 五 结算 ================= -->'
    assert anchor in src, 'settlement anchor not found'
    src = src.replace(anchor, SECTION + '\n' + anchor, 1)
    old_head = '<div class="sechead"><span class="idx">五</span><h2>两笔结算</h2>'
    new_head = '<div class="sechead"><span class="idx">六</span><h2>两笔结算</h2>'
    assert old_head in src
    src = src.replace(old_head, new_head, 1)

    # 3) ATLAS → 足本案 hook (inside renderAtlas)
    hook_anchor = "const r=H('button','wbtn ghost','↩ 回精推域',bt);"
    assert hook_anchor in src, 'atlas hook anchor not found'
    hook = ("if(window.DC_CASE_BY_NAME&&DC_CASE_BY_NAME[sy.n]!=null){var _dcc=DC_CASE_BY_NAME[sy.n];"
            "var _gg=H('button','wbtn','\\u25b8 \\u6253\\u5f00\\u8db3\\u672c\\u8bca\\u65ad\\uff1a\\u7b2c '+_dcc+' \\u6848',bt);"
            "_gg.onclick=()=>dcOpenCase(_dcc);}\n  ")
    src = src.replace(hook_anchor, hook + hook_anchor, 1)

    # 4) JS before final </script>
    i = src.rfind('</script>')
    assert i != -1
    src = src[:i] + js + '\n' + src[i:]

    open(OUT, 'w', encoding='utf-8').write(src)
    print('written:', OUT, len(src), 'bytes')
    # quick sanity
    print('sec-diag inserted:', 'id="sec-diag"' in src)
    print('settlement renumbered 六:', new_head in src)
    print('atlas hook inserted:', 'dcOpenCase(_dcc)' in src)
    print('DC_DATA embedded:', 'window.DC_CASE_BY_NAME' in src)
    print('</script> in embedded data?', '</script' in safe)

if __name__ == '__main__':
    main()

