#!/usr/bin/env python3
"""把关键帧和文稿沿时间轴对齐，产出单文件 HTML 和 Markdown。

关键帧的时间点就是章节锚点：每一页幻灯片管辖到下一页出现为止，
文稿按这个区间切段。这样「课件」和「文稿」不是两份东西，而是同一条时间轴的两个投影。

视频本身不嵌进 HTML（几百 MB 到几 GB，嵌了就没法用了）。
改成让用户在页面里选中本地视频文件，用 createObjectURL 绑给 <video>——
单文件依然可以随便拷贝，播放同步也照样能用，视频不出本机。

用法:
    python3 build.py OUTDIR [--title "课程名"] [--out courseware.html]
"""
import argparse
import base64
import html
import json
import re
from pathlib import Path

SENT_END = re.compile(r"[。！？!?；;]\s*")


def fmt_ts(s: float) -> str:
    s = int(round(s))
    h, r = divmod(s, 3600)
    m, sec = divmod(r, 60)
    return f"{h}:{m:02d}:{sec:02d}" if h else f"{m}:{sec:02d}"


def align(keyframes, segments):
    """按中点归属。不切分 ASR 句子——句子边界本来就带误差，
    强行按秒切会把一句话劈成两半，读起来比归错档更糟。"""
    if not keyframes:
        return [{"index": 1, "t_start": 0, "t_end": 10 ** 9, "file": None,
                 "text": "", "revisits": [], "segments": segments}]
    bounds = [k["t_start"] for k in keyframes]
    sections = [dict(k, segments=[]) for k in keyframes]
    for seg in segments:
        mid = (seg["start"] + seg["end"]) / 2 if seg["end"] > seg["start"] else seg["start"]
        i = 0
        for j, b in enumerate(bounds):
            if mid >= b:
                i = j
            else:
                break
        sections[i]["segments"].append(seg)
    return sections


def section_title(sec) -> str:
    """用 OCR 到的首行当标题——它通常就是幻灯片标题。
    识别为空时退回时间戳，不编造。"""
    txt = (sec.get("text") or "").strip()
    if txt:
        first = re.split(r"[\n·•]", txt)[0].strip()
        first = re.sub(r"\s+", " ", first)
        if 1 < len(first) <= 40:
            return first
    return f"片段 {fmt_ts(sec['t_start'])}"


def to_markdown(meta, sections):
    L = [f"# {meta['title']}", ""]
    L.append(f"> 源文件 `{Path(meta['source']).name}` · "
             f"{len(sections)} 个片段 · 时长 {fmt_ts(meta['duration'])}")
    L.append("")
    for s in sections:
        L.append(f"## {fmt_ts(s['t_start'])} {section_title(s)}")
        L.append("")
        if s.get("file"):
            L.append(f"![{section_title(s)}]({s['file']})")
            L.append("")
        if s.get("revisits"):
            r = "、".join(f"{fmt_ts(v['t_start'])}" for v in s["revisits"])
            L.append(f"*讲者在 {r} 处回看了这一页*")
            L.append("")
        body = "".join(seg["text"] for seg in s["segments"]).strip()
        if body:
            for para in SENT_END.split(body):
                if para.strip():
                    L.append(para.strip() + "。")
            L.append("")
    return "\n".join(L)


def b64_img(path: Path) -> str:
    return "data:image/jpeg;base64," + base64.b64encode(path.read_bytes()).decode()


TEMPLATE = r"""<!DOCTYPE html>
<html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>__TITLE__</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;600&display=swap');
:root{
  --parchment:#F3EAD3; --parchment-2:#EDE2C6; --ink:#2B2A26; --ink-soft:#5C5852;
  --teal:#2A6F73; --teal-soft:#E1EBEA; --terracotta:#B4553A; --rule:#D8C9A6;
}
*{box-sizing:border-box}
body{margin:0;background:var(--parchment);color:var(--ink);
  font-family:"Noto Serif SC",Georgia,serif;line-height:1.75;font-weight:300}
header{padding:26px 34px 18px;border-bottom:1px solid var(--rule)}
h1{margin:0 0 6px;font-size:26px;font-weight:600;letter-spacing:.02em}
.meta{color:var(--ink-soft);font-size:13px}
.meta b{color:var(--teal);font-weight:600}
.bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;
  padding:12px 34px;border-bottom:1px solid var(--rule);background:var(--parchment-2)}
button,label.fake{font-family:inherit;font-size:13px;padding:6px 14px;cursor:pointer;
  border:1px solid var(--rule);background:var(--parchment);color:var(--ink);border-radius:2px}
button:hover,label.fake:hover{background:var(--teal);color:#fff;border-color:var(--teal)}
button.on{background:var(--teal);color:#fff;border-color:var(--teal)}
input[type=search]{font-family:inherit;font-size:13px;padding:6px 12px;flex:1;min-width:180px;
  border:1px solid var(--rule);background:var(--parchment);color:var(--ink);border-radius:2px}
#vidwrap{display:none;padding:14px 34px 0}
#vidwrap.on{display:block}
video{width:100%;max-height:46vh;background:#000;border:1px solid var(--rule)}
main{display:grid;grid-template-columns:290px 1fr;gap:0;align-items:start}
#rail{border-right:1px solid var(--rule);padding:16px 14px;position:sticky;top:0;
  max-height:100vh;overflow-y:auto}
.thumb{display:block;width:100%;margin-bottom:14px;cursor:pointer;
  border:1px solid var(--rule);background:var(--parchment-2);padding:6px;border-radius:2px}
.thumb.active{border-color:var(--terracotta);box-shadow:0 0 0 2px rgba(180,85,58,.18)}
.thumb img{width:100%;display:block;border:1px solid var(--rule)}
.thumb .cap{font-size:11px;color:var(--ink-soft);margin-top:5px;display:flex;
  justify-content:space-between;gap:6px}
.thumb .cap b{color:var(--teal);font-weight:600}
#doc{padding:20px 34px 120px;max-width:820px}
section{margin-bottom:34px;scroll-margin-top:16px}
section.hide{display:none}
h2{font-size:19px;font-weight:600;margin:0 0 4px;
  border-left:3px solid var(--terracotta);padding-left:10px}
.stamp{color:var(--teal);font-size:12px;cursor:pointer;font-variant-numeric:tabular-nums}
.stamp:hover{text-decoration:underline}
.revisit{font-size:12px;color:var(--terracotta);margin:4px 0 0}
.slide{margin:12px 0;border:1px solid var(--rule);cursor:zoom-in;max-width:100%}
.slide.zoom{position:fixed;inset:4vh 4vw;z-index:50;max-width:92vw;max-height:92vh;
  object-fit:contain;background:#000;cursor:zoom-out;box-shadow:0 8px 40px rgba(0,0,0,.5)}
p.line{margin:.4em 0}
p.line .t{color:var(--teal);font-size:11px;margin-right:8px;cursor:pointer;
  font-variant-numeric:tabular-nums;opacity:.65}
p.line.playing{background:var(--teal-soft);border-radius:2px}
mark{background:#F0D9A8;color:inherit}
.ocr{font-size:12px;color:var(--ink-soft);background:var(--parchment-2);
  border:1px dashed var(--rule);padding:8px 10px;margin:8px 0;white-space:pre-wrap;display:none}
.ocr.on{display:block}
@media(max-width:860px){main{grid-template-columns:1fr}
  #rail{position:static;max-height:none;border-right:0;border-bottom:1px solid var(--rule);
    display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}
  .thumb{margin-bottom:0}}
</style></head><body>
<header>
  <h1>__TITLE__</h1>
  <div class="meta">__META__</div>
</header>
<div class="bar">
  <label class="fake">载入本地视频<input type="file" accept="video/*" id="pick" hidden></label>
  <button id="tog-ocr">显示 OCR 原文</button>
  <button id="tog-follow" class="on">跟随播放</button>
  <input type="search" id="q" placeholder="搜索文稿与幻灯片文字…">
  <span class="meta" id="hits"></span>
</div>
<div id="vidwrap"><video id="v" controls preload="metadata"></video></div>
<main>
  <nav id="rail">__RAIL__</nav>
  <div id="doc">__DOC__</div>
</main>
<script>
const DATA = __DATA__;
const v = document.getElementById('v');
let follow = true;

document.getElementById('pick').addEventListener('change', e => {
  const f = e.target.files[0]; if (!f) return;
  v.src = URL.createObjectURL(f);
  document.getElementById('vidwrap').classList.add('on');
});
function seek(t){
  if(!v.src){ alert('先点「载入本地视频」选中原视频文件，时间轴才能跳转。'); return; }
  v.currentTime = t; v.play().catch(()=>{});
}
document.addEventListener('click', e => {
  const s = e.target.closest('[data-t]');
  if (s) { seek(parseFloat(s.dataset.t)); return; }
  const img = e.target.closest('.slide');
  if (img) img.classList.toggle('zoom');
});
document.getElementById('tog-ocr').addEventListener('click', e => {
  e.target.classList.toggle('on');
  document.querySelectorAll('.ocr').forEach(n => n.classList.toggle('on'));
});
document.getElementById('tog-follow').addEventListener('click', e => {
  follow = !follow; e.target.classList.toggle('on', follow);
});
v.addEventListener('timeupdate', () => {
  if (!follow) return;
  const t = v.currentTime;
  let cur = null;
  DATA.sections.forEach(s => { if (t >= s.t_start) cur = s.index; });
  document.querySelectorAll('.thumb').forEach(n =>
    n.classList.toggle('active', +n.dataset.i === cur));
  let hit = null;
  document.querySelectorAll('p.line').forEach(n => {
    const a = +n.dataset.s, b = +n.dataset.e;
    const on = t >= a && t < b;
    n.classList.toggle('playing', on);
    if (on && !hit) hit = n;
  });
  if (hit && !hit._seen) { hit._seen = 1;
    const r = hit.getBoundingClientRect();
    if (r.top < 60 || r.bottom > innerHeight - 60)
      hit.scrollIntoView({block:'center', behavior:'smooth'});
  }
});
const q = document.getElementById('q'), hits = document.getElementById('hits');
q.addEventListener('input', () => {
  const k = q.value.trim();
  document.querySelectorAll('mark').forEach(m => m.replaceWith(m.textContent));
  if (!k) { document.querySelectorAll('section').forEach(s=>s.classList.remove('hide'));
            hits.textContent=''; return; }
  let n = 0;
  document.querySelectorAll('section').forEach(sec => {
    let found = false;
    sec.querySelectorAll('p.line, .ocr, h2').forEach(node => {
      const parts = node.textContent.split(k);
      if (parts.length < 2) return;
      found = true; n += parts.length - 1;
      node.innerHTML = '';
      parts.forEach((p, i) => {
        if (i) { const m = document.createElement('mark'); m.textContent = k; node.append(m); }
        node.append(document.createTextNode(p));
      });
    });
    sec.classList.toggle('hide', !found);
  });
  hits.textContent = n ? `命中 ${n} 处` : '无匹配';
});
</script></body></html>
"""


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("outdir")
    ap.add_argument("--title", default=None)
    ap.add_argument("--out", default=None, help="HTML 输出路径，默认 OUTDIR/courseware.html")
    ap.add_argument("--no-markdown", action="store_true")
    args = ap.parse_args()

    outdir = Path(args.outdir)
    kf_path = outdir / "keyframes.json"
    tr_path = outdir / "transcript.json"
    if not kf_path.exists() and not tr_path.exists():
        raise SystemExit("keyframes.json 和 transcript.json 至少要有一个")

    kf = json.loads(kf_path.read_text(encoding="utf-8")) if kf_path.exists() else {
        "keyframes": [], "source": "", "stats": {}}
    tr = json.loads(tr_path.read_text(encoding="utf-8")) if tr_path.exists() else {
        "segments": [], "engine": None}

    source = kf.get("source") or tr.get("source_video") or ""
    title = args.title or (Path(source).stem if source else "课程记录")
    sections = align(kf["keyframes"], tr["segments"])
    duration = max([s["t_end"] for s in sections] +
                   [s["end"] for s in tr["segments"]] + [0])

    # ---- 轨道栏
    rail = []
    for s in sections:
        if not s.get("file"):
            continue
        img = b64_img(outdir / s["file"])
        rail.append(
            f'<a class="thumb" data-i="{s["index"]}" data-t="{s["t_start"]}">'
            f'<img src="{img}" alt="{html.escape(section_title(s))}">'
            f'<span class="cap"><b>{fmt_ts(s["t_start"])}</b>'
            f'<span>{html.escape(section_title(s))[:14]}</span></span></a>')

    # ---- 正文
    doc = []
    for s in sections:
        doc.append(f'<section id="s{s["index"]}">')
        doc.append(f'<h2>{html.escape(section_title(s))}</h2>')
        doc.append(f'<div class="stamp" data-t="{s["t_start"]}">'
                   f'{fmt_ts(s["t_start"])} – {fmt_ts(s["t_end"])}</div>')
        if s.get("revisits"):
            r = "、".join(f'<span class="stamp" data-t="{v["t_start"]}">'
                          f'{fmt_ts(v["t_start"])}</span>' for v in s["revisits"])
            doc.append(f'<p class="revisit">讲者在 {r} 处回看了这一页</p>')
        if s.get("file"):
            doc.append(f'<img class="slide" src="{b64_img(outdir / s["file"])}" '
                       f'alt="{html.escape(section_title(s))}">')
        if (s.get("text") or "").strip():
            doc.append(f'<div class="ocr">{html.escape(s["text"])}</div>')
        for seg in s["segments"]:
            doc.append(
                f'<p class="line" data-s="{seg["start"]:.2f}" data-e="{seg["end"]:.2f}">'
                f'<span class="t" data-t="{seg["start"]:.2f}">{fmt_ts(seg["start"])}</span>'
                f'{html.escape(seg["text"])}</p>')
        if not s["segments"]:
            doc.append('<p class="line meta" data-s="0" data-e="0">'
                       '<em>这一段没有对应的文稿</em></p>')
        doc.append("</section>")

    meta_line = (
        f'<b>{len(sections)}</b> 个片段 · '
        f'<b>{sum(len(s["segments"]) for s in sections)}</b> 句文稿 · '
        f'时长 <b>{fmt_ts(duration)}</b> · '
        f'文稿来源 {html.escape(str(tr.get("engine") or "无"))} · '
        f'OCR {html.escape(str(kf.get("ocr_backend") or "无"))}'
        f'<br>源文件 {html.escape(Path(source).name if source else "?")}')

    payload = {"sections": [{"index": s["index"], "t_start": s["t_start"]}
                            for s in sections]}
    html_out = (TEMPLATE
                .replace("__TITLE__", html.escape(title))
                .replace("__META__", meta_line)
                .replace("__RAIL__", "\n".join(rail) or
                         '<p class="meta">没有关键帧</p>')
                .replace("__DOC__", "\n".join(doc))
                .replace("__DATA__", json.dumps(payload, ensure_ascii=False)))

    out_html = Path(args.out) if args.out else outdir / "courseware.html"
    out_html.write_text(html_out, encoding="utf-8")

    result = {"html": str(out_html),
              "size_mb": round(out_html.stat().st_size / 1e6, 2),
              "sections": len(sections),
              "lines": sum(len(s["segments"]) for s in sections)}

    if not args.no_markdown:
        md = outdir / "courseware.md"
        md.write_text(to_markdown(
            {"title": title, "source": source, "duration": duration}, sections),
            encoding="utf-8")
        result["markdown"] = str(md)

    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

