/* ================= 应用层：状态 / 存储 / 交互 ================= */
(function () {
  'use strict';
  var C = PivotCore;
  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };

  /* ---------- 格式化 ---------- */
  function fmtInt(n) { return n == null ? '–' : Math.round(n).toLocaleString('zh-CN'); }
  function fmtMoney(n) { return n == null ? '–' : n.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function fmtPct(x) { return (x == null || !isFinite(x)) ? '–' : (x * 100).toFixed(2) + '%'; }
  function cls(n) { return (typeof n === 'number' && n < 0) ? ' class="neg"' : ''; }
  function tdNum(v, f) { return '<td' + cls(v) + '>' + f(v) + '</td>'; }
  function metricCells(mt) {
    return tdNum(mt.units, fmtInt) + tdNum(mt.sales, fmtMoney) + tdNum(mt.gross, fmtMoney) +
      tdNum(mt.margin, fmtPct) + tdNum(mt.ad, fmtPct) + tdNum(mt.promo, fmtPct) +
      tdNum(mt.mkt, fmtPct) + tdNum(mt.wh, fmtPct);
  }
  function dayLabel(d) { return d.ds === d.de ? d.ds : (d.ds + '～' + d.de); }

  /* ---------- 存储层：IndexedDB，失败则内存兜底 ---------- */
  var DB = (function () {
    var db = null, mem = false;
    function open() {
      return new Promise(function (resolve) {
        try {
          if (!window.indexedDB) { mem = true; return resolve(); }
          var req = indexedDB.open('kokodi_sales_pivot', 1);
          req.onupgradeneeded = function (e) {
            var d = e.target.result;
            if (!d.objectStoreNames.contains('rows')) d.createObjectStore('rows', { keyPath: 'k' });
            if (!d.objectStoreNames.contains('batches')) d.createObjectStore('batches', { keyPath: 'id' });
          };
          req.onsuccess = function (e) { db = e.target.result; resolve(); };
          req.onerror = function () { mem = true; resolve(); };
        } catch (err) { mem = true; resolve(); }
      });
    }
    function tx(store, mode, fn) {
      return new Promise(function (resolve, reject) {
        if (mem || !db) return resolve();
        var t = db.transaction(store, mode);
        fn(t.objectStore(store));
        t.oncomplete = function () { resolve(); };
        t.onerror = function (e) { reject(e); };
      });
    }
    function readAll(store) {
      return new Promise(function (resolve) {
        if (mem || !db) return resolve([]);
        var out = [];
        var t = db.transaction(store, 'readonly');
        var cur = t.objectStore(store).openCursor();
        cur.onsuccess = function (e) {
          var c = e.target.result;
          if (c) { out.push(c.value); c.continue(); } else resolve(out);
        };
        cur.onerror = function () { resolve([]); };
      });
    }
    return {
      open: open,
      isMemory: function () { return mem; },
      loadAll: function () {
        return Promise.all([readAll('rows'), readAll('batches')]).then(function (r) { return { rows: r[0], batches: r[1] }; });
      },
      putRows: function (rows) { return tx('rows', 'readwrite', function (s) { rows.forEach(function (r) { s.put(r); }); }); },
      delRows: function (keys) { return tx('rows', 'readwrite', function (s) { keys.forEach(function (k) { s.delete(k); }); }); },
      putBatch: function (b) { return tx('batches', 'readwrite', function (s) { s.put(b); }); },
      delBatch: function (id) { return tx('batches', 'readwrite', function (s) { s.delete(id); }); },
      clearAll: function () {
        return tx('rows', 'readwrite', function (s) { s.clear(); }).then(function () {
          return tx('batches', 'readwrite', function (s) { s.clear(); });
        });
      }
    };
  })();

  /* ---------- 全局状态 ---------- */
  var S = {
    rows: [], batches: [],
    f: { '国家': new Set(), '店铺': new Set(), '负责人': new Set(), '部门': new Set(), '分类': new Set(), years: new Set(), months: new Set() },
    gran: 'month',
    collapsed: {},          // pathKey -> true
    pending: null,          // 待入库 { built, dup, overlaps, srcName }
    page: 1, tab: 'pivot'
  };
  var PAGE = 50;

  function toast(msg, warn) {
    var t = $('toast');
    t.textContent = msg;
    t.className = 'toast show' + (warn ? ' warn' : '');
    clearTimeout(toast._t);
    toast._t = setTimeout(function () { t.className = 'toast'; }, 3200);
  }

  /* ---------- 筛选器渲染 ---------- */
  var DIM_UI = [
    { key: '国家', label: '国家' }, { key: '店铺', label: '店铺' },
    { key: '负责人', label: 'Listing 负责人' }, { key: '部门', label: '部门' }, { key: '分类', label: '分类' }
  ];
  var expandedGroups = {}; // 超长组的"更多"展开态

  function chipHtml(text, active, dataAttr, extraCls) {
    return '<button type="button" class="chip' + (active ? ' on' : '') + (extraCls ? ' ' + extraCls : '') + '" ' + dataAttr + '>' + esc(text) + '</button>';
  }

  function renderFilters() {
    var dv = C.dimValues(S.rows);
    // 清理已不存在的选中值
    DIM_UI.forEach(function (d) {
      var valid = new Set(dv[d.key]);
      S.f[d.key] = new Set(Array.from(S.f[d.key]).filter(function (v) { return valid.has(v); }));
    });
    S.f.years = new Set(Array.from(S.f.years).filter(function (y) { return dv.years.indexOf(y) >= 0; }));
    S.f.months = new Set(Array.from(S.f.months).filter(function (m) { return dv.months.indexOf(m) >= 0; }));

    var html = '';
    DIM_UI.forEach(function (d) {
      var vals = dv[d.key];
      if (!vals.length) return;
      var set = S.f[d.key];
      var limit = 14;
      var showAll = expandedGroups[d.key] || vals.length <= limit;
      var shown = showAll ? vals : vals.slice(0, limit);
      html += '<div class="fgroup"><span class="flabel">' + esc(d.label) + '</span><div class="chips">';
      html += chipHtml('全部', set.size === 0, 'data-fdim="' + esc(d.key) + '" data-fval="__ALL__"', 'all');
      shown.forEach(function (v) {
        html += chipHtml(v, set.has(v), 'data-fdim="' + esc(d.key) + '" data-fval="' + esc(v) + '"');
      });
      if (!showAll) html += chipHtml('+' + (vals.length - limit) + ' 更多', false, 'data-more="' + esc(d.key) + '"', 'more');
      html += '</div></div>';
    });
    $('filterArea').innerHTML = html || '<div class="hint">导入数据后此处出现维度筛选</div>';

    // 日期切片：年 chips + 按年分组的月 chips
    var sh = '';
    if (dv.years.length) {
      sh += '<div class="fgroup"><span class="flabel">年份</span><div class="chips">';
      sh += chipHtml('全部', S.f.years.size === 0, 'data-year="__ALL__"', 'all');
      dv.years.forEach(function (y) { sh += chipHtml(y, S.f.years.has(y), 'data-year="' + y + '"'); });
      sh += '</div></div>';
      sh += '<div class="fgroup"><span class="flabel">月份</span><div class="chips">';
      sh += chipHtml('全部', S.f.months.size === 0, 'data-month="__ALL__"', 'all');
      dv.years.forEach(function (y) {
        var ms = dv.months.filter(function (m) { return m.slice(0, 4) === y; });
        if (dv.years.length > 1) sh += '<span class="ytag">' + y + '</span>';
        ms.forEach(function (m) {
          sh += chipHtml(+m.slice(5, 7) + '月', S.f.months.has(m), 'data-month="' + m + '"');
        });
      });
      sh += '</div></div>';
    }
    $('sliceArea').innerHTML = sh;
  }

  /* ---------- 透视表渲染 ---------- */
  function activeFilterDesc(key) {
    var s = S.f[key];
    if (!s || s.size === 0) return 'All';
    return Array.from(s).join('、');
  }

  function renderPivot() {
    var hasData = S.rows.length > 0;
    $('pivotEmpty').style.display = hasData ? 'none' : '';
    $('pivotBody').style.display = hasData ? '' : 'none';
    if (!hasData) { $('kpiRow').innerHTML = ''; $('trendBox').innerHTML = ''; return; }

    var agg = C.aggregate(S.rows, S.f, S.gran);
    renderKpi(agg);
    renderTrend(agg.monthly);
    renderTable(agg);
    S._agg = agg;
  }

  function renderKpi(agg) {
    var m = agg.total.metrics;
    var cards = [
      ['销量合计', fmtInt(m.units), ''],
      ['销售额合计', fmtMoney(m.sales), ''],
      ['毛利合计', fmtMoney(m.gross), m.gross < 0 ? 'neg' : 'pos'],
      ['毛利率', fmtPct(m.margin), (m.margin != null && m.margin < 0) ? 'neg' : 'pos']
    ];
    $('kpiRow').innerHTML = cards.map(function (c) {
      return '<div class="kpi"><div class="kv ' + c[2] + '">' + c[1] + '</div><div class="kl">' + c[0] + '</div></div>';
    }).join('');
  }

  function renderTrend(monthly) {
    if (!monthly.length) { $('trendBox').innerHTML = ''; return; }
    var W = Math.max(560, monthly.length * 64), H = 168, padL = 8, padR = 8, padT = 18, padB = 30;
    var iw = W - padL - padR, ih = H - padT - padB;
    var maxS = Math.max.apply(null, monthly.map(function (m) { return m.sales; }).concat([1]));
    var gVals = monthly.map(function (m) { return m.gross; });
    var gMax = Math.max.apply(null, gVals.concat([0])), gMin = Math.min.apply(null, gVals.concat([0]));
    var gSpan = (gMax - gMin) || 1;
    var bw = Math.min(34, iw / monthly.length * 0.55);
    var x = function (i) { return padL + iw * (i + 0.5) / monthly.length; };
    var yS = function (v) { return padT + ih * (1 - v / maxS); };
    var yG = function (v) { return padT + ih * (1 - (v - gMin) / gSpan); };
    var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" class="trend" role="img" aria-label="月度销售额与毛利">';
    svg += '<line x1="' + padL + '" y1="' + (padT + ih) + '" x2="' + (W - padR) + '" y2="' + (padT + ih) + '" class="axis"/>';
    if (gMin < 0 && gMax > 0) svg += '<line x1="' + padL + '" y1="' + yG(0) + '" x2="' + (W - padR) + '" y2="' + yG(0) + '" class="zero"/>';
    monthly.forEach(function (m, i) {
      var bx = x(i) - bw / 2, by = yS(m.sales);
      svg += '<rect x="' + bx.toFixed(1) + '" y="' + by.toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + (padT + ih - by).toFixed(1) + '" class="bar"><title>' + m.ym + ' 销售额 ' + fmtMoney(m.sales) + '</title></rect>';
      svg += '<text x="' + x(i).toFixed(1) + '" y="' + (H - 10) + '" class="xl">' + m.ym.slice(2) + '</text>';
    });
    var pts = monthly.map(function (m, i) { return x(i).toFixed(1) + ',' + yG(m.gross).toFixed(1); }).join(' ');
    svg += '<polyline points="' + pts + '" class="gline"/>';
    monthly.forEach(function (m, i) {
      svg += '<circle cx="' + x(i).toFixed(1) + '" cy="' + yG(m.gross).toFixed(1) + '" r="3.2" class="gdot"><title>' + m.ym + ' 毛利 ' + fmtMoney(m.gross) + '</title></circle>';
    });
    svg += '</svg>';
    $('trendBox').innerHTML = '<div class="trendhead"><span><i class="sw bar"></i>销售额</span><span><i class="sw dot"></i>毛利</span></div><div class="trendscroll">' + svg + '</div>';
  }

  function caret(path, has) {
    if (!has) return '<span class="caret-slot"></span>';
    return '<button type="button" class="caret" data-path="' + esc(path) + '">' + (S.collapsed[path] ? '▸' : '▾') + '</button>';
  }

  function renderTable(agg) {
    var g = S.gran;
    var h = '<table class="pivot"><thead><tr>' +
      '<th class="dim">父品名汇总 / 层级</th>' +
      '<th>销量<i>TotalUnits</i></th><th>销售额<i>TotalSales</i></th><th>毛利<i>TotalGross</i></th>' +
      '<th>毛利率<i>Margin</i></th><th>广告占比<i>Ad Rate</i></th><th>促销折扣占比<i>Promotion</i></th>' +
      '<th>推广费占比<i>Marketing</i></th><th>仓储费占比<i>Warehouse</i></th></tr></thead><tbody>';
    agg.tree.forEach(function (p) {
      var pPath = 'p|' + p.name;
      var pHas = g !== 'year' ? p.years.length > 0 : p.years.length > 0;
      h += '<tr class="lv0"><td class="dim">' + caret(pPath, pHas) + '<span class="nm">' + esc(p.name) + '</span></td>' + metricCells(p.metrics) + '</tr>';
      if (S.collapsed[pPath]) return;
      p.years.forEach(function (y) {
        var yPath = pPath + '|' + y.year;
        var yHas = g !== 'year' && y.months.length > 0;
        h += '<tr class="lv1"><td class="dim">' + caret(yPath, yHas) + '<span class="nm">' + y.year + ' 年</span></td>' + metricCells(y.metrics) + '</tr>';
        if (g === 'year' || S.collapsed[yPath]) return;
        y.months.forEach(function (m) {
          var mPath = yPath + '|' + m.ym;
          var mHas = g === 'day' && m.days.length > 0;
          h += '<tr class="lv2"><td class="dim">' + caret(mPath, mHas) + '<span class="nm">' + (+m.ym.slice(5, 7)) + ' 月 <i class="en">' + m.label + '</i></span></td>' + metricCells(m.metrics) + '</tr>';
          if (g !== 'day' || S.collapsed[mPath]) return;
          m.days.forEach(function (d) {
            h += '<tr class="lv3"><td class="dim"><span class="caret-slot"></span><span class="nm">' + dayLabel(d) + (d.fullMonth ? ' <em class="tagfull">整月</em>' : '') + '</span></td>' + metricCells(d.metrics) + '</tr>';
          });
        });
      });
    });
    h += '<tr class="grand"><td class="dim">总计</td>' + metricCells(agg.total.metrics) + '</tr>';
    h += '</tbody></table>';
    $('pivotWrap').innerHTML = h;
    var fdesc = [];
    ['国家', '店铺', '负责人'].forEach(function (k) { if (S.f[k].size) fdesc.push(k + '=' + activeFilterDesc(k)); });
    if (S.f.years.size) fdesc.push('年=' + Array.from(S.f.years).join('、'));
    if (S.f.months.size) fdesc.push('月=' + Array.from(S.f.months).join('、'));
    $('pivotScope').textContent = fdesc.length ? '当前口径：' + fdesc.join('；') : '当前口径：全部数据（未加筛选）';
  }

  /* ---------- 导入 ---------- */
  function ensureXLSX() {
    if (typeof XLSX === 'undefined') {
      $('cdnWarn').style.display = '';
      return false;
    }
    return true;
  }

  function handleFile(file) {
    if (/\.(csv|tsv|txt)$/i.test(file.name)) {
      var fr = new FileReader();
      fr.onload = function () { previewImport(parseCSV(String(fr.result)), file.name); };
      fr.readAsText(file, 'utf-8');
      return;
    }
    if (!ensureXLSX()) { toast('表格解析库未加载：可改用「粘贴 CSV」导入', true); return; }
    var fr2 = new FileReader();
    fr2.onload = function () {
      try {
        var wb = XLSX.read(new Uint8Array(fr2.result), { type: 'array' });
        var name = wb.SheetNames.indexOf('销售明细') >= 0 ? '销售明细' : wb.SheetNames[0];
        var aoa = XLSX.utils.sheet_to_json(wb.Sheets[name], { header: 1, raw: true, defval: '' });
        previewImport(aoa, file.name + '（' + name + '）');
      } catch (e) { toast('文件解析失败：' + e.message, true); }
    };
    fr2.readAsArrayBuffer(file);
  }

  function parseCSV(text) {
    text = text.replace(/^\uFEFF/, '');
    var firstLine = text.split(/\r?\n/, 1)[0] || '';
    var delim = (firstLine.split('\t').length > firstLine.split(',').length) ? '\t' : ',';
    var rows = [], row = [], cur = '', inQ = false;
    for (var i = 0; i < text.length; i++) {
      var ch = text[i];
      if (inQ) {
        if (ch === '"') { if (text[i + 1] === '"') { cur += '"'; i++; } else inQ = false; }
        else cur += ch;
      } else if (ch === '"') inQ = true;
      else if (ch === delim) { row.push(cur); cur = ''; }
      else if (ch === '\n' || ch === '\r') {
        if (ch === '\r' && text[i + 1] === '\n') i++;
        row.push(cur); rows.push(row); row = []; cur = '';
      } else cur += ch;
    }
    if (cur !== '' || row.length) { row.push(cur); rows.push(row); }
    return rows.filter(function (r) { return r.some(function (c) { return String(c).trim() !== ''; }); });
  }

  function previewImport(aoa, srcName) {
    var built = C.buildRows(aoa, '__pending__');
    var iss = built.issues;
    var box = $('importReport');
    if (iss.fatal) {
      box.innerHTML = '<div class="card danger"><b>无法入库</b><div>' + esc(iss.fatal) + '</div>' +
        (iss.unknown && iss.unknown.length ? '<div class="sub">未识别列：' + esc(iss.unknown.join('、')) + '</div>' : '') +
        '<div class="sub">请核对财务模板表头后重试。</div></div>';
      S.pending = null;
      return;
    }
    var existing = new Set(S.rows.map(function (r) { return r.k; }));
    var dup = built.rows.filter(function (r) { return existing.has(r.k); });
    // 期间×店铺 重叠
    var libCombo = new Set(S.rows.map(function (r) { return r.ds.slice(0, 7) + ' × ' + r.d['店铺']; }));
    var overlaps = Array.from(new Set(built.rows
      .map(function (r) { return r.ds.slice(0, 7) + ' × ' + r.d['店铺']; })
      .filter(function (c) { return libCombo.has(c); }))).sort();
    S.pending = { built: built, dup: dup, overlaps: overlaps, srcName: srcName };

    function issueList(arr, fmt) {
      if (!arr.length) return '';
      var head = arr.slice(0, 8).map(fmt).join('；');
      return head + (arr.length > 8 ? '；…共 ' + arr.length + ' 处' : '');
    }
    var h = '<div class="card">';
    h += '<div class="cardtitle">校验报告 · ' + esc(srcName) + '</div>';
    h += '<div class="repgrid">';
    h += '<div><b>' + built.rows.length + '</b><span>有效明细行</span></div>';
    h += '<div><b>' + built.months.join('、') + '</b><span>期间覆盖</span></div>';
    h += '<div><b>' + (C.NUM_COLS.length + C.DIM_COLS.length - iss.missing.length) + ' / ' + (C.NUM_COLS.length + C.DIM_COLS.length) + '</b><span>识别标准列</span></div>';
    h += '<div><b class="' + (dup.length ? 'warn' : '') + '">' + dup.length + '</b><span>与库中重复行</span></div>';
    h += '</div>';
    if (iss.missing.length) h += '<div class="isline">缺失列（按 0 处理）：' + esc(iss.missing.join('、')) + '</div>';
    if (iss.unknown.length) h += '<div class="isline">未识别列（已忽略）：' + esc(iss.unknown.join('、')) + '</div>';
    if (iss.badDate.length) h += '<div class="isline bad">日期无法解析（该行剔除）：' + esc(issueList(iss.badDate, function (x) { return '第' + x.line + '行「' + x.raw + '」'; })) + '</div>';
    if (iss.badNum.length) h += '<div class="isline bad">数值异常（按 0 计）：' + esc(issueList(iss.badNum, function (x) { return '第' + x.line + '行·' + x.col + '「' + x.raw + '」'; })) + '</div>';
    if (iss.emptyDim.length) h += '<div class="isline">关键维度为空：' + esc(issueList(iss.emptyDim, function (x) { return '第' + x.line + '行·' + x.col; })) + '</div>';
    if (overlaps.length) h += '<div class="isline warn2">期间重叠提示：库中已存在 ' + esc(overlaps.slice(0, 6).join('；')) + (overlaps.length > 6 ? ' 等 ' + overlaps.length + ' 组' : '') + ' 的数据。若本次为补发/修订，请选「覆盖」。</div>';
    h += '<div class="strat"><span class="flabel">重复行策略</span>' +
      '<label><input type="radio" name="dupStrategy" value="skip" checked> 跳过重复行（保留库中原值）</label>' +
      '<label><input type="radio" name="dupStrategy" value="replace"> 覆盖重复行（以本次文件为准）</label></div>';
    h += '<div class="strat"><span class="flabel">批次备注</span><input id="noteInput" class="txt" placeholder="例如：2026-02 财务终版" maxlength="60"></div>';
    h += '<div class="actrow"><button id="btnCommit" class="btn primary">确认入库 ' + built.rows.length + ' 行</button>' +
      '<button id="btnCancelImport" class="btn ghost">放弃本次</button></div>';
    h += '</div>';
    box.innerHTML = h;
    $('btnCommit').onclick = commitImport;
    $('btnCancelImport').onclick = function () { S.pending = null; box.innerHTML = ''; };
  }

  function commitImport() {
    var p = S.pending;
    if (!p) return;
    var strat = (document.querySelector('input[name="dupStrategy"]:checked') || {}).value || 'skip';
    var note = ($('noteInput') && $('noteInput').value.trim()) || '';
    var id = 'B' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
    var existing = new Set(S.rows.map(function (r) { return r.k; }));
    var toAdd = [], replacedKeys = [];
    p.built.rows.forEach(function (r) {
      r.b = id;
      if (existing.has(r.k)) {
        if (strat === 'replace') { replacedKeys.push(r.k); toAdd.push(r); }
      } else toAdd.push(r);
    });
    if (replacedKeys.length) {
      var rk = new Set(replacedKeys);
      S.rows = S.rows.filter(function (r) { return !rk.has(r.k); });
    }
    S.rows = S.rows.concat(toAdd);
    var batch = {
      id: id, ts: new Date().toISOString(), name: p.srcName, note: note,
      added: toAdd.length - replacedKeys.length, replaced: replacedKeys.length,
      skipped: p.dup.length - replacedKeys.length, months: p.built.months
    };
    S.batches.push(batch);
    DB.putRows(toAdd).then(function () { return DB.putBatch(batch); }).catch(function () { });
    S.pending = null;
    $('importReport').innerHTML = '<div class="card ok"><b>已入库</b> 新增 ' + batch.added + ' 行' +
      (batch.replaced ? '，覆盖 ' + batch.replaced + ' 行' : '') +
      (batch.skipped ? '，跳过重复 ' + batch.skipped + ' 行' : '') +
      '。<button class="btn link" id="goPivot">去透视分析 →</button></div>';
    $('goPivot').onclick = function () { switchTab('pivot'); };
    renderAll();
    toast('入库完成：' + batch.added + ' 行新增');
  }

  /* ---------- 批次管理 ---------- */
  function renderBatches() {
    if (!S.batches.length) { $('batchList').innerHTML = '<div class="hint">尚无导入批次。每次导入都会在这里留档，可单独撤销。</div>'; return; }
    var h = '<table class="flat"><thead><tr><th>时间</th><th>来源</th><th>期间</th><th>新增</th><th>覆盖</th><th>跳过</th><th>备注</th><th></th></tr></thead><tbody>';
    S.batches.slice().sort(function (a, b) { return a.ts < b.ts ? 1 : -1; }).forEach(function (b) {
      var live = S.rows.filter(function (r) { return r.b === b.id; }).length;
      h += '<tr><td>' + esc(b.ts.slice(0, 16).replace('T', ' ')) + '</td><td>' + esc(b.name) + '</td><td>' + esc((b.months || []).join('、')) + '</td>' +
        '<td>' + b.added + '</td><td>' + (b.replaced || 0) + '</td><td>' + (b.skipped || 0) + '</td><td>' + esc(b.note || '') + '</td>' +
        '<td><button class="btn tiny danger" data-delbatch="' + b.id + '">删除本批（现存 ' + live + ' 行）</button></td></tr>';
    });
    h += '</tbody></table>';
    $('batchList').innerHTML = h;
  }

  function deleteBatch(id) {
    var victim = S.rows.filter(function (r) { return r.b === id; });
    if (!confirm('删除该批次将移除其现存 ' + victim.length + ' 行明细（被后续批次覆盖的行不受影响）。继续？')) return;
    var keys = victim.map(function (r) { return r.k; });
    S.rows = S.rows.filter(function (r) { return r.b !== id; });
    S.batches = S.batches.filter(function (b) { return b.id !== id; });
    DB.delRows(keys).then(function () { return DB.delBatch(id); }).catch(function () { });
    renderAll();
    toast('批次已删除');
  }

  function wipeAll() {
    if (!S.rows.length && !S.batches.length) return;
    if (!confirm('清空全库：' + S.rows.length + ' 行明细与 ' + S.batches.length + ' 个批次都将删除。建议先「备份 JSON」。确认清空？')) return;
    if (!confirm('再次确认：清空后不可恢复（除非用备份文件）。')) return;
    S.rows = []; S.batches = []; S.collapsed = {};
    DB.clearAll().catch(function () { });
    renderAll();
    toast('已清空全库', true);
  }

  /* ---------- 明细浏览 ---------- */
  function renderBrowse() {
    var dv = C.dimValues(S.rows);
    var sel = $('browseMonth');
    var cur = sel.value;
    sel.innerHTML = '<option value="">全部月份</option>' + dv.months.map(function (m) { return '<option' + (m === cur ? ' selected' : '') + '>' + m + '</option>'; }).join('');
    var q = $('browseQ').value.trim().toLowerCase();
    var mSel = sel.value;
    var list = S.rows.filter(function (r) {
      if (mSel && r.ds.slice(0, 7) !== mSel) return false;
      if (!q) return true;
      var hay = [r.d['国家'], r.d['店铺'], r.d['父品名汇总'], r.d['品名'], r.d['SKU'], r.d['MSKU'], r.d['ASIN'], r.d['Listing负责人']].join(' ').toLowerCase();
      return hay.indexOf(q) >= 0;
    }).sort(function (a, b) { return a.ds === b.ds ? b.m['销售额'] - a.m['销售额'] : (a.ds < b.ds ? 1 : -1); });
    var pages = Math.max(1, Math.ceil(list.length / PAGE));
    if (S.page > pages) S.page = pages;
    var slice = list.slice((S.page - 1) * PAGE, S.page * PAGE);
    var h = '<table class="flat"><thead><tr><th>日期</th><th>国家</th><th>店铺</th><th>父品名汇总</th><th>品名</th><th>SKU</th><th>负责人</th><th class="r">销量</th><th class="r">销售额</th><th class="r">毛利</th></tr></thead><tbody>';
    slice.forEach(function (r) {
      h += '<tr><td>' + esc(r.draw || r.ds) + '</td><td>' + esc(r.d['国家']) + '</td><td>' + esc(r.d['店铺']) + '</td><td>' + esc(r.d['父品名汇总']) + '</td><td class="clip" title="' + esc(r.d['品名']) + '">' + esc(r.d['品名']) + '</td><td>' + esc(r.d['SKU']) + '</td><td>' + esc(r.d['Listing负责人']) + '</td>' +
        '<td class="r">' + fmtInt(r.m['销量']) + '</td><td class="r">' + fmtMoney(r.m['销售额']) + '</td><td class="r' + (r.m['毛利'] < 0 ? ' neg' : '') + '">' + fmtMoney(r.m['毛利']) + '</td></tr>';
    });
    if (!slice.length) h += '<tr><td colspan="10" class="hint">无匹配明细</td></tr>';
    h += '</tbody></table>';
    $('browseTable').innerHTML = h;
    $('browsePager').innerHTML = '共 ' + list.length + ' 行 · 第 ' +
      '<button class="btn tiny" id="pgPrev"' + (S.page <= 1 ? ' disabled' : '') + '>‹</button> ' + S.page + ' / ' + pages +
      ' <button class="btn tiny" id="pgNext"' + (S.page >= pages ? ' disabled' : '') + '>›</button> 页';
    $('pgPrev').onclick = function () { if (S.page > 1) { S.page--; renderBrowse(); } };
    $('pgNext').onclick = function () { if (S.page < pages) { S.page++; renderBrowse(); } };
  }

  /* ---------- 备份 / 恢复 ---------- */
  function download(blobParts, type, filename) {
    var blob = new Blob(blobParts, { type: type });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 800);
  }
  function stamp() {
    var d = new Date();
    var p = function (n) { return (n < 10 ? '0' : '') + n; };
    return '' + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + '_' + p(d.getHours()) + p(d.getMinutes());
  }
  function backup() {
    var payload = { app: 'sales-pivot', version: 1, exportedAt: new Date().toISOString(), batches: S.batches, rows: S.rows };
    download([JSON.stringify(payload)], 'application/json', '销售明细库备份_' + stamp() + '.json');
    toast('备份已下载（' + S.rows.length + ' 行）');
  }
  function restoreFile(file) {
    var fr = new FileReader();
    fr.onload = function () {
      try {
        var p = JSON.parse(String(fr.result));
        if (p.app !== 'sales-pivot' || !Array.isArray(p.rows) || !Array.isArray(p.batches)) throw new Error('不是本工具的备份文件');
        if (!confirm('恢复将替换当前全部数据（现有 ' + S.rows.length + ' 行 → 备份 ' + p.rows.length + ' 行）。继续？')) return;
        S.rows = p.rows; S.batches = p.batches; S.collapsed = {};
        DB.clearAll().then(function () { return DB.putRows(S.rows); }).then(function () {
          return Promise.all(S.batches.map(function (b) { return DB.putBatch(b); }));
        }).catch(function () { });
        renderAll();
        toast('恢复完成：' + S.rows.length + ' 行');
      } catch (e) { toast('恢复失败：' + e.message, true); }
    };
    fr.readAsText(file, 'utf-8');
  }

  /* ---------- 导出透视 ---------- */
  function pivotAoa() {
    var agg = S._agg || C.aggregate(S.rows, S.f, S.gran);
    var head = [
      ['国家', activeFilterDesc('国家')], ['店铺', activeFilterDesc('店铺')],
      ['Listing负责人', activeFilterDesc('负责人')],
      ['日期切片', (S.f.years.size ? '年=' + Array.from(S.f.years).join('、') + ' ' : '') + (S.f.months.size ? '月=' + Array.from(S.f.months).join('、') : (S.f.years.size ? '' : 'All'))],
      ['粒度', { year: '年', month: '月', day: '日' }[S.gran]],
      [],
      ['父品名汇总', 'Year', 'Month', 'DateColumn', 'TotalUnits 销量', 'TotalSales 销售额', 'TotalGross 毛利', 'Margin 毛利率', 'Ad Sales Rate 广告占比', 'Promotion Sales Rate 促销折扣占比', 'Marketing Cost Sales Rate 推广费占比', 'Warehouse Charges Sales Rate 仓储费占比']
    ];
    var rows = [];
    var M = function (mt) { return [mt.units, mt.sales, mt.gross, mt.margin, mt.ad, mt.promo, mt.mkt, mt.wh]; };
    agg.tree.forEach(function (p) {
      var pFirst = true;
      p.years.forEach(function (y) {
        var yFirst = true;
        if (S.gran === 'year') {
          rows.push([pFirst ? p.name : '', y.year, '', ''].concat(M(y.metrics)));
          pFirst = false;
          return;
        }
        y.months.forEach(function (m) {
          if (S.gran === 'day' && m.days.length > 1) {
            var mFirst = true;
            m.days.forEach(function (d) {
              rows.push([pFirst ? p.name : '', yFirst ? y.year : '', mFirst ? m.label : '', dayLabel(d)].concat(M(d.metrics)));
              pFirst = false; yFirst = false; mFirst = false;
            });
            rows.push(['', '', m.label + ' 汇总', ''].concat(M(m.metrics)));
          } else {
            var dc = (S.gran === 'day' && m.days.length === 1) ? dayLabel(m.days[0]) : '';
            rows.push([pFirst ? p.name : '', yFirst ? y.year : '', m.label, dc].concat(M(m.metrics)));
            pFirst = false; yFirst = false;
          }
        });
        rows.push(['', y.year + ' 汇总', '', ''].concat(M(y.metrics)));
      });
      rows.push([p.name + ' 汇总', '', '', ''].concat(M(p.metrics)));
    });
    rows.push(['总计', '', '', ''].concat(M(agg.total.metrics)));
    return { head: head, rows: rows };
  }

  function exportXlsx() {
    if (!ensureXLSX()) { toast('表格库未加载，已为你导出 CSV', true); return exportCsv(); }
    var a = pivotAoa();
    var aoa = a.head.concat(a.rows);
    var ws = XLSX.utils.aoa_to_sheet(aoa);
    var start = a.head.length; // 数据起始行(0基)
    for (var r = start; r < aoa.length; r++) {
      for (var c = 4; c <= 11; c++) {
        var addr = XLSX.utils.encode_cell({ r: r, c: c });
        if (!ws[addr] || typeof ws[addr].v !== 'number') continue;
        ws[addr].z = c === 4 ? '#,##0' : (c <= 6 ? '#,##0.00' : '0.00%');
      }
    }
    ws['!cols'] = [{ wch: 16 }, { wch: 8 }, { wch: 12 }, { wch: 22 }, { wch: 10 }, { wch: 14 }, { wch: 14 }, { wch: 9 }, { wch: 9 }, { wch: 9 }, { wch: 9 }, { wch: 9 }];
    var wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '销售明细数据透视表');
    XLSX.writeFile(wb, '销售透视_' + stamp() + '.xlsx');
    toast('已导出 Excel');
  }

  function exportCsv() {
    var a = pivotAoa();
    var fmtRow = function (row, isData) {
      return row.map(function (v, i) {
        if (isData && typeof v === 'number') {
          if (i === 4) return Math.round(v);
          if (i === 5 || i === 6) return v.toFixed(2);
          if (i >= 7) return (v * 100).toFixed(2) + '%';
        }
        var s = String(v == null ? '' : v);
        return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
      }).join(',');
    };
    var lines = a.head.map(function (r) { return fmtRow(r, false); }).concat(a.rows.map(function (r) { return fmtRow(r, true); }));
    download(['\uFEFF' + lines.join('\r\n')], 'text/csv;charset=utf-8', '销售透视_' + stamp() + '.csv');
    toast('已导出 CSV');
  }

  /* ---------- 事件绑定 ---------- */
  function switchTab(t) {
    S.tab = t;
    document.querySelectorAll('.tabbar button').forEach(function (b) { b.classList.toggle('on', b.dataset.tab === t); });
    document.querySelectorAll('.panel').forEach(function (p) { p.classList.toggle('show', p.id === 'panel-' + t); });
  }

  function renderAll() {
    renderFilters();
    renderPivot();
    renderBatches();
    renderBrowse();
    $('dataCount').textContent = S.rows.length ? S.rows.length + ' 行 · ' + S.batches.length + ' 批' : '空库';
  }

  function bind() {
    document.querySelectorAll('.tabbar button').forEach(function (b) {
      b.onclick = function () { switchTab(b.dataset.tab); };
    });
    // 筛选与切片（事件委托）
    document.body.addEventListener('click', function (e) {
      var t = e.target.closest ? e.target.closest('button') : null;
      if (!t) return;
      if (t.dataset.fdim) {
        var set = S.f[t.dataset.fdim];
        if (t.dataset.fval === '__ALL__') set.clear();
        else if (set.has(t.dataset.fval)) set.delete(t.dataset.fval);
        else set.add(t.dataset.fval);
        renderFilters(); renderPivot();
      } else if (t.dataset.more) {
        expandedGroups[t.dataset.more] = true; renderFilters();
      } else if (t.dataset.year) {
        if (t.dataset.year === '__ALL__') S.f.years.clear();
        else if (S.f.years.has(t.dataset.year)) S.f.years.delete(t.dataset.year);
        else S.f.years.add(t.dataset.year);
        renderFilters(); renderPivot();
      } else if (t.dataset.month) {
        if (t.dataset.month === '__ALL__') S.f.months.clear();
        else if (S.f.months.has(t.dataset.month)) S.f.months.delete(t.dataset.month);
        else S.f.months.add(t.dataset.month);
        renderFilters(); renderPivot();
      } else if (t.dataset.path) {
        if (S.collapsed[t.dataset.path]) delete S.collapsed[t.dataset.path];
        else S.collapsed[t.dataset.path] = true;
        renderPivot();
      } else if (t.dataset.delbatch) {
        deleteBatch(t.dataset.delbatch);
      }
    });
    // 粒度
    document.querySelectorAll('#granSeg button').forEach(function (b) {
      b.onclick = function () {
        S.gran = b.dataset.g;
        document.querySelectorAll('#granSeg button').forEach(function (x) { x.classList.toggle('on', x === b); });
        renderPivot();
      };
    });
    $('btnExpandAll').onclick = function () { S.collapsed = {}; renderPivot(); };
    $('btnCollapseAll').onclick = function () {
      S.collapsed = {};
      (S._agg ? S._agg.tree : []).forEach(function (p) { S.collapsed['p|' + p.name] = true; });
      renderPivot();
    };
    $('btnExportX').onclick = exportXlsx;
    $('btnExportC').onclick = exportCsv;
    // 导入
    var dz = $('dropZone');
    dz.onclick = function () { $('fileInput').click(); };
    $('fileInput').onchange = function (e) { if (e.target.files[0]) handleFile(e.target.files[0]); e.target.value = ''; };
    ['dragover', 'dragenter'].forEach(function (ev) { dz.addEventListener(ev, function (e) { e.preventDefault(); dz.classList.add('drag'); }); });
    ['dragleave', 'drop'].forEach(function (ev) { dz.addEventListener(ev, function (e) { e.preventDefault(); dz.classList.remove('drag'); }); });
    dz.addEventListener('drop', function (e) {
      var f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
      if (f) handleFile(f);
    });
    $('btnParsePaste').onclick = function () {
      var txt = $('pasteArea').value;
      if (!txt.trim()) { toast('粘贴区为空', true); return; }
      previewImport(parseCSV(txt), '粘贴数据');
    };
    $('btnDemo').onclick = function () {
      previewImport(SAMPLE_AOA, '内置示例（本文件模板 10 行）');
      switchTab('import');
    };
    $('btnDemo2').onclick = $('btnDemo').onclick;
    // 批次
    $('btnWipe').onclick = wipeAll;
    // 备份恢复
    $('btnBackup').onclick = backup;
    $('btnRestore').onclick = function () { $('restoreInput').click(); };
    $('restoreInput').onchange = function (e) { if (e.target.files[0]) restoreFile(e.target.files[0]); e.target.value = ''; };
    // 明细浏览
    $('browseQ').oninput = function () { S.page = 1; renderBrowse(); };
    $('browseMonth').onchange = function () { S.page = 1; renderBrowse(); };
    // 口径说明
    $('btnGauge').onclick = function () { $('gaugeModal').classList.add('show'); };
    $('gaugeClose').onclick = function () { $('gaugeModal').classList.remove('show'); };
    $('gaugeModal').addEventListener('click', function (e) { if (e.target === $('gaugeModal')) $('gaugeModal').classList.remove('show'); });
  }

  /* ---------- 启动 ---------- */
  DB.open().then(function () {
    return DB.loadAll();
  }).then(function (d) {
    S.rows = d.rows || [];
    S.batches = d.batches || [];
    if (DB.isMemory()) {
      $('storageBadge').textContent = '仅内存运行 · 关闭页面即丢失（请部署到本地或 GitHub Pages 获得持久化）';
      $('storageBadge').classList.add('warn');
    } else {
      $('storageBadge').textContent = '本地持久化 · IndexedDB';
      if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(function () { });
    }
    bind();
    renderAll();
    switchTab(S.rows.length ? 'pivot' : 'pivot');
  });
})();

