/* ===================================================================
 * PivotCore —— 销售明细透视台 核心纯函数层（无 DOM 依赖，可在 Node 测试）
 * 口径与列结构以财务《销售明细》42 列模板为准
 * =================================================================== */
const PivotCore = (() => {
  'use strict';

  /* ---------- 1. 列名归一 ---------- */
  // 匹配键：去掉所有空白（含换行、全角空格、不间断空格），半角括号转全角，ASCII 转小写
  const matchKey = (s) => String(s == null ? '' : s)
    .replace(/[\s\u00A0\u3000]+/g, '')
    .replace(/\(/g, '（').replace(/\)/g, '）')
    .replace(/[A-Z]/g, (c) => c.toLowerCase());

  const DIM_COLS = ['国家', '日期', 'MSKU', 'ASIN', '父ASIN', '店铺', '品名', 'SKU', '父品名汇总', 'Listing负责人', '部门', '分类'];
  const NUM_COLS = ['销量', '补（换）货量', '多渠道销量', '销售额', '买家运费', '促销折扣', '退款金额', '退款量', '其它收入',
    'FBA库存赔偿', '平台费', 'FBA发货费', '其他订单费用', '月仓储', '长期仓储', 'FBA销毁费', 'FBA移除费', '其他仓储费',
    '广告费', '推广费', 'FBA国际物流运费', '调整费', '平台其他费', '入库配置费', '采购单价', '采购成本', '头程单价', '头程成本', '站外测评', '毛利'];
  const ALL_COLS = DIM_COLS.concat(NUM_COLS);
  // 关键列：缺失则拒绝入库
  const REQUIRED = ['国家', '日期', '店铺', '父品名汇总', 'Listing负责人', '销量', '销售额', '毛利'];

  const EXACT = {};
  ALL_COLS.forEach((c) => { EXACT[matchKey(c)] = c; });
  // 常见别名
  [['其他收入', '其它收入'], ['listing负责人', 'Listing负责人'], ['负责人', 'Listing负责人']]
    .forEach(([a, c]) => { EXACT[matchKey(a)] = c; });
  // 前缀规则：兼容「FBA发货费（已扣减多渠道发货费）」「入库配置费（原合仓费）」等尾注变体
  const PREFIX = ['FBA发货费', '入库配置费', '月仓储', '长期仓储', '平台费'].map((c) => [matchKey(c), c]);

  function resolveHeader(raw) {
    const k = matchKey(raw);
    if (!k) return null;
    if (EXACT[k]) return EXACT[k];
    for (const [p, c] of PREFIX) if (k.indexOf(p) === 0) return c;
    return null;
  }

  // headers: 原始表头数组 → { map: {canonical: colIndex}, unknown: [原始名], missing: [canonical], requiredMissing: [] }
  function mapHeaders(headers) {
    const map = {}; const unknown = [];
    headers.forEach((h, i) => {
      const c = resolveHeader(h);
      if (c) { if (!(c in map)) map[c] = i; }
      else if (String(h == null ? '' : h).trim() !== '') unknown.push(String(h));
    });
    const missing = ALL_COLS.filter((c) => !(c in map));
    const requiredMissing = REQUIRED.filter((c) => !(c in map));
    return { map, unknown, missing, requiredMissing };
  }

  /* ---------- 2. 日期解析 ----------
   * 支持：Excel 序列号 / JS Date / "YYYY-MM-DD~YYYY-MM-DD" 区间（~ ～ 至 到）
   *      / 单日 "YYYY-MM-DD" "YYYY/M/D" "YYYY.M.D" "YYYY年M月D日" "YYYYMMDD"
   *      / 年月 "YYYY-MM" "YYYY年M月" "YYYYMM" → 整月区间
   * 输出 { ds:'YYYY-MM-DD', de:'YYYY-MM-DD' }，失败返回 null            */
  const pad2 = (n) => (n < 10 ? '0' : '') + n;
  const ymd = (y, m, d) => y + '-' + pad2(m) + '-' + pad2(d);
  const daysInMonth = (y, m) => new Date(Date.UTC(y, m, 0)).getUTCDate();

  function serialToYMD(n) { // Excel 1900 体系：1899-12-30 + n 天（现代数据不涉 1900 闰年 bug）
    const t = Date.UTC(1899, 11, 30) + Math.round(n) * 86400000;
    const d = new Date(t);
    return ymd(d.getUTCFullYear(), d.getUTCMonth() + 1, d.getUTCDate());
  }

  function parseSingleDate(s) {
    s = s.trim();
    let m;
    if ((m = s.match(/^(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})日?$/)))
      return validYMD(+m[1], +m[2], +m[3]);
    if ((m = s.match(/^(\d{4})(\d{2})(\d{2})$/)))
      return validYMD(+m[1], +m[2], +m[3]);
    return null;
  }
  function parseYearMonth(s) {
    s = s.trim();
    let m;
    if ((m = s.match(/^(\d{4})[-/.年](\d{1,2})月?$/)) || (m = s.match(/^(\d{4})(\d{2})$/))) {
      const y = +m[1], mo = +m[2];
      if (mo >= 1 && mo <= 12) return { ds: ymd(y, mo, 1), de: ymd(y, mo, daysInMonth(y, mo)) };
    }
    return null;
  }
  function validYMD(y, mo, d) {
    if (y < 1990 || y > 2100 || mo < 1 || mo > 12 || d < 1 || d > daysInMonth(y, mo)) return null;
    return ymd(y, mo, d);
  }

  function parseDateCell(v) {
    if (v == null || v === '') return null;
    if (typeof v === 'number' && isFinite(v)) {
      if (v < 20000 || v > 80000) return null; // 约 1954–2119 年之外视为异常
      const d = serialToYMD(v); return { ds: d, de: d };
    }
    if (v instanceof Date && !isNaN(v)) {
      // SheetJS cellDates 产物按 UTC 取分量，避免时区回拨一天
      const d = ymd(v.getUTCFullYear(), v.getUTCMonth() + 1, v.getUTCDate());
      return { ds: d, de: d };
    }
    const s = String(v).trim();
    if (!s) return null;
    // 区间：~ ～ 至 到（不拿 "-" 当区间分隔，避免与日期连字符冲突）
    const parts = s.split(/\s*(?:~|～|至|到)\s*/);
    if (parts.length === 2) {
      const a = parseSingleDate(parts[0]); const b = parseSingleDate(parts[1]);
      if (a && b) return a <= b ? { ds: a, de: b } : { ds: b, de: a };
      return null;
    }
    const one = parseSingleDate(s);
    if (one) return { ds: one, de: one };
    const mo = parseYearMonth(s);
    if (mo) return mo;
    // 纯数字字符串按序列号兜底
    if (/^\d+(\.\d+)?$/.test(s)) return parseDateCell(+s);
    return null;
  }

  const isFullMonth = (ds, de) => {
    const y = +ds.slice(0, 4), m = +ds.slice(5, 7);
    return ds.slice(8) === '01' && de === ymd(y, m, daysInMonth(y, m));
  };

  /* ---------- 3. 数值清洗 ----------
   * 空/横线 → 0（视为无发生额）；"1,234.5" "￥-3.2" "(500)" "12%" 均可解析
   * 解析失败返回 { v:0, bad:true }                                     */
  function parseNumber(v) {
    if (v == null || v === '') return { v: 0, blank: true };
    if (typeof v === 'number') return isFinite(v) ? { v: v } : { v: 0, bad: true };
    let s = String(v).trim();
    if (s === '' || s === '-' || s === '—' || s === '--') return { v: 0, blank: true };
    let neg = false;
    if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
    let pct = false;
    if (/%$/.test(s)) { pct = true; s = s.slice(0, -1); }
    s = s.replace(/[,，\s\u00A0]/g, '').replace(/^[￥¥$€£]/, '');
    const n = Number(s);
    if (!isFinite(n)) return { v: 0, bad: true };
    let r = n; if (neg) r = -r; if (pct) r = r / 100;
    return { v: r };
  }

  /* ---------- 4. 行构建（导入管线） ---------- */
  function fnv1a(str) {
    let h = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = (h * 0x01000193) >>> 0; }
    return ('0000000' + h.toString(16)).slice(-8);
  }
  const rowKey = (r) => fnv1a([r.d['国家'], r.d['店铺'], r.ds, r.de, r.d['MSKU'], r.d['SKU'], r.d['ASIN'], r.d['品名']].join('\x1f'));

  /**
   * aoa: 含表头的二维数组（SheetJS sheet_to_json header:1, raw:true, defval:''）
   * 返回 { rows, issues:{unknown,missing,requiredMissing,badDate:[{line,raw}],badNum:[{line,col,raw}],emptyDim:[{line,col}]}, months:['YYYY-MM'…] }
   */
  function buildRows(aoa, batchId) {
    if (!aoa || !aoa.length) return { rows: [], issues: { fatal: '文件为空' } };
    // 允许表头前有空行/标题行：找到能命中最多关键列的一行作为表头（前 10 行内）
    let hdrIdx = 0, best = -1, hm = null;
    for (let i = 0; i < Math.min(10, aoa.length); i++) {
      const t = mapHeaders(aoa[i] || []);
      const score = REQUIRED.length - t.requiredMissing.length;
      if (score > best) { best = score; hdrIdx = i; hm = t; }
      if (t.requiredMissing.length === 0) { hdrIdx = i; hm = t; break; }
    }
    if (!hm || hm.requiredMissing.length) {
      return { rows: [], issues: { fatal: '缺少关键列：' + (hm ? hm.requiredMissing.join('、') : '无法识别表头'), unknown: hm ? hm.unknown : [], missing: hm ? hm.missing : [] } };
    }
    const { map, unknown, missing } = hm;
    const rows = []; const badDate = []; const badNum = []; const emptyDim = [];
    const monthSet = new Set();
    for (let i = hdrIdx + 1; i < aoa.length; i++) {
      const arr = aoa[i]; if (!arr) continue;
      const isEmpty = arr.every((c) => c == null || String(c).trim() === '');
      if (isEmpty) continue;
      const line = i + 1; // 供报告用（1 基）
      const d = {};
      DIM_COLS.forEach((c) => { d[c] = (c in map) ? String(arr[map[c]] == null ? '' : arr[map[c]]).trim() : ''; });
      const pd = parseDateCell(arr[map['日期']]);
      if (!pd) { badDate.push({ line, raw: String(arr[map['日期']]) }); continue; }
      ['国家', '店铺', '父品名汇总', 'Listing负责人'].forEach((c) => { if (!d[c]) emptyDim.push({ line, col: c }); });
      if (!d['父品名汇总']) d['父品名汇总'] = '(未填写)';
      if (!d['Listing负责人']) d['Listing负责人'] = '(未填写)';
      const m = {};
      NUM_COLS.forEach((c) => {
        if (!(c in map)) { m[c] = 0; return; }
        const p = parseNumber(arr[map[c]]);
        if (p.bad) badNum.push({ line, col: c, raw: String(arr[map[c]]) });
        m[c] = p.v;
      });
      const row = { b: batchId, d, ds: pd.ds, de: pd.de, draw: String(arr[map['日期']]), m: m };
      row.k = rowKey(row);
      monthSet.add(pd.ds.slice(0, 7));
      rows.push(row);
    }
    return { rows, issues: { unknown, missing, badDate, badNum, emptyDim }, months: Array.from(monthSet).sort() };
  }

  /* ---------- 5. 透视聚合 ----------
   * 指标口径（率值均为汇总层「和÷和」，与 Excel 计算字段一致）：
   *  TotalUnits=Σ销量  TotalSales=Σ销售额  TotalGross=Σ毛利  Margin=Gross/Sales
   *  Ad=Σ广告费/Σ销售额  Promotion=Σ促销折扣/Σ销售额  Marketing=Σ推广费/Σ销售额
   *  Warehouse=Σ(月仓储+长期仓储+FBA销毁费+FBA移除费+其他仓储费)/Σ销售额          */
  const SUM_KEYS = ['销量', '销售额', '毛利', '广告费', '促销折扣', '推广费', '月仓储', '长期仓储', 'FBA销毁费', 'FBA移除费', '其他仓储费'];
  const MONTH_EN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

  const zeroSums = () => { const o = {}; SUM_KEYS.forEach((k) => { o[k] = 0; }); return o; };
  const addRow = (o, r) => { SUM_KEYS.forEach((k) => { o[k] += r.m[k] || 0; }); };
  function metricsOf(s) {
    const sales = s['销售额'];
    const rate = (x) => (sales ? x / sales : null);
    return {
      units: s['销量'], sales: sales, gross: s['毛利'],
      margin: rate(s['毛利']), ad: rate(s['广告费']), promo: rate(s['促销折扣']), mkt: rate(s['推广费']),
      wh: rate(s['月仓储'] + s['长期仓储'] + s['FBA销毁费'] + s['FBA移除费'] + s['其他仓储费'])
    };
  }

  /**
   * filters: { 国家:Set|null, 店铺:Set|null, 负责人:Set|null, 部门:Set|null, 分类:Set|null, years:Set|null, months:Set('YYYY-MM')|null }
   * granularity: 'year' | 'month' | 'day'
   * 返回 { tree:[父品名节点…], total:{sums,metrics}, monthly:[{ym,sales,gross}…] }
   */
  function aggregate(rows, filters, granularity) {
    const f = filters || {};
    const pass = (set, v) => !set || set.size === 0 || set.has(v);
    const top = new Map(); const total = zeroSums(); const monthly = new Map();
    for (const r of rows) {
      if (!pass(f['国家'], r.d['国家'])) continue;
      if (!pass(f['店铺'], r.d['店铺'])) continue;
      if (!pass(f['负责人'], r.d['Listing负责人'])) continue;
      if (!pass(f['部门'], r.d['部门'])) continue;
      if (!pass(f['分类'], r.d['分类'])) continue;
      const y = r.ds.slice(0, 4); const ym2 = r.ds.slice(0, 7);
      if (!pass(f.years, y)) continue;
      if (!pass(f.months, ym2)) continue;
      addRow(total, r);
      let mo = monthly.get(ym2); if (!mo) { mo = zeroSums(); monthly.set(ym2, mo); } addRow(mo, r);
      const p = r.d['父品名汇总'];
      let pn = top.get(p); if (!pn) { pn = { sums: zeroSums(), years: new Map() }; top.set(p, pn); }
      addRow(pn.sums, r);
      if (granularity === 'year') continue;
      let yn = pn.years.get(y); if (!yn) { yn = { sums: zeroSums(), months: new Map() }; pn.years.set(y, yn); }
      addRow(yn.sums, r);
      let mn = yn.months.get(ym2); if (!mn) { mn = { sums: zeroSums(), days: new Map() }; yn.months.set(ym2, mn); }
      addRow(mn.sums, r);
      if (granularity !== 'day') continue;
      const dk = r.ds + '|' + r.de;
      let dn = mn.days.get(dk); if (!dn) { dn = { sums: zeroSums(), ds: r.ds, de: r.de }; mn.days.set(dk, dn); }
      addRow(dn.sums, r);
    }
    // year 粒度下也要能给出年小计：重算（year 模式跳过了 years 累计以省时，这里补）
    if (granularity === 'year') {
      for (const r of rows) {
        if (!pass(f['国家'], r.d['国家']) || !pass(f['店铺'], r.d['店铺']) || !pass(f['负责人'], r.d['Listing负责人']) ||
          !pass(f['部门'], r.d['部门']) || !pass(f['分类'], r.d['分类'])) continue;
        const y = r.ds.slice(0, 4); const ym2 = r.ds.slice(0, 7);
        if (!pass(f.years, y) || !pass(f.months, ym2)) continue;
        const pn = top.get(r.d['父品名汇总']);
        let yn = pn.years.get(y); if (!yn) { yn = { sums: zeroSums(), months: new Map() }; pn.years.set(y, yn); }
        addRow(yn.sums, r);
      }
    }
    // 物化为有序数组：父品名按销售额降序，年月日按时间升序
    const tree = Array.from(top.entries()).map(([name, pn]) => ({
      name: name,
      sums: pn.sums, metrics: metricsOf(pn.sums),
      years: Array.from(pn.years.entries()).sort((a, b) => a[0] < b[0] ? -1 : 1).map(([y, yn]) => ({
        year: y, sums: yn.sums, metrics: metricsOf(yn.sums),
        months: Array.from(yn.months.entries()).sort((a, b) => a[0] < b[0] ? -1 : 1).map(([ym2, mn]) => ({
          ym: ym2, label: MONTH_EN[+ym2.slice(5, 7) - 1], sums: mn.sums, metrics: metricsOf(mn.sums),
          days: Array.from(mn.days.values()).sort((a, b) => a.ds < b.ds ? -1 : 1).map((dn) => ({
            ds: dn.ds, de: dn.de, fullMonth: isFullMonth(dn.ds, dn.de), sums: dn.sums, metrics: metricsOf(dn.sums)
          }))
        }))
      }))
    })).sort((a, b) => b.sums['销售额'] - a.sums['销售额']);
    const monthlyArr = Array.from(monthly.entries()).sort((a, b) => a[0] < b[0] ? -1 : 1)
      .map(([ym2, s]) => ({ ym: ym2, sales: s['销售额'], gross: s['毛利'] }));
    return { tree: tree, total: { sums: total, metrics: metricsOf(total) }, monthly: monthlyArr };
  }

  /* ---------- 6. 维度取值（供筛选器） ---------- */
  function dimValues(rows) {
    const acc = { '国家': new Map(), '店铺': new Map(), '负责人': new Map(), '部门': new Map(), '分类': new Map(), years: new Set(), months: new Set() };
    const bump = (m, v) => { if (v) m.set(v, (m.get(v) || 0) + 1); };
    rows.forEach((r) => {
      bump(acc['国家'], r.d['国家']); bump(acc['店铺'], r.d['店铺']); bump(acc['负责人'], r.d['Listing负责人']);
      bump(acc['部门'], r.d['部门']); bump(acc['分类'], r.d['分类']);
      acc.years.add(r.ds.slice(0, 4)); acc.months.add(r.ds.slice(0, 7));
    });
    const sortKeys = (m) => Array.from(m.keys()).sort((a, b) => a.localeCompare(b, 'zh-Hans-CN'));
    return {
      '国家': sortKeys(acc['国家']), '店铺': sortKeys(acc['店铺']), '负责人': sortKeys(acc['负责人']),
      '部门': sortKeys(acc['部门']), '分类': sortKeys(acc['分类']),
      years: Array.from(acc.years).sort(), months: Array.from(acc.months).sort()
    };
  }

  return { matchKey, resolveHeader, mapHeaders, parseDateCell, isFullMonth, parseNumber, serialToYMD,
    buildRows, aggregate, dimValues, rowKey, DIM_COLS, NUM_COLS, REQUIRED, SUM_KEYS, MONTH_EN };
})();
if (typeof module !== 'undefined') module.exports = PivotCore;

