const fs = require('fs');
const { JSDOM } = require('jsdom');
let failures = 0;
const assert = (c, m) => { if (!c) { failures++; console.error('FAIL: ' + m); } else console.log('ok  : ' + m); };
const tick = (ms) => new Promise(r => setTimeout(r, ms || 30));

(async () => {
  const html = fs.readFileSync('dist/sales-pivot.html', 'utf8');
  const dom = new JSDOM(html, {
    runScripts: 'dangerously',
    url: 'https://example.github.io/sales/',
    pretendToBeVisual: true,
    beforeParse(w) {
      w.confirm = () => true;                       // 危险操作一律确认
      w.URL.createObjectURL = () => 'blob:fake';    // 下载桩
      w.URL.revokeObjectURL = () => {};
      w.HTMLAnchorElement.prototype.click = function () { w.__lastDownload = this.download; };
    }
  });
  const w = dom.window, d = w.document;
  const $ = id => d.getElementById(id);
  await tick(80); // 等 DB.open→loadAll→bind→renderAll

  // 0. 外部 CDN 不可用环境（jsdom 不加载外链脚本）：应走内存兜底 + 空库空态
  assert(typeof w.XLSX === 'undefined', '模拟环境无 SheetJS（CDN 失败路径）');
  assert($('storageBadge').classList.contains('warn'), '无 IndexedDB → 内存兜底徽章');
  assert($('pivotEmpty').style.display !== 'none', '空库显示空态引导');

  // 1. 载入内置示例 → 校验报告
  $('btnDemo').dispatchEvent(new w.Event('click'));
  await tick();
  assert($('importReport').textContent.indexOf('10') >= 0, '校验报告出现（10 行）');
  assert(d.querySelector('input[name="dupStrategy"]'), '重复策略单选存在');
  assert($('importReport').textContent.indexOf('2026-01') >= 0, '期间覆盖 2026-01');

  // 2. 确认入库 → 透视渲染
  $('btnCommit').dispatchEvent(new w.Event('click'));
  await tick();
  assert($('dataCount').textContent.indexOf('10 行') >= 0, '入库后计数 10 行 1 批');
  assert(d.querySelectorAll('#pivotWrap tr.lv0').length === 5, '透视表 5 个父品名层');
  assert(d.querySelectorAll('#pivotWrap tr.grand').length === 1, '总计行存在');
  assert($('kpiRow').textContent.indexOf('22,850') >= 0, 'KPI 销量合计 22,850');
  assert($('trendBox').querySelector('svg'), '月度趋势 SVG 渲染');
  const lv0Names = Array.from(d.querySelectorAll('#pivotWrap tr.lv0 .nm')).map(x => x.textContent);
  assert(lv0Names[0].indexOf('10寸方形') >= 0, '父品名按销售额降序，首位 10寸方形');

  // 3. 粒度切换：日 → 出现日期桶行 + 整月标记
  d.querySelector('#granSeg button[data-g="day"]').dispatchEvent(new w.Event('click'));
  await tick();
  assert(d.querySelectorAll('#pivotWrap tr.lv3').length === 5, '日粒度出现 5 个日期桶行');
  assert($('pivotWrap').textContent.indexOf('整月') >= 0, '整月区间标记');
  d.querySelector('#granSeg button[data-g="month"]').dispatchEvent(new w.Event('click'));
  await tick();

  // 4. 筛选：店铺 A0002-US → KPI 变化到该店铺销售额
  const shopChip = Array.from(d.querySelectorAll('#filterArea .chip')).find(c => c.textContent === 'A0002-US');
  assert(!!shopChip, '店铺筛选 chip 存在');
  shopChip.dispatchEvent(new w.Event('click', { bubbles: true }));
  await tick();
  assert($('pivotScope').textContent.indexOf('A0002-US') >= 0, '口径行显示店铺筛选');
  // A0002-US 四行销售额和 = 422051.84+217768.89+85328.69+314266.46 = 1039415.88
  assert($('kpiRow').textContent.indexOf('1,039,415.88') >= 0, '筛选后销售额合计正确');
  // 清除筛选
  const allChip = Array.from(d.querySelectorAll('#filterArea .chip.all'))[1];
  allChip.dispatchEvent(new w.Event('click', { bubbles: true }));
  await tick();

  // 5. 折叠/展开
  const firstCaret = d.querySelector('#pivotWrap .caret');
  firstCaret.dispatchEvent(new w.Event('click', { bubbles: true }));
  await tick();
  assert(d.querySelectorAll('#pivotWrap tr.lv1').length === 4, '折叠首个父品名后年层减少到 4');
  $('btnExpandAll').dispatchEvent(new w.Event('click'));
  await tick();
  assert(d.querySelectorAll('#pivotWrap tr.lv1').length === 5, '全部展开恢复 5 个年层');
  $('btnCollapseAll').dispatchEvent(new w.Event('click'));
  await tick();
  assert(d.querySelectorAll('#pivotWrap tr.lv1').length === 0, '全部收起后无年层');
  $('btnExpandAll').dispatchEvent(new w.Event('click'));

  // 6. 重复导入 → 判重 + 跳过策略
  $('btnDemo').dispatchEvent(new w.Event('click'));
  await tick();
  const repTxt = $('importReport').textContent;
  assert(repTxt.indexOf('10') >= 0 && d.querySelector('.repgrid b.warn'), '二次导入检出 10 行重复');
  assert(repTxt.indexOf('期间重叠') >= 0, '期间×店铺重叠提示出现');
  $('btnCommit').dispatchEvent(new w.Event('click'));
  await tick();
  assert($('dataCount').textContent.indexOf('10 行') >= 0, '跳过策略下总行数仍为 10');
  assert($('importReport').textContent.indexOf('跳过重复 10 行') >= 0, '入库结果说明跳过 10 行');

  // 7. 粘贴 CSV 导入新月份（2026-02）→ 追加成功
  $('pasteArea').value = [
    '国家,日期,店铺,Listing负责人,父品名汇总,品名,SKU,MSKU,ASIN,销量,销售额,毛利,广告费,促销折扣,推广费,月仓储,长期仓储,FBA销毁费,FBA移除费,其他仓储费',
    '美国,2026-02-01~2026-02-28,A0002-US,魏荷芬,10寸方形,"KKD10寸,蓝",A1-210C-BLU,LCD-CS-BLUE-10-X,B082KFTF41,"3,000","300,000.50",(15000),-9000,-3000,-3000.005,-100,0,0,0,-50'
  ].join('\n');
  $('btnParsePaste').dispatchEvent(new w.Event('click'));
