const fs = require('fs');
const { JSDOM } = require('jsdom');
let failures = 0;
const assert = (c, m) => { if (!c) { failures++; console.error('FAIL: ' + m); } else console.log('ok  : ' + m); };
const tick = (ms) => new Promise(r => setTimeout(r, ms || 30));

(async () => {
  const html = fs.readFileSync('dist/sales-pivot.html', 'utf8');
  const dom = new JSDOM(html, {
    runScripts: 'dangerously',
    url: 'https://example.github.io/sales/',
    pretendToBeVisual: true,
    beforeParse(w) {
      w.confirm = () => true;                       // 危险操作一律确认
      w.URL.createObjectURL = () => 'blob:fake';    // 下载桩
      w.URL.revokeObjectURL = () => {};
      w.HTMLAnchorElement.prototype.click = function () { w.__lastDownload = this.download; };
    }
  });
  const w = dom.window, d = w.document;
  const $ = id => d.getElementById(id);
  await tick(80); // 等 DB.open→loadAll→bind→renderAll

  // 0. 外部 CDN 不可用环境（jsdom 不加载外链脚本）：应走内存兜底 + 空库空态
  assert(typeof w.XLSX === 'undefined', '模拟环境无 SheetJS（CDN 失败路径）');
