  assert(repTxt.indexOf('期间重叠') >= 0, '期间×店铺重叠提示出现');
  $('btnCommit').dispatchEvent(new w.Event('click'));
  await tick();
  assert($('dataCount').textContent.indexOf('10 行') >= 0, '跳过策略下总行数仍为 10');
  assert($('importReport').textContent.indexOf('跳过重复 10 行') >= 0, '入库结果说明跳过 10 行');

  // 7. 粘贴 CSV 导入新月份（2026-02）→ 追加成功
  $('pasteArea').value = [
    '国家,日期,店铺,Listing负责人,父品名汇总,品名,SKU,MSKU,ASIN,销量,销售额,毛利,广告费,促销折扣,推广费,月仓储,长期仓储,FBA销毁费,FBA移除费,其他仓储费',
    '美国,2026-02-01~2026-02-28,A0002-US,魏荷芬,10寸方形,"KKD10寸,蓝",A1-210C-BLU,LCD-CS-BLUE-10-X,B082KFTF41,"3,000","300,000.50",(15000),-9000,-3000,-3000.005,-100,0,0,0,-50'
  ].join('\n');
  $('btnParsePaste').dispatchEvent(new w.Event('click'));
  await tick();
  assert($('importReport').textContent.indexOf('2026-02') >= 0, '粘贴 CSV 识别 2026-02');
  $('btnCommit').dispatchEvent(new w.Event('click'));
  await tick();
  assert($('dataCount').textContent.indexOf('11 行') >= 0, '追加后 11 行');
  assert(d.querySelectorAll('#pivotWrap tr.lv2').length >= 2, '月层出现 1 月与 2 月');
  assert($('pivotWrap').textContent.indexOf('-15,000.00') >= 0, '括号负数毛利入表(-15000)');

  // 8. 月份切片：只看 2026-02
  const febChip = Array.from(d.querySelectorAll('#sliceArea .chip')).find(c => c.dataset.month === '2026-02');
  febChip.dispatchEvent(new w.Event('click', { bubbles: true }));
  await tick();
  assert($('kpiRow').textContent.indexOf('300,000.50') >= 0, '月切片后销售额=2月单行');
  Array.from(d.querySelectorAll('#sliceArea .chip.all')).forEach(c => c.dispatchEvent(new w.Event('click', { bubbles: true })));
  await tick();

  // 9. 导出（CSV 路径，XLSX 缺库时自动降级也走 CSV）
  $('btnExportC').dispatchEvent(new w.Event('click'));
  await tick();
  assert(String(w.__lastDownload || '').indexOf('销售透视_') === 0, 'CSV 导出触发下载');
  $('btnExportX').dispatchEvent(new w.Event('click'));
  await tick();
  assert(String(w.__lastDownload || '').slice(-4) === '.csv', '无 SheetJS 时 Excel 导出降级为 CSV');

  // 10. 备份 → 明细浏览 → 批次删除
  $('btnBackup').dispatchEvent(new w.Event('click'));
  assert(String(w.__lastDownload || '').indexOf('销售明细库备份_') === 0, '备份 JSON 触发下载');
  d.querySelector('.tabbar button[data-tab="browse"]').dispatchEvent(new w.Event('click'));
  $('browseQ').value = '点读笔';
  $('browseQ').dispatchEvent(new w.Event('input'));
  await tick();
  assert($('browseTable').textContent.indexOf('PP001点读笔') >= 0, '明细搜索命中点读笔');
  assert($('browsePager').textContent.indexOf('共 1 行') >= 0, '搜索计数正确');
  d.querySelector('.tabbar button[data-tab="batches"]').dispatchEvent(new w.Event('click'));
  const delBtns = d.querySelectorAll('[data-delbatch]');
  assert(delBtns.length === 3, '三个批次留档（示例、重复导入、CSV 追加）');
  // 删除 CSV 那批（最新一批）→ 回到 10 行
  delBtns[0].dispatchEvent(new w.Event('click', { bubbles: true }));
  await tick();
  assert($('dataCount').textContent.indexOf('10 行') >= 0, '删除批次后回滚到 10 行');

  console.log('\n' + (failures ? '=== 冒烟存在失败 ===' : '=== 集成冒烟全部通过 ==='));
  process.exit(failures ? 1 : 0);
})().catch(e => { console.error('SMOKE CRASH:', e); process.exit(1); });

