// ==UserScript==
// @name         悬停取词 · Hover Dict
// @namespace    https://cavno.github.io/
// @version      0.1.0
// @description  按住 Shift 把鼠标指向任意英文单词，即时弹出释义。本地词典优先，在线兜底。
// @match        *://*/*
// @grant        GM_xmlhttpRequest
// @connect      cavno.github.io
// @connect      api.dictionaryapi.dev
// @run-at       document-idle
// ==/UserScript==

(() => {
  'use strict';

  // ═══════════════════ 配置 ═══════════════════
  const CFG = {
    // 触发修饰键：'shiftKey' | 'altKey' | 'ctrlKey' | null
    // 设为 null 是纯悬停，鼠标扫过就弹窗，极吵。除非你真的想要，否则别改。
    modifier: 'shiftKey',

    dwell: 120,        // 鼠标在同一个词上停留多少毫秒才查
    minLen: 2,         // 短于此长度的词不查（a / I 之类）
    maxLen: 32,

    // 本地词典分片：按首两字母切片，形如 <base>ab.json
    // 每片是一个扁平对象 { "abandon": "vt. 遗弃；放弃", ... }
    // 留空则跳过本地词典，直接走在线兜底。
    shardBase: '',     // 例：'https://cavno.github.io/dict/'

    // 在线兜底（免费英英，无需 key）。想换有道/DeepL 在 fetchOnline 里改。
    onlineEnabled: true,
  };

  // ═══════════════════ 状态 ═══════════════════
  const memCache = new Map();     // word -> {text} | null
  const shardCache = new Map();   // 'ab' -> Promise<Object>
  let lastWord = '';
  let dwellTimer = 0;
  let rafPending = false;
  let lastEvt = null;

  // ═══════════════════ 浮层（Shadow DOM 隔离，不受页面 CSS 污染）═══════════════════
  const host = document.createElement('div');
  host.style.cssText = 'all:initial;position:fixed;top:0;left:0;z-index:2147483647;';
  const root = host.attachShadow({ mode: 'closed' });
  root.innerHTML = `
    <style>
      :host { all: initial; }
      .card {
        position: fixed; max-width: 340px; padding: 10px 13px;
        background: #F3EAD3; color: #23201B;
        border: 1px solid rgba(35,32,27,.18);
        border-left: 3px solid #C2643F;
        border-radius: 3px;
        box-shadow: 0 6px 22px rgba(35,32,27,.22);
        font: 14px/1.6 "Noto Serif SC", Georgia, serif;
        opacity: 0; transform: translateY(-3px);
        transition: opacity .1s ease, transform .1s ease;
        pointer-events: none; white-space: pre-wrap;
      }
      .card.show { opacity: 1; transform: none; }
      .w { display:block; font-size:12px; letter-spacing:.04em; text-transform:lowercase;
           color:#2A6F6B; margin-bottom:3px; font-family: ui-monospace, monospace; }
      .m { color:#6B6459; font-style:italic; }
      .u { position: fixed; height: 2px; background: #C2643F; opacity: 0; pointer-events: none; }
      .u.show { opacity: .7; }
      @media (prefers-color-scheme: dark) {
        .card { background:#22201C; color:#E8E1D2; border-color:rgba(232,225,210,.16); }
        .m { color:#9A9284; }
      }
    </style>
    <div class="card"><span class="w"></span><span class="d"></span></div>
    <div class="u"></div>`;
  const card = root.querySelector('.card');
  const elW = root.querySelector('.w');
  const elD = root.querySelector('.d');
  const under = root.querySelector('.u');
  document.documentElement.appendChild(host);

  function hide() {
    card.classList.remove('show');
    under.classList.remove('show');
    lastWord = '';
  }

  function show(word, def, rect) {
    elW.textContent = word;
    elD.textContent = def ?? '查不到';
    elD.className = def ? 'd' : 'd m';

    // 先渲染再量尺寸，避免翻转判断用到旧值
    card.style.left = '-9999px';
    card.style.top = '0';
    card.classList.add('show');
    const cw = card.offsetWidth, ch = card.offsetHeight;

    let x = rect.left;
    let y = rect.bottom + 8;
    if (x + cw > innerWidth - 8) x = innerWidth - cw - 8;
    if (x < 8) x = 8;
    if (y + ch > innerHeight - 8) y = rect.top - ch - 8;   // 下方放不下就翻到上方
    card.style.left = x + 'px';
    card.style.top = Math.max(8, y) + 'px';

    under.style.left = rect.left + 'px';
    under.style.top = (rect.bottom - 1) + 'px';
    under.style.width = rect.width + 'px';
    under.classList.add('show');
  }

  // ═══════════════════ 核心：从坐标取出单词 ═══════════════════
  const WORD = /[A-Za-z\u2019'-]/;

  function wordAt(x, y) {
    // Firefox 原生标准 API；Chrome 116+ 才有，旧 Chrome 用 caretRangeFromPoint
    const pos = document.caretPositionFromPoint?.(x, y);
    if (!pos) return null;
    const node = pos.offsetNode;
    if (!node || node.nodeType !== Node.TEXT_NODE) return null;

    // 输入框 / 可编辑区不干扰
    const el = node.parentElement;
    if (!el || el.closest('input,textarea,[contenteditable=""],[contenteditable="true"]')) return null;

    const text = node.nodeValue;
    let i = Math.min(pos.offset, text.length - 1);
    if (i < 0 || !WORD.test(text[i])) {
      // 光标可能落在词尾右侧的空格上，往左退一格再试
      if (i > 0 && WORD.test(text[i - 1])) i -= 1; else return null;
    }
    let s = i, e = i + 1;
    while (s > 0 && WORD.test(text[s - 1])) s--;
    while (e < text.length && WORD.test(text[e])) e++;

    const raw = text.slice(s, e).replace(/^[-']+|[-']+$/g, '');
    if (raw.length < CFG.minLen || raw.length > CFG.maxLen) return null;
    if (!/^[A-Za-z]/.test(raw)) return null;

    // 用 Range 量出这个词的真实矩形——鼠标可能悬在词的任意位置，
    // 浮层要对齐词本身，不是对齐光标
    const r = document.createRange();
    r.setStart(node, s); r.setEnd(node, e);
    const rects = r.getClientRects();
    if (!rects.length) return null;

    // 折行时取包含鼠标 y 的那一行
    let rect = rects[0];
    for (const cr of rects) if (y >= cr.top && y <= cr.bottom) { rect = cr; break; }

    return { word: raw, rect };
  }

  // ═══════════════════ 查词 ═══════════════════
  // 粗糙但够用的词形还原：running → run, studies → study
  function* lemmas(w) {
    yield w;
    const L = w.length;
    if (w.endsWith('ies') && L > 4) yield w.slice(0, -3) + 'y';
    if (w.endsWith('es') && L > 3) yield w.slice(0, -2);
    if (w.endsWith('s') && !w.endsWith('ss') && L > 2) yield w.slice(0, -1);
    if (w.endsWith('ing') && L > 4) {
      const st = w.slice(0, -3);
      yield st; yield st + 'e';
      if (/([bdfglmnprt])\1$/.test(st)) yield st.slice(0, -1);
    }
    if (w.endsWith('ed') && L > 3) {
      const st = w.slice(0, -2);
      yield st; yield w.slice(0, -1);
      if (/([bdfglmnprt])\1$/.test(st)) yield st.slice(0, -1);
    }
    if (w.endsWith('ly') && L > 4) yield w.slice(0, -2);
    if (w.endsWith('er') && L > 4) { yield w.slice(0, -2); yield w.slice(0, -1); }
    if (w.endsWith('est') && L > 5) { yield w.slice(0, -3); yield w.slice(0, -2); }
  }

  function loadShard(key) {
    if (!shardCache.has(key)) {
      shardCache.set(key, fetch(CFG.shardBase + key + '.json')
        .then(r => r.ok ? r.json() : {})
        .catch(() => ({})));
    }
    return shardCache.get(key);
  }

  async function lookupLocal(word) {
    if (!CFG.shardBase) return null;
    const key = word.slice(0, 2).toLowerCase();
    if (!/^[a-z]{2}$/.test(key)) return null;
    const dict = await loadShard(key);
    for (const cand of lemmas(word.toLowerCase())) {
      if (dict[cand]) return cand === word.toLowerCase() ? dict[cand] : `${cand} · ${dict[cand]}`;
    }
    return null;
  }

  function lookupOnline(word) {
    if (!CFG.onlineEnabled) return Promise.resolve(null);
    const url = `https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(word)}`;
    return new Promise(resolve => {
      // 用 GM_xmlhttpRequest 绕过页面 CSP —— 直接 fetch 在很多站点会被拦
      GM_xmlhttpRequest({
        method: 'GET', url, timeout: 4000,
        onload: res => {
          try {
            const j = JSON.parse(res.responseText);
            const ms = j?.[0]?.meanings ?? [];
            const out = ms.slice(0, 3).map(m =>
              `${m.partOfSpeech}. ${m.definitions[0].definition}`).join('\n');
            resolve(out || null);
          } catch { resolve(null); }
        },
        onerror: () => resolve(null),
        ontimeout: () => resolve(null),
      });
    });
  }

  async function lookup(word) {
    const k = word.toLowerCase();
    if (memCache.has(k)) return memCache.get(k);
    let def = await lookupLocal(k);
    if (!def) def = await lookupOnline(k);
    memCache.set(k, def);
    if (memCache.size > 800) memCache.delete(memCache.keys().next().value);
    return def;
  }

  // ═══════════════════ 事件 ═══════════════════
  function process(e) {
    if (CFG.modifier && !e[CFG.modifier]) { if (lastWord) hide(); return; }

    const hit = wordAt(e.clientX, e.clientY);
    if (!hit) { if (lastWord) hide(); return; }
    if (hit.word === lastWord) return;      // 同一个词，不重复查

    lastWord = hit.word;
    clearTimeout(dwellTimer);
    dwellTimer = setTimeout(async () => {
      const w = hit.word;
      const def = await lookup(w);
      if (lastWord === w) show(w, def, hit.rect);   // 期间鼠标没移开才显示
    }, CFG.dwell);
  }

  // mousemove 频率极高，用 rAF 折叠成每帧最多一次
  addEventListener('mousemove', e => {
    lastEvt = e;
    if (rafPending) return;
    rafPending = true;
    requestAnimationFrame(() => { rafPending = false; process(lastEvt); });
  }, { passive: true, capture: true });

  addEventListener('keyup', e => { if (e.key === 'Shift') hide(); }, true);
  addEventListener('scroll', hide, { passive: true, capture: true });
  addEventListener('blur', hide);
})();

