const fs = require('fs');
const MP = '/home/claude/xizhe';
const OUT = '/home/claude/web';

const { LECTURES } = require(MP + '/data/lectures.js');
const { SPINE, THREADS } = require(MP + '/data/threads.js');
const { CONCEPTS, DUALITIES } = require(MP + '/data/atlas.js');
const { BANDS } = require(MP + '/data/figures.js');

const DATA = { LECTURES, SPINE, THREADS, CONCEPTS, DUALITIES, BANDS };

// JSON 注入安全处理:防止 </script> 提前闭合、行分隔符破坏字面量
const json = JSON.stringify(DATA)
  .replace(/</g, '\\u003c')
  .replace(/>/g, '\\u003e')
  .replace(/\u2028/g, '\\u2028')
  .replace(/\u2029/g, '\\u2029');

