// 近似渲染器 v2:复刻 WXML 模板 + WXSS(rpx→px ×0.5)
const fs = require('fs');
const path = require('path');
const ROOT = '/home/claude/xizhe';

function cssOf(...files) {
  let css = files.map(f => fs.readFileSync(path.join(ROOT, f), 'utf-8')).join('\n');
  css = css.replace(/page\s*\{/g, 'body {');
  css = css.replace(/(-?\d+(?:\.\d+)?)rpx/g, (m, n) => (parseFloat(n) * 0.5) + 'px');
  return css;
}
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const doc = (body, css, title) => `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${title}</title>
<style>*{margin:0;padding:0;box-sizing:border-box}span{display:inline}${css}</style></head><body>${body}</body></html>`;

const { LECTURES } = require(ROOT + '/data/lectures.js');
const { SPINE, THREADS } = require(ROOT + '/data/threads.js');
const { CONCEPTS, DUALITIES } = require(ROOT + '/data/atlas.js');
const { BANDS } = require(ROOT + '/data/figures.js');

/* index */
function renderIndex() {
  const chain = [
    { name: '人类出现', on: false }, { name: '语言诞生', on: false },
    { name: '图腾禁忌', on: true }, { name: '巫术仪式', on: true },
    { name: '神话史诗', on: true }, { name: '宗教', on: true },
    { name: '哲学', on: true }, { name: '科学', on: false }
  ];
  const specials = [
    { name: '思想脉络', sub: '六条贯穿线:恒常的追问 · 连续与转换 · 命运的长河 · Logos 的漂流 · 解释权的转移 · 语言的边界', accent: 'ink' },
    { name: '概念谱系', sub: '六条长河:Logos · 命运 · 一 · 灵魂 · 神圣 · 共相', accent: 'aegean' },
    { name: '张力总表', sub: '原始之分 · 希腊十六对 · 神学五矛盾 · 近代对子', accent: 'wine' },
    { name: '人物长廊', sub: '从巫师到康德,再到回望者', accent: 'gold' }
  ];
  let h = `<div class="wrap"><div class="hero"><span class="eyebrow">西方哲学史考察十讲 · 梅春雷</span>
  <span class="hero-title">前五讲 · 思想脉络</span>
  <span class="hero-sub">图腾禁忌 — 神话宗教 — 希腊哲学 — 神学千年 — 理性时代</span>
  <span class="hero-dates">2026.03 — 2026.07</span></div>
  <div class="card chain-card"><span class="chain-label">课程主轴 · 人应当用人类史来说明</span><div class="chain">`;
  chain.forEach((c, i) => {
    h += `<div class="chain-node ${c.on ? 'chain-node-on' : ''}"><span>${c.name}</span></div>`;
    if (i < chain.length - 1) h += `<span class="chain-arrow">→</span>`;
  });
  h += `</div><span class="chain-note">深色为前五讲覆盖段;「科学」与现代部分为课程后续。</span></div>
  <div class="quote"><span class="qmark">「</span><span class="qtx">认识你自己,就是认识历史。理解历史文化传统,才能理解世界,理解自己。</span><span class="qby">—— 孔德 · 课程开篇</span></div>
  <div class="thread-entry"><div class="te-left"><span class="te-name">思想脉络</span><span class="te-sub">六条贯穿线:恒常的追问 · 连续与转换 · 命运的长河 · Logos 的漂流 · 解释权的转移 · 语言的边界</span></div><span class="te-go">读</span></div>
  <span class="orn">· · ·</span><span class="sec-label">五讲讲义</span><div class="lec-list">`;
  LECTURES.forEach(l => {
    h += `<div class="lec-card ac-${l.accent}"><div class="lec-top"><span class="lec-num">${l.num}</span><span class="lec-date">${l.date}</span></div><span class="lec-title">${l.title}</span><span class="lec-sub">${esc(l.sub)}</span></div>`;
  });
  h += `</div><span class="orn">· · ·</span><span class="sec-label">专题工具</span><div class="sp-list">`;
  specials.forEach(s => {
    h += `<div class="sp-card"><div class="sp-dot sp-${s.accent}"></div><div class="sp-body"><span class="sp-name">${s.name}</span><span class="sp-sub">${esc(s.sub)}</span></div></div>`;
  });
  h += `</div><div class="foot"><span class="foot-tx">讲义来源:梅春雷《西方哲学史考察十讲》前五讲</span><span class="foot-tx">视频号:老K的呐喊</span></div></div>`;
  return doc(h, cssOf('app.wxss', 'pages/index/index.wxss'), 'index');
}

/* lecture */
function renderLecture(id) {
  const lec = LECTURES.find(l => l.id === id);
  const prev = LECTURES.find(l => l.id === id - 1) || null;
  const next = LECTURES.find(l => l.id === id + 1) || null;
  let h = `<div class="wrap"><div class="lhead ac-${lec.accent}"><div class="lhead-top"><span class="lhead-num">${lec.num}</span><span class="lhead-date">${lec.date}</span></div>
  <span class="lhead-title">${lec.title}</span><span class="lhead-sub">${esc(lec.sub)}</span>
  <div class="lhead-pos"><span>${esc(lec.pos)}</span></div>
  <div class="lhead-q ac-bg-${lec.accent}"><span class="lhead-q-label">核心之问</span><span class="lhead-q-tx">${esc(lec.q)}</span></div></div>
  <div class="link-strip"><div class="link-item"><span class="link-label">承前</span><span class="link-tx">${esc(lec.inherit)}</span></div>
  <div class="link-item"><span class="link-label">启后</span><span class="link-tx">${esc(lec.pass)}</span></div></div>`;
  lec.sections.forEach(s => {
    if (s.t === 'h') h += `<div class="sec-h"><span class="h-num ac-bg-${lec.accent}">${s.n}</span><span class="h-tx">${esc(s.tx)}</span></div>`;
    else if (s.t === 'lead') { h += `<div class="lead">`; s.tx.forEach(p => h += `<span class="lead-p">${esc(p)}</span>`); h += `</div>`; }
    else if (s.t === 'quote') h += `<div class="quote"><span class="qmark">「</span><span class="qtx">${esc(s.tx)}</span><span class="qby">—— ${esc(s.by)}</span></div>`;
    else if (s.t === 'def') h += `<div class="def-card"><div class="def-head"><span class="def-term">${s.term}</span><span class="def-en">${s.en}</span></div><span class="def-tx">${esc(s.tx)}</span></div>`;
    else if (s.t === 'cards') { h += `<div class="cgrid">`; s.items.forEach(c => h += `<div class="cg-card"><span class="cg-h ac-${lec.accent}">${esc(c.h)}</span><span class="cg-d">${esc(c.d)}</span></div>`); h += `</div>`; }
    else if (s.t === 'nums') { h += `<div class="nums">`; s.items.forEach((n, i) => h += `<div class="num-row"><div class="num-badge ac-bg-${lec.accent}"><span>${i + 1}</span></div><div class="num-body"><span class="num-h">${esc(n.h)}</span><span class="num-d">${esc(n.d)}</span></div></div>`); h += `</div>`; }
    else if (s.t === 'vs') {
      h += `<div class="vs"><div class="vs-head"><span class="vs-a">${esc(s.a)}</span><span class="vs-x">×</span><span class="vs-b">${esc(s.b)}</span></div>`;
      s.rows.forEach(r => h += `<div class="vs-row"><span class="vs-k">${esc(r.k)}</span><div class="vs-pair"><div class="vs-cell vs-cell-a"><span>${esc(r.a)}</span></div><div class="vs-cell vs-cell-b"><span>${esc(r.b)}</span></div></div></div>`);
      h += `</div>`;
    }
    else if (s.t === 'flow') {
      h += `<div class="flow card">`;
      s.items.forEach((f, i) => {
        h += `<div class="flow-step"><div class="flow-item"><div class="flow-dot ac-bg-${lec.accent}"></div><span class="flow-tx">${esc(f)}</span></div>`;
        if (i < s.items.length - 1) h += `<div class="flow-line"></div>`;
        h += `</div>`;
      });
      if (s.note) h += `<span class="flow-note">${esc(s.note)}</span>`;
      h += `</div>`;
    }
    else if (s.t === 'persons') {
      h += `<div class="persons">`;
      s.items.forEach(p => {
        h += `<div class="p-card"><div class="p-head"><span class="p-name">${esc(p.name)}</span><span class="p-dates">${esc(p.dates)}</span></div><span class="p-tag ac-${lec.accent}">${esc(p.tag)}</span><div class="p-pts">`;
        p.pts.forEach(pt => h += `<div class="p-pt"><div class="p-pt-dot"></div><span class="p-pt-tx">${esc(pt)}</span></div>`);
        h += `</div></div>`;
      });
      h += `</div>`;
    }
    else if (s.t === 'band') h += `<div class="band"><span>${esc(s.tx)}</span></div>`;
    else if (s.t === 'bridge') h += `<div class="bridge"><span class="bridge-label">承上启下</span><span class="bridge-tx">${esc(s.tx)}</span></div>`;
    else if (s.t === 'books') {
      h += `<div class="books"><span class="books-label">推荐书目</span>`;
      s.items.forEach(b => h += `<div class="book-row"><span class="book-h">${esc(b.h)}</span><span class="book-by">${esc(b.by)}</span></div>`);
      h += `</div>`;
    }
  });
  h += `<div class="lnav"><div class="lnav-btn ${prev ? '' : 'lnav-dis'}"><span>${prev ? '上一讲 · ' + prev.title : '已是第一讲'}</span></div><div class="lnav-btn lnav-home"><span>脉络</span></div><div class="lnav-btn ${next ? '' : 'lnav-dis'}"><span>${next ? '下一讲 · ' + next.title : '已是最后一讲'}</span></div></div>
  <div class="foot"><span class="foot-tx">梅春雷 · 西方哲学史考察十讲 · ${lec.num}</span></div></div>`;
  return doc(h, cssOf('app.wxss', 'pages/lecture/lecture.wxss'), 'lecture-' + id);
}

/* thread */
function renderThread() {
  let h = `<div class="wrap"><div class="thead"><span class="eyebrow">五讲如何连成一条河</span><span class="thead-title">思想脉络</span><span class="thead-sub">一条主轴 · 六条贯穿线——把图腾、神话、哲学、神学、近代理性读成同一个故事。</span></div>
  <span class="orn">· · ·</span><span class="t-sec">主轴 · 精神形式的演进</span><div class="spine">`;
  SPINE.forEach((st, i) => {
    h += `<div class="spine-row"><div class="spine-rail"><div class="spine-dot sd-${st.accent}"></div>${i < SPINE.length - 1 ? '<div class="spine-line"></div>' : ''}</div>
    <div class="spine-body"><div class="spine-top"><span class="spine-name">${st.name}</span><span class="spine-lec">${st.lec}</span></div>
    <span class="spine-role sr-${st.accent}">${st.role}</span><span class="spine-desc">${esc(st.desc)}</span></div></div>`;
  });
  h += `</div><span class="orn">· · ·</span><span class="t-sec">六条贯穿线</span>`;
  THREADS.forEach(th => {
    h += `<div class="th-block"><div class="th-head"><div class="th-no"><span>${th.id}</span></div><div class="th-head-tx"><span class="th-title">${esc(th.title)}</span><span class="th-sub">${esc(th.sub)}</span></div></div>
    <span class="th-intro">${esc(th.intro)}</span><div class="th-stops">`;
    th.stops.forEach(sp => h += `<div class="th-stop"><div class="th-stop-tag"><span>${sp.lec}</span></div><span class="th-stop-tx">${esc(sp.tx)}</span></div>`);
    h += `</div><div class="th-close"><span>${esc(th.close)}</span></div></div>`;
  });
  h += `<div class="foot"><span class="foot-tx">主轴各站可点按跳转至对应讲义</span></div></div>`;
  return doc(h, cssOf('app.wxss', 'pages/thread/thread.wxss'), 'thread');
}

/* atlas */
function renderAtlas(tab) {
  let h = `<div class="wrap"><div class="tabs"><div class="tab ${tab === 'concepts' ? 'tab-on' : ''}"><span>概念谱系</span></div><div class="tab ${tab === 'dual' ? 'tab-on' : ''}"><span>张力总表</span></div></div>`;
  if (tab === 'concepts') {
    h += `<span class="a-intro">六个概念,六条长河:看同一个词如何从神话流入哲学、神学,再流入近代——直至今天。</span>`;
    CONCEPTS.forEach(cv => {
      h += `<div class="cv-card"><div class="cv-head bd-${cv.accent}"><span class="cv-name">${cv.name}</span><span class="cv-cn">${cv.cn}</span></div><span class="cv-line">${esc(cv.line)}</span><div class="cv-stages">`;
      cv.stages.forEach((st, i) => {
        h += `<div class="cv-stage"><div class="cv-rail"><div class="cv-dot dt-${cv.accent}"></div>${i < cv.stages.length - 1 ? '<div class="cv-rail-line"></div>' : ''}</div>
        <div class="cv-body"><div class="cv-meta"><span class="cv-era">${st.era}</span><span class="cv-who">${esc(st.who)}</span></div><span class="cv-tx">${esc(st.tx)}</span></div></div>`;
      });
      h += `</div></div>`;
    });
  } else {
    h += `<span class="a-intro">张力是思想的发动机:每个时代都用一对核心对立组织其精神世界。</span>`;
    DUALITIES.forEach(dg => {
      h += `<div class="dg-block"><div class="dg-head"><div class="dg-bar bg-${dg.accent}"></div><span class="dg-title">${dg.title}</span></div><span class="dg-note">${esc(dg.note)}</span>`;
      dg.pairs.forEach(p => h += `<div class="dg-pair"><div class="dg-vs"><span class="dg-a">${esc(p.a)}</span><span class="dg-x">/</span><span class="dg-b">${esc(p.b)}</span></div><span class="dg-tx">${esc(p.tx)}</span></div>`);
      h += `</div>`;
    });
  }
  h += `<div class="foot"><span class="foot-tx">谱系与张力 · 跨五讲综合</span></div></div>`;
  return doc(h, cssOf('app.wxss', 'pages/atlas/atlas.wxss'), 'atlas-' + tab);
}

/* figures */
function renderFigures() {
  let h = `<div class="wrap"><div class="fhead"><span class="eyebrow">从巫师到康德,再到回望者</span><span class="fhead-title">人物长廊</span><span class="fhead-sub">五讲出场的思想者,按时代排成一条走廊。</span></div>`;
  BANDS.forEach(bd => {
    h += `<div class="fband"><div class="fband-head"><div class="fband-bar fb-${bd.accent}"></div><div class="fband-tx"><span class="fband-era">${bd.era}</span><span class="fband-note">${esc(bd.note)}</span></div></div>`;
    bd.list.forEach(p => h += `<div class="fp"><div class="fp-head"><span class="fp-name">${esc(p.name)}</span><span class="fp-dates">${esc(p.dates)}</span></div><span class="fp-tag">${esc(p.tag)}</span></div>`);
    h += `</div>`;
  });
  h += `<div class="foot"><span class="foot-tx">人物长廊 · 跨五讲综合</span></div></div>`;
  return doc(h, cssOf('app.wxss', 'pages/figures/figures.wxss'), 'figures');
}

const OUT = '/home/claude/preview';
fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(OUT + '/index.html', renderIndex());
fs.writeFileSync(OUT + '/lecture-5.html', renderLecture(5));
fs.writeFileSync(OUT + '/thread.html', renderThread());
fs.writeFileSync(OUT + '/atlas-concepts.html', renderAtlas('concepts'));
fs.writeFileSync(OUT + '/atlas-dual.html', renderAtlas('dual'));
fs.writeFileSync(OUT + '/figures.html', renderFigures());
console.log('generated:', fs.readdirSync(OUT).filter(f => f.endsWith('.html')).join(', '));

