/* ================= 第五讲 ================= */
const LECTURE5 = {
  id: 5,
  num: '第五讲',
  date: '2026 · 07 · 04',
  title: '从笛卡尔到康德',
  sub: '近代哲学与启蒙运动:理性的自立与自审',
  accent: 'teal',
  pos: '哲学的核心问题从「世界是什么」转向「人如何认识世界」:唯理论不断纯化理性而陷入独断,经验论不断彻底化经验而陷入怀疑;康德以哥白尼式革命让对象符合认知形式,为理性立法并划定边界——近代哲学的思想闭环在此完成,现代哲学由此起步。',
  q: '人类何以普遍必然地认识世界?——知识源于理性还是经验;当两条路各自走进绝境,哲学如何自救?',
  inherit: '唯名论与宗教改革释放的个体、经验与简约性(第四讲),加上文艺复兴的人文主义与科学革命的新方法——理性挣脱神学附庸,认知主体登场。',
  pass: '康德是终点亦是起点:德国观念论、现象学、分析哲学、存在主义都在他的问题框架内展开——现代哲学与「信仰的重生」(后续讲次)。',
  sections: [
    { t: 'lead', tx: [
      '中世纪哲学以神学为绝对核心,「信仰高于理性」,人类理性的价值仅在于为上帝存在提供论证,认知主体的独立地位被完全遮蔽。文艺复兴把哲学的重心从「上帝」拉回到「人」,科学革命以数学演绎与实验实证重塑方法——理性终于自立。',
      '从笛卡尔到康德的百年发展,始终围绕一个核心问题:知识的来源与合法性。它天然分化为两条对立且互补的路径——大陆唯理论与英国经验论——并在康德手中完成综合。'
    ]},

    { t: 'h', n: '一', tx: '时代语境:理性挣脱附庸' },
    { t: 'cards', items: [
      { h: '中世纪:信仰遮蔽理性', d: '以神学为绝对核心,遵循「信仰高于理性」;理性的价值仅在于论证上帝存在,认知主体的独立地位被完全遮蔽。' },
      { h: '文艺复兴:人文主义的觉醒', d: '人文主义思潮打破神学禁锢,将哲学重心从「上帝」重新拉回到「人」的存在、价值与认知本身,确立人的主体性地位。' },
      { h: '科学革命:方法论的重塑', d: '哥白尼、伽利略、牛顿的理论推翻亚里士多德体系,数学演绎与实验实证成为认识自然的新方法,彻底挑战传统的权威认知。' }
    ]},
    { t: 'band', tx: '核心转向:从古代哲学追问「世界的本原是什么」的本体论,转向近代哲学探究「人类何以普遍必然地认识世界」的认识论——哲学不再仅关注世界本身,更聚焦「人与世界的认知关系」。核心议题:知识的来源(经验还是理性)、知识的可靠性基础、人类认知能力的范围与限度。' },

    { t: 'h', n: '二', tx: '概念与地图:两条路径与一次综合' },
    { t: 'cards', items: [
      { h: '先天 A priori', d: '独立于一切经验、逻辑先于经验的认知形式,具有普遍性与必然性。' },
      { h: '后天 A posteriori', d: '源于感官经验、依托具体经验场景的认知内容,具有偶然性与特殊性。' },
      { h: '天赋观念', d: '唯理论的核心概念:人类理性与生俱来、无需后天习得的基础观念与认知原则。' },
      { h: '知觉 · 印象 · 观念', d: '经验论的核心范畴,构成人类经验认知的全部内容——也是休谟怀疑论的理论基础。' }
    ]},
    { t: 'vs', a: '大陆唯理论', b: '英国经验论', rows: [
      { k: '核心代表', a: '笛卡尔、斯宾诺莎、莱布尼茨', b: '洛克、贝克莱、休谟' },
      { k: '根本原则', a: '理性先验论', b: '经验后验论' },
      { k: '知识来源', a: '先天固有的理性能力与天赋观念', b: '感官经验与内心反省;心灵如同「白板」' },
      { k: '方法论', a: '逻辑演绎,构建普遍必然的真理体系', b: '对经验素材的整理与归纳' },
      { k: '动态演进', a: '不断纯化理性原则,规避经验的偶然性', b: '不断彻底化经验原则,从温和走向彻底的经验还原' },
      { k: '极致化困境', a: '独断论:无法证明理性与客观世界的契合', b: '怀疑论:消解知识的必然性,颠覆科学的哲学根基' }
    ]},
    { t: 'band', tx: '康德的批判综合:打破传统「知识符合对象」的认知模式,重构「对象符合主体先天认知形式」的先验认识论;以先天综合判断为核心,整合理性的先天性与经验的实在性,划定知识与信仰、现象与本体的边界——最终完成近代哲学的思想闭环。' },

    { t: 'h', n: '三', tx: '笛卡尔:近代哲学的真正开端' },
    { t: 'persons', items: [
      { name: '勒内·笛卡尔', dates: '1596—1650', tag: '「近代哲学之父」· 主体理性的确立 · 《谈谈方法》《第一哲学沉思集》《哲学原理》', pts: [
        '普遍怀疑的方法:为寻找不可动摇的真理基石,对一切感官经验、书本知识进行系统性怀疑,直至抵达绝对确定的起点。',
        '我思故我在(Cogito):即便怀疑一切,「我正在怀疑/思考」这一事实本身无法被怀疑——「思维主体」成为哲学的第一确定性基点。',
        '真理标准与心物二元:以「清晰、分明的观念」为真理准则;实体分为思维的心灵与广延的物质,二者互不依赖,构成世界的本原。',
        '上帝存在证明:我心中有一个无限完满的上帝观念,而我自身是不完满、会怀疑的有限存在,不可能是这个观念的来源——故它只能由真正无限完满的实体置于我心中,上帝必然存在。'
      ]}
    ]},
    { t: 'nums', items: [
      { h: '开创近代哲学', d: '完成从「本体论」到「认识论」的根本转向。' },
      { h: '唯理论源头', d: '划分近代两大认识论阵营,理性主义由此发端。' },
      { h: '塑造核心议题', d: '后世形而上学、心灵哲学的核心问题(身心关系、实体、观念)皆由其设定。' },
      { h: '方法论革新', d: '普遍怀疑与数学化演绎,革新科学范式。' },
      { h: '遗留永恒难题', d: '身心如何交互等难题悬而未决——持续推动后世反思。' }
    ]},

    { t: 'h', n: '四', tx: '斯宾诺莎:一元论与必然真理' },
    { t: 'persons', items: [
      { name: '巴鲁赫·斯宾诺莎', dates: '1632—1677', tag: '大陆唯理论第二位奠基人 · 《伦理学》(几何证明体系)《知性改进论》《神学政治论》', pts: [
        '神即自然(Deus sive Natura):宇宙间唯一的绝对实体即「神」或「自然」,是一切存在的根基——实体一元论消解笛卡尔的二元割裂;心灵与物质只是实体的两种属性,平行对应、共同表达实体本质(平行论替代交互论)。',
        '三重知识等级:想象/意见(源于感官与传闻,混乱片面,是错误来源)→ 理性(源于推理与公理,把握必然规律)→ 直观知识(理性直观把握实体本质,通达终极真理)。',
        '理性决定论与自由的真谛:万物皆受必然性支配,无偶然,一切在永恒因果链中;自由是对必然性的认识——凭理性理解秩序,摆脱情感奴役。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '「近代哲学的真正枢纽」', d: '黑格尔如此评价:以唯一实体一元论彻底消解二元割裂,以真观念自明性破除真理证明循环,把大陆理性主义推至逻辑彻底化形态,确立内在论形而上学。' },
      { h: '德国古典哲学与浪漫派', d: '谢林的自然哲学与同一哲学完全继承内在一元论;歌德、席勒推崇其泛神论,塑造浪漫派自然观;费尔巴哈与青年黑格尔派将内在神论解读为无神论唯物主义;马克思称其为「近代唯物主义的伟大代表」。' },
      { h: '身心平行论:永久议题', d: '副现象论、中立一元论、当代属性二元论均以其平行论为历史原型;「心灵是身体的观念」预现当代认知科学「意识对应身体活动」的基本框架。' },
      { h: '政教分离与圣经批判先河', d: '《神学政治论》是近代政教分离、思想自由的经典文献;拆解人格化上帝、去神话化圣经解读,开创圣经历史批判先河,影响后世宗教批判与世俗化思潮。' },
      { h: '尼采与德勒兹', d: '尼采的「权力意志」直接改造其「自我保存努力(Conatus)」;德勒兹《斯宾诺莎:实践哲学》复兴内在性与力量伦理学,成为当代后现代、生成论哲学的核心资源。' }
    ]},
    { t: 'band', tx: '遗留难题:平行论无法解释心理与物理为何精准对应(缺乏因果联结);一元实体如何分化出无限属性与有限样式(一与多难题);彻底决定论与道德责任、自由如何兼容;「对神的理智之爱」是否混淆形而上学实体与宗教情感——引发有神论与无神论的持续争辩。' },

    { t: 'h', n: '五', tx: '莱布尼茨:单子论与双重真理' },
    { t: 'persons', items: [
      { name: '戈特弗里德·莱布尼茨', dates: '1646—1716', tag: '大陆唯理论第三位奠基人 · 数学家、逻辑学家 · 《单子论》《新系统》《神正论》《人类理智新论》', pts: [
        '单子论:宇宙的终极实体是无广延、不可分的精神性「单子」;核心是「前定和谐」——上帝在创世之初预设所有单子的运动秩序,心灵与身体虽独立发展却始终完美同步,如两架精准的时钟。',
        '双重真理:必然的「推理真理」(数学、逻辑)与偶然的「事实真理」(自然科学)。',
        '有纹路的大理石:心灵并非白板,天赋观念潜存其中,经验是唤醒这些观念的机缘。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '完成唯理论完整体系', d: '以单子多元实体论折中前两条路径:既承认无数独立个体实体,又靠上帝前定和谐维系宇宙统一;确立充足理由律为独立核心公理;沃尔夫将其体系化为18世纪德国大学官方哲学——构成康德早年接受的「独断论形而上学」。' },
      { h: '康德的核心对话对手', d: '《纯粹理性批判》的核心任务之一就是清算莱布尼茨—沃尔夫独断唯理论;其现象/本体、感性知觉/理性认识、偶然事实/必然推理的划分,直接启发康德区分现象界与物自体、知性与理性;二律背反与模态范畴大量吸收其可能世界与真理类型论述。' },
      { h: '逻辑与可能世界', d: '最早提出普遍文字与数理逻辑构想;首创可能世界理论,区分现实世界与无限多逻辑可能世界;提出不可分辨者同一律——现代分析哲学与模态逻辑的奠基者。' },
      { h: '科学跨域', d: '独立创立微积分;发明二进制算术与自动演算机构想;区分动力因与目的因,调和机械论科学与目的论世界观;《神正论》开创系统的「恶之难题」哲学辩护路径。' }
    ]},
    { t: 'band', tx: '遗留难题:单子「无窗口」却能完整表象宇宙,内在表象的客观依据难以解释;前定和谐预设上帝一次性创世安排,自然主义框架下难以自洽;「最好可能世界」论证难以消解现实中的大量苦难;单子多元与宇宙统一之间存在一与多的内在张力。' },

    { t: 'h', n: '六', tx: '唯理论的整体局限:不可避免的独断论' },
    { t: 'nums', items: [
      { h: '脱离经验的先天预设', d: '体系建立在「实体」「上帝」等先天理性预设之上,缺乏直接经验验证,如同空中楼阁,难以获得直观的事实支撑。' },
      { h: '未经批判的独断倾向', d: '武断断言人类理性结构与外部世界结构必然契合,却无法证明:为何先天观念一定能反映客观实在?对理性的盲目崇信使其陷入独断论泥潭。' },
      { h: '具体经验的解释乏力', d: '过度强调知识的普遍必然性,难以合理解释具体、偶然、多样的经验科学事实——擅长构建宏大体系,面对真实自然现象却苍白无力。' }
    ]},
    { t: 'band', tx: '理性并非万能的钥匙:脱离经验的理性演绎,最终只能走向封闭的独断——这为经验论对知识来源的重新审视与批判,提供了必要的理论契机。' },

    { t: 'h', n: '七', tx: '洛克:经验论奠基与白板说' },
    { t: 'persons', items: [
      { name: '约翰·洛克', dates: '1632—1704', tag: '英国经验论奠基人 · 自由主义政治哲学之父 · 《人类理解论》《政府论(下篇)》《论宗教宽容》', pts: [
        '旗帜鲜明的反天赋论:儿童与智力障碍者并不拥有所谓先天公理或道德原则——这些观念实则是后天教育与社会习俗的产物。',
        '心灵白板说(Tabula Rasa):心灵在出生时如同一块「白板」,一切知识与观念都不是与生俱来,而是完全通过后天经验逐步书写上去的。',
        '第一与第二性质:第一性质是物体固有的客观属性(广延、形状、运动);第二性质是物体借助第一性质作用于感官而产生的主观感受(颜色、声音、气味),非物体本身固有。',
        '划定知识的有限边界:人只能认识经验赋予的观念,可以感知物体的各种属性,但永远无法认知实体本身的终极实在。'
      ]}
    ]},
    { t: 'band', tx: '洛克是温和经验论:并未彻底否定理性(承认理性可以整理、归纳经验素材),也保留了对物质实体与上帝存在的基本信念;但「一切观念源于经验」的核心立场,已彻底颠覆唯理论的理论根基,开启经验论的百年发展。' },
    { t: 'cards', items: [
      { h: '百年论战的开启者', d: '确立经验论核心纲领,与笛卡尔、斯宾诺莎、莱布尼茨的唯理论形成长达百年的认识论论战,构成近代哲学的核心线索;直接传承者:贝克莱、休谟。' },
      { h: '康德的对话对象', d: '对「现象知觉」与「不可知实体」的划分,直接启发康德区分现象界与物自体;对认知界限的反思,推动康德转向对认识能力本身的批判考察。' },
      { h: '自由主义与宪政源头', d: '《政府论》是现代自由主义、宪政民主的思想源头,经启蒙运动全欧传播,重塑现代革命与宪政。' },
      { h: '语言哲学与实证主义先驱', d: '第一/第二性质区分为机械论自然科学提供认识论基础;实体不可知论催生后世实证主义与不可知论传统;《人类理解论》第三卷系统讨论语言、观念、名称的关系,是近代语言哲学的重要先驱。' },
      { h: '教育与宽容', d: '《教育漫话》以白板说为根基,提出环境与经验塑造人的教育观;《论宗教宽容》是近代系统论证政教分离、信仰自由的里程碑。' }
    ]},

    { t: 'h', n: '八', tx: '贝克莱:消解物质实体' },
    { t: 'persons', items: [
      { name: '乔治·贝克莱', dates: '1685—1753', tag: '经验论的激进转折 · 主观唯心主义奠基人 · 《视觉新论》《人类知识原理》《三篇对话》', pts: [
        '存在就是被感知:所有事物认知都来源于感官感知的观念集合;所谓外物并非独立于心灵的物质实体,只是颜色、形状、硬度、气味等感官观念的组合——脱离感知,事物便无法被认知,也无存在的意义。',
        '诉诸上帝的永恒感知:为保证世界在无人感知时仍持续存在,引入上帝作为「永恒的感知者」——上帝的全知与持续观照,确保事物的客观性、连续性与自然秩序,填补经验论可能导致的虚无主义缺口。'
      ]}
    ]},
    { t: 'band', tx: '关键转折:洛克只是限制了人类对实体的认知,贝克莱则直接消解了物质实体本身——彻底贯彻洛克的经验论,同时釜底抽薪否定洛克设定的「物质实体」,将一切存在还原为心灵与观念,为休谟的彻底怀疑论铺平道路。' },
    { t: 'cards', items: [
      { h: '经验论激进路线的确立', d: '以经验一致性彻底清算洛克体系的内在矛盾;与休谟共同构成近代经验论巅峰,揭示纯粹经验原则内在的怀疑论后果,倒逼康德开启批判哲学。' },
      { h: '康德的批判对象', d: '康德在《纯粹理性批判》中专门区分先验唯心论(自身立场)与贝克莱的经验唯心论;其对知觉、表象、心灵建构经验的讨论,启发康德「知性范畴整理感性杂多」的认识论框架。' },
      { h: '现象论与实证主义资源', d: '密尔、马赫、罗素的现象论核心思路承其而来;马赫经验批判主义与维也纳学派继承「命题意义必须可被知觉验证」的经验标准;19世纪英国观念论与现象学亦吸收其「意识优先、存在依赖显现」的思考。' },
      { h: '视觉心理学与符号论', d: '《视觉新论》是近代知觉心理学奠基文本;提出「视觉是上帝的自然符号语言」,开创语言符号论思路。' }
    ]},
    { t: 'band', tx: '遗留难题:唯我论困境(如何证明他人与客观世界不只是我的私人观念);独断保留不可被知觉的精神实体(休谟随即指出这违背其自身经验论原则);客观秩序完全依托上帝意志,脱离宗教视角后难以解释知觉间稳定的关联;无法区分真实知觉与幻觉、梦境。' },

    { t: 'h', n: '九', tx: '休谟:经验论的极致与总危机' },
    { t: 'persons', items: [
      { name: '大卫·休谟', dates: '1711—1776', tag: '英国经验论集大成者 · 彻底怀疑论代表 · 《人性论》《人类理解研究》《道德原则研究》《自然宗教对话录》', pts: [
        '印象与观念:人类所有心理认知分为两类;经验论的终极准则——一切合法的观念必须有对应的原始印象支撑,无对应印象的观念皆是空洞无意义的幻想。',
        '因果与归纳的解构:感官印象中只有事物的先后伴随,没有必然的因果联系;从过去经验推导未来规律的归纳推理在逻辑上不严密——「未来必定与过去相似」这一假设本身无法被证明。',
        '知识的二元划界:观念关系的知识(数学、逻辑、几何)先天成立、绝对必然,但只是概念推演,无法拓展对现实世界的认知;事实存在的知识(自然科学、日常经验)能拓展认知,却完全基于偶然经验,不具备绝对必然性。',
        '形而上学的彻底否定:上帝、灵魂、实体、自由等所有形而上学核心概念,均无对应的感官印象支撑——按照经验准则,全部是人类虚构的空洞观念。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '唤醒康德', d: '「休谟打破了我独断论的迷梦」;其对理性、情感、事实与价值的划分,直接启发康德区分理论理性(认识自然)与实践理性(道德立法);其划定知识边界的怀疑精神,奠定「批判哲学」的核心任务。' },
      { h: '归纳问题两百年', d: '归纳问题成为科学哲学的核心议题,持续争论至今;对因果的心理学解释区分了逻辑必然性与经验习惯性,深刻影响模态逻辑与因果语义学;爱因斯坦自承,休谟对经验与因果的反思启发了相对论对经典时空因果观的重构。' },
      { h: '休谟法则:是—应当鸿沟', d: '划分描述性语言与规范性语言,成为20世纪元伦理学的核心框架,催生情感主义伦理学;「理性服务情感」颠覆传统理性至上的伦理观,开创道德情感主义传统。' },
      { h: '知觉束与实证主义', d: '知觉束理论开启无实体自我的心灵观;实证主义与维也纳学派继承「无印象则无意义」的经验划界标准;胡塞尔将休谟哲学视作现象学的重要预备。' },
      { h: '宗教与社会思想', d: '对神迹与自然神学的经验批判,成为后世世俗人文主义、宗教怀疑论的经典论证;人性论与习俗理论影响社会契约论与保守自由主义。' }
    ]},
    { t: 'band', tx: '遗留难题:归纳难题至今无公认完满解答;知觉束理论难以解释知觉的统一性与人格同一性;事实—价值二分引发持续争议;温和怀疑论自身存在内在张力。' },

    { t: 'h', n: '十', tx: '僵局:近代哲学的终极绝境' },
    { t: 'flow', items: ['洛克 · 温和奠基:保留实体,承认心灵的整理能力', '贝克莱 · 消解物质:存在即被感知,仅存精神与上帝', '休谟 · 剥离一切:因果沦为习惯,实体全部消解'], note: '经验论的彻底化三阶段——纠正了唯理论的空想独断,却使科学知识失去必然性基础。' },
    { t: 'nums', items: [
      { h: '唯理论的困境', d: '坚持理性可独立获得普遍必然知识,但缺乏经验根基,无法说明知识如何对应实在——沦为独断论。' },
      { h: '经验论的困境', d: '坚持知识来源于经验,但否定因果必然性,使科学知识沦为偶然归纳——失去普遍有效性。' },
      { h: '科学的危机', d: '近代科学依托因果规律构建,但休谟证明因果非客观必然——科学真理失去绝对的哲学基础。' },
      { h: '绝境的表征', d: '近代认识论在独断与怀疑之间摇摆:既无法为知识提供必然性证明,又无法放弃对普遍性的追求。' }
    ]},
    { t: 'cards', items: [
      { h: '自然科学的合法性危机', d: '科学的核心价值在于揭示普遍必然的自然规律,但其立足的因果律被证明无客观必然性——科学真理沦为偶然的经验归纳。' },
      { h: '道德与自由的危机', d: '若一切认知都是偶然经验,道德法则、自由意志、价值准则便失去普遍有效性——道德沦为个体主观偏好,价值秩序崩塌。' },
      { h: '传统形而上学的破产', d: '自古希腊以来对上帝、灵魂、实体、宇宙本原的超验追问,均无经验依据——形而上学彻底失去了作为科学的可能性。' }
    ]},
    { t: 'quote', tx: '休谟打破了我独断论的迷梦。', by: '康德' },
    { t: 'band', tx: '康德的诊断:近代哲学的所有争论,都源于未对人类理性本身进行批判考察——唯有先批判理性、划定理性的能力与边界,才能同时规避独断论与怀疑论,为知识、道德、形而上学重新奠基。这便是批判哲学的根本出发点。' },

    { t: 'h', n: '十一', tx: '康德:综合、超越与终结' },
    { t: 'persons', items: [
      { name: '伊曼努尔·康德', dates: '1724—1804', tag: '德国古典哲学开创者 · 近代哲学分水岭 · 三大批判 + 《道德形而上学奠基》《永久和平论》', pts: [
        '哥白尼式革命:传统认为知识必须符合对象,康德反转为「对象必须符合我们的认识形式」——人并非被动接收信息,而是带着先天的时空直观与知性范畴,主动整理和建构经验世界。',
        '现象界与物自体:能认识的「现象界」是经主体认知形式整理后的世界,是科学的合法疆域;独立于认知的「物自体」不可经验认识,仅能被理性思维——为信仰与道德保留空间。',
        '先天综合判断:数学与自然科学的基本命题兼具「先天」的普遍必然性与「综合」的知识扩展性——调和唯理论与经验论的对立,为科学知识的确定性提供哲学证明;感性先天形式是时间与空间,知性先天范畴(因果性、实体性等)是思维整理经验的规则。',
        '先验辩证论:揭示理性的越界与困境,完成对传统形而上学的批判与祛魅。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '《纯粹理性批判》', d: '核心问题:我能够知道什么?——为「知性」立法,划定科学知识的范围与界限,回答普遍必然的科学知识何以可能。' },
      { h: '《实践理性批判》', d: '核心问题:我应当做什么?——为「理性」自身立法,提出道德法则的「定言命令」,确立「人是目的而非手段」的伦理基石,论证自由意志的客观实在性。' },
      { h: '《判断力批判》', d: '核心问题:我可以希望什么?——以审美判断力与目的论为桥梁,沟通自然的必然性与道德的自由,完成哲学体系的最终统一。' }
    ]},
    { t: 'band', tx: '三大批判分别对应知识、道德与审美(信仰),共同构筑「真、善、美」合一的宏大体系——回答关于人类理性与存在的终极问题。' },
    { t: 'nums', items: [
      { h: '完成「批判转向」', d: '化解休谟因果危机,推翻莱布尼茨—沃尔夫独断形而上学,同时限定经验论的认知边界——终结前康德的独断论与经验论。' },
      { h: '义务论伦理学奠基', d: '颠覆古代幸福论与功利主义后果论;「人是目的」——罗尔斯正义论、哈贝马斯交往行动理论、当代道义论均直接继承其普遍立法与人格尊严原则;区分经验欲望与理性自律,重新定义自由。' },
      { h: '开启德国古典观念论', d: '费希特、谢林、黑格尔——整个德国古典哲学全部以回应、超越康德二元论为核心任务。' },
      { h: '美学独立化', d: '首次系统区分审美、认识、道德三种心灵活动;提出审美共通感,为审美普遍性与跨文化对话提供哲学基础——现代美学源头。' },
      { h: '现代思想源头', d: '先验方法深刻影响胡塞尔现象学;成为20世纪分析哲学与逻辑实证主义的核心争论起点;「人为自然立法」预现当代科学建构论。' },
      { h: '政治与人权基石', d: '《永久和平论》是联合国理念的源头;人格尊严思想写入《世界人权宣言》;区分公共理性与私人偏好,启发当代协商民主理论;经黑格尔中介影响马克思。' }
    ]},
    { t: 'nums', items: [
      { h: '物自体难题', d: '既然物自体完全不可认识,康德何以断定其存在?黑格尔与后世观念论直接取消物自体,实证主义则质疑这一空洞预设。' },
      { h: '现象与本体的二元割裂', d: '自然必然与道德自由如何真正统一?仅以审美作桥,未能彻底消解二元对立。' },
      { h: '定言命令形式空洞', d: '纯粹形式化的普遍法则缺少具体内容——黑格尔与功利主义批判其无法应对复杂现实的道德情境。' },
      { h: '先天综合判断的有效性', d: '20世纪逻辑学与数学的发展质疑「数学是先天综合判断」,引发持续论战。' },
      { h: '道德悬设的张力', d: '上帝与不朽仅具备实践有效性,无法思辨证明——信仰与知识之间的张力始终存在。' }
    ]},

    { t: 'h', n: '十二', tx: '历史意义:终点亦是起点' },
    { t: 'nums', items: [
      { h: '确立主体地位:理性的回归', d: '知识、真理与价值的终极根基,从超验的上帝与传统权威,彻底转移到人的理性自身——人类自我意识的真正觉醒。' },
      { h: '思想的辩证运动', d: '唯理论与经验论的长期对峙,充分暴露单一片面认知模式的内在缺陷——为康德的批判性综合提供了思想素材与理论土壤。' },
      { h: '康德的双重角色', d: '既是近代哲学的终点(以批判哲学终结二元对立),更是现代哲学的起点——其批判方法与问题框架深刻影响从德国古典哲学到存在主义的几乎所有后世流派。' },
      { h: '塑造现代精神', d: '不仅实现认识论革命,更深远地塑造了现代人类的理性精神、科学思维方式与基本价值秩序——为现代社会的伦理与文明形态奠基。' }
    ]},
    { t: 'bridge', tx: '康德既终结又开启:德国观念论以消解其二元论为使命,现象学与分析哲学在其先验方法与划界问题上分道扬镳。理性完成了对自身的审判,「信仰的危机」之后如何「重生」——现代哲学的故事从这里开始(后续讲次)。' },
    { t: 'books', items: [
      { h: '《第一哲学沉思集》', by: '笛卡尔' },
      { h: '《伦理学》', by: '斯宾诺莎' },
      { h: '《人类理解论》', by: '洛克' },
      { h: '《人性论》', by: '休谟' },
      { h: '《纯粹理性批判》', by: '康德' }
    ]}
  ]
};

module.exports = { LECTURE5 };

versions.content:
/* ================= 第五讲 ================= */
const LECTURE5 = {
  id: 5,
  num: '第五讲',
  date: '2026 · 07 · 04',
  title: '从笛卡尔到康德',
  sub: '近代哲学与启蒙运动:理性的自立与自审',
  accent: 'teal',
  pos: '哲学的核心问题从「世界是什么」转向「人如何认识世界」:唯理论不断纯化理性而陷入独断,经验论不断彻底化经验而陷入怀疑;康德以哥白尼式革命让对象符合认知形式,为理性立法并划定边界——近代哲学的思想闭环在此完成,现代哲学由此起步。',
  q: '人类何以普遍必然地认识世界?——知识源于理性还是经验;当两条路各自走进绝境,哲学如何自救?',
  inherit: '唯名论与宗教改革释放的个体、经验与简约性(第四讲),加上文艺复兴的人文主义与科学革命的新方法——理性挣脱神学附庸,认知主体登场。',
  pass: '康德是终点亦是起点:德国观念论、现象学、分析哲学、存在主义都在他的问题框架内展开——现代哲学与「信仰的重生」(后续讲次)。',
  sections: [
    { t: 'lead', tx: [
      '中世纪哲学以神学为绝对核心,「信仰高于理性」,人类理性的价值仅在于为上帝存在提供论证,认知主体的独立地位被完全遮蔽。文艺复兴把哲学的重心从「上帝」拉回到「人」,科学革命以数学演绎与实验实证重塑方法——理性终于自立。',
      '从笛卡尔到康德的百年发展,始终围绕一个核心问题:知识的来源与合法性。它天然分化为两条对立且互补的路径——大陆唯理论与英国经验论——并在康德手中完成综合。'
    ]},

    { t: 'h', n: '一', tx: '时代语境:理性挣脱附庸' },
    { t: 'cards', items: [
      { h: '中世纪:信仰遮蔽理性', d: '以神学为绝对核心,遵循「信仰高于理性」;理性的价值仅在于论证上帝存在,认知主体的独立地位被完全遮蔽。' },
      { h: '文艺复兴:人文主义的觉醒', d: '人文主义思潮打破神学禁锢,将哲学重心从「上帝」重新拉回到「人」的存在、价值与认知本身,确立人的主体性地位。' },
      { h: '科学革命:方法论的重塑', d: '哥白尼、伽利略、牛顿的理论推翻亚里士多德体系,数学演绎与实验实证成为认识自然的新方法,彻底挑战传统的权威认知。' }
    ]},
    { t: 'band', tx: '核心转向:从古代哲学追问「世界的本原是什么」的本体论,转向近代哲学探究「人类何以普遍必然地认识世界」的认识论——哲学不再仅关注世界本身,更聚焦「人与世界的认知关系」。核心议题:知识的来源(经验还是理性)、知识的可靠性基础、人类认知能力的范围与限度。' },

    { t: 'h', n: '二', tx: '概念与地图:两条路径与一次综合' },
    { t: 'cards', items: [
      { h: '先天 A priori', d: '独立于一切经验、逻辑先于经验的认知形式,具有普遍性与必然性。' },
      { h: '后天 A posteriori', d: '源于感官经验、依托具体经验场景的认知内容,具有偶然性与特殊性。' },
      { h: '天赋观念', d: '唯理论的核心概念:人类理性与生俱来、无需后天习得的基础观念与认知原则。' },
      { h: '知觉 · 印象 · 观念', d: '经验论的核心范畴,构成人类经验认知的全部内容——也是休谟怀疑论的理论基础。' }
    ]},
    { t: 'vs', a: '大陆唯理论', b: '英国经验论', rows: [
      { k: '核心代表', a: '笛卡尔、斯宾诺莎、莱布尼茨', b: '洛克、贝克莱、休谟' },
      { k: '根本原则', a: '理性先验论', b: '经验后验论' },
      { k: '知识来源', a: '先天固有的理性能力与天赋观念', b: '感官经验与内心反省;心灵如同「白板」' },
      { k: '方法论', a: '逻辑演绎,构建普遍必然的真理体系', b: '对经验素材的整理与归纳' },
      { k: '动态演进', a: '不断纯化理性原则,规避经验的偶然性', b: '不断彻底化经验原则,从温和走向彻底的经验还原' },
      { k: '极致化困境', a: '独断论:无法证明理性与客观世界的契合', b: '怀疑论:消解知识的必然性,颠覆科学的哲学根基' }
    ]},
    { t: 'band', tx: '康德的批判综合:打破传统「知识符合对象」的认知模式,重构「对象符合主体先天认知形式」的先验认识论;以先天综合判断为核心,整合理性的先天性与经验的实在性,划定知识与信仰、现象与本体的边界——最终完成近代哲学的思想闭环。' },

    { t: 'h', n: '三', tx: '笛卡尔:近代哲学的真正开端' },
    { t: 'persons', items: [
      { name: '勒内·笛卡尔', dates: '1596—1650', tag: '「近代哲学之父」· 主体理性的确立 · 《谈谈方法》《第一哲学沉思集》《哲学原理》', pts: [
        '普遍怀疑的方法:为寻找不可动摇的真理基石,对一切感官经验、书本知识进行系统性怀疑,直至抵达绝对确定的起点。',
        '我思故我在(Cogito):即便怀疑一切,「我正在怀疑/思考」这一事实本身无法被怀疑——「思维主体」成为哲学的第一确定性基点。',
        '真理标准与心物二元:以「清晰、分明的观念」为真理准则;实体分为思维的心灵与广延的物质,二者互不依赖,构成世界的本原。',
        '上帝存在证明:我心中有一个无限完满的上帝观念,而我自身是不完满、会怀疑的有限存在,不可能是这个观念的来源——故它只能由真正无限完满的实体置于我心中,上帝必然存在。'
      ]}
    ]},
    { t: 'nums', items: [
      { h: '开创近代哲学', d: '完成从「本体论」到「认识论」的根本转向。' },
      { h: '唯理论源头', d: '划分近代两大认识论阵营,理性主义由此发端。' },
      { h: '塑造核心议题', d: '后世形而上学、心灵哲学的核心问题(身心关系、实体、观念)皆由其设定。' },
      { h: '方法论革新', d: '普遍怀疑与数学化演绎,革新科学范式。' },
      { h: '遗留永恒难题', d: '身心如何交互等难题悬而未决——持续推动后世反思。' }
    ]},

    { t: 'h', n: '四', tx: '斯宾诺莎:一元论与必然真理' },
    { t: 'persons', items: [
      { name: '巴鲁赫·斯宾诺莎', dates: '1632—1677', tag: '大陆唯理论第二位奠基人 · 《伦理学》(几何证明体系)《知性改进论》《神学政治论》', pts: [
        '神即自然(Deus sive Natura):宇宙间唯一的绝对实体即「神」或「自然」,是一切存在的根基——实体一元论消解笛卡尔的二元割裂;心灵与物质只是实体的两种属性,平行对应、共同表达实体本质(平行论替代交互论)。',
        '三重知识等级:想象/意见(源于感官与传闻,混乱片面,是错误来源)→ 理性(源于推理与公理,把握必然规律)→ 直观知识(理性直观把握实体本质,通达终极真理)。',
        '理性决定论与自由的真谛:万物皆受必然性支配,无偶然,一切在永恒因果链中;自由是对必然性的认识——凭理性理解秩序,摆脱情感奴役。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '「近代哲学的真正枢纽」', d: '黑格尔如此评价:以唯一实体一元论彻底消解二元割裂,以真观念自明性破除真理证明循环,把大陆理性主义推至逻辑彻底化形态,确立内在论形而上学。' },
      { h: '德国古典哲学与浪漫派', d: '谢林的自然哲学与同一哲学完全继承内在一元论;歌德、席勒推崇其泛神论,塑造浪漫派自然观;费尔巴哈与青年黑格尔派将内在神论解读为无神论唯物主义;马克思称其为「近代唯物主义的伟大代表」。' },
      { h: '身心平行论:永久议题', d: '副现象论、中立一元论、当代属性二元论均以其平行论为历史原型;「心灵是身体的观念」预现当代认知科学「意识对应身体活动」的基本框架。' },
      { h: '政教分离与圣经批判先河', d: '《神学政治论》是近代政教分离、思想自由的经典文献;拆解人格化上帝、去神话化圣经解读,开创圣经历史批判先河,影响后世宗教批判与世俗化思潮。' },
      { h: '尼采与德勒兹', d: '尼采的「权力意志」直接改造其「自我保存努力(Conatus)」;德勒兹《斯宾诺莎:实践哲学》复兴内在性与力量伦理学,成为当代后现代、生成论哲学的核心资源。' }
    ]},
    { t: 'band', tx: '遗留难题:平行论无法解释心理与物理为何精准对应(缺乏因果联结);一元实体如何分化出无限属性与有限样式(一与多难题);彻底决定论与道德责任、自由如何兼容;「对神的理智之爱」是否混淆形而上学实体与宗教情感——引发有神论与无神论的持续争辩。' },

    { t: 'h', n: '五', tx: '莱布尼茨:单子论与双重真理' },
    { t: 'persons', items: [
      { name: '戈特弗里德·莱布尼茨', dates: '1646—1716', tag: '大陆唯理论第三位奠基人 · 数学家、逻辑学家 · 《单子论》《新系统》《神正论》《人类理智新论》', pts: [
        '单子论:宇宙的终极实体是无广延、不可分的精神性「单子」;核心是「前定和谐」——上帝在创世之初预设所有单子的运动秩序,心灵与身体虽独立发展却始终完美同步,如两架精准的时钟。',
        '双重真理:必然的「推理真理」(数学、逻辑)与偶然的「事实真理」(自然科学)。',
        '有纹路的大理石:心灵并非白板,天赋观念潜存其中,经验是唤醒这些观念的机缘。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '完成唯理论完整体系', d: '以单子多元实体论折中前两条路径:既承认无数独立个体实体,又靠上帝前定和谐维系宇宙统一;确立充足理由律为独立核心公理;沃尔夫将其体系化为18世纪德国大学官方哲学——构成康德早年接受的「独断论形而上学」。' },
      { h: '康德的核心对话对手', d: '《纯粹理性批判》的核心任务之一就是清算莱布尼茨—沃尔夫独断唯理论;其现象/本体、感性知觉/理性认识、偶然事实/必然推理的划分,直接启发康德区分现象界与物自体、知性与理性;二律背反与模态范畴大量吸收其可能世界与真理类型论述。' },
      { h: '逻辑与可能世界', d: '最早提出普遍文字与数理逻辑构想;首创可能世界理论,区分现实世界与无限多逻辑可能世界;提出不可分辨者同一律——现代分析哲学与模态逻辑的奠基者。' },
      { h: '科学跨域', d: '独立创立微积分;发明二进制算术与自动演算机构想;区分动力因与目的因,调和机械论科学与目的论世界观;《神正论》开创系统的「恶之难题」哲学辩护路径。' }
    ]},
    { t: 'band', tx: '遗留难题:单子「无窗口」却能完整表象宇宙,内在表象的客观依据难以解释;前定和谐预设上帝一次性创世安排,自然主义框架下难以自洽;「最好可能世界」论证难以消解现实中的大量苦难;单子多元与宇宙统一之间存在一与多的内在张力。' },

    { t: 'h', n: '六', tx: '唯理论的整体局限:不可避免的独断论' },
    { t: 'nums', items: [
      { h: '脱离经验的先天预设', d: '体系建立在「实体」「上帝」等先天理性预设之上,缺乏直接经验验证,如同空中楼阁,难以获得直观的事实支撑。' },
      { h: '未经批判的独断倾向', d: '武断断言人类理性结构与外部世界结构必然契合,却无法证明:为何先天观念一定能反映客观实在?对理性的盲目崇信使其陷入独断论泥潭。' },
      { h: '具体经验的解释乏力', d: '过度强调知识的普遍必然性,难以合理解释具体、偶然、多样的经验科学事实——擅长构建宏大体系,面对真实自然现象却苍白无力。' }
    ]},
    { t: 'band', tx: '理性并非万能的钥匙:脱离经验的理性演绎,最终只能走向封闭的独断——这为经验论对知识来源的重新审视与批判,提供了必要的理论契机。' },

    { t: 'h', n: '七', tx: '洛克:经验论奠基与白板说' },
    { t: 'persons', items: [
      { name: '约翰·洛克', dates: '1632—1704', tag: '英国经验论奠基人 · 自由主义政治哲学之父 · 《人类理解论》《政府论(下篇)》《论宗教宽容》', pts: [
        '旗帜鲜明的反天赋论:儿童与智力障碍者并不拥有所谓先天公理或道德原则——这些观念实则是后天教育与社会习俗的产物。',
        '心灵白板说(Tabula Rasa):心灵在出生时如同一块「白板」,一切知识与观念都不是与生俱来,而是完全通过后天经验逐步书写上去的。',
        '第一与第二性质:第一性质是物体固有的客观属性(广延、形状、运动);第二性质是物体借助第一性质作用于感官而产生的主观感受(颜色、声音、气味),非物体本身固有。',
        '划定知识的有限边界:人只能认识经验赋予的观念,可以感知物体的各种属性,但永远无法认知实体本身的终极实在。'
      ]}
    ]},
    { t: 'band', tx: '洛克是温和经验论:并未彻底否定理性(承认理性可以整理、归纳经验素材),也保留了对物质实体与上帝存在的基本信念;但「一切观念源于经验」的核心立场,已彻底颠覆唯理论的理论根基,开启经验论的百年发展。' },
    { t: 'cards', items: [
      { h: '百年论战的开启者', d: '确立经验论核心纲领,与笛卡尔、斯宾诺莎、莱布尼茨的唯理论形成长达百年的认识论论战,构成近代哲学的核心线索;直接传承者:贝克莱、休谟。' },
      { h: '康德的对话对象', d: '对「现象知觉」与「不可知实体」的划分,直接启发康德区分现象界与物自体;对认知界限的反思,推动康德转向对认识能力本身的批判考察。' },
      { h: '自由主义与宪政源头', d: '《政府论》是现代自由主义、宪政民主的思想源头,经启蒙运动全欧传播,重塑现代革命与宪政。' },
      { h: '语言哲学与实证主义先驱', d: '第一/第二性质区分为机械论自然科学提供认识论基础;实体不可知论催生后世实证主义与不可知论传统;《人类理解论》第三卷系统讨论语言、观念、名称的关系,是近代语言哲学的重要先驱。' },
      { h: '教育与宽容', d: '《教育漫话》以白板说为根基,提出环境与经验塑造人的教育观;《论宗教宽容》是近代系统论证政教分离、信仰自由的里程碑。' }
    ]},

    { t: 'h', n: '八', tx: '贝克莱:消解物质实体' },
    { t: 'persons', items: [
      { name: '乔治·贝克莱', dates: '1685—1753', tag: '经验论的激进转折 · 主观唯心主义奠基人 · 《视觉新论》《人类知识原理》《三篇对话》', pts: [
        '存在就是被感知:所有事物认知都来源于感官感知的观念集合;所谓外物并非独立于心灵的物质实体,只是颜色、形状、硬度、气味等感官观念的组合——脱离感知,事物便无法被认知,也无存在的意义。',
        '诉诸上帝的永恒感知:为保证世界在无人感知时仍持续存在,引入上帝作为「永恒的感知者」——上帝的全知与持续观照,确保事物的客观性、连续性与自然秩序,填补经验论可能导致的虚无主义缺口。'
      ]}
    ]},
    { t: 'band', tx: '关键转折:洛克只是限制了人类对实体的认知,贝克莱则直接消解了物质实体本身——彻底贯彻洛克的经验论,同时釜底抽薪否定洛克设定的「物质实体」,将一切存在还原为心灵与观念,为休谟的彻底怀疑论铺平道路。' },
    { t: 'cards', items: [
      { h: '经验论激进路线的确立', d: '以经验一致性彻底清算洛克体系的内在矛盾;与休谟共同构成近代经验论巅峰,揭示纯粹经验原则内在的怀疑论后果,倒逼康德开启批判哲学。' },
      { h: '康德的批判对象', d: '康德在《纯粹理性批判》中专门区分先验唯心论(自身立场)与贝克莱的经验唯心论;其对知觉、表象、心灵建构经验的讨论,启发康德「知性范畴整理感性杂多」的认识论框架。' },
      { h: '现象论与实证主义资源', d: '密尔、马赫、罗素的现象论核心思路承其而来;马赫经验批判主义与维也纳学派继承「命题意义必须可被知觉验证」的经验标准;19世纪英国观念论与现象学亦吸收其「意识优先、存在依赖显现」的思考。' },
      { h: '视觉心理学与符号论', d: '《视觉新论》是近代知觉心理学奠基文本;提出「视觉是上帝的自然符号语言」,开创语言符号论思路。' }
    ]},
    { t: 'band', tx: '遗留难题:唯我论困境(如何证明他人与客观世界不只是我的私人观念);独断保留不可被知觉的精神实体(休谟随即指出这违背其自身经验论原则);客观秩序完全依托上帝意志,脱离宗教视角后难以解释知觉间稳定的关联;无法区分真实知觉与幻觉、梦境。' },

    { t: 'h', n: '九', tx: '休谟:经验论的极致与总危机' },
    { t: 'persons', items: [
      { name: '大卫·休谟', dates: '1711—1776', tag: '英国经验论集大成者 · 彻底怀疑论代表 · 《人性论》《人类理解研究》《道德原则研究》《自然宗教对话录》', pts: [
        '印象与观念:人类所有心理认知分为两类;经验论的终极准则——一切合法的观念必须有对应的原始印象支撑,无对应印象的观念皆是空洞无意义的幻想。',
        '因果与归纳的解构:感官印象中只有事物的先后伴随,没有必然的因果联系;从过去经验推导未来规律的归纳推理在逻辑上不严密——「未来必定与过去相似」这一假设本身无法被证明。',
        '知识的二元划界:观念关系的知识(数学、逻辑、几何)先天成立、绝对必然,但只是概念推演,无法拓展对现实世界的认知;事实存在的知识(自然科学、日常经验)能拓展认知,却完全基于偶然经验,不具备绝对必然性。',
        '形而上学的彻底否定:上帝、灵魂、实体、自由等所有形而上学核心概念,均无对应的感官印象支撑——按照经验准则,全部是人类虚构的空洞观念。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '唤醒康德', d: '「休谟打破了我独断论的迷梦」;其对理性、情感、事实与价值的划分,直接启发康德区分理论理性(认识自然)与实践理性(道德立法);其划定知识边界的怀疑精神,奠定「批判哲学」的核心任务。' },
      { h: '归纳问题两百年', d: '归纳问题成为科学哲学的核心议题,持续争论至今;对因果的心理学解释区分了逻辑必然性与经验习惯性,深刻影响模态逻辑与因果语义学;爱因斯坦自承,休谟对经验与因果的反思启发了相对论对经典时空因果观的重构。' },
      { h: '休谟法则:是—应当鸿沟', d: '划分描述性语言与规范性语言,成为20世纪元伦理学的核心框架,催生情感主义伦理学;「理性服务情感」颠覆传统理性至上的伦理观,开创道德情感主义传统。' },
      { h: '知觉束与实证主义', d: '知觉束理论开启无实体自我的心灵观;实证主义与维也纳学派继承「无印象则无意义」的经验划界标准;胡塞尔将休谟哲学视作现象学的重要预备。' },
      { h: '宗教与社会思想', d: '对神迹与自然神学的经验批判,成为后世世俗人文主义、宗教怀疑论的经典论证;人性论与习俗理论影响社会契约论与保守自由主义。' }
    ]},
    { t: 'band', tx: '遗留难题:归纳难题至今无公认完满解答;知觉束理论难以解释知觉的统一性与人格同一性;事实—价值二分引发持续争议;温和怀疑论自身存在内在张力。' },

    { t: 'h', n: '十', tx: '僵局:近代哲学的终极绝境' },
    { t: 'flow', items: ['洛克 · 温和奠基:保留实体,承认心灵的整理能力', '贝克莱 · 消解物质:存在即被感知,仅存精神与上帝', '休谟 · 剥离一切:因果沦为习惯,实体全部消解'], note: '经验论的彻底化三阶段——纠正了唯理论的空想独断,却使科学知识失去必然性基础。' },
    { t: 'nums', items: [
      { h: '唯理论的困境', d: '坚持理性可独立获得普遍必然知识,但缺乏经验根基,无法说明知识如何对应实在——沦为独断论。' },
      { h: '经验论的困境', d: '坚持知识来源于经验,但否定因果必然性,使科学知识沦为偶然归纳——失去普遍有效性。' },
      { h: '科学的危机', d: '近代科学依托因果规律构建,但休谟证明因果非客观必然——科学真理失去绝对的哲学基础。' },
      { h: '绝境的表征', d: '近代认识论在独断与怀疑之间摇摆:既无法为知识提供必然性证明,又无法放弃对普遍性的追求。' }
    ]},
    { t: 'cards', items: [
      { h: '自然科学的合法性危机', d: '科学的核心价值在于揭示普遍必然的自然规律,但其立足的因果律被证明无客观必然性——科学真理沦为偶然的经验归纳。' },
      { h: '道德与自由的危机', d: '若一切认知都是偶然经验,道德法则、自由意志、价值准则便失去普遍有效性——道德沦为个体主观偏好,价值秩序崩塌。' },
      { h: '传统形而上学的破产', d: '自古希腊以来对上帝、灵魂、实体、宇宙本原的超验追问,均无经验依据——形而上学彻底失去了作为科学的可能性。' }
    ]},
    { t: 'quote', tx: '休谟打破了我独断论的迷梦。', by: '康德' },
    { t: 'band', tx: '康德的诊断:近代哲学的所有争论,都源于未对人类理性本身进行批判考察——唯有先批判理性、划定理性的能力与边界,才能同时规避独断论与怀疑论,为知识、道德、形而上学重新奠基。这便是批判哲学的根本出发点。' },

    { t: 'h', n: '十一', tx: '康德:综合、超越与终结' },
    { t: 'persons', items: [
      { name: '伊曼努尔·康德', dates: '1724—1804', tag: '德国古典哲学开创者 · 近代哲学分水岭 · 三大批判 + 《道德形而上学奠基》《永久和平论》', pts: [
        '哥白尼式革命:传统认为知识必须符合对象,康德反转为「对象必须符合我们的认识形式」——人并非被动接收信息,而是带着先天的时空直观与知性范畴,主动整理和建构经验世界。',
        '现象界与物自体:能认识的「现象界」是经主体认知形式整理后的世界,是科学的合法疆域;独立于认知的「物自体」不可经验认识,仅能被理性思维——为信仰与道德保留空间。',
        '先天综合判断:数学与自然科学的基本命题兼具「先天」的普遍必然性与「综合」的知识扩展性——调和唯理论与经验论的对立,为科学知识的确定性提供哲学证明;感性先天形式是时间与空间,知性先天范畴(因果性、实体性等)是思维整理经验的规则。',
        '先验辩证论:揭示理性的越界与困境,完成对传统形而上学的批判与祛魅。'
      ]}
    ]},
    { t: 'cards', items: [
      { h: '《纯粹理性批判》', d: '核心问题:我能够知道什么?——为「知性」立法,划定科学知识的范围与界限,回答普遍必然的科学知识何以可能。' },
      { h: '《实践理性批判》', d: '核心问题:我应当做什么?——为「理性」自身立法,提出道德法则的「定言命令」,确立「人是目的而非手段」的伦理基石,论证自由意志的客观实在性。' },
      { h: '《判断力批判》', d: '核心问题:我可以希望什么?——以审美判断力与目的论为桥梁,沟通自然的必然性与道德的自由,完成哲学体系的最终统一。' }
    ]},
    { t: 'band', tx: '三大批判分别对应知识、道德与审美(信仰),共同构筑「真、善、美」合一的宏大体系——回答关于人类理性与存在的终极问题。' },
    { t: 'nums', items: [
      { h: '完成「批判转向」', d: '化解休谟因果危机,推翻莱布尼茨—沃尔夫独断形而上学,同时限定经验论的认知边界——终结前康德的独断论与经验论。' },
      { h: '义务论伦理学奠基', d: '颠覆古代幸福论与功利主义后果论;「人是目的」——罗尔斯正义论、哈贝马斯交往行动理论、当代道义论均直接继承其普遍立法与人格尊严原则;区分经验欲望与理性自律,重新定义自由。' },
      { h: '开启德国古典观念论', d: '费希特、谢林、黑格尔——整个德国古典哲学全部以回应、超越康德二元论为核心任务。' },
      { h: '美学独立化', d: '首次系统区分审美、认识、道德三种心灵活动;提出审美共通感,为审美普遍性与跨文化对话提供哲学基础——现代美学源头。' },
      { h: '现代思想源头', d: '先验方法深刻影响胡塞尔现象学;成为20世纪分析哲学与逻辑实证主义的核心争论起点;「人为自然立法」预现当代科学建构论。' },
      { h: '政治与人权基石', d: '《永久和平论》是联合国理念的源头;人格尊严思想写入《世界人权宣言》;区分公共理性与私人偏好,启发当代协商民主理论;经黑格尔中介影响马克思。' }
    ]},
    { t: 'nums', items: [
      { h: '物自体难题', d: '既然物自体完全不可认识,康德何以断定其存在?黑格尔与后世观念论直接取消物自体,实证主义则质疑这一空洞预设。' },
      { h: '现象与本体的二元割裂', d: '自然必然与道德自由如何真正统一?仅以审美作桥,未能彻底消解二元对立。' },
      { h: '定言命令形式空洞', d: '纯粹形式化的普遍法则缺少具体内容——黑格尔与功利主义批判其无法应对复杂现实的道德情境。' },
      { h: '先天综合判断的有效性', d: '20世纪逻辑学与数学的发展质疑「数学是先天综合判断」,引发持续论战。' },
      { h: '道德悬设的张力', d: '上帝与不朽仅具备实践有效性,无法思辨证明——信仰与知识之间的张力始终存在。' }
    ]},

    { t: 'h', n: '十二', tx: '历史意义:终点亦是起点' },
    { t: 'nums', items: [
      { h: '确立主体地位:理性的回归', d: '知识、真理与价值的终极根基,从超验的上帝与传统权威,彻底转移到人的理性自身——人类自我意识的真正觉醒。' },
      { h: '思想的辩证运动', d: '唯理论与经验论的长期对峙,充分暴露单一片面认知模式的内在缺陷——为康德的批判性综合提供了思想素材与理论土壤。' },
      { h: '康德的双重角色', d: '既是近代哲学的终点(以批判哲学终结二元对立),更是现代哲学的起点——其批判方法与问题框架深刻影响从德国古典哲学到存在主义的几乎所有后世流派。' },
      { h: '塑造现代精神', d: '不仅实现认识论革命,更深远地塑造了现代人类的理性精神、科学思维方式与基本价值秩序——为现代社会的伦理与文明形态奠基。' }
    ]},
    { t: 'bridge', tx: '康德既终结又开启:德国观念论以消解其二元论为使命,现象学与分析哲学在其先验方法与划界问题上分道扬镳。理性完成了对自身的审判,「信仰的危机」之后如何「重生」——现代哲学的故事从这里开始(后续讲次)。' },
    { t: 'books', items: [
      { h: '《第一哲学沉思集》', by: '笛卡尔' },
      { h: '《伦理学》', by: '斯宾诺莎' },
      { h: '《人类理解论》', by: '洛克' },
      { h: '《人性论》', by: '休谟' },
      { h: '《纯粹理性批判》', by: '康德' }
    ]}
  ]
};

module.exports = { LECTURE5 };

files.content:
/* ========= 设计系统 =========
   parchment #f3ebda · ink #1c1916 · terra #a73e2c
   aegean #1d4e5f · gold #b8893a · wine #7e2a38
   ============================ */

page {
  background: #f3ebda;
  color: #1c1916;
  font-family: "Songti SC", "Noto Serif SC", "Source Han Serif SC", "STSong", serif;
  font-size: 30rpx;
  line-height: 1.85;
  -webkit-font-smoothing: antialiased;
}

view, text { box-sizing: border-box; }

/* ---- 页面容器 ---- */
.wrap { padding: 36rpx 32rpx 120rpx; }

/* ---- 眉题(小标签) ---- */
.eyebrow {
  font-size: 22rpx;
  letter-spacing: 6rpx;
  color: #8a7a5e;
  display: block;
}

/* ---- 分隔符号 ---- */
.orn {
  text-align: center;
  color: #b8893a;
  font-size: 26rpx;
  letter-spacing: 14rpx;
  margin: 30rpx 0 6rpx;
  display: block;
}

/* ---- 卡片基底 ---- */
.card {
  background: #faf5ea;
  border: 1rpx solid rgba(28, 25, 22, 0.13);
  border-radius: 14rpx;
  padding: 28rpx 28rpx;
  box-shadow: 0 2rpx 10rpx rgba(28, 25, 22, 0.05);
}

/* ---- 主色文字 ---- */
.c-terra { color: #a73e2c; }
.c-aegean { color: #1d4e5f; }
.c-gold { color: #b8893a; }
.c-wine { color: #7e2a38; }
.c-ink { color: #1c1916; }
.c-dim { color: #6f6452; }

/* ---- 引用块 ---- */
.quote {
  margin: 28rpx 0;
  padding: 30rpx 32rpx;
  background: #1c1916;
  color: #f3ebda;
  border-radius: 14rpx;
  position: relative;
}
.quote .qmark {
  font-size: 60rpx;
  line-height: 1;
  color: #b8893a;
  display: block;
  margin-bottom: 6rpx;
  font-family: Georgia, serif;
}
.quote .qtx {
  font-size: 31rpx;
  line-height: 1.9;
  display: block;
}
.quote .qby {
  display: block;
  margin-top: 16rpx;
  font-size: 24rpx;
  color: rgba(243, 235, 218, 0.65);
  letter-spacing: 2rpx;
}

/* ---- 强调横幅 ---- */
.band {
  margin: 26rpx 0;
  padding: 24rpx 28rpx;
  border-radius: 12rpx;
  background: rgba(184, 137, 58, 0.12);
  border: 1rpx solid rgba(184, 137, 58, 0.4);
  font-size: 28rpx;
  line-height: 1.85;
  color: #5d4a22;
}

/* ---- 通用标题 ---- */
.h-num {
  display: inline-block;
  font-size: 22rpx;
  letter-spacing: 4rpx;
  color: #f3ebda;
  background: #1c1916;
  border-radius: 6rpx;
  padding: 4rpx 14rpx;
  margin-right: 14rpx;
  vertical-align: middle;
}
.h-tx {
  font-size: 36rpx;
  font-weight: 700;
  letter-spacing: 2rpx;
  vertical-align: middle;
}

/* ---- 流程链 ---- */
.flow { margin: 24rpx 0; }
.flow-item {
  display: flex;
  align-items: center;
  margin-bottom: 6rpx;
}
.flow-dot {
  width: 14rpx;
  height: 14rpx;
  border-radius: 50%;
  background: #a73e2c;
  margin-right: 18rpx;
  flex-shrink: 0;
}
.flow-line {
  width: 2rpx;
  height: 26rpx;
  background: rgba(28, 25, 22, 0.25);
  margin-left: 6rpx;
}
.flow-tx { font-size: 30rpx; font-weight: 600; }

/* ---- 按钮 ---- */
.btn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22rpx 30rpx;
  border-radius: 12rpx;
  font-size: 28rpx;
  letter-spacing: 2rpx;
}
.btn-dark { background: #1c1916; color: #f3ebda; }
.btn-line {
  background: transparent;
  color: #1c1916;
  border: 1rpx solid rgba(28, 25, 22, 0.35);
}

/* ---- 页脚 ---- */
.foot {
  margin-top: 70rpx;
  text-align: center;
}
.foot-tx {
  display: block;
  font-size: 22rpx;
  color: #8a7a5e;
  letter-spacing: 3rpx;
  line-height: 2;
}

