/* 人物长廊:从巫师到加尔文,再到回望者 */

const BANDS = [
  {
    id: 'b0', era: '原始时代', accent: 'terra', note: '没有名字的思想者',
    list: [
      { name: '巫师 / 萨满', dates: '旧石器—新石器', tag: '知识与权力的最初集中者:精神领袖、医生、气象员、仲裁者——部落的「活字典」。' }
    ]
  },
  {
    id: 'b1', era: '神话与先知', accent: 'gold', note: '以叙事回答终极问题',
    list: [
      { name: '《吉尔伽美什》诗人', dates: '约前2100起', tag: '死亡、友谊与不朽——人类最早的命运之问。' },
      { name: '《埃努玛·埃利什》祭司', dates: '约前18世纪', tag: '混沌之尸造世界;人是神的奴隶——秩序与王权的神话。' },
      { name: '荷马', dates: '约前8世纪', tag: '命运(Moira)与诸神干预的史诗世界——哲学的继承对象。' },
      { name: '赫西俄德', dates: '约前8—前7世纪', tag: '《神谱》:从混沌到宙斯的宇宙生成——本原追问的神话形态。' },
      { name: '摩西(传统)', dates: '传约前13世纪', tag: '《摩西五经》:创世、原罪、律法——道德的基础。' }
    ]
  },
  {
    id: 'b2', era: '自然哲学家', accent: 'aegean', note: '用自然解释自然',
    list: [
      { name: '泰勒斯', dates: '约前624—前546', tag: '本原是水;自然祛魅——西方哲学之父。' },
      { name: '阿那克西曼德', dates: '约前610—前546', tag: '阿派朗(无限者);宇宙正义;演化萌芽。' },
      { name: '阿那克西美尼', dates: '约前585—前525', tag: '气之稀散凝聚——量变生质变。' },
      { name: '赫拉克利特', dates: '约前535—前475', tag: '活火与逻各斯;万物皆流;对立统一——辩证法之源。' },
      { name: '克塞诺芬尼', dates: '约前570—前475', tag: '批判神人同形;唯一神论;真理/意见之分——通往爱利亚之桥。' },
      { name: '巴门尼德', dates: '约前515—前450', tag: '存在唯一、永恒、不动;理性高于感官——形而上学开端。' },
      { name: '芝诺(爱利亚)', dates: '约前490—前430', tag: '四大悖论反证捍卫「一」——无限与运动的千年难题。' },
      { name: '毕达哥拉斯', dates: '约前570—前495', tag: '万物皆数;和谐宇宙;净化灵魂——理性本体论开端。' },
      { name: '恩培多克勒', dates: '约前492—前432', tag: '四根 + 爱与争——调和不变与流变。' },
      { name: '阿那克萨戈拉', dates: '约前500—前428', tag: '种子 + 努斯:首提精神性本原;把哲学带入雅典。' },
      { name: '德谟克利特', dates: '约前460—前370', tag: '原子与虚空——机械唯物论顶峰,近代科学远祖。' }
    ]
  },
  {
    id: 'b3', era: '智者与三圣', accent: 'aegean', note: '哲学转向人',
    list: [
      { name: '普罗泰戈拉', dates: '约前490—前420', tag: '「人是万物的尺度」;德性可教——民主思想之源。' },
      { name: '高尔吉亚', dates: '约前483—前375', tag: '三大否定;修辞即力量——语言怀疑论的最早宣言。' },
      { name: '苏格拉底', dates: '前469—前399', tag: '自知无知;助产术;德性即知识——西方哲学的分水岭。' },
      { name: '柏拉图', dates: '前427—前347', tag: '理念论;洞穴喻;理想国——形而上学奠基。' },
      { name: '亚里士多德', dates: '前384—前322', tag: '四因;潜能与现实;逻辑学——古希腊集大成者。' }
    ]
  },
  {
    id: 'b4', era: '希腊化五派', accent: 'aegean', note: '从城邦到心灵',
    list: [
      { name: '第欧根尼', dates: '约前412—前323', tag: '犬儒:回归自然、蔑视世俗——精神自足。' },
      { name: '伊壁鸠鲁', dates: '前341—前270', tag: '花园学派:祛除怕死惧神,宁静即至乐。' },
      { name: '芝诺(斯多葛)', dates: '约前334—前262', tag: '顺应逻各斯;区分可控与不可控。' },
      { name: '皮浪', dates: '约前360—前270', tag: '悬置判断(Epoché)以达不动心(Ataraxia)。' },
      { name: '普罗提诺', dates: '204—270', tag: '太一流溢;灵魂回归——古希腊哲学最后的集大成。' }
    ]
  },
  {
    id: 'b5', era: '桥梁与教父', accent: 'wine', note: '哲学语汇的神学化',
    list: [
      { name: '斐洛', dates: '约前20—公元50', tag: '逻各斯中介;寓意解经——「基督教神学的真正奠基人」。' },
      { name: '游斯丁', dates: '约100—165', tag: '逻各斯基督论;「苏格拉底在基督以前就是基督徒」。' },
      { name: '德尔图良', dates: '约160—225', tag: '首创「三位一体」;「我信,因它荒谬」——拉丁神学之父。' },
      { name: '奥利金', dates: '约185—254', tag: '三层寓意解经;永恒受生——第一位系统神学家。' },
      { name: '奥古斯丁', dates: '354—430', tag: '原罪、恩典、预定;上帝之城;时间是心灵的延伸——集大成定型。' }
    ]
  },
  {
    id: 'b6', era: '经院与神秘主义', accent: 'wine', note: '大全与裂缝',
    list: [
      { name: '安瑟尔谟', dates: '1033—1109', tag: '信仰寻求理解;本体论证明——经院哲学之父。' },
      { name: '阿伯拉尔', dates: '约1079—1142', tag: '辩证神学;概念论;动机伦理。' },
      { name: '托马斯·阿奎那', dates: '1225—1274', tag: '五路证明;自然法;信仰与理性和谐——经院巅峰。' },
      { name: '邓斯·司各脱', dates: '1266—1308', tag: '存在单义性;此性;意志优先——唯名论先驱。' },
      { name: '埃克哈特大师', dates: '约1260—1328', tag: '神性深渊;灵魂火花;圣子在灵魂中诞生——德意志神秘主义之父。' },
      { name: '奥卡姆的威廉', dates: '约1287—1347', tag: '剃刀:如无必要勿增实体——唯名论集大成,撬动千年。' }
    ]
  },
  {
    id: 'b7', era: '改革者', accent: 'wine', note: '回归与释放',
    list: [
      { name: '威克里夫', dates: '约1320—1384', tag: '首倡「圣经是唯一最高权威」——改革的先声。' },
      { name: '扬·胡斯', dates: '约1372—1415', tag: '批判教会腐败与功德神学——以身殉道的前驱。' },
      { name: '伊拉斯谟', dates: '1466—1536', tag: '圣经校勘;基督教人文主义——「改革铺路石」。' },
      { name: '马丁·路德', dates: '1483—1546', tag: '三个唯独;因信称义——打破千年一统。' },
      { name: '约翰·加尔文', dates: '1509—1564', tag: '预定论五要点;长老制;天职观——通向现代世界。' }
    ]
  },
  {
    id: 'b8', era: '回望者', accent: 'ink', note: '研究与反思这段历史的人',
    list: [
      { name: '弗雷泽', dates: '1854—1941', tag: '《金枝》:交感巫术两律——进化论视角(及其西方中心局限)。' },
      { name: '涂尔干', dates: '1858—1917', tag: '图腾是社会神圣的原始表达;禁忌划分神圣与世俗。' },
      { name: '列维-布留尔', dates: '1857—1939', tag: '《原始思维》:互渗律——主客未分的神秘思维。' },
      { name: '马林诺夫斯基', dates: '1884—1942', tag: '功能学派:习俗各有实际功能。' },
      { name: '卡西尔', dates: '1874—1945', tag: '神话是一切人类文化的源头;人是符号的动物。' },
      { name: '列维-斯特劳斯', dates: '1908—2009', tag: '《野性的思维》:具体的科学;从具象逻辑到抽象逻辑。' },
      { name: '格尔茨', dates: '1926—2006', tag: '文化是公开的符号;意义之网。' },
      { name: '萨义德', dates: '1935—2003', tag: '《东方学》:谁在书写他者?' },
      { name: '维特根斯坦', dates: '1889—1951', tag: '语言的界限;不可说者,只可显示——与神秘主义的共鸣与分歧。' }
    ]
  }
];

module.exports = { BANDS };

