      { name: '涂尔干', dates: '1858—1917', tag: '图腾是社会神圣的原始表达;禁忌划分神圣与世俗。' },
      { name: '列维-布留尔', dates: '1857—1939', tag: '《原始思维》:互渗律——主客未分的神秘思维。' },
