      { name: '列维-斯特劳斯', dates: '1908—2009', tag: '《野性的思维》:具体的科学;从具象逻辑到抽象逻辑。' },
      { name: '格尔茨', dates: '1926—2006', tag: '文化是公开的符号;意义之网。' },
      { name: '萨义德', dates: '1935—2003', tag: '《东方学》:谁在书写他者?' },
      { name: '维特根斯坦', dates: '1889—1951', tag: '语言的界限;不可说者,只可显示——与神秘主义的共鸣与分歧。' }
    ]
  }
];

