  { id: 6, lec: '第四讲', name: '神学千年', role: '信仰与理性的博弈', desc: '哲学概念被神学整体转换;经院筑成大全,唯名论撬动,宗教改革回归。', accent: 'wine' },
  { id: 7, lec: '后续', name: '启蒙 · 科学', role: '危机与重生', desc: '唯名论与改革释放的个体、经验、简约性原则,流向经验论、科学与启蒙。', accent: 'ink' }
];

const THREADS = [
  {
    id: 1,
    title: '恒常的追问,变换的回答',
    sub: '同一组终极问题,贯穿八千年',
    intro: '世界是什么?我们是谁?命运为何?应当如何生活?——这四个问题从图腾时代一直问到宗教改革,每个时代给出的只是不同的「回答技术」。神话面临的根本问题(存在与本原、人的本质、自由与必然、伦理基础),正是日后哲学的四大问题;而旧形式从未死去,只是改换媒介存续。',
    stops: [
      { lec: '一', tx: '图腾解释世界、禁忌建立秩序、巫术求取控制、仪式给予归属——第一套完整的「世界观操作系统」,核心是缓解生存焦虑。' },
      { lec: '二', tx: '神话以故事回答起源与命运;宗教以制度提供终极关怀、道德指引与社群归属——「人生的意义是什么?死后会怎样?应当如何生活?」' },
      { lec: '三', tx: '哲学以 Arche 回答起源、以 Logos 回答秩序、以伦理学回答生活;希腊化五派的目标干脆就是「心灵安顿」——与巫术时代的安全感需求同构。' },
      { lec: '四', tx: '「从求真到求安」:希腊化的真理真空为救赎信仰准备了听众;神学以恩典回答全部四问。' },
      { lec: '今', tx: '古老形式的当代存续是这条线的最佳证据:图腾 → 国旗、市花、Logo;禁忌 → 避讳语、政治正确、潜规则;巫术 → 星座、水晶、幸运数字;仪式 → 国庆、春节、婚礼。' }
    ],
    close: '梅师一句话总纲:每个时代人类的处境与问题不同,但心理需求是一致的。'
  },
  {
    id: 2,
    title: '连续与转换',
    sub: '从具象逻辑到抽象逻辑(列维-斯特劳斯命题)',
    intro: '文明的发展不是从「非逻辑」走向「逻辑」,而是从「具象的逻辑系统」演进为「抽象的逻辑系统」——每个阶段都继承前者的框架、更换操作媒介、提升抽象层级。四讲呈现了四次大转换,没有一次是凭空发生的。',
    stops: [
      { lec: '一', tx: '转换的元理论:图腾分类、巫术因果都是当时最先进的「认知技术」,与科学同为符号系统;修补术与工程师之别只在媒介,不在逻辑。' },
      { lec: '二', tx: '第一次转换:巫术仪式被宗教吸收为礼仪;多元神话被整合为统一神学。第二次转换:神话 → 哲学——从讲故事到讲道理,概念遗产(本源、秩序、命运、Logos)整体移交。' },
      { lec: '三', tx: '希腊哲学的「继承与突破」五源(荷马、赫西俄德、俄耳甫斯教、巴比伦、埃及):继承框架,以非人格原则替换神格——「前苏格拉底哲学并非凭空诞生」。' },
      { lec: '四', tx: '第三次转换:哲学语汇的神学化七条(存在→自有永有、Arche→创世主宰、Logos→道成肉身、Nous→圣灵、理念→上帝心中的蓝图、四因→第一因、太一→三位一体之源)。第四次转换:唯名论瓦解经院,把「共相之争」转换为语言与经验问题——流向经验论与近代科学。' }
    ],
    close: '理解这条线,就不会再把任何一个时代斥为「蒙昧」:每个阶段都是同一心智在不同媒介上的运行。'
  },
  {
    id: 3,
    title: '命运的长河',
    sub: '「自由与必然」是同一个问题换了衣服',
    intro: '在神话之前没有命运:泛灵世界里一切只是个体之「灵」的作为——「没有注定,只有发生」。当拟人化神祇将自然力秩序化,命运才诞生为可讲述、可敬畏的抽象法则;此后它一路改名换姓,直到今天。',
    stops: [
      { lec: '一', tx: '泛灵论:事件由具体的灵引起,不可预测、纯属偶然——命运概念尚未出现,这是「零点」。' },
      { lec: '二', tx: '命运的四种原型:苏美尔 Namtar(个体必死)与 Me(结构法则)构成决定论宇宙;埃及 Maat 是需每日维护的动态平衡;希腊 Moira 连神也屈从,人却明知不可抗而搏斗——悲剧精神;犹太传统中上帝的旨意与律法。' },
      { lec: '三', tx: '哲学接管:Ananke(必然)与 Logos(规律)取代神意;斯多葛把问题改写为「可控的内心德性 vs 不可控的外部命运」;Prohairesis(自由抉择)入场。' },
      { lec: '四', tx: '神学战场:奥古斯丁(原罪、恩典、预定)vs 伯拉纠(自由意志)——431年裁决;经院温和预定论居中;宗教改革再爆发:路德加尔文「神恩独作」vs 特伦托「神人合作」,加尔文五要点 vs 阿明尼乌——「主权与意志」成为贯穿千年的核心矛盾之一。' }
    ],
    close: '从 Moira 的天平到加尔文的预定,从斯多葛的「可控/不可控」到存在主义的「自由与必然」——这条河至今未断流。'
  },
  {
    id: 4,
    title: 'Logos 的漂流',
    sub: '一个词,两副面孔,两千年博弈',
    intro: 'Logos 在哲学中是理性、语言、逻辑,在神学中是基督、道、真理——这个词的双义,本身就是「信仰与理性博弈」的浓缩史。与它并行的还有「一」(Hen)的漂流:从唯一神到唯一存在,再到太一与上帝。',
    stops: [
      { lec: '二', tx: '起点在两处:赫西俄德笔下混沌生成秩序的追问;《约翰福音》「太初有道,道与神同在,道就是神」——道是神圣理性与创造原则(此句日后影响斯宾诺莎与黑格尔)。' },
      { lec: '三', tx: '哲学的 Logos:赫拉克利特让万物按逻各斯燃烧熄灭;克塞诺芬尼的「唯一神」五属性被巴门尼德转化为「唯一存在」;斯多葛使逻各斯成为渗透万物的宇宙理性;普罗提诺以努斯为太一的直接显现。' },
      { lec: '四', tx: '嫁接完成:斐洛以逻各斯为上帝与世界的中介中保;游斯丁的逻各斯基督论(「苏格拉底在基督以前就是基督徒」);《约翰福音》把 Logos 直接等同于耶稣——「道成肉身」;太一成为三位一体之源,否定神学诞生。' },
      { lec: '四', tx: '博弈与再分离:德尔图良「我信,因它荒谬」 vs 安瑟尔谟「信仰寻求理解」 vs 阿奎那「双重真理和谐」 vs 奥卡姆「信仰与理性二分」——Logos 的两副面孔最终各归其位,理性面孔流向近代哲学与科学。' }
    ],
    close: '读懂 Logos 的漂流,就读懂了西方思想史的主旋律:理性与信仰不是简单对立,而是同一个词的内部张力。'
  },
  {
    id: 5,
    title: '解释权的转移',
    sub: '谁能解释世界,谁就拥有权力',
    intro: '知识与权力从一开始就绑在一起:解释世界的权利每下放一次,社会结构就重塑一次。这条线从巫师走到「人人直面文本」,也顺带解释了正典、解经方法与教会权威之争为何如此惨烈。',
    stops: [
      { lec: '一', tx: '巫师是知识与权力的最初集中者:精神领袖、医生、气象员、仲裁者,部落的「活字典」——并配有失败免责机制(神力对抗、仪式瑕疵、替罪羊)保护其解释垄断。' },
      { lec: '二', tx: '祭司阶层组织化:神庙集祭祀、文化、政治、经济、教育五种权力于一身;文字与经典使教义固定化——解释权制度化;政教关系四型本质上是「解释权与统治权」的不同配比。' },
      { lec: '三', tx: '哲学家把解释拉入公共论辩:城邦辩论打破王权与神话权威;智者宣称「人是万物的尺度」、修辞即权力;苏格拉底以诘问把真理的裁判权交给每个人的理性。' },
      { lec: '四', tx: '教会重建垄断又被瓦解:正典定型(马吉安倒逼)、寓意 vs 字面解经之争、大公会议裁定正统、主教掌赦罪权;随后唯名论宣告「共同体只是个体的集合名称」,威克里夫、胡斯到路德的「唯独圣经」让个体直面文本——印刷术与识字普及把解释权交还个人。' }
    ],
    close: '从巫师的免责机制到「人人皆祭司」,解释权的每一次转移都是一场社会革命——这条线也通向福柯的「真理、话语、权力」。'
  },
  {
    id: 6,
    title: '语言的边界',
    sub: '终极之物始终居于言辞之外',
    intro: '这是梅师课程最深的底色:从原始互渗到否定神学,从「道可道非常道」到维特根斯坦,人类一再撞上同一堵墙——语言依赖概念与二分,而终极是整体的、超越对立的;一经言说,即失其本真。',
    stops: [
      { lec: '一', tx: '互渗思维:主体与客体、词与物尚未分离——对名字的禁忌(避讳神名、首领名)说明语言被当作有实际效力的力量;语言与世界还未拉开距离。' },
      { lec: '二', tx: '各传统的「不可说」:涅槃、道、梵、与神合一、Ein Sof;老子「道可道,非常道」;传达只能靠隐喻、否定性语言、体验引导与修行——「修行是意识训练,不是魔法」。' },
      { lec: '三', tx: '哲学三角(世界—自我—语言)确立;高尔吉亚的第三否定(即使认识了也无法传达)是语言怀疑论的最早宣言;爱利亚学派则相信「思维与存在同一」——语言乐观与悲观两条路同时开出。' },
      { lec: '四', tx: '否定神学正式登场:太一/上帝只能说「不是什么」;埃克哈特的「神性深渊」不可名状;唯名论则反向宣告:共相只是词——语言的指称能力被釜底抽薪;维特根斯坦总结:不可说者,只可显示;哲学止于沉默,而宗教视界限之外为起点。' }
    ],
    close: '语言的边界问题没有终点:它从图腾时代的名讳禁忌,一直延伸到分析哲学与今天的 AI 语言模型——这门课的下一程。'
  }
];

module.exports = { SPINE, THREADS };

files.content:
/* ---- 标签 ---- */
.tabs {
  display: flex;
  background: #faf5ea;
  border: 1rpx solid rgba(28, 25, 22, 0.2);
  border-radius: 999rpx;
  padding: 6rpx;
  margin: 16rpx 0 28rpx;
}
.tab {
  flex: 1;
  text-align: center;
  padding: 16rpx 0;
  border-radius: 999rpx;
  font-size: 28rpx;
  letter-spacing: 3rpx;
  color: #6f6452;
}
.tab-on {
  background: #1c1916;
  color: #f3ebda;
}

.a-intro {
  display: block;
  font-size: 26rpx;
  line-height: 1.85;
  color: #5d5346;
  margin-bottom: 26rpx;
  padding: 0 6rpx;
}

/* ---- 概念长河 ---- */
.cv-card {
  background: #faf5ea;
  border: 1rpx solid rgba(28, 25, 22, 0.13);
  border-radius: 16rpx;
  padding: 28rpx;
  margin-bottom: 28rpx;
}
.cv-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  border-left: 10rpx solid #1c1916;
  padding-left: 18rpx;
}
.bd-terra { border-left-color: #a73e2c; }
.bd-gold { border-left-color: #b8893a; }
.bd-aegean { border-left-color: #1d4e5f; }
.bd-wine { border-left-color: #7e2a38; }
.bd-ink { border-left-color: #1c1916; }
.cv-name {
  font-size: 38rpx;
  font-weight: 700;
  letter-spacing: 1rpx;
  font-family: Georgia, "Times New Roman", serif;
  margin-right: 16rpx;
}
.cv-cn { font-size: 27rpx; color: #6f6452; }
.cv-line {
  display: block;
  margin: 16rpx 0 20rpx;
  font-size: 23rpx;
  line-height: 1.7;
  color: #8a6420;
}
.cv-stages {}
.cv-stage { display: flex; }
.cv-rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-right: 20rpx;
}
.cv-dot {
  width: 16rpx;
  height: 16rpx;
  border-radius: 50%;
  margin-top: 12rpx;
  flex-shrink: 0;
}
.dt-terra { background: #a73e2c; }
.dt-gold { background: #b8893a; }
.dt-aegean { background: #1d4e5f; }
.dt-wine { background: #7e2a38; }
.dt-ink { background: #1c1916; }
.cv-rail-line {
  width: 2rpx;
  flex: 1;
  background: rgba(28, 25, 22, 0.18);
  margin: 4rpx 0;
}
.cv-body { flex: 1; padding-bottom: 24rpx; }
.cv-meta { display: flex; align-items: baseline; flex-wrap: wrap; }
.cv-era {
  font-size: 21rpx;
  letter-spacing: 2rpx;
  color: #f3ebda;
  background: #1c1916;
  border-radius: 6rpx;
  padding: 2rpx 12rpx;
  margin-right: 14rpx;
}
.cv-who { font-size: 26rpx; font-weight: 700; }
.cv-tx {
  display: block;
  margin-top: 6rpx;
  font-size: 24rpx;
  line-height: 1.8;
  color: #463d30;
}

/* ---- 张力 ---- */
.dg-block {
  background: #faf5ea;
  border: 1rpx solid rgba(28, 25, 22, 0.13);
  border-radius: 16rpx;
  padding: 28rpx;
  margin-bottom: 28rpx;
}
.dg-head { display: flex; align-items: center; }
.dg-bar {
  width: 14rpx;
  height: 36rpx;
  border-radius: 6rpx;
  margin-right: 16rpx;
}
.bg-terra { background: #a73e2c; }
.bg-gold { background: #b8893a; }
.bg-aegean { background: #1d4e5f; }
.bg-wine { background: #7e2a38; }
.bg-ink { background: #1c1916; }
.dg-title { font-size: 34rpx; font-weight: 700; letter-spacing: 1rpx; }
.dg-note {
  display: block;
  margin: 12rpx 0 20rpx;
  font-size: 23rpx;
  line-height: 1.75;
  color: #8a7a5e;
}
.dg-pair {
  padding: 18rpx 0;
  border-top: 1rpx dashed rgba(28, 25, 22, 0.15);
}
.dg-vs { display: flex; align-items: baseline; flex-wrap: wrap; }
.dg-a { font-size: 28rpx; font-weight: 700; color: #1d4e5f; }
.dg-b { font-size: 28rpx; font-weight: 700; color: #a73e2c; }
.dg-x { margin: 0 12rpx; color: #b8893a; font-size: 26rpx; }
.dg-tx {
  display: block;
  margin-top: 4rpx;
  font-size: 24rpx;
  line-height: 1.75;
  color: #5d5346;
}

