const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, VerticalAlign,
  TableLayoutType, Footer, PageNumber
} = require('docx');

const SONG = { ascii: 'Times New Roman', hAnsi: 'Times New Roman', eastAsia: '宋体' };
const HEI  = { ascii: 'Arial', hAnsi: 'Arial', eastAsia: '黑体' };
const KAI  = { ascii: 'Times New Roman', hAnsi: 'Times New Roman', eastAsia: '楷体' };

// **加粗** 语法解析
const mdRuns = (text, font = SONG, size = 24) =>
  text.split(/(\*\*[^*]+\*\*)/g).filter(Boolean).map(seg =>
    seg.startsWith('**') && seg.endsWith('**')
      ? new TextRun({ text: seg.slice(2, -2), bold: true, font, size })
      : new TextRun({ text: seg, font, size }));

const P = (text) => new Paragraph({
  alignment: AlignmentType.JUSTIFIED,
  indent: { firstLine: 480 },
  spacing: { line: 360, after: 80 },
  children: mdRuns(text),
});

const H = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 320, after: 160 },
  children: [new TextRun({ text, bold: true, font: HEI, size: 32, color: '000000' })],
});

// ---------- 封面题头 ----------
const front = [
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 240, after: 100 },
    children: [new TextRun({ text: '系统论推演下的德国古典哲学神学史', bold: true, font: HEI, size: 44 })],
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 },
    children: [new TextRun({ text: '——对《德国古典哲学家的神学背景》的分析与总结', font: KAI, size: 30 })],
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 260 },
    children: [new TextRun({ text: '(2026年7月15日)', font: KAI, size: 24 })],
  }),
  new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    indent: { firstLine: 480 },
    spacing: { line: 360, after: 220 },
    children: [
      new TextRun({ text: '编制说明:', bold: true, font: KAI, size: 24 }),
      new TextRun({ text: '本文以《用现代的系统论的观点去分析和总结逻辑这套系统的发展历史》(下称"蓝本")所确立的系统推演思路与方法为本,审视《德国古典哲学家的神学背景》(下称"文本")全部四章,对其内容作出分析与总结。蓝本提供的解剖工具为:区分(distinction)、操作闭合与自创生(autopoiesis)、必要变异度定律(requisite variety)、再进入(re-entry)、盲点(blind spot)、解悖(Entparadoxierung)、分层架构(stratification)与系统生态化。', font: KAI, size: 24 }),
    ],
  }),
];

// ---------- 正文 ----------
const body = [];

body.push(H('总纲(结论先行)'));
body.push(P(`用系统论的X光去照《德国古典哲学家的神学背景》,四章内容立刻从"四位哲学家的神学传记"坍缩为**一个单一的系统事件**:"上帝"这个概念,本是西方认知系统在自身之外设定的终极锚点——一个没有盲点的观察者、一个终结奠基回溯的固定点、一个担保全系统一致性的外部担保人。德国古典哲学七十年(1781–1854)做的是同一件事:**把这个外部锚点强行拖进系统内部**。这是思想史上规模最大的一次再进入(re-entry)事件。`));
body.push(P(`更有意思的是,它把逻辑史那部电影**倒着放了一遍**。逻辑系统是先做闭合梦(亚里士多德—莱布尼茨—希尔伯特),后撞墙(哥德尔1931),再分层止损(罗素/塔尔斯基),最后开放成生态。神学系统却是**先拿到不完备性判决(康德1781),然后用三代人的力气拒绝执行这份判决**——文本原话:费希特、谢林、黑格尔"全部以回应康德'理论理性无法证明上帝'为起点,各自尝试打通认识与信仰的鸿沟"。三次重建,一次比一次宏大,直到最宏大的那次(黑格尔)当场碎裂成解释的生态。德国古典哲学因此是蓝本那条铁律的**对照实验**:一个系统收到自己的哥德尔判决之后拒不签收,会发生什么。`));

body.push(H('一、先把"上帝"翻译成系统论:闭合梦的人格化存放处'));
