const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, VerticalAlign,
  TableLayoutType, Footer, PageNumber
} = require('docx');

const SONG = { ascii: 'Times New Roman', hAnsi: 'Times New Roman', eastAsia: '宋体' };
const HEI  = { ascii: 'Arial', hAnsi: 'Arial', eastAsia: '黑体' };
const KAI  = { ascii: 'Times New Roman', hAnsi: 'Times New Roman', eastAsia: '楷体' };

// **加粗** 语法解析
const mdRuns = (text, font = SONG, size = 24) =>
  text.split(/(\*\*[^*]+\*\*)/g).filter(Boolean).map(seg =>
    seg.startsWith('**') && seg.endsWith('**')
      ? new TextRun({ text: seg.slice(2, -2), bold: true, font, size })
      : new TextRun({ text: seg, font, size }));

const P = (text) => new Paragraph({
  alignment: AlignmentType.JUSTIFIED,
  indent: { firstLine: 480 },
  spacing: { line: 360, after: 80 },
  children: mdRuns(text),
});

const H = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 320, after: 160 },
  children: [new TextRun({ text, bold: true, font: HEI, size: 32, color: '000000' })],
});

// ---------- 封面题头 ----------
const front = [
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 240, after: 100 },
    children: [new TextRun({ text: '系统论推演下的德国古典哲学神学史', bold: true, font: HEI, size: 44 })],
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 },
    children: [new TextRun({ text: '——对《德国古典哲学家的神学背景》的分析与总结', font: KAI, size: 30 })],
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 260 },
    children: [new TextRun({ text: '(2026年7月15日)', font: KAI, size: 24 })],
  }),
  new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    indent: { firstLine: 480 },
    spacing: { line: 360, after: 220 },
    children: [
      new TextRun({ text: '编制说明:', bold: true, font: KAI, size: 24 }),
      new TextRun({ text: '本文以《用现代的系统论的观点去分析和总结逻辑这套系统的发展历史》(下称"蓝本")所确立的系统推演思路与方法为本,审视《德国古典哲学家的神学背景》(下称"文本")全部四章,对其内容作出分析与总结。蓝本提供的解剖工具为:区分(distinction)、操作闭合与自创生(autopoiesis)、必要变异度定律(requisite variety)、再进入(re-entry)、盲点(blind spot)、解悖(Entparadoxierung)、分层架构(stratification)与系统生态化。', font: KAI, size: 24 }),
    ],
  }),
];

// ---------- 正文 ----------
const body = [];

body.push(H('总纲(结论先行)'));
body.push(P(`用系统论的X光去照《德国古典哲学家的神学背景》,四章内容立刻从"四位哲学家的神学传记"坍缩为**一个单一的系统事件**:"上帝"这个概念,本是西方认知系统在自身之外设定的终极锚点——一个没有盲点的观察者、一个终结奠基回溯的固定点、一个担保全系统一致性的外部担保人。德国古典哲学七十年(1781–1854)做的是同一件事:**把这个外部锚点强行拖进系统内部**。这是思想史上规模最大的一次再进入(re-entry)事件。`));
body.push(P(`更有意思的是,它把逻辑史那部电影**倒着放了一遍**。逻辑系统是先做闭合梦(亚里士多德—莱布尼茨—希尔伯特),后撞墙(哥德尔1931),再分层止损(罗素/塔尔斯基),最后开放成生态。神学系统却是**先拿到不完备性判决(康德1781),然后用三代人的力气拒绝执行这份判决**——文本原话:费希特、谢林、黑格尔"全部以回应康德'理论理性无法证明上帝'为起点,各自尝试打通认识与信仰的鸿沟"。三次重建,一次比一次宏大,直到最宏大的那次(黑格尔)当场碎裂成解释的生态。德国古典哲学因此是蓝本那条铁律的**对照实验**:一个系统收到自己的哥德尔判决之后拒不签收,会发生什么。`));

body.push(H('一、先把"上帝"翻译成系统论:闭合梦的人格化存放处'));
body.push(P(`文本第一章其实自己给出了翻译词典。康德说上帝是"理性的先验理想"——理性自然会追求无条件的完满大全,上帝是理性自身的必然构想。换成系统论语言:**上帝理念就是系统为自己的"完成态"所生成的自画像,是闭合梦的存放处**。神学是认知系统专门用来保管"我终将完整、一致、自我奠基"这个梦的部门。`));
body.push(P(`由此,三大上帝证明的系统论身份一目了然:它们是**用系统内部手段推导出系统外部锚点存在**的三次尝试——即神学版的希尔伯特纲领。这里有一个两份文档共享的、堪称结构性证据的细节:**莱布尼茨在两条战线上都是同一个做梦者**。在逻辑那边,他梦想 characteristica universalis 和"让我们来算";在神学这边,莱布尼茨—沃尔夫理性神学梦想仅凭纯粹逻辑证明上帝实存。同一个人,同一个闭合梦,两个战场——而两个战场后来各自收到了自己的不可能性判决(1781年的康德,1931年的哥德尔)。`));
body.push(P(`还有一个被文本反复陈述四次、却容易被当作传记花絮的事实:康德、费希特、谢林、黑格尔全部浸泡在**路德宗/虔敬主义**里长大。虔敬主义"弱化人格上帝的外在超越性,强调神性内在于人的理性良知"。用系统论读,这不是花絮,这是**预装的再进入**:新教已经先把"对上帝的观察"从教会的外部仪式操作,搬进了个体良知的内部操作。德国古典哲学不过是这场文化层面的再进入达到了哲学的自我意识。四个人共享同一个先验(prior),所以四个人殊途同归。`));

body.push(H('二、康德:神学的哥德尔时刻,与第一次分层解悖'));
body.push(P(`休谟是让1.0版理性神学死机的那条边缘输入。康德接手后做的,严格对应逻辑史3.0阶段的两个动作:**先证明不可能,再分层止损**——只是他比罗素、塔尔斯基早了一百二十年。`));
body.push(P(`三大证明的驳斥,每一条都能精确翻译:**本体论证明**的驳斥("存在不是实在谓词","概念的一百元不等于口袋里的一百元")即是:句法生成不了语义,系统的符号操作产不出模型的实存——地图上画不出领土。**宇宙论证明**的驳斥,文本原话是"把因果范畴超验运用到物自体领域,超出经验合法边界"——这就是一份**类型错误(type error)诊断书**:范畴的类型签名限定在现象界,越级调用即非法操作。康德是在罗素之前就开出类型论罚单的人。**目的论证明**的驳斥("仅能证明世界有一位秩序建筑师,无法证明无限、全能、完满的唯一上帝")是最干净的必要变异度论证:有限证据的变异度托不起无限结论,调节端永远追不上被控端。`));
body.push(P(`然后是止损。"我不得不悬置知识,以便给信仰腾出位置"——理论理性与实践理性的切分,就是对象语言/元语言的切分:两层各配一个真值谓词(Wissen/Glaube),"主观充足、客观不足"即真值的**层级索引化**。上帝从认知对象降格为调节性理念,从系统内的实体变成**系统边界上的路标**。三大公设也各有工程学身份:上帝存有=两个因果解耦的子系统(道德秩序/自然秩序)之间被设定的**耦合担保人**(德福一致问题本质是子系统同步问题);灵魂不朽=有限系统渐近收敛于理想所需的**无限运行时预算**;意志自由=系统的无因发起操作。`));
body.push(P(`这里有一个值得单独记下的语文学细节:Bxxx那句名言里康德用的德文动词恰恰是 **aufheben**(das Wissen aufheben)。同一个词,黑格尔后来拿去做了辩证法的核心算子。文本把康德的译成"悬置"、黑格尔的译成"扬弃",无意间标出了两套系统策略的分岔:**康德的 aufheben 是在边界处悬置(分层),黑格尔的 aufheben 是穿越边界的代谢(消化)**。而蓝本的结尾正好说过:希腊的ἐποχή是绝望的终点,现代逻辑把悬置焊进了架构。现在可以补上中间缺失的一环——**康德是悬置从绝望转为架构的铰链**,是第一个把ἐποχή当作承重结构来施工的人。塔尔斯基的真值层级,不过是把康德的现象/物自体之切用数学重做了一遍。`));
body.push(P(`代价也和一切分层解悖一样:悖论没有被解决,只被推迟,而且**接缝永远可见**。这道可见的接缝("二元分裂"),就是后面三个人全部的起点和全部的痛。`));

body.push(H('三、费希特:再进入的全量执行——创世改写为"画一个区分"'));
body.push(P(`如果说康德把上帝挪到了边界上,费希特则直接执行了再进入:**把创世者函数改写为系统自身的奠基操作**。`));
body.push(P(`看1794年那句原文:"自我原初设定自身;紧接着,自我设定一个非我与自身相对立。"这就是 Spencer-Brown 的 draw a distinction 的德语先验唯心论版本——第一刀:自我标记自身;第二刀立即随赠:里(自我)与外(非我)同时诞生,determinatio est negatio。Tathandlung(本原行动)之所以拒绝一切静态实体、坚持"先于任何状态的纯粹行动",正因为**区分是操作,不是东西**。而"不存在独立于绝对自我的物自体,非我完全由自我内在活动派生"——这是教科书级的**自创生(autopoiesis)宣言**:系统自己生产构成自己的元件,自己生产自己的边界,乃至自己生产自己的环境。文本说学界公认"自我是唯一本源,非我是派生产物,在因果范式上等同于创造者—受造物关系"——准确,但系统论要补一句:这不是神学的复刻,这是**操作闭合要求的首次显式建模**。`));
body.push(P(`逻各斯传统为什么是核心资源,系统论给出比思想史更硬的理由:约翰福音的道"既是本原自身,又是显现自身的活动"——**算子同时是自己的操作数**。这正是再进入的形式定义。费希特晚年直接引"太初有道"自注知识学,等于承认:我的绝对自我,就是把再进入结构从神学表象里剥出来的哲学裸机。`));
body.push(P(`然后系统给出了教科书级的反应。**无神论事件(1799,被逐出耶拿)是社会系统的免疫应答**:宗教系统的奠基代码是创造者/受造物这道区分,费希特把它去悖论化、暴露为主体的内部操作,等于当众观察了宗教系统赖以运转却不可被观察的那道刀刃——系统随即排异。而费希特危机后的自救,又是教科书级的**解悖操作**:晚期三层结构(神圣太一→绝对自我/逻各斯→有限世界)在绝对自我**头上再加一层**"不可被思维、不可被规定"的寂静太一。请注意这个定语——他等于在塔顶显式安装了一个盲点。悖论没有解决,塔升高了一层,与罗素类型论、塔尔斯基层级的招式分毫不差。`));

body.push(H('四、谢林:未标记空间、黑暗本原,与"实存不可推导"'));
body.push(P(`谢林三个阶段,是三次不同的系统论操作。`));
body.push(P(`**同一哲学阶段**:谢林对费希特的诊断完全正确——绝对自我已经站在一道区分(主/客)的某一侧,不配当终极。于是他退到"先于主体与客体、自我与非我的无差别绝对同一"。用 Spencer-Brown 的词,这是退回**未标记空间(unmarked space)**。但代价立刻显形:零变异度的绝对没有引擎——纯粹同一生不出任何东西。黑格尔那句"静态同一只是空洞深渊"(一切牛都是黑的之夜),本质是阿什比定律的反向陈述:**没有变异度,就没有生成**。至于"艺术直观"作为知神最高道路——主客完全融合、直接直观绝对同一——第二序控制论的判词很冷:不存在不用区分的观察,每一次看都踩着一道自己看不见的刀刃。艺术直观是"无盲点观察"的浪漫主义幻想。`));
body.push(P(`**1809年《自由论文》**是文本中最惊人的系统论时刻:上帝内部有黑暗本原(根据、欲望、无意识)与光明本原,恶的根源在上帝自身的黑暗根据。翻译过来:**系统的奠基处自身不被照亮——谢林把盲点本体论化了,并安放进上帝**。晚期的"无根据(Ungrund)"——"超越一切对立、先于一切存在、不可言说的深渊"——就是未标记空间领了神学的封号。这里值得对照蓝本的一贯标准(悖论暴露的是工具的极限,不是存在的结构):黑格尔把辩证引擎投射进存在,谢林把**不透明性**投射进存在。两人都越了界,但方向相反;而谢林的越界诚实得多——他至少登记了"根基不可推导"这个事实,只是登记在了错误的账户(存在)而非正确的账户(观察者)上。`));
body.push(P(`**晚期柏林讲座**则贡献了第二份不完备性判决,这次瞄准黑格尔:否定哲学从纯粹概念只能推演出"上帝是什么"(本质,Was),永远推不出"上帝实存"(Dass)。**实存,是一切纯概念系统的不可判定语句**——康德"存在不是谓词"在更高一层的复现。而肯定哲学的应对,恰是系统论意义上的**开放系统转向**:既然内部推导封顶,就引入外部输入——把人类全部神话史、启示史当作上帝自我揭示的经验材料来处理。从封闭演绎转为吃进历史数据的开放系统,这是神学阵营里最早的"4.0手势"(尽管内容仍是前现代的)。顺带,"万物在上帝之中,但不等于上帝"的万有在神论,是一次精细的**边界重画**,防止上帝/世界这道区分像斯宾诺莎那里一样彻底塌缩。克尔凯郭尔坐在这个讲座的听众席上——生存对概念的抗议,从这里领了火种。`));

body.push(H('五、黑格尔:神学的希尔伯特纲领——以再进入为引擎的全闭合'));
body.push(P(`黑格尔是四人中唯一读过全部前案卷宗的人,他的方案也最激进:不分层、不退却、不开放——**宣告闭合已经完成**。`));
body.push(P(`三位一体的辩证重构,用 Spencer-Brown 的演算翻译,干净得近乎尴尬:**圣父**=未标记状态(未分化的纯粹理念——注意文本里黑格尔自己的狠话:"抽象的圣父单独不能称为完整上帝",即未标记状态单独什么都不是);**圣子**=画出区分、越过边界(创世与道成肉身:上帝亲手划刀、进入标记态、成为有限);**圣灵**=再进入(区分重返自身,共同体的自我认识,和解)。"上帝必须经历外化自身、回归自身的完整过程,才是完满真实的上帝"——一句话:**上帝就是那个完成了的再进入回路**。原罪被改写为必然的异化环节("分离是合一的前提"),即蓝本2.0阶段的核心翻转:悖论从Bug变燃料。连宗教史的三级台阶都严格按区分演算排列:自然宗教=系统尚未与环境分化;犹太教=区分划下但绝不回返(纯粹超越、主奴、无和解);基督教=**唯一以再进入为教义内容的宗教**(上帝亲自穿越自己划下的边界)——这就是它被封"绝对宗教"的真正理由。`));
body.push(P(`然后是那个致命的最后台阶:宗教以表象(Vorstellung)把握真理,哲学以纯概念把握;绝对精神在哲学中"完全自我认识"。翻译:**哲学自命为最终元层级——无盲点的观察之观察,系统在内部完成对自身一致性与完备性的证明**。"无物外在于绝对精神"=完备性;"一切矛盾终被扬弃"=一致性。这就是神学的希尔伯特纲领,而蓝本的铁律早已备案:足够表达力的闭合系统,二者不可兼得。`));
body.push(P(`历史随即交付了经验形态的不完备性证明,而且样样对号:**左右派黑格尔的分裂,就是这个系统的不可判定语句**——同一套公理,右派推出"绝对精神=圣经人格上帝"(有神论),左派推出"绝对精神=人类类本质"(无神论),系统无法在内部裁决自己的神学指称,大师尸骨未寒即当庭分叉。**费尔巴哈的颠倒**("神学是颠倒的人类学")是一次再进入攻击:把系统自己的还原算子回打到系统的上帝概念上。**马克思**则把辩证引擎整机拆下,换装到物质生产的底盘上运转——引擎在异体上照常点火,反而证明它从来不是Geist的专利。**克尔凯郭尔**是被排除的剩余项:生存着的个体,是概念调节器无论如何吸收不掉的那份变异度(与晚期谢林的Dass同源)。**巴特**的辩证神学是反向重划:把"完全的他者"重新钉回系统之外——再进入事件的复辟运动。至于**尼采**对康德道德上帝的判词("奴隶道德最后的庇护所"),系统论可以说得更冷:**内在化本身就是那次刺杀**——一旦上帝函数被暴露为系统内部的构件(公设、投射、环节),外部性所独有的权威便已死亡,无论持刀者主观上多想保全它。`));
body.push(P(`最后是可直接归档到蓝本既有立场上的谱系学收束。蓝本说:卢曼=被去本体论化的黑格尔。文本补上了缺失的上游:**黑格尔=被本体论化的三位一体**(他自己招供:神学叙事是他的概念真理的"图像化表象")。完整链条于是接通——**三位一体(图像态)→黑格尔(本体论态)→卢曼(操作态)**:辩证引擎在图宾根神学院的车间里设计,被黑格尔装进存在的发动机舱,再被系统论拆回观察者的工作台。这同时回答了一个更深的问题:黑格尔**凭什么**能把矛盾放进存在?因为只有一种存在能够"承受"外化、受难与回归——那就是暗中仍是三一上帝的存在。神学背景不是传记注脚,而是那个范畴错误(把认知的不完备投射为存在的结构)得以成立的**授权条件**。抽掉神学,再进入装进存在就失去了牌照。蓝本对黑格尔的一贯指控,在这里拿到了它的历史发生机制。`));

body.push(H('六、整条弧线:一部倒放的电影,四种闭合策略'));

// ---------- 对照表 ----------
const COLS = [1404, 1725, 1725, 1725, 1725]; // 合计 8304 DXA
const cellP = (text, opts = {}) => new Paragraph({
  alignment: (opts.head || opts.stub) ? AlignmentType.CENTER : AlignmentType.LEFT,
  spacing: { line: 240, before: 20, after: 20 },
  children: [new TextRun({ text, bold: !!(opts.head || opts.stub), font: (opts.head || opts.stub) ? HEI : SONG, size: 18 })],
});
const mkCell = (text, w, opts = {}) => new TableCell({
  width: { size: w, type: WidthType.DXA },
  verticalAlign: VerticalAlign.CENTER,
  margins: { top: 40, bottom: 40, left: 80, right: 80 },
  shading: opts.head ? { type: ShadingType.CLEAR, fill: 'F3EAD3' }
        : opts.stub ? { type: ShadingType.CLEAR, fill: 'FBF7ED' } : undefined,
  children: [cellP(text, opts)],
});
const tableData = [
  ['', '康德', '费希特', '谢林', '黑格尔'],
  ['对闭合问题的姿态', '判定不可闭合,分层止损', '在主体侧重建闭合', '先退回未分化,后承认实存缺口、开放系统', '宣告全闭合已完成'],
  ['核心操作', '划界+悬置(理论/实践两层)', '再进入:创世改写为自我设定', '盲点本体论化(黑暗本原/Ungrund)', '再进入引擎化(三一辩证)'],
  ['系统论对应物', '类型论/元语言分层', '自创生+画出区分', '未标记空间+奠基盲点', '操作闭合+悖论代谢的本体论版'],
  ['上帝的位置', '边界上的调节性理念', '系统自身的奠基行动', '系统之根的不可言说深渊', '系统整体的自我认识回路'],
  ['代价/暴露处', '接缝永远可见(二元分裂)', '免疫排异(无神论事件),晚年补塔一层', '引擎缺失("空洞深渊")', '左右派不可判定;生存剩余项'],
];
body.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 60, after: 100 },
  children: [new TextRun({ text: '表1 德国古典哲学四家对"闭合问题"的系统论策略对照', bold: true, font: HEI, size: 18 })],
}));
body.push(new Table({
  width: { size: 8304, type: WidthType.DXA },
  columnWidths: COLS,
  layout: TableLayoutType.FIXED,
  rows: tableData.map((r, ri) => new TableRow({
    children: r.map((c, ci) => mkCell(c, COLS[ci], { head: ri === 0, stub: ri > 0 && ci === 0 })),
  })),
}));
body.push(new Paragraph({ spacing: { after: 120 }, children: [] }));

body.push(P(`逻辑史的次序是:闭合梦→撞墙→分层→生态。神学史在德国的次序是:**撞墙(1781)→三次逐级升格的去分层尝试→最大闭合→碎裂→生态**。碎裂之后的图景,文本各章"历史影响"部分其实已经列成了清单:自由神学、思辨神学、宗教史学、存在神学、辩证神学、费尔巴哈—马克思的世俗人本主义……这正是"一个封闭神学"死后长出的**神学的生态**——每一支适应一个论域,有效性变成环境相对,与非经典逻辑群的涌现完全同构。`));
body.push(P(`为什么这个系统偏偏拒绝签收康德的判决?三个理由叠加。其一,上帝函数的岗位说明书写的就是"总体性"——一个只在某一层级上有效的、公设化的上帝,在宗教意义需求看来根本不是上帝;意义系统无法容忍一道永久可见的接缝。其二,新教内在化传统提供了再进入的动机与工具(前述预装)。其三,用阿什比的话说:他们前赴后继地想造一台变异度不小于"一切、包括它自己"的调节器。而文本里那个反复出现的批评模式,恰是变异度铁律的经验显影——**每一次总体化都会生出新的界外剩余,且剩余在迁移**:费希特把自然留在了外面(谢林的指控),谢林把运动和历史留在了外面(黑格尔的指控),黑格尔把实存和个体留在了外面(晚期谢林与克尔凯郭尔的指控)。剩余项杀不死,只会搬家。这就是"控制端永远追不上被控端"在思想史里的肉眼可见版。`));

body.push(H('七、诚实的残余'));
body.push(P(`按蓝本的规矩,最后必须自曝。用系统论审视这部神学史,这个动作本身又是一次再进入:把上帝之言翻译为闭合之言,等于预先(和康德、维特根斯坦、卢曼站在一边,反对黑格尔与晚期谢林)裁定了悖论住在观察者这一侧。这个裁定有它自己的盲点,而晚期谢林的抗议正好标出了盲点的位置:任何观察框架——包括系统论——都能解释区分如何运作,却给不出**区分之发生本身**这个赤裸的Dass。系统论能说"每次观察都有盲点",说不出"为什么竟有观察"。这个问题不在塔的任何一层上,也不该被吸收为新的一层;按未济的规矩,让它站在塔外。另需照例声明:称康德为"神学的哥德尔时刻"是一座结构性的桥,不是等号——康德没有证明任何定理,同构的是不可能性的形状与止损方案的形状,一如蓝本对阿什比—哥德尔之桥的自我警示。`));

// ---------- 页脚页码 ----------
const footer = new Footer({
  children: [new Paragraph({
    alignment: AlignmentType.CENTER,
    children: [new TextRun({ children: ['— ', PageNumber.CURRENT, ' —'], font: SONG, size: 18 })],
  })],
});

const doc = new Document({
  creator: 'Claude',
  title: '系统论推演下的德国古典哲学神学史',
  styles: {
    default: {
      document: { run: { font: SONG, size: 24, color: '000000' } },
    },
  },
  sections: [{
    properties: {
      page: { margin: { top: 1440, bottom: 1440, left: 1800, right: 1800 } },
    },
    footers: { default: footer },
    children: [...front, ...body],
  }],
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/out.docx', buf);
  console.log('OK', buf.length, 'bytes');
});

