// 古希腊哲学·操作系统 —— 讲义放映小程序
function pad(n){ return n < 10 ? '0' + n : '' + n; }

const RAW = [
  { kind:'序', title:'整个古希腊哲学的操作系统', sub:'PROLOGOS · 序章', chip:'序章' },
  { kind:'图', title:'十六组核心二元对立', sub:'THE CONSTELLATION · 星座图', chip:'星座图' },
