  { kind:'14', title:'德性 — 快乐', sub:'Ἀρετή · Ἡδονή' },
  { kind:'15', title:'灵魂 — 肉体', sub:'Ψυχή · Σῶμα' },
  { kind:'16', title:'悬置判断 — 不动心', sub:'Ἐποχή · Ἀταραξία' },
  { kind:'结', title:'这16对对立到底揭示了什么？', sub:'SYNTHESIS · 结语', chip:'结语' },
  { kind:'尾', title:'尾声', sub:'ΕΠΙΛΟΓΟΣ · 尾声', chip:'尾声' }
];

Page({
  data: {
    slides: [], opps: [], chips: [],
    current: 0, swiperH: 220, cur: {},
    showCat: false, zoom: false, zoomSrc: ''
  },

  onLoad(){
    let W = 375; try { W = (wx.getSystemInfoSync().windowWidth || 375); } catch(e){}
    const slides = RAW.map((s, idx) => ({ i: idx, no: idx + 1, kind: s.kind, title: s.title, sub: s.sub, chip: s.chip || '', src: '/images/slide-' + pad(idx + 1) + '.jpg' }));
    const opps = slides.filter(s => /^\d\d$/.test(s.kind)).map(s => ({ i: s.i, no: s.kind, cn: s.title, gk: s.sub }));
    const chips = slides.filter(s => s.chip).map(s => ({ i: s.i, label: s.chip }));
    this.setData({ slides, opps, chips, swiperH: Math.round(W * 9 / 16), cur: slides[0] });
  },

  onSwiper(e){ const i = e.detail.current; this.setData({ current: i, cur: this.data.slides[i] }); },
  prev(){ if(this.data.current > 0){ const i = this.data.current - 1; this.setData({ current: i, cur: this.data.slides[i] }); } },
  next(){ if(this.data.current < this.data.slides.length - 1){ const i = this.data.current + 1; this.setData({ current: i, cur: this.data.slides[i] }); } },

  jump(e){ const i = +e.currentTarget.dataset.i; this.setData({ current: i, cur: this.data.slides[i], showCat: false }); },

  toggleCat(){ this.setData({ showCat: !this.data.showCat }); },
  closeCat(){ this.setData({ showCat: false }); },

  openZoom(){ this.setData({ zoom: true, zoomSrc: this.data.slides[this.data.current].src }); },
  closeZoom(){ this.setData({ zoom: false }); },

  noop(){}
});

