function chip(id){
  const n=NODES[id],c=kindColor(id),k=kindOf(id);
  const head=n.num||n.label||'';
  let extra='';
  if(k==='ax'||k==='post')extra=' '+(n.name||'');
  else if(k!=='def'&&n.title)extra=' '+clip(n.title,8);
  return `<span class="chip" data-target="${id}"><span class="k" style="background:${c}"></span>${head}${extra}</span>`;
}

