`[19] Tarski, A. The Concept of Truth in Formalized Languages (1933), in Logic, Semantics, Metamathematics. Oxford: Clarendon Press, 1956.`,
`[20] Kripke, S. Outline of a Theory of Truth. The Journal of Philosophy, 72 (1975): 690—716.`,
`[21] Priest, G. In Contradiction: A Study of the Transconsistent. 2nd ed. Oxford: Oxford University Press, 2006.`,
`[22] Lovejoy, A. O. The Great Chain of Being. Cambridge, MA: Harvard University Press, 1936.`,
`[23] Minsky, H. P. Stabilizing an Unstable Economy. New Haven: Yale University Press, 1986.`,
`[24] Nāgārjuna. Vigrahavyāvartanī（《回诤论》，论\u201c量\u201d之自证与无穷回退）。`,
].forEach(t=>doc.push(ref(t)));

const document=new Document({styles:{default:{document:{run:{font:CN,size:24}}}},
 sections:[{properties:{page:{size:{width:11906,height:16838},margin:{top:1440,bottom:1440,left:1440,right:1440}}},
 headers:{default:new Header({children:[P({alignment:AlignmentType.RIGHT,spacing:{after:0},children:[R("一台机器，两个行程——\u201c自我奠基之不可能\u201d作为哲学史的结构定理",{size:16,color:"8a7f6d"})]})]})},
 footers:{default:new Footer({children:[new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({children:[PageNumber.CURRENT],font:CN,size:18})]})]})},
 children:doc}]});
