const fs = require("fs");
const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle, Header, Footer, PageNumber } = require("docx");
const CN = "SimSun", HEI = "SimHei";
function P(o){return new Paragraph(Object.assign({spacing:{after:140,line:320}},o));}
function R(t,o){return new TextRun(Object.assign({text:t,font:CN,size:24},o));}
function runsOf(text,base){const parts=text.split(/(\*\*[^*]+\*\*)/g).filter(s=>s.length);
 return parts.map(p=>p.startsWith("**")&&p.endsWith("**")?R(p.slice(2,-2),Object.assign({bold:true},base)):R(p,base));}
function body(text){return P({children:runsOf(text),indent:{firstLine:480}});}
function h1(t){return new Paragraph({heading:HeadingLevel.HEADING_1,spacing:{before:360,after:180},children:[new TextRun({text:t,font:HEI,size:30,bold:true,color:"1c1916"})]});}
function h3(t){return new Paragraph({spacing:{before:150,after:90},children:[new TextRun({text:t,font:HEI,size:24,bold:true,color:"1d4e5f"})]});}
function note(text){return P({indent:{left:360},border:{left:{style:BorderStyle.SINGLE,size:12,color:"a73e2c",space:8}},children:runsOf(text,{italics:true,color:"3a342c"})});}
function ref(t){return P({spacing:{after:60,line:280},indent:{left:360,hanging:360},children:[R(t,{size:20})]});}
function abs(text){return P({indent:{left:480,right:480},children:runsOf(text,{size:21,color:"3a342c"})});}

const doc=[];
doc.push(new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:100},children:[new TextRun({text:"一台机器，两个行程",font:HEI,size:38,bold:true})]}));
doc.push(new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:60},children:[new TextRun({text:"——\u201c自我奠基之不可能\u201d作为哲学史的结构定理：基于四十一组二元对立的谱系考察",font:HEI,size:25,color:"3a342c"})]}));
doc.push(new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:320},children:[new TextRun({text:"（从古希腊十六组到近代与启蒙二十五组）",font:CN,size:21,color:"6e6253"})]}));

doc.push(new Paragraph({spacing:{before:60,after:80},children:[new TextRun({text:"摘要",font:HEI,size:24,bold:true})]}));
doc.push(abs(`本文提出并论证一个哲学史的结构性论题：**哲学史是\u201c任何足够丰富的系统都无法为自身奠基\u201d这一结构定理在时间中的展开**。文明先后押上宇宙、神、主体、语言四种介质，去充当那个能自我担保的确定性支点，每一次都在同一个逻辑位置失败，又每一次都从失败中习得更精确的边界。本文以两份对立谱系为史料单位——古希腊十六组二元对立与近代及启蒙二十五组二元对立——证明二者不是两段并列的历史，而是**同一台机器的两个行程**：两条链各自呈现\u201c开机之刀—约束展开—引擎自爆—缝合搭建—战场转移—边界收尾\u201d的六环节同构骨架；连接两个行程的传动轴是中世纪的\u201c总中介\u201d建制（神作为全宇宙唯一持照的自因）；巴门尼德冲击与休谟冲击被证明为同一逻辑事件（系统以自身标准审计自身而自爆）；两条链的终点——悬置与成年——是同一种边界意识的两种姿态，其姿态之差解释了希腊终点为何成为中世纪的入场券、近代终点为何直接成为现代的起点。本文进而给出三条\u201c筛选律\u201d作为哲学史的沉淀机制、\u201c洞的迁移定律\u201d作为问题域的动力学，并以运筹学（约束优化）与信用体系两个独立域的同构复现，为总纲定理提供跨语言检验；最后正面回应黑格尔式竞争解读、辉格史学指控与论题的自我适用问题。`));
doc.push(P({spacing:{before:60,after:280},children:[new TextRun({text:"关键词：",font:HEI,size:21,bold:true}),R("奠基问题；二元对立；巴门尼德冲击；休谟冲击；自我指涉；充足理由律；哥德尔不完备性；哲学史方法论",{size:21})]}));

doc.push(h1(`一、引言：问题、论题与方法`));
doc.push(body(`哲学史的书写长期在两种体例之间摆动：编年的人物志（谁在何时说了什么）与观念的传承史（哪个学说影响了哪个学说）。两种体例共享一个默认假设——哲学史的连续性在于**答案的传承**。本文提出并论证一个相反的假设：哲学史的连续性在于**裂缝的遗传**。真正跨越世纪存续的不是任何学说，而是一批结构性的二元对立；它们之所以存续，是因为它们标记着同一个从未被解决、也不可能在原地被解决的难题——**系统的自我奠基问题**。`));
doc.push(body(`本文的核心论题可压缩为一句：**任何足够丰富的系统，都无法为自身奠基；哲学史就是这条结构定理在时间中的展开。**理性为世界寻找一个能自我担保的支点——找到，压垮，承认边界；古希腊以宇宙为介质完整地跑了一遍这个循环，近代以主体为介质又跑了一遍。本文的史料单位是四十一组二元对立：古希腊十六组（神话—理性、无定—有限、一—多、真理—意见、思维—存在、存在—非存在、形式—质料、潜能—现实、个别—共相、感性—理性、现象—本体、必然—自由、德性—快乐、灵魂—肉体、悬置—不动心等）与近代及启蒙二十五组（分属本体论、认识论、自我、伦理、政治五个问题域）。论证策略是三步：第一步（第三至五节）分别重构两条链的内部因果——每一组对立如何为收拾上一组留下的缺口而生，又如何凿开下一个缺口；第二步（第六至九节）证明两条链的六环节同构、支点的搬家史、两次自爆的同一逻辑形式，以及两个终点的类型学差异；第三步（第十至十一节）以两个独立领域的同构复现检验总纲定理，并回应主要反驳。`));
doc.push(body(`方法论上需要预先声明一点：本文不主张历史目的论。四十一组对立的沉淀不是任何精神实体自我实现的脚印，而是三条可陈述的**筛选机制**反复作用的结果（第二节）；六环节骨架的两次重现不是\u201c历史押韵\u201d的修辞，而是同一组逻辑约束在两种介质上被逼出的同一形状。结构解释与目的论解释的区别，正如断层线的力学解释与\u201c大地意欲开裂\u201d的区别。`));

doc.push(h1(`二、方法论：二元对立作为记录单位与三条筛选律`));
doc.push(body(`为什么用二元对立读史？因为**对立即应力**。一个哲学论题若被某一方彻底解决，它就以定论的形式沉入学科底层，不再作为\u201c对立\u201d存续；反之，凡以对立形态存续两千年者，必是两股力量都无法消灭对方的**应力点**——一与多、共相之争、身心问题、归纳问题、是与应当、物自体难题，至今全部是开放问题。于是对立谱系天然构成一份\u201c未结案卷宗\u201d的清单，而哲学史的深层结构，恰恰写在这份清单的**生成顺序与迁移路径**里。这一方法与洛夫乔伊的\u201c观念单元\u201d史学表面相似而实质相反：观念单元追踪的是被继承的**答案要素**，对立单元追踪的是被遗传的**问题应力**；前者的连续性靠文本影响链维系，后者的连续性由逻辑结构自身保证——即便文本失传，同一追问也会在同一位置重新裂出同一形状的缝。`));
doc.push(body(`对立为什么恰好沉淀为\u201c这些\u201d？三条筛选律给出机制性解释。**筛选律一（分析蕴含律）**：沉淀下来的对立都是\u201c终极性/确定性追问\u201d分析地蕴含的后承，不是偶然选题。一旦决定追问\u201c万物的终极本原\u201d，你就在逻辑上被迫面对：它是否无限（否则不够终极）、是否为一（否则还须追问多背后的一）、能否被思想、能否容纳非存在；一旦决定追问\u201c确定性的最终担保\u201d，你就被迫面对：支点在哪、无穷倒退如何截断、心与物如何契合、必然与自由如何分账。**筛选律二（死结存续律）**：只有未结案者存续，已结案者退出对立清单——这解释了清单的成员资格。**筛选律三（闭环锁定律）**：存续的对立彼此构成\u201c缺口—填补—新缺口\u201d的闭环，环环锁死：删掉任何一环，后续诸环便失去存在理由——删掉\u201c思维—存在\u201d的公设，\u201c存在—非存在\u201d的爆炸就没有引信；删掉\u201c阿基米德点—无穷倒退\u201d的支点之争，\u201c心灵—广延\u201d的二元就无从铸成。三条筛选律在相隔两千年的两次运转中**一字不改地重现**（第八节将回到这一点），这提示它们不是某个时代的特征，而是哲学史的沉淀机制本身：历史筛选思想，如同地质筛选岩层——筛子是常数，变的只是被筛的材料。`));

doc.push(h1(`三、第一次运转：从\u201c神话—理性\u201d到\u201c悬置—不动心\u201d`));
doc.push(body(`希腊链的第一推动不是一个问题，而是一个动作：把解释世界的方式从\u201c讲故事\u201d换成\u201c给出可被反驳的命题\u201d（神话—理性）。这一刀的性质是**解释权换轨**：荷马的谱系叙事无法被反驳，泰勒斯的\u201c万物是水\u201d可以——可反驳性是理性话语的准生证。但理性一旦获得追问资格便无法自限：能追问自然，凭什么不能追问人间规范？于是\u201c自然—约定\u201d将追问外溢到礼法领域。追问\u201c终极本原\u201d随即分析地蕴含出两道墙：本原必须无界（无定—有限）且必须为一（一—多）——整个前苏格拉底哲学，就是\u201c一与多如何兼容\u201d这道题的解法竞赛。`));
doc.push(body(`决定性的一步在巴门尼德。他把\u201c本原必须为一、必须终极\u201d的要求毫不妥协地贯彻到底，并为整台机器装上一条公设：能被思想的才能存在——\u201c思维与存在是同一的\u201d（残篇B3）。用这把逻辑锁一推，灾难性结论呼之欲出：\u201c非存在不存在\u201d（残篇B2、B8）——于是虚空不存在故运动不可能，\u201c尚未是\u201d不存在故变化不可能，\u201c不是\u201d不存在故多不可能；世界是唯一、不动、不变的一，芝诺的悖论为这套结论提供归谬护航；感官所报告的变化与多，被判入\u201c意见之路\u201d（真理—意见）。这就是本文所称的**巴门尼德冲击**：不引入任何怪论，只把系统自身的公设执行到底，让系统当众自爆。此后的希腊哲学，本质上全是对这道伤口的缝合手术。`));
doc.push(body(`缝合分两代完成。柏拉图以空间切割消化冲击：不变的一放进理念界（满足理性），变化的多留在感性界（安抚常识）——\u201c感性—理性\u201d\u201c现象—本体\u201d是这次切割在认知端与本体端的登记；代价是世界被撕成两半，两半之间横着\u201c第三人\u201d式的鸿沟。亚里士多德的三件工具将裂缝内化回一个世界：\u201c个别—共相\u201d摆明分歧（共相不在天上而在个别之中），\u201c形式—质料\u201d提供机制（形式内在于质料，如雕像之形内在于青铜），\u201c潜能—现实\u201d则是为堵\u201c变化不可能\u201d**专造的定制件**——橡子以潜能的方式\u201c是\u201d橡树，变化不是从无到有，而是从潜在的有到实现的有：巴门尼德未被否认，变化却拿到了户口。值得强调的是，亚里士多德同时完成了对可行域形状的自觉守卫：《形而上学》Γ卷（1005b）宣布矛盾律\u201c不可证明，但凡欲反驳它者开口即已使用它\u201d——挑战者自缚，这是对系统边界的第一次明文立法。`));
doc.push(body(`城邦解体后战场转移：同一批宇宙论对立降级为伦理形态复现——宇宙的必然压到人身上（必然—自由：斯多葛以\u201c在我与不在我\u201d划界，伊壁鸠鲁以原子偏斜留缝隙），\u201c好的存在\u201d降为\u201c好的生活\u201d（德性—快乐），两世界内化为人自身的构造（灵魂—肉体）。链条的收尾是皮浪怀疑派：每个论证都有等力的反论证（isostheneia），而追问理由则堕入阿格里帕三难——无穷倒退、循环、独断（第欧根尼·拉尔修IX.88—89；塞克斯都《皮浪学说概要》I.164—177）。三难即\u201c奠基不可能\u201d的第一份完整清单。怀疑派的处置是悬置判断以获不动心（悬置—不动心）：不锯任何一根梁，起身离开桌子。**首尾在此咬合：第一组对立让逻各斯开机，第十六组让逻各斯认命**——理性承认自己封不住真理。`));

doc.push(h1(`四、传动轴：中世纪总中介与\u201c自因\u201d特许`));
doc.push(body(`两条链不是并列的，而是首尾相接的；接口是常被结构史跳过的中世纪。看清接口的力学：希腊链终点的\u201c悬置\u201d等于**留下一个真空**——确定性的岗位空缺了，而文明无法长期在无担保状态下运行。基督教应聘上岗：神成为**总中介**，把两个时代的全部二分一次性焊死——无限担保有限、神圣贯通世俗、启示统摄理性、天国锚定尘世、神法奠基王权。这套建制里有一个精确的逻辑细节值得单独陈述：**神是全宇宙唯一持照的\u201c自因\u201d（causa sui）**。自我奠基这个在任何别处都非法的动作——阿格里帕三难中的\u201c循环\u201d支——被特许在一个点上合法：安瑟伦的本体论证明让\u201c其大无可思议者\u201d从概念自证存在，阿奎那的五路证明让一切理由链止于\u201c自身即存在\u201d的第一因（《神学大全》I, q.2, a.3），斯宾诺莎后来把这张执照写进《伦理学》第一定义（causa sui：其本质包含存在者）。整个中世纪体系，就靠这一个特许自指点撑住。`));
doc.push(body(`传动轴还输送了火种：中世纪唯实论与唯名论的共相之争，是希腊\u201c个别—共相\u201d的直系续审；奥卡姆的剃刀（如无必要勿增实体）预演了近代对形而上冗余的清剿；而这场争论将原封不动地转世为近代的\u201c天赋观念—白板\u201d之争。近代的开端，用本文的语言说只有一句：**科学革命吊销了那张自因执照**——哥白尼、伽利略、牛顿把奇迹逐出自然、把目的因逐出物体，神从\u201c干预者\u201d被改聘为\u201c立法者\u201d，再被逼退到创世那一刻；担保功能名存实亡，于是被总中介焊死的全部二分同时重新开裂，且比希腊时代多裂出两个域（第五节末将解释为何多出）。`));

doc.push(h1(`五、第二次运转：从\u201c信仰—理性\u201d到\u201c未成年—成年\u201d`));
doc.push(body(`近代链的开机之刀是\u201c信仰—理性\u201d：理性从\u201c神学的婢女\u201d升为审计员——不是消灭信仰，而是调换主从。升职立刻带来麻烦：婢女的确定性由主人担保，审计员的确定性由谁担保？\u201c权威—方法\u201d将知识的合法性从出处改为程序（伽利略的数学实验、笛卡尔的方法），而任何程序都需要一个不再依赖出处的起点——\u201c阿基米德点—无穷倒退\u201d由此成为整个近代的头号工程，它正是**充足理由律在认识论的化身**。笛卡尔的\u201c我思\u201d是第一份标书：普遍怀疑是方法化的筛子，筛到底剩下\u201c怀疑这个行为自证怀疑者在\u201d（《第一哲学沉思集》第二沉思）——支点不是教条，而是一次无法自我取消的行为，即**自指的良性用法**（与说谎者句同构而方向相反：彼自毁，此自证）。但支点只救\u201c我在\u201d救不了\u201c世界在\u201d，笛卡尔只好请\u201c诚实的上帝\u201d从认识论后门回来担保清楚分明——被本体论域解雇的神，在认识论域再就业。同时，被抽走中介的\u201c目的因—动力因\u201d裂缝被铸成本体：思维与广延两实体（心灵—广延）——身心问题从此成为近代哲学的伤口，本体论的裂缝整体掉进自我域。`));
doc.push(body(`唯理论沿\u201c必然\u201d一极纯化：斯宾诺莎焊死二元（神即自然，一实体两属性，自由被重新定义为\u201c对必然性的认识\u201d）；莱布尼茨将\u201c逻辑必然—经验或然\u201d建制化为推理真理与事实真理的双轨，并把充足理由律抬为与矛盾律并列的最高公理（《单子论》31—32节）——这是对\u201c防无穷倒退\u201d的正面立法，理由链收束于神（前定和谐：神从担保人升格为程序员）。独断论的病理由此定型：它始终无法证明\u201c理性结构＝世界结构\u201d，因为能作此担保的只有那位已被撤职的神。经验论沿\u201c或然\u201d一极彻底化：洛克以白板处决天赋观念（唯实—唯名之争的近代续审），却留下不可知的\u201c实体基质\u201d与第一/第二性质之分（\u201c物自体—现象\u201d的胚胎）；贝克莱以\u201c凡不可感知者不得设定\u201d消解物质实体，却引入上帝作永恒感知者——与笛卡尔同一个结构动作：桥塌处请神垫板；休谟拒绝再垫，并把同一把刀挥向精神实体：向内省察只见知觉束，永远抓不到\u201c抓知觉的人\u201d（《人性论》1.4.6及附录）——两大实体双双出局，**审计员把自己也审掉了**。`));
doc.push(body(`风暴的风眼是**休谟冲击**：把\u201c观念须有印象\u201d贯彻到底再查因果本身——印象里只有先后相随与恒常联结，\u201c必然产生\u201d从未被给予；因果是习惯性期待，归纳的自我辩护是循环（《人类理解研究》第四、五节）。其结构与巴门尼德冲击完全相同：系统以自身公设审计自身，当众自爆——科学的地基被自己的审计员抽走。休谟之叉（观念关系必然而空转，事实知识扩展而或然）随即为康德预制了问题格式：\u201c又必然又扩展的知识如何可能\u201d，逐字即\u201c先天综合判断如何可能\u201d（《纯粹理性批判》B19）。是—应当的铡刀则把价值域从事实域整体切离——古老的Physis/Nomos之裂拿到逻辑公证书。`));
doc.push(body(`康德的搭建与柏拉图—亚里士多德严格对位。\u201c现象—物自体\u201d把两个世界改写为一条**权限边界**：物自体可思而不可认识——巴门尼德\u201c可思即可在\u201d统治两千年后的第一次修宪。\u201c接受性—自发性\u201d（感性接收杂多、知性以范畴加工）是形式—质料的转世：\u201c思维无内容则空，直观无概念则盲\u201d（A51/B75）；由此\u201c哥白尼式革命\u201d（Bxvi）——对象须符合主体的先天形式，契合被制造而非被担保，**担保人正式失业**：这是全部竞标中第一份不需要神的方案。休谟之洞被逐一回填：因果复活为知性写进一切可能经验的语法；知觉束由先验统觉收束（\u201c我思必须能伴随我的一切表象\u201d，B131）；必然与自由分治两界（理论理性为自然立法，实践理性自我立法——自由从斯宾诺莎的\u201c认识必然\u201d升格为\u201c自我立法\u201d）。启蒙将这场认识论革命外推为社会建制：主权的理由链从神授倒转为同意（社会契约），信仰退为私域（政教分离），道德归于自律——三大法则（自然、秩序、道德）各自成年。链条以康德《什么是启蒙》（1784）收口：启蒙是摆脱自我招致的未成年状态；而成年的完整含义是**自我立法加自知界限**——去掉后半句，成年即退化为\u201c跪拜者成为新的上帝\u201d的自我封神。近代比希腊多出自我域与政治域两级，正是总中介之死的直接后果：担保责任被私有化（每个主体自己扛，\u201c我\u201d遂成独立问题域）同时被公共化（秩序须由同意重建，政治遂成独立问题域）。`));

doc.push(h1(`六、同构骨架与工具的转世`));
doc.push(body(`将两条链并排，六个环节严格对位，列表如下：`));
