/* ---------- SUMMARY (merged principles + quote) ---------- */
.sm .inner{flex:1;display:flex;flex-direction:column;padding:42px 64px 44px;}
.sm-eyebrow{text-align:center;font-size:13px;letter-spacing:.4em;color:var(--terracotta);text-transform:uppercase;margin-bottom:26px;}
