let slides = [];
const phaseName = {1:"一 · 起点",2:"二 · 本原",3:"三 · 巴门尼德",4:"四 · 形而上学",5:"五 · 希腊化"};
function runhead(){return `<div class="runhead">古希腊哲学 <span class="o">·</span> 操作系统</div>`;}

// 1 COVER
slides.push(`<div class="slide cover">
  <div class="key top">✦ &nbsp; ΦΙΛΟΣΟΦΙΑ &nbsp; ✦</div>
  <div class="inner">
    <div class="eyebrow">PROLOGOS · 序章</div>
    <h1>整个古希腊哲学的<br><span class="accent">操作系统</span></h1>
    <div class="sub">讲义末尾那张“<strong>十六组核心概念二元对立</strong>”不是附录，而是骨架。把500年希腊思想压成一张X光片，看到的就是这16对张力在不同思想家身上反复显影、变形、嫁接。这套程序把它们重新组装成一条逻辑链：每一对都是一道<strong>应力点</strong>，每一位哲学家由他在这些应力点上的姿态被精确定位。</div>
  </div>
  <div class="key bot">核 心 二 元 对 立 · 十 六 组</div>
</div>`);

// 2 CONSTELLATION
const ciHTML = D.dualities.map(d=>`<div class="ci">
  <span class="n">N° ${String(d.id).padStart(2,"0")}</span>
  <div class="cn">${d.cn.left} — ${d.cn.right}</div>
  <div class="gk greek">${d.greek.left} · ${d.greek.right}</div>
</div>`).join("");
slides.push(`<div class="slide const">${runhead()}
  <div class="inner">
    <div class="head"><div class="eyebrow">THE CONSTELLATION · 星座图</div>
      <h2>十六组<span class="accent">核心二元对立</span></h2></div>
    <div class="const-grid">${ciHTML}</div>
  </div>
  <div class="pageno">02</div>
</div>`);

// phases + dualities
let pageNo = 2;
const dieById = id => D.dualities.find(x=>x.id===id);
D.phases.forEach(ph=>{
  pageNo++;
  // phase divider
  const chips = ph.dualityIds.map(id=>{const d=dieById(id);return `<span class="dchip"><b>${String(id).padStart(2,"0")}</b> ${d.cn.left}—${d.cn.right}</span>`;}).join("");
  slides.push(`<div class="slide phase">${runhead()}
    <div class="inner">
      <div class="marker"><div class="circle">${ROMAN[ph.id]}</div>
        <div class="eyebrow">${ph.eyebrow}<span class="dim">PHASE ${ph.id}</span></div></div>
      <h2>${ph.title}</h2>
      <div class="intro">${ph.intro}</div>
      <div class="dnav">${chips}</div>
    </div>
    <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
  </div>`);
  // dualities
  ph.dualityIds.forEach(id=>{
    pageNo++;
    const d=dieById(id);
    const expl=d.explanation.map(p=>`<p>${p}</p>`).join("");
    slides.push(`<div class="slide dz">${runhead()}
      <div class="inner">
        <div class="dhead">
          <div class="dnum greek">${String(d.id).padStart(2,"0")}</div>
          <div>
            <div class="pair"><span class="g greek">${d.greek.left}</span><span class="vs">VS</span><span class="g greek">${d.greek.right}</span></div>
            <div class="cn">${d.cn.left}<span class="dash">—</span>${d.cn.right}</div>
          </div>
          <div class="q"><span class="qm">「</span>${d.question}<span class="qm">」</span></div>
        </div>
        <div class="dbody">
          <div class="poles">
            <div class="pole l"><div class="lab">左极 · ${d.poles.left.term}</div>
              <div><span class="term">${d.poles.left.term}</span><span class="pg greek">${d.poles.left.greek}</span></div>
              <div class="desc">${d.poles.left.desc}</div>
              <div class="det">${d.poles.left.detail}</div></div>
            <div class="vsmid">VS</div>
            <div class="pole r"><div class="lab">右极 · ${d.poles.right.term}</div>
              <div><span class="term">${d.poles.right.term}</span><span class="pg greek">${d.poles.right.greek}</span></div>
              <div class="desc">${d.poles.right.desc}</div>
              <div class="det">${d.poles.right.detail}</div></div>
          </div>
          <div class="explain">
            <div class="stakes">${d.stakes}</div>
            ${expl}
          </div>
        </div>
      </div>
      <div class="foot">${phaseName[d.phaseId]}　·　对立 ${String(d.id).padStart(2,"0")}</div>
      <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
    </div>`);
  });
});

// conclusion intro
pageNo++;
slides.push(`<div class="slide cc">${runhead()}
  <div class="inner">
    <div class="eyebrow">EPILOGOS · 底层原理</div>
    <h2>这16对对立<br>到底揭示了什么？</h2>
    <div class="sub">把16组对立连起来看，古希腊500年哲学的<em>深层语法</em>可以浓缩成三句话。</div>
  </div>
  <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
</div>`);

// principles + final quote merged into ONE summary slide
pageNo++;
const prCols = D.principles.map(p=>`<div class="sm-p">
    <div class="sm-pnum greek">${p.num}</div>
    <div class="sm-ptitle">${p.title}</div>
    <div class="sm-pbody">${p.body}</div>
  </div>`).join(`<div class="sm-div"></div>`);
slides.push(`<div class="slide sm">${runhead()}
  <div class="inner">
    <div class="sm-eyebrow">EPILOGOS · 底层原理 · 三句话</div>
    <div class="sm-principles">${prCols}</div>
    <div class="sm-quote">
      <span class="qmark">❝</span>
      这16组对立<span class="accent">不是答案</span>，而是<span class="accent">问题的结构</span>。希腊哲学最终给出的，不是关于世界的真理，而是<span class="accent">面对世界的姿态</span>。
    </div>
  </div>
  <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
</div>`);

const html=`<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><style>${CSS}</style></head><body>${slides.join("\n")}</body></html>`;
fs.writeFileSync("/home/claude/slides.html", html);
