  </div>
  <div class="pageno">02</div>
</div>`);

// phases + dualities
let pageNo = 2;
const dieById = id => D.dualities.find(x=>x.id===id);
D.phases.forEach(ph=>{
  pageNo++;
  // phase divider
  const chips = ph.dualityIds.map(id=>{const d=dieById(id);return `<span class="dchip"><b>${String(id).padStart(2,"0")}</b> ${d.cn.left}—${d.cn.right}</span>`;}).join("");
  slides.push(`<div class="slide phase">${runhead()}
    <div class="inner">
      <div class="marker"><div class="circle">${ROMAN[ph.id]}</div>
        <div class="eyebrow">${ph.eyebrow}<span class="dim">PHASE ${ph.id}</span></div></div>
      <h2>${ph.title}</h2>
      <div class="intro">${ph.intro}</div>
      <div class="dnav">${chips}</div>
    </div>
    <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
  </div>`);
  // dualities
  ph.dualityIds.forEach(id=>{
    pageNo++;
    const d=dieById(id);
    const expl=d.explanation.map(p=>`<p>${p}</p>`).join("");
    slides.push(`<div class="slide dz">${runhead()}
      <div class="inner">
        <div class="dhead">
          <div class="dnum greek">${String(d.id).padStart(2,"0")}</div>
          <div>
            <div class="pair"><span class="g greek">${d.greek.left}</span><span class="vs">VS</span><span class="g greek">${d.greek.right}</span></div>
            <div class="cn">${d.cn.left}<span class="dash">—</span>${d.cn.right}</div>
          </div>
          <div class="q"><span class="qm">「</span>${d.question}<span class="qm">」</span></div>
        </div>
        <div class="dbody">
          <div class="poles">
            <div class="pole l"><div class="lab">左极 · ${d.poles.left.term}</div>
              <div><span class="term">${d.poles.left.term}</span><span class="pg greek">${d.poles.left.greek}</span></div>
              <div class="desc">${d.poles.left.desc}</div>
              <div class="det">${d.poles.left.detail}</div></div>
            <div class="vsmid">VS</div>
            <div class="pole r"><div class="lab">右极 · ${d.poles.right.term}</div>
              <div><span class="term">${d.poles.right.term}</span><span class="pg greek">${d.poles.right.greek}</span></div>
              <div class="desc">${d.poles.right.desc}</div>
              <div class="det">${d.poles.right.detail}</div></div>
          </div>
          <div class="explain">
            <div class="stakes">${d.stakes}</div>
            ${expl}
          </div>
        </div>
      </div>
      <div class="foot">${phaseName[d.phaseId]}　·　对立 ${String(d.id).padStart(2,"0")}</div>
      <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
    </div>`);
  });
});

// conclusion intro
pageNo++;
slides.push(`<div class="slide cc">${runhead()}
  <div class="inner">
    <div class="eyebrow">EPILOGOS · 底层原理</div>
    <h2>这16对对立<br>到底揭示了什么？</h2>
    <div class="sub">把16组对立连起来看，古希腊500年哲学的<em>深层语法</em>可以浓缩成三句话。</div>
  </div>
  <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
</div>`);

// principles
D.principles.forEach(p=>{
  pageNo++;
  slides.push(`<div class="slide pr">${runhead()}
    <div class="inner">
      <div class="eyebrow">底层原理 · PRINCIPLE ${p.num}</div>
      <div class="row"><div class="num greek">${p.num}</div>
        <div><h2>${p.title}</h2><div class="body">${p.body}</div></div></div>
    </div>
    <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
  </div>`);
});

// final quote
pageNo++;
slides.push(`<div class="slide quote">
  <div class="inner">
    <div class="mark">❝</div>
    <div class="big">这16组对立<span class="accent">不是答案</span>，<br>而是<span class="accent">问题的结构</span>。<br>希腊哲学最终给出的，不是关于世界的真理，<br>而是<span class="accent">面对世界的姿态</span>。</div>
    <div class="foot">以16组核心二元对立梳理 <span class="o">✦</span> 古希腊哲学专题</div>
  </div>
  <div class="pageno">${String(pageNo).padStart(2,"0")}</div>
</div>`);

const html=`<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><style>${CSS}</style></head><body>${slides.join("\n")}</body></html>`;
fs.writeFileSync("/home/claude/slides.html", html);
console.log("slides:", slides.length);

