.rl-n{ font-size:21rpx; font-weight:700; }
.rl-f{ font-size:16rpx; color:#6e6253; font-family:"Courier New",monospace; }
.head-corner{ background:transparent; border:none; }
.mcell{ width:74rpx; flex:none; margin-right:5rpx; border:1rpx solid rgba(28,25,22,.14); border-radius:8rpx; background:#faf4e6; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:6rpx 0; min-height:66rpx; }
.mhead{ background:transparent; border:none; min-height:54rpx; }
.hpip{ width:18rpx; height:18rpx; border-radius:50%; margin-bottom:4rpx; }
.hlab{ font-size:17rpx; color:#6e6253; }
