.cchar{ font-size:22rpx; color:#3a342c; }
.cell.on{ border-width:3rpx; }
.cell.on .cchar{ font-weight:700; color:#1c1916; }
.anycell{ }
.anycell .cchar{ font-size:18rpx; color:#6e6253; }
.anycell.on{ background:#e8ddc6; border-color:#6e6253; }

.readout{ margin-top:8rpx; font-size:20rpx; color:#6e6253; display:flex; align-items:center; flex-wrap:wrap; gap:4rpx; }
