.cur{ display:flex; align-items:center; gap:5rpx; margin-left:8rpx; }
.cur-any{ font-size:17rpx; color:#6e6253; }
.cur-pip{ width:20rpx; height:20rpx; border-radius:50%; }

/* scatter */
.scwrap{ flex:1; min-height:0; }
.scatter{ position:relative; margin:10rpx auto 0; }
.ax-v,.ax-h{ position:absolute; background:transparent; }
.ax-v{ width:0; border-left:1rpx dashed rgba(28,25,22,.26); }
.ax-h{ height:0; border-top:1rpx dashed rgba(28,25,22,.26); }
.axlab{ position:absolute; font-size:17rpx; color:#6e6253; transform:translateX(6rpx); }
.axlab.r{ transform:translateY(-22rpx); }
.axlab.rr{ transform:translate(-86rpx,-22rpx); }
.region{ position:absolute; font-size:19rpx; color:#9a8e7c; opacity:.6; letter-spacing:1rpx; }
