.cnode.sel{ border-width:3rpx; border-color:#a73e2c; }
.nlab{ position:absolute; width:88rpx; text-align:center; font-size:16rpx; color:#3a342c; pointer-events:none; }
.scleg{ display:flex; flex-wrap:wrap; gap:12rpx; padding:8rpx 18rpx 14rpx; font-size:18rpx; color:#6e6253; }
