.sheet{ position:fixed; left:0; right:0; bottom:0; background:#faf4e6; border-top:1rpx solid rgba(28,25,22,.2); box-shadow:0 -6rpx 24rpx rgba(28,25,22,.14); border-radius:22rpx 22rpx 0 0; z-index:50; height:60vh; transition:transform .3s ease; }
