.subline{ font-size:21rpx; color:#6e6253; font-family:"Courier New",monospace; margin:4rpx 0 12rpx; }
.ism-chip{ display:inline-block; margin:8rpx 0 12rpx; font-size:22rpx; color:#a73e2c; border:1rpx solid #d9a89c; border-radius:26rpx; padding:6rpx 16rpx; }
.cfgrow{ margin:6rpx 0 14rpx; }
.cfg{ display:flex; align-items:center; padding:6rpx 0; }
.cfg .cn{ width:120rpx; font-size:23rpx; color:#3a342c; }
.cfg .pip{ width:20rpx; height:20rpx; border-radius:50%; margin:0 14rpx 0 2rpx; }
.cfg .cv{ font-size:23rpx; font-weight:700; }
.cfg .cf{ margin-left:auto; font-size:17rpx; color:#6e6253; font-family:"Courier New",monospace; }
.blurb{ font-size:24rpx; line-height:1.65; color:#3a342c; border-left:6rpx solid #b8893a; padding:3rpx 0 3rpx 14rpx; margin-bottom:12rpx; }
.p-label{ font-size:19rpx; letter-spacing:2rpx; color:#a73e2c; text-transform:uppercase; margin:14rpx 0 8rpx; }
.note{ font-size:24rpx; line-height:1.7; color:#3a342c; }
.note.sm{ font-size:22rpx; color:#6e6253; }
.em{ color:#a73e2c; }
.pipline{ display:flex; flex-wrap:wrap; margin:8rpx 0; }
.pk{ display:inline-flex; align-items:center; gap:5rpx; margin:0 16rpx 8rpx 0; font-size:21rpx; }
.pk .pip{ width:20rpx; height:20rpx; border-radius:50%; }
.chips{ display:flex; flex-wrap:wrap; }
.chip{ font-size:22rpx; color:#3a342c; background:#f3ebda; border:1rpx solid rgba(28,25,22,.26); border-radius:24rpx; padding:5rpx 15rpx; margin:0 12rpx 12rpx 0; }

.card{ border:1rpx solid rgba(28,25,22,.26); border-radius:12rpx; background:#f3ebda; padding:12rpx 14rpx; margin-bottom:11rpx; }
.card-h{ display:flex; align-items:center; gap:8rpx; margin-bottom:8rpx; }
.card-n{ font-size:25rpx; font-weight:700; color:#1c1916; }
.card-c{ margin-left:auto; font-size:18rpx; color:#6e6253; font-family:"Courier New",monospace; }
.card-pips{ display:flex; align-items:center; gap:8rpx; margin-bottom:7rpx; }
.card-pips .pip{ width:18rpx; height:18rpx; border-radius:50%; }
.card-sig{ font-size:17rpx; color:#6e6253; font-family:"Courier New",monospace; margin-left:6rpx; }
.card-mem{ font-size:20rpx; color:#6e6253; line-height:1.5; }

/* browse overlay */
.browse{ position:fixed; inset:0; background:#f3ebda; z-index:80; display:none; flex-direction:column; }
.browse.show{ display:flex; }
