page{ background:#e8ddc6; color:#1c1916; font-family:Georgia,"Songti SC",serif; height:100%; }
.app{ display:flex; flex-direction:column; min-height:100vh; }

/* 顶部 */
.topbar{ flex:none; display:flex; align-items:center; justify-content:space-between; padding:16rpx 22rpx 12rpx; background:#f3ebda; border-bottom:1rpx solid rgba(28,25,22,.14); }
.tt{ display:flex; flex-direction:column; min-width:0; }
.t1{ font-size:32rpx; font-weight:700; letter-spacing:1rpx; }
.t2{ font-size:20rpx; color:#6e6253; margin-top:2rpx; }
.cat-btn{ flex:none; font-size:24rpx; color:#a73e2c; border:1rpx solid #d9a89c; border-radius:28rpx; padding:8rpx 20rpx; margin-left:12rpx; }

/* 幻灯片台面 */
.stage{ position:relative; background:#efe6d2; }
.swiper{ width:100%; }
.slide{ width:100%; height:100%; display:block; }
.zoom-hint{ position:absolute; right:16rpx; bottom:16rpx; font-size:19rpx; color:#fff; background:rgba(28,25,22,.5); border-radius:24rpx; padding:5rpx 14rpx; }

/* 翻页条 */
.navbar{ flex:none; display:flex; align-items:center; gap:10rpx; padding:14rpx 18rpx; background:#f3ebda; border-top:1rpx solid rgba(28,25,22,.1); }
.nav-btn{ flex:none; width:64rpx; height:64rpx; border-radius:50%; border:1rpx solid rgba(28,25,22,.26); background:#faf4e6; display:flex; align-items:center; justify-content:center; font-size:38rpx; color:#1c1916; }
.nav-btn.disabled{ opacity:.3; }
.meta{ flex:1; min-width:0; text-align:center; display:flex; flex-direction:column; }
.meta-no{ font-size:19rpx; color:#a73e2c; letter-spacing:2rpx; font-family:"Courier New",monospace; }
.meta-tt{ font-size:28rpx; font-weight:700; color:#1c1916; line-height:1.2; margin-top:2rpx; }
.meta-sub{ font-size:20rpx; color:#6e6253; margin-top:2rpx; }

.hint{ flex:none; text-align:center; font-size:19rpx; color:#9a8e7c; padding:12rpx 24rpx 26rpx; }

/* 目录 */
.cat{ position:fixed; inset:0; z-index:60; visibility:hidden; }
.cat.show{ visibility:visible; }
.cat-mask{ position:absolute; inset:0; background:rgba(28,25,22,.42); opacity:0; transition:opacity .25s; }
.cat.show .cat-mask{ opacity:1; }
.cat-panel{ position:absolute; left:0; right:0; bottom:0; max-height:82vh; background:#f3ebda; border-radius:24rpx 24rpx 0 0; transform:translateY(100%); transition:transform .3s ease; display:flex; flex-direction:column; }
.cat.show .cat-panel{ transform:translateY(0); }
.cat-h{ display:flex; align-items:center; padding:22rpx 26rpx 14rpx; border-bottom:1rpx solid rgba(28,25,22,.12); }
.cat-t{ font-size:30rpx; font-weight:700; }
.cat-x{ margin-left:auto; font-size:42rpx; color:#6e6253; line-height:1; }
.cat-body{ padding:16rpx 22rpx 50rpx; }
.chips{ display:flex; flex-wrap:wrap; margin-bottom:14rpx; }
.chip{ font-size:22rpx; color:#a73e2c; background:#faf4e6; border:1rpx solid #d9a89c; border-radius:24rpx; padding:7rpx 16rpx; margin:0 12rpx 12rpx 0; }
.grid{ display:flex; flex-wrap:wrap; justify-content:space-between; }
.gcell{ width:48.5%; box-sizing:border-box; background:#faf4e6; border:1rpx solid rgba(28,25,22,.2); border-radius:12rpx; padding:12rpx 14rpx; margin-bottom:12rpx; display:flex; flex-direction:column; }
.g-no{ font-size:18rpx; color:#a73e2c; letter-spacing:2rpx; }
.g-cn{ font-size:27rpx; font-weight:700; color:#1c1916; margin-top:4rpx; }
.g-gk{ font-size:19rpx; color:#6e6253; margin-top:3rpx; font-style:italic; }

/* 放大查看 */
.zoomwrap{ position:fixed; inset:0; z-index:80; background:rgba(20,17,14,.96); display:none; }
.zoomwrap.show{ display:block; }
.zarea{ width:100%; height:100vh; }
.zview{ width:100%; height:100%; }
.zimg{ width:100%; height:100%; }
.z-close{ position:fixed; top:60rpx; right:30rpx; width:64rpx; height:64rpx; border-radius:50%; background:rgba(255,255,255,.16); color:#fff; font-size:44rpx; line-height:60rpx; text-align:center; z-index:81; }
.z-tip{ position:fixed; bottom:50rpx; left:0; right:0; text-align:center; color:rgba(255,255,255,.7); font-size:22rpx; z-index:81; }

