const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Header, Footer,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle,
  TabStopType, TabStopPosition, PageNumber, ShadingType
} = require('docx');

// ============================================================
// 字体配置（中西混排：宋体/黑体 + Cambria）
// ============================================================
const fontBody = { ascii: "Cambria", eastAsia: "宋体", hAnsi: "Cambria", cs: "Cambria" };
const fontHeading = { ascii: "Cambria", eastAsia: "黑体", hAnsi: "Cambria", cs: "Cambria" };
const fontGreek = { ascii: "Cambria", eastAsia: "宋体", hAnsi: "Cambria", cs: "Cambria" };

// 字号常量（half-points: 22 = 11pt; 24 = 12pt; 28 = 14pt; 32 = 16pt; 44 = 22pt）
const SIZE_BODY = 24;       // 12pt 小四
const SIZE_TITLE = 44;      // 22pt 标题
const SIZE_SUBTITLE = 32;   // 16pt 副标题
const SIZE_H1 = 32;         // 16pt 一级标题
const SIZE_H2 = 28;         // 14pt 二级标题

// ============================================================
// 工具：解析 **粗体** 标记，返回 TextRun 数组
// ============================================================
function parseRich(text, opts = {}) {
  const font = opts.font || fontBody;
  const size = opts.size || SIZE_BODY;
  const runs = [];
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  for (const part of parts) {
    if (!part) continue;
    if (part.startsWith('**') && part.endsWith('**')) {
      const inner = part.slice(2, -2);
      runs.push(new TextRun({ text: inner, bold: true, font, size }));
    } else {
      runs.push(new TextRun({ text: part, font, size }));
    }
  }
  return runs;
}

// ============================================================
// 段落构造器
// ============================================================
// 正文段落：首行缩进 2 字符，1.5 倍行距，段后 6pt
function p(text) {
  return new Paragraph({
    children: parseRich(text),
    spacing: { before: 0, after: 120, line: 360, lineRule: "auto" },
    indent: { firstLine: 480 },
    alignment: AlignmentType.JUSTIFIED
  });
}

// 列表项段落（带圆点缩进）
function bullet(text) {
  return new Paragraph({
    children: parseRich(text),
    spacing: { before: 0, after: 80, line: 360, lineRule: "auto" },
    numbering: { reference: "bullets", level: 0 },
    alignment: AlignmentType.JUSTIFIED
  });
}

// 主标题
function title(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, font: fontHeading, size: SIZE_TITLE })],
    spacing: { before: 0, after: 240 },
    alignment: AlignmentType.CENTER
  });
}

// 副标题
function subtitle(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, font: fontHeading, size: SIZE_SUBTITLE })],
    spacing: { before: 240, after: 240 },
    alignment: AlignmentType.CENTER
  });
}

// 一级标题（带下划线装饰）
function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, bold: true, font: fontHeading, size: SIZE_H1 })],
    spacing: { before: 480, after: 240 },
    border: {
      bottom: { style: BorderStyle.SINGLE, size: 8, color: "1F3864", space: 4 }
    }
  });
}

// 二级标题（对立 N）
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, bold: true, font: fontHeading, size: SIZE_H2, color: "1F3864" })],
    spacing: { before: 320, after: 160 }
  });
}

// 16 对立总表的条目（编号+希腊文+中文，居中）
function dualityListItem(num, text) {
  return new Paragraph({
    children: [
      new TextRun({ text: `${num}. `, bold: true, font: fontBody, size: SIZE_BODY }),
      new TextRun({ text, font: fontBody, size: SIZE_BODY }),
    ],
    spacing: { before: 0, after: 60, line: 320, lineRule: "auto" },
    indent: { left: 720, hanging: 360 }
  });
}

// 空行
function blank() {
  return new Paragraph({ children: [new TextRun({ text: "", font: fontBody, size: SIZE_BODY })] });
}

// ============================================================
// 文档内容
// ============================================================
const content = [];

// —— 主标题 ——
content.push(title("16 组核心概念二元对立去看古希腊哲学"));

// —— 副标题 ——
content.push(subtitle("古希腊哲学核心概念二元对立总表"));

// —— 16 对立列表 ——
const dualities = [
  "Μῦθος  VS  Λόγος    神话 — 理性",
  "Φύσις  VS  Νόμος    自然 — 约定",
  "Ἄπειρον  VS  Πέρας    无定 — 有限",
  "Ἕν  VS  Πολλά    一 — 多",
  "Ἐπιστήμη  VS  Δόξα    真理 — 意见",
  "Νοεῖν  VS  Εἶναι    思维 — 存在",
  "Ὄν  VS  Μὴ Ὄν    存在 — 非存在",
  "Μορφή  VS  Ὕλη    形式 — 质料",
  "Δύναμις  VS  Ἐνέργεια    潜能 — 现实",
  "Καθ' ἕκαστον  VS  Καθόλου    个别 — 共相",
  "Αἴσθησις  VS  Νοῦς    感性 — 理性",
  "Φαινόμενον  VS  Οὐσία    现象 — 本体",
  "Ἀνάγκη  VS  Προαίρεσις    必然 — 自由",
  "Ἀρετή  VS  Ἡδονή    德性 — 快乐",
  "Ψυχή  VS  Σῶμα    灵魂 — 肉体",
  "Ἐποχή  VS  Αταραξία    悬置判断 — 不动心",
];
dualities.forEach((d, i) => content.push(dualityListItem(i + 1, d)));

content.push(blank());

// —— 引言 ——
content.push(p("用古希腊哲学核心概念二元对立的\u201C骨架\u201D，把整部古希腊哲学史压扁成一张X光片，看到的就是这16组对立在不同思想家身上反复显影、变形、嫁接。"));
content.push(p("下面把这16组当成16把钥匙，按古希腊哲学**实际发生的历史顺序**重新编组，把讲义里那些人名和学派串成一条线。"));

// ============================================================
// 一、起点：哲学是怎么诞生的（对立1—2）
// ============================================================
content.push(h1("一、起点：哲学是怎么诞生的（对立 1—2）"));

content.push(h2("对立 1：Μῦθος vs Λόγος（神话 — 理性）"));
content.push(p("这是**哲学得以存在的那一刀**。在泰勒斯之前，希腊人解释世界靠的是Mythos——荷马、赫西俄德的故事：宙斯发怒于是打雷，海神波塞冬不爽于是地震。Mythos的特征是叙事性、人格化、不可追问（你不能问\u201C为什么宙斯会发怒\u201D，神就是这样）。"));
content.push(p("公元前6世纪，米利都的泰勒斯说了一句很怪的话：\u201C万物的本原是水。\u201D这句话本身对不对不重要，重要的是它的**形式**变了：它不再讲故事，而是给出一个可以被讨论、反驳、修改的命题。阿那克西曼德接着说\u201C不对，是阿派朗\u201D，阿那克西美尼又说\u201C是气\u201D——师徒三代彼此反驳，这就是Logos：可言说、可论证、可追问的理性。"));
content.push(p("讲义里那句\u201C从神创世界转向自然本原的理性追问\u201D，本质上说的就是这一组对立。**整个古希腊哲学就是Logos一步步从Mythos里挣脱出来的过程**。"));

content.push(h2("对立 2：Φύσις vs Νόμος（自然 — 约定）"));
content.push(p("但Logos的胜利留下了一个新问题：如果可以用Logos追问自然（Physis），那为什么不能追问人类社会的规则（Nomos）？"));
content.push(p("这就是**智者派**的突破。普罗泰戈拉发现：希腊各城邦的法律、习俗、道德彼此不同——斯巴达觉得偷东西没问题，雅典觉得不行；波斯人觉得乱伦正常，希腊人觉得是禁忌。那么道德到底是Physis（自然本有的、放之四海皆准）还是Nomos（人为约定、随时可改）？"));
content.push(p("智者派的答案是后者，于是导出\u201C人是万物的尺度\u201D。色拉叙马霍斯更激进：\u201C正义就是强者的利益\u201D——所谓的\u201C公平\u201D只是强者立的规矩。"));
content.push(p("这一组对立直接催生了**苏格拉底转向**。苏格拉底之所以要去街头辩论\u201C什么是正义\u201D\u201C什么是勇敢\u201D，就是要回击智者派——他试图证明，德性虽然不在自然现象里，但仍然有Logos可以把握的客观结构。"));

// ============================================================
// 二、宇宙论的核心问题：找"那个东西"（对立3—4）
// ============================================================
content.push(h1("二、宇宙论的核心问题：找\u201C那个东西\u201D（对立 3—4）"));

content.push(h2("对立 3：Ἄπειρον vs Πέρας（无定 — 有限）"));
content.push(p("米利都学派一动手就遇到一个麻烦。泰勒斯说本原是水，但水是\u201C有形\u201D的，是有限的——如果它是有限的，那它之外是什么？阿那克西曼德立刻看出这个漏洞，提出**Apeiron（阿派朗，无定形/无限者）**：本原必须是无限、无规定、无属性的，否则就不能生出有限多样的万物。"));
content.push(p("但这又走到另一个极端：完全无规定的东西怎么生出有规定的东西？"));
content.push(p("毕达哥拉斯学派给出了革命性回答：**Peras（有限/界限/比例）才是世界之所以有秩序的关键**。无定形的东西要\u201C被数限定\u201D，才成为可认识的事物。一根弦本身是连续的（无定），但当弦长按1:2、2:3、3:4的比例划分时，就产生了八度、五度、四度——和谐由此诞生。"));
content.push(p("这一组的底层原理是：**秩序 = 给无定形加上限定**。这个直觉后来变成柏拉图的\u201C理念赋予感性世界以形式\u201D，再变成亚里士多德的\u201C形式作用于质料\u201D。"));

content.push(h2("对立 4：Ἕν vs Πολλά（一 — 多）"));
content.push(p("这是古希腊形而上学**最核心**的问题。"));
content.push(p("你看到的世界是\u201C多\u201D：千万种事物、千万种变化。但理性追问\u201C本原\u201D时，本原必须是\u201C一\u201D——否则它就不是终极的，因为还要追问这\u201C多\u201D背后的\u201C一\u201D。"));
content.push(p("讲义里每一个前苏格拉底哲学家其实都在回答同一个问题：**一与多如何兼容？**"));
content.push(bullet("泰勒斯：水（一）→ 万物（多），但没解释\u201C怎么\u201D变"));
content.push(bullet("阿那克西美尼：气（一）通过稀散/凝聚（机制）→ 万物（多）"));
content.push(bullet("赫拉克利特：火（一）按逻各斯燃烧/熄灭 → 万物（多），但\u201C一\u201D本身就是流变"));
content.push(bullet("毕达哥拉斯：数（一）通过比例 → 万物（多）"));
content.push(bullet("巴门尼德：只有\u201C一\u201D是真的，\u201C多\u201D是假象——**直接砍掉一边**"));
content.push(bullet("恩培多克勒：四根（多元的\u201C一\u201D群）+ 爱与争（机制）→ 万物"));
content.push(bullet("阿那克萨戈拉：无限种子（多元）+ 努斯（一个统一的推动者）"));
content.push(bullet("原子论：无限原子（多）+ 虚空 → 万物"));
content.push(p("整个前苏格拉底的演化，就是**\u201C一与多\u201D这道题的不同解法的竞赛**。"));

// ============================================================
// 三、巴门尼德冲击：哲学进入"存在论"主场（对立5—7）
// ============================================================
content.push(h1("三、巴门尼德冲击：哲学进入\u201C存在论\u201D主场（对立 5—7）"));
content.push(p("巴门尼德是讲义里最该认真对待的人。他几乎以一己之力，把希腊哲学从\u201C宇宙论\u201D推到\u201C本体论/存在论\u201D。他的整个体系建立在三组对立上："));

content.push(h2("对立 5：Ἐπιστήμη vs Δόξα（真理 — 意见）"));
content.push(p("巴门尼德的诗分两条路：**真理之路**（Aletheia/Episteme）与**意见之路**（Doxa）。"));
content.push(p("感官告诉你万物在变化、生灭、运动——这是Doxa，意见，假象。理性告诉你：存在者存在，非存在者不存在——这是Episteme，真理。两者不在同一个层级。"));
content.push(p("这是西方哲学**第一次**严格区分\u201C看上去如何\u201D和\u201C实际如何\u201D。柏拉图后来的整个理念论，本质上就是把这条区分**做大、做实**：可见世界是Doxa，可知世界（理念）是Episteme。"));

content.push(h2("对立 6：Νοεῖν vs Εἶναι（思维 — 存在）"));
content.push(p("巴门尼德有一句残篇，海德格尔后来花了一辈子去琢磨：\u201C**思维与存在是同一的**\u201D（τὸ γὰρ αὐτὸ νοεῖν ἐστίν τε καὶ εἶναι）。"));
content.push(p("什么意思？意思是：能被思想的，就是能存在的；不能被思想的，就不能存在。逻辑可能性 = 本体可能性。"));
content.push(p("这是一个极其大胆的形而上学公设——它直接把**思想的内在结构当作存在本身的结构**。后世从柏拉图（理念是可思的本质）到黑格尔（思维与存在的同一性）都吃这碗饭。"));
content.push(p("顺便说一句：你之前讨论过的\u201C维特根斯坦语言界限即世界界限\u201D这个进路，和巴门尼德这句话是**远房亲戚**——都把\u201C可言说/可思想\u201D作为\u201C存在\u201D的边界。但维特根斯坦把它当成限制（语言之外有不可说的），巴门尼德把它当成胜利（不可思的就是无）。这正是你那条\u201C语言极限\u201D路径与\u201C辩证法\u201D路径分野的最早源头。"));

content.push(h2("对立 7：Ὄν vs Μὴ Ὄν（存在 — 非存在）"));
content.push(p("从上面那句话，巴门尼德推出：\u201C非存在不存在。\u201D"));
content.push(p("听起来像同义反复，但杀伤力极大："));
content.push(bullet("如果\u201C非存在不存在\u201D，那\u201C虚空\u201D不存在 → 没有运动空间 → **运动不可能**"));
content.push(bullet("如果\u201C非存在不存在\u201D，那\u201C还不是的状态\u201D不存在 → **变化不可能**（因为变化要求事物从\u201C还不是X\u201D变成\u201C是X\u201D）"));
content.push(bullet("如果\u201C非存在不存在\u201D，那存在只能是\u201C一\u201D（因为\u201C多\u201D要求事物之间有\u201C不是\u201D的区分）→ **多不可能**"));
content.push(p("芝诺四个悖论（飞矢不动、阿喀琉斯追龟等）就是为这一论点提供反证。"));
content.push(p("巴门尼德留下的烂摊子，是整个后续希腊哲学不得不收拾的："));
content.push(bullet("**恩培多克勒**让步：四根本身永恒不变（向巴门尼德低头），但它们的组合分离造成变化（救回常识）"));
content.push(bullet("**原子论**反击：让\u201C虚空\u201D重新拥有某种存在地位——虚空就是\u201C非存在\u201D，但它\u201C是\u201D——以此为运动腾出空间"));
content.push(bullet("**柏拉图**在《智者篇》里\u201C弑父巴门尼德\u201D，正面承认\u201C非存在\u201D以某种方式存在（即\u201C相异性\u201D）"));
content.push(p("所以对立7不是一道考题，而是**整个古典哲学的引擎**。"));

// ============================================================
// 四、柏拉图—亚里士多德的形而上学搭建（对立8—12）
// ============================================================
content.push(h1("四、柏拉图—亚里士多德的形而上学搭建（对立 8—12）"));
content.push(p("讲义里柏拉图和亚里士多德这两页看起来很短，但其实他们做的事情是：**把前面所有遗留问题打包成一个统一的形而上学架构**。这套架构由五对概念支撑。"));

content.push(h2("对立 11：Αἴσθησις vs Νοῦς（感性 — 理性）& 对立 12：Φαινόμενον vs Οὐσία（现象 — 本体）"));
content.push(p("先看这两对，因为它们是柏拉图整个体系的入口。"));
content.push(p("**柏拉图的\u201C二重世界\u201D**就是这两组对立的具体化："));
content.push(bullet("感性（Aisthesis）只能接触**现象（Phainomenon）**——洞穴墙上的影子"));
content.push(bullet("理性（Nous）才能把握**本体（Ousia）**——洞穴外的真实事物，即理念"));
content.push(p("讲义里的\u201C洞穴喻\u201D，本质上就是把对立5（真理—意见）+ 对立11（感性—理性）+ 对立12（现象—本体）画成了一幅画。这三组其实在柏拉图那里是**同一组**对立的三种表述。"));

content.push(h2("对立 10：Καθ' ἕκαστον vs Καθόλου（个别 — 共相）"));
content.push(p("这一对是**柏拉图与亚里士多德分家**的核心。"));
content.push(p("你看到一匹具体的马（个别），又看到\u201C马本身\u201D这个概念（共相）。问题是：哪一个更真实？"));
content.push(bullet("**柏拉图**说：**共相（理念）更真实**。具体的马是对\u201C马的理念\u201D的不完美摹本。马会死，但\u201C马本身\u201D永恒。"));
content.push(bullet("**亚里士多德**说：**个别（这匹具体的马）更真实**。\u201C马本身\u201D不是飘在天上的独立实体，它只是从无数具体的马里抽出来的共同结构。"));
content.push(p("这就是亚里士多德\u201C批判柏拉图\u201D那一栏的核心：他要把柏拉图分裂在两个世界的\u201C个别\u201D和\u201C共相\u201D重新粘回一个世界。"));

content.push(h2("对立 8：Μορφή vs Ὕλη（形式 — 质料）"));
content.push(p("亚里士多德怎么粘？答案是**形质论（hylomorphism）**。"));
content.push(p("一块青铜（质料Hyle）被铸成雕像（形式Morphe）。形式不是另一个世界的理念，**它就内在于这块青铜里**。没有无形式的质料，也没有无质料的形式（除了纯形式即神）。"));
content.push(p("这一对解决了对立10：共相（形式）不在彼岸，而**在个别（具体物）之中**作为其内在结构。"));

content.push(h2("对立 9：Δύναμις vs Ἐνέργεια（潜能 — 现实）"));
content.push(p("这对解决的是巴门尼德留下的**变化问题**。"));
content.push(p("巴门尼德说变化不可能：橡子怎么\u201C变成\u201D橡树？要么橡子已经是橡树（无变化），要么橡子\u201C不是\u201D橡树而变成\u201C是\u201D橡树（违反\u201C非存在不存在\u201D）。"));
content.push(p("亚里士多德说：橡子里以**潜能（Dynamis）**的方式\u201C是\u201D橡树，长成后以**现实（Energeia）**的方式\u201C是\u201D橡树。变化不是从\u201C无\u201D到\u201C有\u201D，而是从\u201C潜在的有\u201D到\u201C实现的有\u201D。"));
content.push(p("这是一个绝妙的修辞策略：他**没有否认巴门尼德**（潜能也是某种\u201C是\u201D），但**给了变化以本体论位置**。讲义里\u201C四因说\u201D的\u201C目的因\u201D——橡子的目的就是橡树——也是建立在这个区分上。"));

// ============================================================
// 五、希腊化转向：从"世界是什么"到"我该如何活"（对立13—16）
// ============================================================
content.push(h1("五、希腊化转向：从\u201C世界是什么\u201D到\u201C我该如何活\u201D（对立 13—16）"));
content.push(p("讲义后半部分的关键词是：**\u201C哲学从城邦公共政治思辨转向个人安身立命\u201D**。这个转向通过最后四组对立呈现。"));

content.push(h2("对立 13：Ἀνάγκη vs Προαίρεσις（必然 — 自由）"));
content.push(p("希腊化时代的人面对的世界是：城邦没了、帝国说散就散、自己的命运被宏大力量碾压。**Ananke（必然/宿命）**变成压倒性的体验。"));
content.push(bullet("**德谟克利特原子论**：一切都是原子机械碰撞的必然结果——彻底的决定论"));
content.push(bullet("**斯多葛主义**：宇宙逻各斯支配一切，外部事件全是必然，**但**你的内心判断仍可Prohairesis（自由抉择）——爱比克泰德的核心：区分\u201C在我\u201D与\u201C不在我\u201D"));
content.push(bullet("**伊壁鸠鲁**：在原子论里偷偷塞入\u201C原子的偏斜\u201D（clinamen），为自由意志保留物理学空间"));
content.push(p("这一对**今天仍然活着**——它是后来基督教恩典与自由意志之争、近代决定论与自由意志之争、当代脑科学与道德责任之争的源头。"));

content.push(h2("对立 14：Ἀρετή vs Ἡδονή（德性 — 快乐）"));
content.push(p("人生最高的善是什么？"));
content.push(bullet("**苏格拉底/柏拉图/亚里士多德/斯多葛**：是**德性（Arete）**——人之为人的卓越状态、品格的完善"));
content.push(bullet("**伊壁鸠鲁**：是**快乐（Hedone）**——但要注意，他说的不是放纵享乐，而是**身体无痛苦、心灵不受扰**的稳定状态，所以本质上是一种\u201C高级快乐\u201D"));
content.push(bullet("**犬儒第欧根尼**：两边都骂——德性要的不是社会承认的\u201C卓越\u201D，快乐也不是感官放纵，而是**Autarkeia（自足）**"));
content.push(p("这一对其实暗藏一个更深的问题：**伦理学的基础是\u201C人应当如何\u201D（规范）还是\u201C人实际欲求什么\u201D（事实）？**——这是后来休谟、康德、功利主义之争的源头。"));

content.push(h2("对立 15：Ψυχή vs Σῶμα（灵魂 — 肉体）"));
content.push(p("这一对最早不是哲学问题，是宗教问题——讲义里讲得很清楚：**俄耳甫斯教**带来灵魂轮回与净化观念，毕达哥拉斯把它**理性化**，柏拉图再把它**哲学化**："));
content.push(bullet("灵魂在进入肉体前已认识理念（回忆说）"));
content.push(bullet("肉体是灵魂的\u201C坟墓\u201D（soma sema）"));
content.push(bullet("哲学就是练习死亡——让灵魂摆脱肉体回归理念世界"));
content.push(p("亚里士多德反过来：灵魂不是独立的实体，**灵魂是肉体的形式**（重新用对立8来解决问题）——这是一个非常优雅的内化。"));
content.push(p("新柏拉图主义则把柏拉图灵魂论推向极致：\u201C**太一 → 理智 → 灵魂 → 物质**\u201D的流溢说，灵魂的使命是逆流而上回归太一。"));
content.push(p("讲义最后一页特别讲新柏拉图主义如何影响基督教，本质上就是**Psyche/Soma这对对立被基督教全盘继承**：灵魂不朽、肉体堕落、灵性救赎——直到马丁·路德、笛卡尔、乃至当代的\u201C意识—身体\u201D问题，都活在这条阴影里。"));

content.push(h2("对立 16：Ἐποχή vs Ἀταραξία（悬置判断 — 不动心）"));
content.push(p("这是讲义压轴的对立，也最微妙。"));
content.push(p("**怀疑主义皮浪派**的核心论证是：每一个哲学命题都有同样有力的反命题（\u201C独断论者越多，他们越证明真理无法获得\u201D）。于是真正智慧的做法是：**Epoche——悬置判断**，对任何事都不肯定不否定。"));
content.push(p("但这不是消极的虚无主义——悬置判断的**目的**是**Ataraxia（不动心、心灵宁静）**。当你不再为\u201C什么是真\u201D焦虑时，你就自由了。"));
content.push(p("这一对呈现的是一个深刻的悖论结构：**通过放弃认识来达到安顿**。它跟你之前讨论过的\u201C理性—逻辑工具失败之后\u201D的处境是一脉相承的——皮浪的姿态可以被读作\u201C语言极限\u201D路径在伦理学层面的早期版本：当Logos工具发现自己无法封闭真理时，正确的回应不是绝望，也不是跳进神秘主义的存在论狂欢，而是**悬置 + 安宁**。这种气质后来在维特根斯坦《逻辑哲学论》末尾\u201C对于不可说的要保持沉默\u201D那里得到了最干净的回响。"));

// ============================================================
// 六、底层原理：这16对对立到底揭示了什么？
// ============================================================
content.push(h1("六、底层原理：这16对对立到底揭示了什么？"));
content.push(p("把这16组对立连起来看，古希腊哲学的底层原理可以浓缩成三句话："));
content.push(p("**第一，哲学是Logos试图驯服Mythos、Physis、Hen的过程。** 哲学的发生就是把\u201C故事\u201D换成\u201C论证\u201D（对立1）、把\u201C自然现象\u201D还原为\u201C本原\u201D（对立3、4）、把\u201C意见\u201D提升为\u201C知识\u201D（对立5）。**所有古希腊哲学都是这场驯服的不同战役。**"));
content.push(p("**第二，Logos在驯服过程中遭遇了自身的极限——这就是巴门尼德的遗产。** 一旦你彻底贯彻Logos（思维=存在），你就会发现Logos无法容纳变化、多样、运动。**整个后巴门尼德哲学（原子论、柏拉图、亚里士多德）都是在这道伤口上做缝合手术**：要么把世界切两半（柏拉图的两重世界），要么把对立内化（亚里士多德的形式—质料、潜能—现实），要么承认非存在以某种方式存在（原子论的虚空）。"));
content.push(p("**第三，当公共世界（城邦）崩溃后，这些对立从\u201C宇宙学的\u201D变成\u201C伦理学的\u201D。** 一与多变成\u201C我与世界\u201D，必然与自由变成\u201C命运与我的态度\u201D，灵魂与肉体变成\u201C我应当向哪里靠拢\u201D，悬置与不动心变成\u201C在不确定中如何活\u201D。**希腊哲学最终给出的不是一套关于世界的真理，而是一套面对世界的姿态。**"));
content.push(p("换一个角度概括：**这16组对立不是答案，是问题的结构**。每一组对立都是一个\u201C应力点\u201D——古希腊每一位重要思想家都可以由他在这16个应力点上的姿态被精确定位。讲义里那一长串名字之所以彼此关联又彼此竞争，是因为他们其实在**共用一套问题清单**，只是给出了不同的答案。"));
content.push(p("这也是为什么后来的整个西方哲学（中世纪到黑格尔，再到现象学和分析哲学）都仍然在这16对里打转——它们不是古董，而是哲学这门手艺的**基础工具箱**。"));

