const pptxgen = require("pptxgenjs");
const fs = require("fs");

const pres = new pptxgen();
pres.defineLayout({ name: "A4P", width: 8.27, height: 11.69 });
pres.layout = "A4P";
pres.author = "古希腊哲学";
pres.title = "16组核心概念二元对立去看古希腊哲学";

// ---------- palette ----------
const INK="262320", AEGEAN="123E49", AEGEAN2="1D5562", TERRA="B0492F",
      GOLD="A9802F", GOLDL="C8A24A", PAPER="FCFAF6", CARD="FFFFFF",
      MUTE="938C81", LINE="E6DECE", WHITE="FFFFFF", CREAM="F3ECDD";
const FONT="Microsoft YaHei";
const mGold = "image/png;base64," + fs.readFileSync("m_gold.png").toString("base64");
const lambda = "image/png;base64," + fs.readFileSync("lambda.png").toString("base64");

// ---------- geometry ----------
const PW=8.27, PH=11.69;
const ML=0.55, MR=0.6;
const GUT_X=0.55, GUT_W=0.62;        // left gutter for badges/numerals
const TX=1.28, TW=PW-TX-MR;          // text column
const TOP=1.04, BOT=10.92;           // content vertical bounds
const LH=1.22;                       // line spacing multiple (body)

// ---------- helpers ----------
function parseBold(s){const o=[];s.split("**").forEach((p,i)=>{if(p!=="")o.push({t:p,b:i%2===1});});return o;}
function effLen(s){let n=0;for(const ch of s){const c=ch.codePointAt(0);
  if(c>=0x2E80||(c>=0x3000&&c<=0x303F)||(c>=0xFF00&&c<=0xFFEF))n+=1.0;       // CJK + fullwidth
  else if(c>=0x370&&c<=0x3FF)n+=0.62;                                        // Greek
  else n+=0.5;} return n;}                                                   // latin/digit/space/punct
function estLines(s, fs, w){const cpl=Math.max(1,Math.floor(w/(fs/72)));return Math.max(1,Math.ceil(effLen(s)/cpl));}
function estPara(s, fs, w, spAfterPt){return estLines(s,fs,w)*(fs*LH/72)+spAfterPt/72+0.012;}

// body blocks -> runs for one flowing text box (bold->TERRA, bullets via feature)
function bodyRuns(blocks){
  const runs=[];
  blocks.forEach(b=>{
    let fs,color,bold=false,bullet=false,spAfter;
    if(b.t==="bullet"){fs=10.5;color=INK;bullet=true;spAfter=3;}
    else if(b.t==="intro"){fs=11;color=AEGEAN2;spAfter=6;}
    else {fs=10.5;color=INK;spAfter=6;}
    const segs=parseBold(b.s);
    segs.forEach((seg,i)=>{
      const last=i===segs.length-1;
      const o={fontFace:FONT,fontSize:fs,lineSpacingMultiple:LH,
        color: seg.b?TERRA:color, bold: seg.b?true:bold};
      if(last){o.breakLine=true;o.paraSpaceAfter=spAfter;if(bullet){o.bullet={indent:15};o.indentLevel=0;}}
      runs.push({text:seg.t,options:o});
    });
  });
  return runs;
}
function estBody(blocks){
  let h=0;
  blocks.forEach(b=>{
    const fs=b.t==="intro"?11:10.5;
    const sp=b.t==="bullet"?3:6;
    h+=estPara(b.s.replace(/\*\*/g,""),fs,TW-(b.t==="bullet"?0.22:0),sp);
  });
  return h;
}

// ---------- page chrome ----------
let pageNo=0, TOTAL=0;
function newContentPage(){
  const s=pres.addSlide(); s.background={color:PAPER}; pageNo++;
  // running header
  s.addShape(pres.shapes.RECTANGLE,{x:ML,y:0.5,w:0.07,h:0.07,fill:{color:GOLD},line:{type:"none"}});
  s.addText("古希腊哲学 · 核心二元对立",{x:ML+0.16,y:0.42,w:5,h:0.24,margin:0,fontFace:FONT,fontSize:8.5,color:MUTE,charSpacing:2,valign:"middle"});
  s.addText(`${String(pageNo).padStart(2,"0")}`,{x:PW-MR-0.6,y:0.42,w:0.6,h:0.24,margin:0,fontFace:FONT,fontSize:9,color:GOLD,bold:true,align:"right",valign:"middle"});
  // footer motif
  s.addText("❖",{x:0,y:PH-0.5,w:PW,h:0.24,margin:0,fontFace:FONT,fontSize:8,color:GOLDL,align:"center",valign:"middle"});
  return s;
}

// ---------- content rendering with measured y-cursor ----------
let slide=null, y=TOP;
function ensure(h){ if(slide===null || y+h>BOT){ slide=newContentPage(); y=TOP; } }

function drawSection(num, title){
  const titleH=estLines(title,15.5,TW)*(15.5*1.3/72)+0.06;
  const blockH=Math.max(0.56,titleH);
  ensure(blockH+0.5+0.9);                       // keep header with following content
  // gutter filled square with numeral
  s_square(num);
  slide.addText(title,{x:TX,y:y-0.02,w:TW,h:blockH+0.1,margin:0,fontFace:FONT,fontSize:15.5,bold:true,color:AEGEAN,valign:"top",lineSpacingMultiple:1.28});
  y+=blockH+0.16;
  // subtle gold rule as section divider (full text column)
  slide.addShape(pres.shapes.LINE,{x:TX,y:y,w:TW,h:0,line:{color:GOLDL,width:1.25}});
  y+=0.16;
}
function s_square(num){
  const d=0.56;
  slide.addShape(pres.shapes.RECTANGLE,{x:GUT_X,y:y-0.02,w:d,h:d,fill:{color:AEGEAN},line:{type:"none"}});
  slide.addText(num,{x:GUT_X,y:y-0.02,w:d,h:d,margin:0,fontFace:FONT,fontSize:21,bold:true,color:GOLDL,align:"center",valign:"middle"});
}

function drawIntro(paras){
  const blocks=paras.map(p=>({t:"intro",s:p}));
  const h=estBody(blocks);
  ensure(h+0.12);
  // gutter accent bar
  slide.addShape(pres.shapes.RECTANGLE,{x:TX-0.2,y:y+0.02,w:0.05,h:h-0.05,fill:{color:GOLD},line:{type:"none"}});
  slide.addText(bodyRuns(blocks),{x:TX,y:y,w:TW,h:h+0.3,margin:0,valign:"top"});
  y+=h+0.06;
}

function drawOpp(o, withSep){
  const headH=estLines(o.greek+"    "+o.gloss,13.5,TW)*(13.5*1.26/72)+0.10;
  const bodyH=estBody(o.body);
  const total=headH+bodyH+(withSep?0.22:0.30);
  ensure(total);
  // gutter circle badge
  const d=0.46;
  slide.addShape(pres.shapes.OVAL,{x:GUT_X+0.04,y:y+0.0,w:d,h:d,fill:{color:TERRA},line:{type:"none"}});
  slide.addText(o.num,{x:GUT_X+0.04,y:y+0.0,w:d,h:d,margin:0,fontFace:FONT,fontSize:o.num.length>1?12.5:14,bold:true,color:WHITE,align:"center",valign:"middle"});
  // greek display + gloss (rich)
  slide.addText([
    {text:o.greek,options:{fontFace:FONT,fontSize:13.5,bold:true,color:AEGEAN}},
    {text:"   "+o.gloss,options:{fontFace:FONT,fontSize:11,bold:true,color:GOLD,breakLine:true}},
  ],{x:TX,y:y-0.04,w:TW,h:headH+0.1,margin:0,valign:"top",lineSpacingMultiple:1.2});
  y+=headH+0.04;
  // body
  slide.addText(bodyRuns(o.body),{x:TX,y:y,w:TW,h:bodyH+0.4,margin:0,valign:"top"});
  y+=bodyH;
  if(withSep){
    y+=0.10;
    slide.addShape(pres.shapes.LINE,{x:TX,y:y,w:TW,h:0,line:{color:LINE,width:1}});
    y+=0.12;
  } else { y+=0.24; }
}

// ===================================================================
// CONTENT (verbatim text)
// ===================================================================
const intro0=[
 "用古希腊哲学核心概念二元对立的“骨架”，把整部古希腊哲学史压扁成一张X光片，看到的就是这16组对立在不同思想家身上反复显影、变形、嫁接。",
 "下面把这16组当成16把钥匙，按古希腊哲学**实际发生的历史顺序**重新编组，把讲义里那些人名和学派串成一条线。",
];

const STREAM=[
 {kind:"section",num:"一",title:"起点：哲学是怎么诞生的（对立 1—2）"},
 {kind:"opp",num:"1",greek:"Μῦθος vs Λόγος",gloss:"神话 — 理性",body:[
   {t:"para",s:"这是**哲学得以存在的那一刀**。在泰勒斯之前，希腊人解释世界靠的是Mythos——荷马、赫西俄德的故事：宙斯发怒于是打雷，海神波塞冬不爽于是地震。Mythos的特征是叙事性、人格化、不可追问（你不能问“为什么宙斯会发怒”，神就是这样）。"},
   {t:"para",s:"公元前6世纪，米利都的泰勒斯说了一句很怪的话：“万物的本原是水。”这句话本身对不对不重要，重要的是它的**形式**变了：它不再讲故事，而是给出一个可以被讨论、反驳、修改的命题。阿那克西曼德接着说“不对，是阿派朗”，阿那克西美尼又说“是气”——师徒三代彼此反驳，这就是Logos：可言说、可论证、可追问的理性。"},
   {t:"para",s:"讲义里那句“从神创世界转向自然本原的理性追问”，本质上说的就是这一组对立。**整个古希腊哲学就是Logos一步步从Mythos里挣脱出来的过程**。"},
 ]},
 {kind:"opp",num:"2",greek:"Φύσις vs Νόμος",gloss:"自然 — 约定",body:[
   {t:"para",s:"但Logos的胜利留下了一个新问题：如果可以用Logos追问自然（Physis），那为什么不能追问人类社会的规则（Nomos）？"},
   {t:"para",s:"这就是**智者派**的突破。普罗泰戈拉发现：希腊各城邦的法律、习俗、道德彼此不同——斯巴达觉得偷东西没问题，雅典觉得不行；波斯人觉得乱伦正常，希腊人觉得是禁忌。那么道德到底是Physis（自然本有的、放之四海皆准）还是Nomos（人为约定、随时可改）？"},
   {t:"para",s:"智者派的答案是后者，于是导出“人是万物的尺度”。色拉叙马霍斯更激进：“正义就是强者的利益”——所谓的“公平”只是强者立的规矩。"},
   {t:"para",s:"这一组对立直接催生了**苏格拉底转向**。苏格拉底之所以要去街头辩论“什么是正义”“什么是勇敢”，就是要回击智者派——他试图证明，德性虽然不在自然现象里，但仍然有Logos可以把握的客观结构。"},
 ]},

 {kind:"section",num:"二",title:"宇宙论的核心问题：找“那个东西”（对立 3—4）"},
 {kind:"opp",num:"3",greek:"Ἄπειρον vs Πέρας",gloss:"无定 — 有限",body:[
   {t:"para",s:"米利都学派一动手就遇到一个麻烦。泰勒斯说本原是水，但水是“有形”的，是有限的——如果它是有限的，那它之外是什么？阿那克西曼德立刻看出这个漏洞，提出**Apeiron（阿派朗，无定形/无限者）**：本原必须是无限、无规定、无属性的，否则就不能生出有限多样的万物。"},
   {t:"para",s:"但这又走到另一个极端：完全无规定的东西怎么生出有规定的东西？"},
   {t:"para",s:"毕达哥拉斯学派给出了革命性回答：**Peras（有限/界限/比例）才是世界之所以有秩序的关键**。无定形的东西要“被数限定”，才成为可认识的事物。一根弦本身是连续的（无定），但当弦长按1:2、2:3、3:4的比例划分时，就产生了八度、五度、四度——和谐由此诞生。"},
   {t:"para",s:"这一组的底层原理是：**秩序 = 给无定形加上限定**。这个直觉后来变成柏拉图的“理念赋予感性世界以形式”，再变成亚里士多德的“形式作用于质料”。"},
 ]},
 {kind:"opp",num:"4",greek:"Ἕν vs Πολλά",gloss:"一 — 多",body:[
   {t:"para",s:"这是古希腊形而上学**最核心**的问题。"},
   {t:"para",s:"你看到的世界是“多”：千万种事物、千万种变化。但理性追问“本原”时，本原必须是“一”——否则它就不是终极的，因为还要追问这“多”背后的“一”。"},
   {t:"para",s:"讲义里每一个前苏格拉底哲学家其实都在回答同一个问题：**一与多如何兼容？**"},
   {t:"bullet",s:"泰勒斯：水（一）→ 万物（多），但没解释“怎么”变"},
   {t:"bullet",s:"阿那克西美尼：气（一）通过稀散/凝聚（机制）→ 万物（多）"},
   {t:"bullet",s:"赫拉克利特：火（一）按逻各斯燃烧/熄灭 → 万物（多），但“一”本身就是流变"},
   {t:"bullet",s:"毕达哥拉斯：数（一）通过比例 → 万物（多）"},
   {t:"bullet",s:"巴门尼德：只有“一”是真的，“多”是假象——**直接砍掉一边**"},
   {t:"bullet",s:"恩培多克勒：四根（多元的“一”群）+ 爱与争（机制）→ 万物"},
   {t:"bullet",s:"阿那克萨戈拉：无限种子（多元）+ 努斯（一个统一的推动者）"},
   {t:"bullet",s:"原子论：无限原子（多）+ 虚空 → 万物"},
   {t:"para",s:"整个前苏格拉底的演化，就是**“一与多”这道题的不同解法的竞赛**。"},
 ]},

 {kind:"section",num:"三",title:"巴门尼德冲击：哲学进入“存在论”主场（对立 5—7）"},
 {kind:"intro",paras:["巴门尼德是讲义里最该认真对待的人。他几乎以一己之力，把希腊哲学从“宇宙论”推到“本体论/存在论”。他的整个体系建立在三组对立上："]},
 {kind:"opp",num:"5",greek:"Ἐπιστήμη vs Δόξα",gloss:"真理 — 意见",body:[
   {t:"para",s:"巴门尼德的诗分两条路：**真理之路**（Aletheia/Episteme）与**意见之路**（Doxa）。"},
   {t:"para",s:"感官告诉你万物在变化、生灭、运动——这是Doxa，意见，假象。理性告诉你：存在者存在，非存在者不存在——这是Episteme，真理。两者不在同一个层级。"},
   {t:"para",s:"这是西方哲学**第一次**严格区分“看上去如何”和“实际如何”。柏拉图后来的整个理念论，本质上就是把这条区分**做大、做实**：可见世界是Doxa，可知世界（理念）是Episteme。"},
 ]},
 {kind:"opp",num:"6",greek:"Νοεῖν vs Εἶναι",gloss:"思维 — 存在",body:[
   {t:"para",s:"巴门尼德有一句残篇，海德格尔后来花了一辈子去琢磨：“**思维与存在是同一的**”（τὸ γὰρ αὐτὸ νοεῖν ἐστίν τε καὶ εἶναι）。"},
   {t:"para",s:"什么意思？意思是：能被思想的，就是能存在的；不能被思想的，就不能存在。逻辑可能性 = 本体可能性。"},
   {t:"para",s:"这是一个极其大胆的形而上学公设——它直接把**思想的内在结构当作存在本身的结构**。后世从柏拉图（理念是可思的本质）到黑格尔（思维与存在的同一性）都吃这碗饭。"},
   {t:"para",s:"顺便说一句：你之前讨论过的“维特根斯坦语言界限即世界界限”这个进路，和巴门尼德这句话是**远房亲戚**——都把“可言说/可思想”作为“存在”的边界。但维特根斯坦把它当成限制（语言之外有不可说的），巴门尼德把它当成胜利（不可思的就是无）。这正是你那条“语言极限”路径与“辩证法”路径分野的最早源头。"},
 ]},
 {kind:"opp",num:"7",greek:"Ὄν vs Μὴ Ὄν",gloss:"存在 — 非存在",body:[
   {t:"para",s:"从上面那句话，巴门尼德推出：“非存在不存在。”"},
   {t:"para",s:"听起来像同义反复，但杀伤力极大："},
   {t:"bullet",s:"如果“非存在不存在”，那“虚空”不存在 → 没有运动空间 → **运动不可能**"},
   {t:"bullet",s:"如果“非存在不存在”，那“还不是的状态”不存在 → **变化不可能**（因为变化要求事物从“还不是X”变成“是X”）"},
   {t:"bullet",s:"如果“非存在不存在”，那存在只能是“一”（因为“多”要求事物之间有“不是”的区分）→ **多不可能**"},
   {t:"para",s:"芝诺四个悖论（飞矢不动、阿喀琉斯追龟等）就是为这一论点提供反证。"},
   {t:"para",s:"巴门尼德留下的烂摊子，是整个后续希腊哲学不得不收拾的："},
   {t:"bullet",s:"**恩培多克勒**让步：四根本身永恒不变（向巴门尼德低头），但它们的组合分离造成变化（救回常识）"},
   {t:"bullet",s:"**原子论**反击：让“虚空”重新拥有某种存在地位——虚空就是“非存在”，但它“是”——以此为运动腾出空间"},
   {t:"bullet",s:"**柏拉图**在《智者篇》里“弑父巴门尼德”，正面承认“非存在”以某种方式存在（即“相异性”）"},
   {t:"para",s:"所以对立7不是一道考题，而是**整个古典哲学的引擎**。"},
 ]},

 {kind:"section",num:"四",title:"柏拉图—亚里士多德的形而上学搭建（对立 8—12）"},
 {kind:"intro",paras:["讲义里柏拉图和亚里士多德这两页看起来很短，但其实他们做的事情是：**把前面所有遗留问题打包成一个统一的形而上学架构**。这套架构由五对概念支撑。"]},
 {kind:"opp",num:"11·12",greek:"Αἴσθησις vs Νοῦς ＆ Φαινόμενον vs Οὐσία",gloss:"感性—理性 ／ 现象—本体",body:[
   {t:"para",s:"先看这两对，因为它们是柏拉图整个体系的入口。"},
   {t:"para",s:"**柏拉图的“二重世界”**就是这两组对立的具体化："},
   {t:"bullet",s:"感性（Aisthesis）只能接触**现象（Phainomenon）**——洞穴墙上的影子"},
   {t:"bullet",s:"理性（Nous）才能把握**本体（Ousia）**——洞穴外的真实事物，即理念"},
   {t:"para",s:"讲义里的“洞穴喻”，本质上就是把对立5（真理—意见）+ 对立11（感性—理性）+ 对立12（现象—本体）画成了一幅画。这三组其实在柏拉图那里是**同一组**对立的三种表述。"},
 ]},
 {kind:"opp",num:"10",greek:"Καθ' ἕκαστον vs Καθόλου",gloss:"个别 — 共相",body:[
   {t:"para",s:"这一对是**柏拉图与亚里士多德分家**的核心。"},
   {t:"para",s:"你看到一匹具体的马（个别），又看到“马本身”这个概念（共相）。问题是：哪一个更真实？"},
   {t:"bullet",s:"**柏拉图**说：**共相（理念）更真实**。具体的马是对“马的理念”的不完美摹本。马会死，但“马本身”永恒。"},
   {t:"bullet",s:"**亚里士多德**说：**个别（这匹具体的马）更真实**。“马本身”不是飘在天上的独立实体，它只是从无数具体的马里抽出来的共同结构。"},
   {t:"para",s:"这就是亚里士多德“批判柏拉图”那一栏的核心：他要把柏拉图分裂在两个世界的“个别”和“共相”重新粘回一个世界。"},
 ]},
 {kind:"opp",num:"8",greek:"Μορφή vs Ὕλη",gloss:"形式 — 质料",body:[
   {t:"para",s:"亚里士多德怎么粘？答案是**形质论（hylomorphism）**。"},
   {t:"para",s:"一块青铜（质料Hyle）被铸成雕像（形式Morphe）。形式不是另一个世界的理念，**它就内在于这块青铜里**。没有无形式的质料，也没有无质料的形式（除了纯形式即神）。"},
   {t:"para",s:"这一对解决了对立10：共相（形式）不在彼岸，而**在个别（具体物）之中**作为其内在结构。"},
 ]},
 {kind:"opp",num:"9",greek:"Δύναμις vs Ἐνέργεια",gloss:"潜能 — 现实",body:[
   {t:"para",s:"这对解决的是巴门尼德留下的**变化问题**。"},
   {t:"para",s:"巴门尼德说变化不可能：橡子怎么“变成”橡树？要么橡子已经是橡树（无变化），要么橡子“不是”橡树而变成“是”橡树（违反“非存在不存在”）。"},
   {t:"para",s:"亚里士多德说：橡子里以**潜能（Dynamis）**的方式“是”橡树，长成后以**现实（Energeia）**的方式“是”橡树。变化不是从“无”到“有”，而是从“潜在的有”到“实现的有”。"},
   {t:"para",s:"这是一个绝妙的修辞策略：他**没有否认巴门尼德**（潜能也是某种“是”），但**给了变化以本体论位置**。讲义里“四因说”的“目的因”——橡子的目的就是橡树——也是建立在这个区分上。"},
 ]},

 {kind:"section",num:"五",title:"希腊化转向：从“世界是什么”到“我该如何活”（对立 13—16）"},
 {kind:"intro",paras:["讲义后半部分的关键词是：**“哲学从城邦公共政治思辨转向个人安身立命”**。这个转向通过最后四组对立呈现。"]},
 {kind:"opp",num:"13",greek:"Ἀνάγκη vs Προαίρεσις",gloss:"必然 — 自由",body:[
   {t:"para",s:"希腊化时代的人面对的世界是：城邦没了、帝国说散就散、自己的命运被宏大力量碾压。**Ananke（必然/宿命）**变成压倒性的体验。"},
   {t:"bullet",s:"**德谟克利特原子论**：一切都是原子机械碰撞的必然结果——彻底的决定论"},
   {t:"bullet",s:"**斯多葛主义**：宇宙逻各斯支配一切，外部事件全是必然，**但**你的内心判断仍可Prohairesis（自由抉择）——爱比克泰德的核心：区分“在我”与“不在我”"},
   {t:"bullet",s:"**伊壁鸠鲁**：在原子论里偷偷塞入“原子的偏斜”（clinamen），为自由意志保留物理学空间"},
   {t:"para",s:"这一对**今天仍然活着**——它是后来基督教恩典与自由意志之争、近代决定论与自由意志之争、当代脑科学与道德责任之争的源头。"},
 ]},
 {kind:"opp",num:"14",greek:"Ἀρετή vs Ἡδονή",gloss:"德性 — 快乐",body:[
   {t:"para",s:"人生最高的善是什么？"},
   {t:"bullet",s:"**苏格拉底/柏拉图/亚里士多德/斯多葛**：是**德性（Arete）**——人之为人的卓越状态、品格的完善"},
   {t:"bullet",s:"**伊壁鸠鲁**：是**快乐（Hedone）**——但要注意，他说的不是放纵享乐，而是**身体无痛苦、心灵不受扰**的稳定状态，所以本质上是一种“高级快乐”"},
   {t:"bullet",s:"**犬儒第欧根尼**：两边都骂——德性要的不是社会承认的“卓越”，快乐也不是感官放纵，而是**Autarkeia（自足）**"},
   {t:"para",s:"这一对其实暗藏一个更深的问题：**伦理学的基础是“人应当如何”（规范）还是“人实际欲求什么”（事实）？**——这是后来休谟、康德、功利主义之争的源头。"},
 ]},
 {kind:"opp",num:"15",greek:"Ψυχή vs Σῶμα",gloss:"灵魂 — 肉体",body:[
   {t:"para",s:"这一对最早不是哲学问题，是宗教问题——讲义里讲得很清楚：**俄耳甫斯教**带来灵魂轮回与净化观念，毕达哥拉斯把它**理性化**，柏拉图再把它**哲学化**："},
   {t:"bullet",s:"灵魂在进入肉体前已认识理念（回忆说）"},
   {t:"bullet",s:"肉体是灵魂的“坟墓”（soma sema）"},
   {t:"bullet",s:"哲学就是练习死亡——让灵魂摆脱肉体回归理念世界"},
   {t:"para",s:"亚里士多德反过来：灵魂不是独立的实体，**灵魂是肉体的形式**（重新用对立8来解决问题）——这是一个非常优雅的内化。"},
   {t:"para",s:"新柏拉图主义则把柏拉图灵魂论推向极致：“**太一 → 理智 → 灵魂 → 物质**”的流溢说，灵魂的使命是逆流而上回归太一。"},
   {t:"para",s:"讲义最后一页特别讲新柏拉图主义如何影响基督教，本质上就是**Psyche/Soma这对对立被基督教全盘继承**：灵魂不朽、肉体堕落、灵性救赎——直到马丁·路德、笛卡尔、乃至当代的“意识—身体”问题，都活在这条阴影里。"},
 ]},
 {kind:"opp",num:"16",greek:"Ἐποχή vs Ἀταραξία",gloss:"悬置判断 — 不动心",body:[
   {t:"para",s:"这是讲义压轴的对立，也最微妙。"},
   {t:"para",s:"**怀疑主义皮浪派**的核心论证是：每一个哲学命题都有同样有力的反命题（“独断论者越多，他们越证明真理无法获得”）。于是真正智慧的做法是：**Epoche——悬置判断**，对任何事都不肯定不否定。"},
   {t:"para",s:"但这不是消极的虚无主义——悬置判断的**目的**是**Ataraxia（不动心、心灵宁静）**。当你不再为“什么是真”焦虑时，你就自由了。"},
   {t:"para",s:"这一对呈现的是一个深刻的悖论结构：**通过放弃认识来达到安顿**。它跟你之前讨论过的“理性—逻辑工具失败之后”的处境是一脉相承的——皮浪的姿态可以被读作“语言极限”路径在伦理学层面的早期版本：当Logos工具发现自己无法封闭真理时，正确的回应不是绝望，也不是跳进神秘主义的存在论狂欢，而是**悬置 + 安宁**。这种气质后来在维特根斯坦《逻辑哲学论》末尾“对于不可说的要保持沉默”那里得到了最干净的回响。"},
 ]},

 {kind:"section",num:"六",title:"底层原理：这16对对立到底揭示了什么？"},
 {kind:"intro",paras:["把这16组对立连起来看，古希腊哲学的底层原理可以浓缩成三句话："]},
 {kind:"opp",num:"壹",greek:"Logos 的驯服",gloss:"第一原理",body:[
   {t:"para",s:"**第一，哲学是Logos试图驯服Mythos、Physis、Hen的过程。** 哲学的发生就是把“故事”换成“论证”（对立1）、把“自然现象”还原为“本原”（对立3、4）、把“意见”提升为“知识”（对立5）。**所有古希腊哲学都是这场驯服的不同战役。**"},
 ]},
 {kind:"opp",num:"贰",greek:"Logos 的极限",gloss:"第二原理",body:[
   {t:"para",s:"**第二，Logos在驯服过程中遭遇了自身的极限——这就是巴门尼德的遗产。** 一旦你彻底贯彻Logos（思维=存在），你就会发现Logos无法容纳变化、多样、运动。**整个后巴门尼德哲学（原子论、柏拉图、亚里士多德）都是在这道伤口上做缝合手术**：要么把世界切两半（柏拉图的两重世界），要么把对立内化（亚里士多德的形式—质料、潜能—现实），要么承认非存在以某种方式存在（原子论的虚空）。"},
 ]},
 {kind:"opp",num:"叁",greek:"宇宙学 → 伦理学",gloss:"第三原理",body:[
   {t:"para",s:"**第三，当公共世界（城邦）崩溃后，这些对立从“宇宙学的”变成“伦理学的”。** 一与多变成“我与世界”，必然与自由变成“命运与我的态度”，灵魂与肉体变成“我应当向哪里靠拢”，悬置与不动心变成“在不确定中如何活”。**希腊哲学最终给出的不是一套关于世界的真理，而是一套面对世界的姿态。**"},
 ]},
 {kind:"intro",paras:[
   "换一个角度概括：**这16组对立不是答案，是问题的结构**。每一组对立都是一个“应力点”——古希腊每一位重要思想家都可以由他在这16个应力点上的姿态被精确定位。讲义里那一长串名字之所以彼此关联又彼此竞争，是因为他们其实在**共用一套问题清单**，只是给出了不同的答案。",
   "这也是为什么后来的整个西方哲学（中世纪到黑格尔，再到现象学和分析哲学）都仍然在这16对里打转——它们不是古董，而是哲学这门手艺的**基础工具箱**。",
 ]},
];

