files.content:
const pptxgen = require("pptxgenjs");
const pres = new pptxgen();
pres.defineLayout({ name: "A4P", width: 8.27, height: 11.69 });
pres.layout = "A4P";
pres.author = "古希腊哲学";
pres.title = "16组核心概念二元对立去看古希腊哲学";

const FONT = "Microsoft YaHei";
const INK = "232323", BOLDINK = "111111", TERRA = "A7402C", AEGEAN = "1D4E5F",
      GOLD = "9A6B1E", MUTE = "8C8C8C", LIGHT = "EFE7DA";

const PW = 8.27, PH = 11.69, MX = 0.66, TOP = 0.72, BOT = 0.62;
const CW = PW - 2 * MX;
const CONTENT_TOP = 0.92;                 // below eyebrow
const CONTENT_H = PH - CONTENT_TOP - BOT; // usable height

const BODY = 10.5, OPP = 12.5, H1 = 16;

function parseBold(s) {
  const out = [];
  const parts = s.split("**");
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] === "") continue;
    out.push({ t: parts[i], b: i % 2 === 1 });
  }
  return out;
}

// block -> array of pptxgen run objects (flowing within one text box)
function blockToRuns(block, isFirstBlock) {
  let fs, color, bold = false, bullet = false, spAfter, spBefore;
  switch (block.type) {
    case "h1":
      fs = H1; color = TERRA; bold = true;
      spBefore = isFirstBlock ? 0 : 12; spAfter = 7; break;
    case "opp":
      fs = OPP; color = AEGEAN; bold = true;
      spBefore = isFirstBlock ? 0 : 9; spAfter = 3; break;
    case "intro":
      fs = BODY + 0.3; color = "3C3C3C";
      spBefore = isFirstBlock ? 0 : 4; spAfter = 6; break;
    case "bullet":
      fs = BODY; color = INK; bullet = true;
      spBefore = 0; spAfter = 3; break;
    default: // para
      fs = BODY; color = INK;
      spBefore = 0; spAfter = 6; break;
  }
  const segs = parseBold(block.text);
  const runs = [];
  for (let i = 0; i < segs.length; i++) {
    const last = i === segs.length - 1;
    const segColor = segs[i].b
      ? (block.type === "para" || block.type === "bullet" || block.type === "intro" ? AEGEAN : color)
      : color;
    const opt = {
      fontFace: FONT,
      fontSize: fs,
      color: segColor,
      bold: segs[i].b ? true : bold,
      lineSpacingMultiple: 1.18,
    };
    // paragraph-level props go ONLY on the terminating run (with breakLine)
    if (last) {
      opt.breakLine = true;
      opt.paraSpaceBefore = spBefore;
      opt.paraSpaceAfter = spAfter;
      if (bullet) { opt.bullet = { indent: 14 }; opt.indentLevel = 0; }
    }
    runs.push({ text: segs[i].t, options: opt });
  }
  return runs;
}

