function addContentPage(blocks, idx, total) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };
  eyebrow(slide, idx, total);
  const runs = [];
  blocks.forEach((b, i) => blockToRuns(b, i === 0).forEach(r => runs.push(r)));
  slide.addText(runs, {
    x: MX, y: CONTENT_TOP, w: CW, h: CONTENT_H,
    margin: 0, valign: "top", align: "left",
  });
}

