const pptxgen = require("pptxgenjs");
const pres = new pptxgen();
pres.defineLayout({ name: "A4P", width: 8.27, height: 11.69 });
pres.layout = "A4P";
pres.author = "古希腊哲学";
pres.title = "16组核心概念二元对立去看古希腊哲学";

const FONT = "Microsoft YaHei";
const INK = "232323", BOLDINK = "111111", TERRA = "A7402C", AEGEAN = "1D4E5F",
      GOLD = "9A6B1E", MUTE = "8C8C8C", LIGHT = "EFE7DA";

const PW = 8.27, PH = 11.69, MX = 0.66, TOP = 0.72, BOT = 0.62;
const CW = PW - 2 * MX;
const CONTENT_TOP = 0.92;                 // below eyebrow
const CONTENT_H = PH - CONTENT_TOP - BOT; // usable height

const BODY = 10.5, OPP = 12.5, H1 = 16;

function parseBold(s) {
  const out = [];
  const parts = s.split("**");
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] === "") continue;
    out.push({ t: parts[i], b: i % 2 === 1 });
  }
  return out;
}

// block -> array of pptxgen run objects (flowing within one text box)
function blockToRuns(block, isFirstBlock) {
  let fs, color, bold = false, bullet = false, spAfter, spBefore;
  switch (block.type) {
    case "h1":
      fs = H1; color = TERRA; bold = true;
      spBefore = isFirstBlock ? 0 : 12; spAfter = 7; break;
    case "opp":
      fs = OPP; color = AEGEAN; bold = true;
      spBefore = isFirstBlock ? 0 : 9; spAfter = 3; break;
    case "intro":
      fs = BODY + 0.3; color = "3C3C3C";
      spBefore = isFirstBlock ? 0 : 4; spAfter = 6; break;
    case "bullet":
      fs = BODY; color = INK; bullet = true;
      spBefore = 0; spAfter = 3; break;
    default: // para
      fs = BODY; color = INK;
      spBefore = 0; spAfter = 6; break;
  }
  const segs = parseBold(block.text);
  const runs = [];
  for (let i = 0; i < segs.length; i++) {
    const first = i === 0, last = i === segs.length - 1;
    const segColor = segs[i].b
      ? (block.type === "para" || block.type === "bullet" || block.type === "intro" ? AEGEAN : color)
      : color;
    const opt = {
      fontFace: FONT,
      fontSize: fs,
      color: segColor,
      bold: segs[i].b ? true : bold,
      lineSpacingMultiple: 1.18,
    };
    // paragraph-level props on the first run of the paragraph
    if (first) {
      opt.paraSpaceBefore = spBefore;
      opt.paraSpaceAfter = spAfter;
      opt.align = "left";
      if (bullet) { opt.bullet = { indent: 14 }; opt.indentLevel = 0; }
    }
    if (last) opt.breakLine = true;
    runs.push({ text: segs[i].t, options: opt });
  }
  return runs;
}

function eyebrow(slide, idx, total) {
  slide.addText("古希腊哲学 · 核心二元对立", {
    x: MX, y: 0.34, w: CW - 0.8, h: 0.3, margin: 0,
    fontFace: FONT, fontSize: 8.5, color: MUTE, align: "left", valign: "middle",
    charSpacing: 2,
  });
  slide.addText(`${idx} / ${total}`, {
    x: PW - MX - 0.9, y: 0.34, w: 0.9, h: 0.3, margin: 0,
    fontFace: FONT, fontSize: 8.5, color: MUTE, align: "right", valign: "middle",
  });
  // thin hairline under eyebrow
  slide.addShape(pres.shapes.LINE, {
    x: MX, y: 0.7, w: CW, h: 0,
    line: { color: "DCD3C4", width: 0.75 },
  });
}

function addContentPage(blocks, idx, total) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };
  eyebrow(slide, idx, total);
  const runs = [];
  blocks.forEach((b, i) => blockToRuns(b, i === 0).forEach(r => runs.push(r)));
  slide.addText(runs, {
    x: MX, y: CONTENT_TOP, w: CW, h: CONTENT_H,
    margin: 0, valign: "top", align: "left",
  });
}

/* ============================== PAGE 1 — TITLE + 总表 ============================== */
const list16 = [
  ["1", "Μῦθος  VS  Λόγος", "神话 — 理性"],
  ["2", "Φύσις  VS  Νόμος", "自然 — 约定"],
  ["3", "Ἄπειρον  VS  Πέρας", "无定 — 有限"],
  ["4", "Ἕν  VS  Πολλά", "一 — 多"],
  ["5", "Ἐπιστήμη  VS  Δόξα", "真理 — 意见"],
  ["6", "Νοεῖν  VS  Εἶναι", "思维 — 存在"],
  ["7", "Ὄν  VS  Μὴ Ὄν", "存在 — 非存在"],
  ["8", "Μορφή  VS  Ὕλη", "形式 — 质料"],
  ["9", "Δύναμις  VS  Ἐνέργεια", "潜能 — 现实"],
  ["10", "Καθ' ἕκαστον  VS  Καθόλου", "个别 — 共相"],
  ["11", "Αἴσθησις  VS  Νοῦς", "感性 — 理性"],
  ["12", "Φαινόμενον  VS  Οὐσία", "现象 — 本体"],
  ["13", "Ἀνάγκη  VS  Προαίρεσις", "必然 — 自由"],
  ["14", "Ἀρετή  VS  Ἡδονή", "德性 — 快乐"],
  ["15", "Ψυχή  VS  Σῶμα", "灵魂 — 肉体"],
  ["16", "Ἐποχή  VS  Αταραξία", "悬置判断 — 不动心"],
];

function titlePage(total) {
  const s = pres.addSlide();
  s.background = { color: "FFFFFF" };
  s.addText("古希腊哲学 · 核心二元对立", {
    x: MX, y: 0.95, w: CW, h: 0.4, margin: 0,
    fontFace: FONT, fontSize: 12.5, color: TERRA, charSpacing: 4, align: "center",
  });
  s.addText("16 组核心概念二元对立去看古希腊哲学", {
    x: MX, y: 1.45, w: CW, h: 0.95, margin: 0,
    fontFace: FONT, fontSize: 27, bold: true, color: AEGEAN, align: "center", valign: "middle",
  });
  s.addText("古希腊哲学核心概念二元对立总表", {
    x: MX, y: 2.5, w: CW, h: 0.45, margin: 0,
    fontFace: FONT, fontSize: 14, bold: true, color: "2E2E2E", align: "center",
  });
  // 16 list
  const runs = [];
  list16.forEach(([n, gr, cn], i) => {
    runs.push({ text: `${n}.`, options: { fontFace: FONT, fontSize: 12, bold: true, color: TERRA, align: "left", paraSpaceBefore: 0, paraSpaceAfter: 6.5 } });
    runs.push({ text: `  ${gr}`, options: { fontFace: FONT, fontSize: 12, color: AEGEAN } });
    runs.push({ text: `    ${cn}`, options: { fontFace: FONT, fontSize: 12, color: INK, breakLine: true } });
  });
  s.addText(runs, { x: MX + 0.7, y: 3.25, w: CW - 1.0, h: 7.6, margin: 0, valign: "top", align: "left" });
  s.addText("1 / " + total, {
    x: PW - MX - 0.9, y: 0.34, w: 0.9, h: 0.3, margin: 0,
    fontFace: FONT, fontSize: 8.5, color: MUTE, align: "right",
  });
}

/* ============================== CONTENT PAGES ============================== */
const P = {}; // named page block-lists

P.p2 = [
  { type: "intro", text: "用古希腊哲学核心概念二元对立的“骨架”，把整部古希腊哲学史压扁成一张X光片，看到的就是这16组对立在不同思想家身上反复显影、变形、嫁接。" },
  { type: "intro", text: "下面把这16组当成16把钥匙，按古希腊哲学**实际发生的历史顺序**重新编组，把讲义里那些人名和学派串成一条线。" },
  { type: "h1", text: "一、起点：哲学是怎么诞生的（对立 1—2）" },
  { type: "opp", text: "对立 1：Μῦθος vs Λόγος（神话 — 理性）" },
  { type: "para", text: "这是**哲学得以存在的那一刀**。在泰勒斯之前，希腊人解释世界靠的是Mythos——荷马、赫西俄德的故事：宙斯发怒于是打雷，海神波塞冬不爽于是地震。Mythos的特征是叙事性、人格化、不可追问（你不能问“为什么宙斯会发怒”，神就是这样）。" },
  { type: "para", text: "公元前6世纪，米利都的泰勒斯说了一句很怪的话：“万物的本原是水。”这句话本身对不对不重要，重要的是它的**形式**变了：它不再讲故事，而是给出一个可以被讨论、反驳、修改的命题。阿那克西曼德接着说“不对，是阿派朗”，阿那克西美尼又说“是气”——师徒三代彼此反驳，这就是Logos：可言说、可论证、可追问的理性。" },
  { type: "para", text: "讲义里那句“从神创世界转向自然本原的理性追问”，本质上说的就是这一组对立。**整个古希腊哲学就是Logos一步步从Mythos里挣脱出来的过程**。" },
  { type: "opp", text: "对立 2：Φύσις vs Νόμος（自然 — 约定）" },
  { type: "para", text: "但Logos的胜利留下了一个新问题：如果可以用Logos追问自然（Physis），那为什么不能追问人类社会的规则（Nomos）？" },
  { type: "para", text: "这就是**智者派**的突破。普罗泰戈拉发现：希腊各城邦的法律、习俗、道德彼此不同——斯巴达觉得偷东西没问题，雅典觉得不行；波斯人觉得乱伦正常，希腊人觉得是禁忌。那么道德到底是Physis（自然本有的、放之四海皆准）还是Nomos（人为约定、随时可改）？" },
  { type: "para", text: "智者派的答案是后者，于是导出“人是万物的尺度”。色拉叙马霍斯更激进：“正义就是强者的利益”——所谓的“公平”只是强者立的规矩。" },
  { type: "para", text: "这一组对立直接催生了**苏格拉底转向**。苏格拉底之所以要去街头辩论“什么是正义”“什么是勇敢”，就是要回击智者派——他试图证明，德性虽然不在自然现象里，但仍然有Logos可以把握的客观结构。" },
];

P.p3 = [
  { type: "h1", text: "二、宇宙论的核心问题：找“那个东西”（对立 3—4）", first: true },
  { type: "opp", text: "对立 3：Ἄπειρον vs Πέρας（无定 — 有限）" },
  { type: "para", text: "米利都学派一动手就遇到一个麻烦。泰勒斯说本原是水，但水是“有形”的，是有限的——如果它是有限的，那它之外是什么？阿那克西曼德立刻看出这个漏洞，提出**Apeiron（阿派朗，无定形/无限者）**：本原必须是无限、无规定、无属性的，否则就不能生出有限多样的万物。" },
  { type: "para", text: "但这又走到另一个极端：完全无规定的东西怎么生出有规定的东西？" },
  { type: "para", text: "毕达哥拉斯学派给出了革命性回答：**Peras（有限/界限/比例）才是世界之所以有秩序的关键**。无定形的东西要“被数限定”，才成为可认识的事物。一根弦本身是连续的（无定），但当弦长按1:2、2:3、3:4的比例划分时，就产生了八度、五度、四度——和谐由此诞生。" },
  { type: "para", text: "这一组的底层原理是：**秩序 = 给无定形加上限定**。这个直觉后来变成柏拉图的“理念赋予感性世界以形式”，再变成亚里士多德的“形式作用于质料”。" },
  { type: "opp", text: "对立 4：Ἕν vs Πολλά（一 — 多）" },
  { type: "para", text: "这是古希腊形而上学**最核心**的问题。" },
  { type: "para", text: "你看到的世界是“多”：千万种事物、千万种变化。但理性追问“本原”时，本原必须是“一”——否则它就不是终极的，因为还要追问这“多”背后的“一”。" },
  { type: "para", text: "讲义里每一个前苏格拉底哲学家其实都在回答同一个问题：**一与多如何兼容？**" },
  { type: "bullet", text: "泰勒斯：水（一）→ 万物（多），但没解释“怎么”变" },
  { type: "bullet", text: "阿那克西美尼：气（一）通过稀散/凝聚（机制）→ 万物（多）" },
  { type: "bullet", text: "赫拉克利特：火（一）按逻各斯燃烧/熄灭 → 万物（多），但“一”本身就是流变" },
  { type: "bullet", text: "毕达哥拉斯：数（一）通过比例 → 万物（多）" },
  { type: "bullet", text: "巴门尼德：只有“一”是真的，“多”是假象——**直接砍掉一边**" },
  { type: "bullet", text: "恩培多克勒：四根（多元的“一”群）+ 爱与争（机制）→ 万物" },
  { type: "bullet", text: "阿那克萨戈拉：无限种子（多元）+ 努斯（一个统一的推动者）" },
  { type: "bullet", text: "原子论：无限原子（多）+ 虚空 → 万物" },
  { type: "para", text: "整个前苏格拉底的演化，就是**“一与多”这道题的不同解法的竞赛**。" },
];

P.p4 = [
  { type: "h1", text: "三、巴门尼德冲击：哲学进入“存在论”主场（对立 5—7）", first: true },
  { type: "intro", text: "巴门尼德是讲义里最该认真对待的人。他几乎以一己之力，把希腊哲学从“宇宙论”推到“本体论/存在论”。他的整个体系建立在三组对立上：" },
  { type: "opp", text: "对立 5：Ἐπιστήμη vs Δόξα（真理 — 意见）" },
  { type: "para", text: "巴门尼德的诗分两条路：**真理之路**（Aletheia/Episteme）与**意见之路**（Doxa）。" },
  { type: "para", text: "感官告诉你万物在变化、生灭、运动——这是Doxa，意见，假象。理性告诉你：存在者存在，非存在者不存在——这是Episteme，真理。两者不在同一个层级。" },
  { type: "para", text: "这是西方哲学**第一次**严格区分“看上去如何”和“实际如何”。柏拉图后来的整个理念论，本质上就是把这条区分**做大、做实**：可见世界是Doxa，可知世界（理念）是Episteme。" },
  { type: "opp", text: "对立 6：Νοεῖν vs Εἶναι（思维 — 存在）" },
  { type: "para", text: "巴门尼德有一句残篇，海德格尔后来花了一辈子去琢磨：“**思维与存在是同一的**”（τὸ γὰρ αὐτὸ νοεῖν ἐστίν τε καὶ εἶναι）。" },
  { type: "para", text: "什么意思？意思是：能被思想的，就是能存在的；不能被思想的，就不能存在。逻辑可能性 = 本体可能性。" },
  { type: "para", text: "这是一个极其大胆的形而上学公设——它直接把**思想的内在结构当作存在本身的结构**。后世从柏拉图（理念是可思的本质）到黑格尔（思维与存在的同一性）都吃这碗饭。" },
  { type: "para", text: "顺便说一句：你之前讨论过的“维特根斯坦语言界限即世界界限”这个进路，和巴门尼德这句话是**远房亲戚**——都把“可言说/可思想”作为“存在”的边界。但维特根斯坦把它当成限制（语言之外有不可说的），巴门尼德把它当成胜利（不可思的就是无）。这正是你那条“语言极限”路径与“辩证法”路径分野的最早源头。" },
];

P.p5 = [
  { type: "opp", text: "对立 7：Ὄν vs Μὴ Ὄν（存在 — 非存在）", first: true },
  { type: "para", text: "从上面那句话，巴门尼德推出：“非存在不存在。”" },
  { type: "para", text: "听起来像同义反复，但杀伤力极大：" },
  { type: "bullet", text: "如果“非存在不存在”，那“虚空”不存在 → 没有运动空间 → **运动不可能**" },
  { type: "bullet", text: "如果“非存在不存在”，那“还不是的状态”不存在 → **变化不可能**（因为变化要求事物从“还不是X”变成“是X”）" },
  { type: "bullet", text: "如果“非存在不存在”，那存在只能是“一”（因为“多”要求事物之间有“不是”的区分）→ **多不可能**" },
  { type: "para", text: "芝诺四个悖论（飞矢不动、阿喀琉斯追龟等）就是为这一论点提供反证。" },
  { type: "para", text: "巴门尼德留下的烂摊子，是整个后续希腊哲学不得不收拾的：" },
  { type: "bullet", text: "**恩培多克勒**让步：四根本身永恒不变（向巴门尼德低头），但它们的组合分离造成变化（救回常识）" },
  { type: "bullet", text: "**原子论**反击：让“虚空”重新拥有某种存在地位——虚空就是“非存在”，但它“是”——以此为运动腾出空间" },
  { type: "bullet", text: "**柏拉图**在《智者篇》里“弑父巴门尼德”，正面承认“非存在”以某种方式存在（即“相异性”）" },
  { type: "para", text: "所以对立7不是一道考题，而是**整个古典哲学的引擎**。" },
  { type: "h1", text: "四、柏拉图—亚里士多德的形而上学搭建（对立 8—12）" },
  { type: "intro", text: "讲义里柏拉图和亚里士多德这两页看起来很短，但其实他们做的事情是：**把前面所有遗留问题打包成一个统一的形而上学架构**。这套架构由五对概念支撑。" },
];

P.p6 = [
  { type: "opp", text: "对立 11：Αἴσθησις vs Νοῦς（感性 — 理性）& 对立 12：Φαινόμενον vs Οὐσία（现象 — 本体）", first: true },
  { type: "para", text: "先看这两对，因为它们是柏拉图整个体系的入口。" },
  { type: "para", text: "**柏拉图的“二重世界”**就是这两组对立的具体化：" },
  { type: "bullet", text: "感性（Aisthesis）只能接触**现象（Phainomenon）**——洞穴墙上的影子" },
  { type: "bullet", text: "理性（Nous）才能把握**本体（Ousia）**——洞穴外的真实事物，即理念" },
  { type: "para", text: "讲义里的“洞穴喻”，本质上就是把对立5（真理—意见）+ 对立11（感性—理性）+ 对立12（现象—本体）画成了一幅画。这三组其实在柏拉图那里是**同一组**对立的三种表述。" },
  { type: "opp", text: "对立 10：Καθ' ἕκαστον vs Καθόλου（个别 — 共相）" },
  { type: "para", text: "这一对是**柏拉图与亚里士多德分家**的核心。" },
  { type: "para", text: "你看到一匹具体的马（个别），又看到“马本身”这个概念（共相）。问题是：哪一个更真实？" },
  { type: "bullet", text: "**柏拉图**说：**共相（理念）更真实**。具体的马是对“马的理念”的不完美摹本。马会死，但“马本身”永恒。" },
  { type: "bullet", text: "**亚里士多德**说：**个别（这匹具体的马）更真实**。“马本身”不是飘在天上的独立实体，它只是从无数具体的马里抽出来的共同结构。" },
  { type: "para", text: "这就是亚里士多德“批判柏拉图”那一栏的核心：他要把柏拉图分裂在两个世界的“个别”和“共相”重新粘回一个世界。" },
  { type: "opp", text: "对立 8：Μορφή vs Ὕλη（形式 — 质料）" },
  { type: "para", text: "亚里士多德怎么粘？答案是**形质论（hylomorphism）**。" },
  { type: "para", text: "一块青铜（质料Hyle）被铸成雕像（形式Morphe）。形式不是另一个世界的理念，**它就内在于这块青铜里**。没有无形式的质料，也没有无质料的形式（除了纯形式即神）。" },
  { type: "para", text: "这一对解决了对立10：共相（形式）不在彼岸，而**在个别（具体物）之中**作为其内在结构。" },
  { type: "opp", text: "对立 9：Δύναμις vs Ἐνέργεια（潜能 — 现实）" },
  { type: "para", text: "这对解决的是巴门尼德留下的**变化问题**。" },
  { type: "para", text: "巴门尼德说变化不可能：橡子怎么“变成”橡树？要么橡子已经是橡树（无变化），要么橡子“不是”橡树而变成“是”橡树（违反“非存在不存在”）。" },
  { type: "para", text: "亚里士多德说：橡子里以**潜能（Dynamis）**的方式“是”橡树，长成后以**现实（Energeia）**的方式“是”橡树。变化不是从“无”到“有”，而是从“潜在的有”到“实现的有”。" },
  { type: "para", text: "这是一个绝妙的修辞策略：他**没有否认巴门尼德**（潜能也是某种“是”），但**给了变化以本体论位置**。讲义里“四因说”的“目的因”——橡子的目的就是橡树——也是建立在这个区分上。" },
];

P.p7 = [
  { type: "h1", text: "五、希腊化转向：从“世界是什么”到“我该如何活”（对立 13—16）", first: true },
  { type: "intro", text: "讲义后半部分的关键词是：**“哲学从城邦公共政治思辨转向个人安身立命”**。这个转向通过最后四组对立呈现。" },
  { type: "opp", text: "对立 13：Ἀνάγκη vs Προαίρεσις（必然 — 自由）" },
  { type: "para", text: "希腊化时代的人面对的世界是：城邦没了、帝国说散就散、自己的命运被宏大力量碾压。**Ananke（必然/宿命）**变成压倒性的体验。" },
  { type: "bullet", text: "**德谟克利特原子论**：一切都是原子机械碰撞的必然结果——彻底的决定论" },
  { type: "bullet", text: "**斯多葛主义**：宇宙逻各斯支配一切，外部事件全是必然，**但**你的内心判断仍可Prohairesis（自由抉择）——爱比克泰德的核心：区分“在我”与“不在我”" },
  { type: "bullet", text: "**伊壁鸠鲁**：在原子论里偷偷塞入“原子的偏斜”（clinamen），为自由意志保留物理学空间" },
  { type: "para", text: "这一对**今天仍然活着**——它是后来基督教恩典与自由意志之争、近代决定论与自由意志之争、当代脑科学与道德责任之争的源头。" },
  { type: "opp", text: "对立 14：Ἀρετή vs Ἡδονή（德性 — 快乐）" },
  { type: "para", text: "人生最高的善是什么？" },
  { type: "bullet", text: "**苏格拉底/柏拉图/亚里士多德/斯多葛**：是**德性（Arete）**——人之为人的卓越状态、品格的完善" },
  { type: "bullet", text: "**伊壁鸠鲁**：是**快乐（Hedone）**——但要注意，他说的不是放纵享乐，而是**身体无痛苦、心灵不受扰**的稳定状态，所以本质上是一种“高级快乐”" },
  { type: "bullet", text: "**犬儒第欧根尼**：两边都骂——德性要的不是社会承认的“卓越”，快乐也不是感官放纵，而是**Autarkeia（自足）**" },
  { type: "para", text: "这一对其实暗藏一个更深的问题：**伦理学的基础是“人应当如何”（规范）还是“人实际欲求什么”（事实）？**——这是后来休谟、康德、功利主义之争的源头。" },
];

P.p8 = [
  { type: "opp", text: "对立 15：Ψυχή vs Σῶμα（灵魂 — 肉体）", first: true },
  { type: "para", text: "这一对最早不是哲学问题，是宗教问题——讲义里讲得很清楚：**俄耳甫斯教**带来灵魂轮回与净化观念，毕达哥拉斯把它**理性化**，柏拉图再把它**哲学化**：" },
  { type: "bullet", text: "灵魂在进入肉体前已认识理念（回忆说）" },
  { type: "bullet", text: "肉体是灵魂的“坟墓”（soma sema）" },
  { type: "bullet", text: "哲学就是练习死亡——让灵魂摆脱肉体回归理念世界" },
  { type: "para", text: "亚里士多德反过来：灵魂不是独立的实体，**灵魂是肉体的形式**（重新用对立8来解决问题）——这是一个非常优雅的内化。" },
  { type: "para", text: "新柏拉图主义则把柏拉图灵魂论推向极致：“**太一 → 理智 → 灵魂 → 物质**”的流溢说，灵魂的使命是逆流而上回归太一。" },
  { type: "para", text: "讲义最后一页特别讲新柏拉图主义如何影响基督教，本质上就是**Psyche/Soma这对对立被基督教全盘继承**：灵魂不朽、肉体堕落、灵性救赎——直到马丁·路德、笛卡尔、乃至当代的“意识—身体”问题，都活在这条阴影里。" },
  { type: "opp", text: "对立 16：Ἐποχή vs Ἀταραξία（悬置判断 — 不动心）" },
  { type: "para", text: "这是讲义压轴的对立，也最微妙。" },
  { type: "para", text: "**怀疑主义皮浪派**的核心论证是：每一个哲学命题都有同样有力的反命题（“独断论者越多，他们越证明真理无法获得”）。于是真正智慧的做法是：**Epoche——悬置判断**，对任何事都不肯定不否定。" },
  { type: "para", text: "但这不是消极的虚无主义——悬置判断的**目的**是**Ataraxia（不动心、心灵宁静）**。当你不再为“什么是真”焦虑时，你就自由了。" },
  { type: "para", text: "这一对呈现的是一个深刻的悖论结构：**通过放弃认识来达到安顿**。它跟你之前讨论过的“理性—逻辑工具失败之后”的处境是一脉相承的——皮浪的姿态可以被读作“语言极限”路径在伦理学层面的早期版本：当Logos工具发现自己无法封闭真理时，正确的回应不是绝望，也不是跳进神秘主义的存在论狂欢，而是**悬置 + 安宁**。这种气质后来在维特根斯坦《逻辑哲学论》末尾“对于不可说的要保持沉默”那里得到了最干净的回响。" },
];

P.p9 = [
  { type: "h1", text: "六、底层原理：这16对对立到底揭示了什么？", first: true },
  { type: "para", text: "把这16组对立连起来看，古希腊哲学的底层原理可以浓缩成三句话：" },
  { type: "para", text: "**第一，哲学是Logos试图驯服Mythos、Physis、Hen的过程。** 哲学的发生就是把“故事”换成“论证”（对立1）、把“自然现象”还原为“本原”（对立3、4）、把“意见”提升为“知识”（对立5）。**所有古希腊哲学都是这场驯服的不同战役。**" },
  { type: "para", text: "**第二，Logos在驯服过程中遭遇了自身的极限——这就是巴门尼德的遗产。** 一旦你彻底贯彻Logos（思维=存在），你就会发现Logos无法容纳变化、多样、运动。**整个后巴门尼德哲学（原子论、柏拉图、亚里士多德）都是在这道伤口上做缝合手术**：要么把世界切两半（柏拉图的两重世界），要么把对立内化（亚里士多德的形式—质料、潜能—现实），要么承认非存在以某种方式存在（原子论的虚空）。" },
  { type: "para", text: "**第三，当公共世界（城邦）崩溃后，这些对立从“宇宙学的”变成“伦理学的”。** 一与多变成“我与世界”，必然与自由变成“命运与我的态度”，灵魂与肉体变成“我应当向哪里靠拢”，悬置与不动心变成“在不确定中如何活”。**希腊哲学最终给出的不是一套关于世界的真理，而是一套面对世界的姿态。**" },
  { type: "para", text: "换一个角度概括：**这16组对立不是答案，是问题的结构**。每一组对立都是一个“应力点”——古希腊每一位重要思想家都可以由他在这16个应力点上的姿态被精确定位。讲义里那一长串名字之所以彼此关联又彼此竞争，是因为他们其实在**共用一套问题清单**，只是给出了不同的答案。" },
  { type: "para", text: "这也是为什么后来的整个西方哲学（中世纪到黑格尔，再到现象学和分析哲学）都仍然在这16对里打转——它们不是古董，而是哲学这门手艺的**基础工具箱**。" },
  { type: "para", text: "—  —" },
];

const order = ["p2", "p3", "p4", "p5", "p6", "p7", "p8", "p9"];
const TOTAL = 1 + order.length;

titlePage(TOTAL);
order.forEach((k, i) => addContentPage(P[k], i + 2, TOTAL));

pres.writeFile({ fileName: "/mnt/user-data/outputs/古希腊哲学16组二元对立.pptx" }).then(f => {
  console.log("WROTE", f, "pages:", TOTAL);
});

