from playwright.sync_api import sync_playwright
import os

with sync_playwright() as p:
    browser = p.chromium.launch()
    page = browser.new_page(viewport={'width': 1280, 'height': 900})
    page.goto(f'file://{os.path.abspath("index.html")}')
    page.wait_for_timeout(2000)
    page.evaluate("document.querySelector('#phase-2 .duality .duality-head').click()")
    page.wait_for_timeout(800)
    info = page.evaluate("""() => {
        const exp = document.querySelector('.duality.expanded');
        if (!exp) return 'no expanded';
        const rect = exp.getBoundingClientRect();
        const body = exp.querySelector('.duality-body');
        return {top: rect.top, height: rect.height, bodyHeight: body ? body.offsetHeight : null, scrollY: window.pageYOffset};
    }""")
    print("info:", info)
    page.evaluate("""() => {
        const exp = document.querySelector('.duality.expanded');
        const y = exp.getBoundingClientRect().top + window.pageYOffset - 80;
        window.scrollTo({top: y, behavior: 'instant'});
    }""")
    page.wait_for_timeout(500)
    page.screenshot(path='verify-expanded2.png', full_page=False)
    # Scroll down to see lower part of expanded card
    page.evaluate("window.scrollBy(0, 700)")
    page.wait_for_timeout(300)
    page.screenshot(path='verify-expanded3.png', full_page=False)
    # Test philosopher modal — find a chip in the expanded card
    chip_count = page.evaluate("document.querySelectorAll('.duality.expanded .phil-chip').length")
    print("chips in expanded card:", chip_count)
    if chip_count > 0:
        page.evaluate("document.querySelector('.duality.expanded .phil-chip').click()")
        page.wait_for_timeout(500)
        modal_active = page.evaluate("document.querySelector('.phil-modal.active') !== null")
        print("modal active:", modal_active)
        page.screenshot(path='verify-modal2.png', full_page=False)
    browser.close()

