function textW(s){let w=0;for(const ch of s){w+= ch.charCodeAt(0)>255?11:7;}return w;}
function rectsOverlap(a,b){return !(a.x2<=b.x1||a.x1>=b.x2||a.y2<=b.y1||a.y1>=b.y2);}

function renderPlot(){
