    nodes.sort((a,b)=>a.y-b.y);
    const placedC=[];
    const halfW=colW/2-12;
    nodes.forEach(nd=>{
      let found=false;
      for(let step=0; step<=halfW; step+=3){
        const dirs= step===0?[0]:[-1,1];
        for(const dir of dirs){
          const x=cx+dir*step;
          if(x<cx-halfW || x>cx+halfW) continue;
          if(placedC.every(p=>{const dx=p.x-x,dy=p.y-nd.y,rr=p.r+nd.r+2.5;return dx*dx+dy*dy>=rr*rr;})){
            nd.x=x; placedC.push(nd); found=true; break;
          }
        }
        if(found) break;
      }
      if(!found){ nd.x=cx; placedC.push(nd); }
      allNodes.push(nd);
    });
  });

  // draw node shapes
  allNodes.forEach(nd=>{
    const d=nd.d;
    const g=el("g",{class:"node"+(state.sel===d?" sel":"")+(nd.on?"":" dim")},svg);
    g.style.opacity = nd.on?1:0.16;
    if(d.k==="m"){
      const s=nd.r;
      el("path",{d:`M${nd.x} ${nd.y-s} L${nd.x+s} ${nd.y} L${nd.x} ${nd.y+s} L${nd.x-s} ${nd.y} Z`,
        fill:"var(--card2)",stroke:BANDCOLOR[d.b],"stroke-width":2},g);
    } else {
      el("circle",{cx:nd.x,cy:nd.y,r:nd.r,fill:BANDCOLOR[d.b],"fill-opacity":.82},g);
    }
    if(nd.on) g.addEventListener("click",()=>select(d));
    nd.g=g;
  });

  // place labels with collision avoidance (active nodes only)
  if(state.labels){
    const nodeBoxes=allNodes.filter(n=>n.on).map(n=>({x1:n.x-n.r,y1:n.y-n.r,x2:n.x+n.r,y2:n.y+n.r}));
    const placedL=labelBlockers.slice();
    allNodes.filter(n=>n.on).sort((a,b)=>a.y-b.y).forEach(nd=>{
      const w=textW(nd.d.s), h=14, r=nd.r, cx=nd.x, cy=nd.y;
      const cands=[
        {x:cx+r+5, y:cy, a:"start",  box:{x1:cx+r+5,y1:cy-h/2,x2:cx+r+5+w,y2:cy+h/2}},
        {x:cx-r-5, y:cy, a:"end",    box:{x1:cx-r-5-w,y1:cy-h/2,x2:cx-r-5,y2:cy+h/2}},
        {x:cx, y:cy-r-9, a:"middle", box:{x1:cx-w/2,y1:cy-r-16,x2:cx+w/2,y2:cy-r-2}},
        {x:cx, y:cy+r+10,a:"middle", box:{x1:cx-w/2,y1:cy+r+3,x2:cx+w/2,y2:cy+r+17}}
      ];
      let ch=null;
      for(const c of cands){
        if(c.box.x1<mL+2 || c.box.x2>mL+plotW-2) continue;
        if(nodeBoxes.some(b=>rectsOverlap(c.box,b))) continue;
        if(placedL.some(b=>rectsOverlap(c.box,b))) continue;
        ch=c; break;
      }
      if(!ch) ch=cands[0];
      placedL.push(ch.box);
      const t=el("text",{x:ch.x,y:ch.y,"text-anchor":ch.a},nd.g);
      t.textContent=nd.d.s;
    });
  }
  renderLegend();
}

