def prep_svg(code):
    code = code.replace('var(--t)', '#2A2622').replace('context-stroke', '#2A2622')
    code = re.sub(r'\s*onclick="[^"]*"', '', code)
    # inject scoped style right after opening <svg ...>
    code = re.sub(r'(<svg\b[^>]*>)', r'\1' + SVG_STYLE, code, count=1)
    return code

def inline_md(s):
    s = html.escape(s, quote=False)
    s = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', s)
    return s

def md(text):
    out = []
    for blk in text.strip().split('\n\n'):
        blk = blk.strip()
        if not blk:
            continue
        if blk.startswith('## '):
            out.append('<h2>' + inline_md(blk[3:]) + '</h2>')
        elif blk.startswith('### '):
            out.append('<h3>' + inline_md(blk[4:]) + '</h3>')
        else:
            out.append('<p>' + inline_md(blk) + '</p>')
    return '\n'.join(out)

def fig(svg, cap):
