const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Header, Footer, PageNumber, NumberFormat, BorderStyle, convertInchesToTwip
} = require("docx");
const fs = require("fs");

const FONT_BODY = "SimSun";
const FONT_HEAD = "黑体";

function body(text, opts = {}) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: 360, after: 200 },
    indent: { firstLine: 480 },
    children: [
      new TextRun({ text, font: FONT_BODY, size: 24, ...opts }),
    ],
  });
}

// parse simple markdown-like emphasis **bold** into runs
function parseRuns(text, baseOpts = {}) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g).filter(p => p.length > 0);
  return parts.map(p => {
    if (p.startsWith("**") && p.endsWith("**")) {
      return new TextRun({ text: p.slice(2, -2), font: FONT_BODY, size: 24, bold: true, ...baseOpts });
    }
    return new TextRun({ text: p, font: FONT_BODY, size: 24, ...baseOpts });
  });
}

function bodyRich(text) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: 360, after: 200 },
    indent: { firstLine: 480 },
    children: parseRuns(text),
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    alignment: AlignmentType.LEFT,
    spacing: { before: 400, after: 240 },
    border: {
      bottom: { color: "8C1D40", space: 4, style: BorderStyle.SINGLE, size: 8 },
    },
    children: [
      new TextRun({ text, font: FONT_HEAD, size: 30, bold: true, color: "8C1D40" }),
    ],
  });
}

