                new TextRun({ children: [PageNumber.CURRENT], font: FONT_BODY, size: 18 }),
                new TextRun({ text: " 页 / 共 ", font: FONT_BODY, size: 18 }),
                new TextRun({ children: [PageNumber.TOTAL_PAGES], font: FONT_BODY, size: 18 }),
