  [3.3, 2.6, 1.9].forEach((r, i) => s.addShape(pres.shapes.OVAL, { x: cx-r, y: cy-r, w: 2*r, h: 2*r,
    fill:{type:"none"}, line:{color: i===1?COP:TEAL, width: 1.2, transparency: 40} }));

  s.addText("结语 · 行动建议", { x: MX, y: 0.7, w: 8, h: 0.4, fontFace: FONT, fontSize: 13,
    color: TEALLT, bold: true, charSpacing: 2, margin: 0 });
  s.addText([
    { text:"燕东正从“铺产能”转向“要效益”。", options:{ breakLine:true, color:WHITE }},
    { text:"谁能在 硅光 + 功率 + IC 三平台同时匹配，谁就锁定其战略供应位——", options:{ breakLine:true, color:WHITE }},
    { text:"我方是当前唯一具备“三位一体”整合能力的候选。", options:{ color:TEALLT }},
  ], { x: MX, y: 1.24, w: 11.6, h: 1.7, fontFace: FONT, fontSize: 23, bold: true, lineSpacing: 32, margin: 0, valign:"top" });

  // 30/60/90 action cards
  const acts = [
    { d:"30 天", ic:"tie_t", t:"高层拜访 · 需求对齐", b:"锁定北电集成/燕东科技技术窗口，交换三平台需求清单。" },
    { d:"60 天", ic:"vial_c", t:"送样 · 规格匹配", b:"功率硅片送样，IC 轻掺 / 硅光 SOI 规格匹配启动验证。" },
    { d:"90 天", ic:"hand_t", t:"签框架 · 阶段一供应", b:"签订联合开发框架协议，落地阶段一供应与月度目标。" },
  ];
  const cw = 3.87, gx = 0.26, y0 = 3.5, ch = 2.34;
  acts.forEach((a, i) => {
    const x = MX + i*(cw+gx), col = i===1?COP:TEAL;
    s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x, y: y0, w: cw, h: ch, fill:{color:INK2}, rectRadius:0.1, line:{color:"2E5064", width:1} });
    s.addShape(pres.shapes.OVAL, { x: x+0.28, y: y0+0.28, w: 0.72, h: 0.72, fill:{color:col} });
    s.addImage({ data: ICONS[i===1?"vial_c":(a.ic)], x: x+0.28+0.18, y: y0+0.28+0.18, w: 0.36, h: 0.36 });
    s.addText(a.d, { x: x+1.14, y: y0+0.3, w: cw-1.3, h: 0.5, fontFace: FONT, fontSize: 19, color: WHITE, bold: true, margin: 0, valign:"middle" });
    s.addText(a.t, { x: x+0.3, y: y0+1.16, w: cw-0.6, h: 0.4, fontFace: FONT, fontSize: 13, color: TEALLT, bold: true, margin: 0 });
    s.addText(a.b, { x: x+0.3, y: y0+1.56, w: cw-0.58, h: 0.7, fontFace: FONT, fontSize: 10.2, color: "C9D7DC", margin: 0, lineSpacing: 13.5, valign:"top" });
  });

  s.addText("〔我方公司名称〕 ｜ 燕东微电子 战略客户开发规划 · 2026", { x: MX, y: 6.15, w: 12, h: 0.3,
    fontFace: FONT, fontSize: 10.5, color: "7E96A0", margin: 0 });
}

// ---------- build ----------
(async () => {
  await prep();
  cover();
  summary();
  status1();
  status2();
  layout1();
  layout2();
  org();
  compete();
  validation();
  roadmap();
  goals();
  resources();
  closing();
  await pres.writeFile({ fileName: "燕东微电子_硅片联合开发规划.pptx" });
  console.log("DECK_WRITTEN");
})();

