const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const FA = require("react-icons/fa");

// ---------- palette ----------
const INK   = "12293B";  // deep slate navy (dark bg)
const INK2  = "1C3E58";  // secondary dark
const TEAL  = "147C6E";  // signature accent (IC / integration)
const TEALD = "0E5E53";
const TEALLT= "5FBFAE";  // light teal for dark bg
const COP   = "BC4B33";  // sharp accent (Power / energy)
const COPLT = "D98A5C";
const AMBER = "D3982C";  // tertiary highlight
const SLATE = "1E293B";  // body text
const MUTE  = "6A7A88";  // muted / captions
const LINE  = "D4DCE0";  // dividers
const CARD  = "F4F7F8";  // neutral card
const CARDT = "EAF4F1";  // teal-tinted card
const CARDC = "FBF1EC";  // copper-tinted card
const WHITE = "FFFFFF";
const FONT  = "Microsoft YaHei";

const W = 13.333, H = 7.5, MX = 0.6, RIGHT = 12.733;

let pres = new pptxgen();
pres.defineLayout({ name: "WIDE", width: W, height: H });
pres.layout = "WIDE";
pres.author = "硅片联合开发规划";
pres.title  = "燕东微电子晶圆制造平台 · 硅片联合开发规划";

// ---------- icon rendering ----------
async function icoPng(Comp, color, size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(Comp, { color, size: String(size) })
  );
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}
const ICONS = {};
async function prep() {
  const spec = [
    ["chip_t", FA.FaMicrochip, "#147C6E"], ["chip_w", FA.FaMicrochip, "#FFFFFF"],
    ["bolt_c", FA.FaBolt, "#BC4B33"], ["bolt_w", FA.FaBolt, "#FFFFFF"],
    ["wave_t", FA.FaWaveSquare, "#147C6E"], ["wave_c", FA.FaWaveSquare, "#BC4B33"],
    ["layer_t", FA.FaLayerGroup, "#147C6E"], ["layer_c", FA.FaLayerGroup, "#BC4B33"],
    ["chart_t", FA.FaChartLine, "#147C6E"], ["chart_c", FA.FaChartLine, "#BC4B33"],
    ["users_t", FA.FaUsers, "#147C6E"], ["tie_t", FA.FaUserTie, "#147C6E"],
    ["target_c", FA.FaBullseye, "#BC4B33"], ["cross_c", FA.FaCrosshairs, "#BC4B33"],
    ["cubes_t", FA.FaCubes, "#147C6E"], ["hand_t", FA.FaHandshake, "#147C6E"],
    ["check_t", FA.FaCheckCircle, "#147C6E"], ["warn_a", FA.FaExclamationTriangle, "#D3982C"],
    ["flag_w", FA.FaFlag, "#FFFFFF"], ["ind_t", FA.FaIndustry, "#147C6E"],
    ["puzzle_c", FA.FaPuzzlePiece, "#BC4B33"], ["puzzle_t", FA.FaPuzzlePiece, "#147C6E"],
    ["vial_c", FA.FaVial, "#BC4B33"], ["scale_t", FA.FaBalanceScale, "#147C6E"],
    ["link_w", FA.FaLink, "#FFFFFF"], ["cog_t", FA.FaCog, "#147C6E"],
    ["sitemap_t", FA.FaSitemap, "#147C6E"], ["road_w", FA.FaRoad, "#FFFFFF"],
    ["arrow_t", FA.FaArrowRight, "#147C6E"], ["arrow_c", FA.FaArrowRight, "#BC4B33"],
    ["light_a", FA.FaLightbulb, "#D3982C"], ["shield_t", FA.FaShieldAlt, "#147C6E"],
    ["clock_w", FA.FaClock, "#FFFFFF"], ["coins_t", FA.FaCoins, "#147C6E"],
    ["chip_a", FA.FaMicrochip, "#D3982C"], ["gem_t", FA.FaGem, "#147C6E"],
  ];
  for (const [k, C, col] of spec) ICONS[k] = await icoPng(C, col);
}

// ---------- helpers ----------
const sh = (o) => ({ type: "outer", color: "0B1620", blur: 9, offset: 3, angle: 90, opacity: 0.16, ...(o||{}) });
function bg(slide, color){ slide.background = { color }; }

function kicker(slide, txt, color=TEAL){
  slide.addText(txt.toUpperCase(), { x: MX, y: 0.40, w: 9, h: 0.32, fontFace: FONT,
    fontSize: 12.5, color, bold: true, charSpacing: 2, margin: 0 });
}
function title(slide, txt, w=11.8){
  slide.addText(txt, { x: MX, y: 0.70, w, h: 0.9, fontFace: FONT, fontSize: 30,
    color: INK, bold: true, margin: 0, valign: "top" });
}
function foot(slide, txt){
  slide.addText(txt, { x: MX, y: 7.06, w: 12.1, h: 0.3, fontFace: FONT, fontSize: 8.5,
    color: MUTE, italic: true, margin: 0 });
}
function card(slide, x, y, w, h, fill=CARD, shadow=true){
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x, y, w, h, fill: { color: fill },
    rectRadius: 0.09, line: { color: LINE, width: 0.75 }, ...(shadow ? { shadow: sh() } : {}) });
}
function iconChip(slide, x, y, d, iconKey, ringColor){
  slide.addShape(pres.shapes.OVAL, { x, y, w: d, h: d, fill: { color: ringColor } });
  const p = d*0.24;
  slide.addImage({ data: ICONS[iconKey], x: x+p, y: y+p, w: d-2*p, h: d-2*p });
}

// ============================================================ SLIDE 1 — COVER
function cover(){
  const s = pres.addSlide(); bg(s, INK);
  // wafer motif — concentric rings, lower-right, partly off canvas
  const cx = 11.7, cy = 6.4;
  const rings = [[3.9, TEALD, 1.6],[3.15, TEAL, 1.4],[2.4, "1C4E5A", 1.2],[1.68, COP, 1.1],[1.0, COPLT, 1.0]];
  for (const [r, c, ww] of rings){
    s.addShape(pres.shapes.OVAL, { x: cx-r, y: cy-r, w: 2*r, h: 2*r, fill: { type:"none" },
      line: { color: c, width: ww, transparency: 22 } });
  }
  s.addShape(pres.shapes.OVAL, { x: cx-0.16, y: cy-0.16, w: 0.32, h: 0.32, fill: { color: TEALLT } });
  // flat edge of wafer (notch line)
  s.addShape(pres.shapes.LINE, { x: cx+2.55, y: cy+2.9, w: 1.1, h: -0.55, line: { color: TEALLT, width: 1.4, transparency: 30 } });

  s.addText("客户开发规划报告 · CUSTOMER DEVELOPMENT PLAN", { x: MX, y: 1.15, w: 10, h: 0.4,
    fontFace: FONT, fontSize: 13, color: TEALLT, bold: true, charSpacing: 2, margin: 0 });

  s.addText([
    { text: "燕东微电子晶圆制造平台", options: { breakLine: true, color: WHITE } },
    { text: "硅片联合开发规划", options: { color: TEALLT } },
  ], { x: MX, y: 1.95, w: 11.5, h: 2.2, fontFace: FONT, fontSize: 46, bold: true, lineSpacing: 58, margin: 0 });

  // sub-line with two fab tags
  s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: MX, y: 4.35, w: 2.15, h: 0.5, fill: { color: INK2 },
    rectRadius: 0.25, line: { color: TEAL, width: 1 } });
  s.addText("北电集成 · 28–55nm", { x: MX, y: 4.35, w: 2.15, h: 0.5, align: "center", valign: "middle",
    fontFace: FONT, fontSize: 11.5, color: WHITE, bold: true, margin: 0 });
  s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: MX+2.35, y: 4.35, w: 2.15, h: 0.5, fill: { color: INK2 },
    rectRadius: 0.25, line: { color: COP, width: 1 } });
  s.addText("燕东科技 · 65nm 特色", { x: MX+2.35, y: 4.35, w: 2.15, h: 0.5, align: "center", valign: "middle",
    fontFace: FONT, fontSize: 11.5, color: WHITE, bold: true, margin: 0 });

  s.addText("硅片供应商视角 ｜ Power × IC × 硅光新材料 三位一体整合", { x: MX, y: 5.25, w: 9.5, h: 0.4,
    fontFace: FONT, fontSize: 14, color: "AEC4CC", margin: 0 });

  s.addShape(pres.shapes.LINE, { x: MX, y: 6.35, w: 4.2, h: 0, line: { color: TEAL, width: 1.5 } });
  s.addText("〔我方公司名称〕· 战略客户开发规划 · 2026", { x: MX, y: 6.5, w: 8, h: 0.35,
    fontFace: FONT, fontSize: 11.5, color: "8CA3AC", margin: 0 });
}

// ============================================================ SLIDE 2 — EXEC SUMMARY
function summary(){
  const s = pres.addSlide(); bg(s, WHITE);
  kicker(s, "执行摘要 · 核心判断");
  title(s, "结论先行：燕东正处于拐点，我方是唯一“三位一体”候选供应商");

  const cards = [
    { t:"客户判断", h:"现在不强，但正在拐点", ic:"chart_c", col:COP, tint:CARDC,
      b:"2025Q2 营收同比 +40.2%、归母净利 +960.5%；6+8+12 三线协同，产能已铺、盈利转正在途。" },
    { t:"生命力来源", h:"新产能 + 硅光 + 组织升级", ic:"layer_t", col:TEAL, tint:CARDT,
      b:"北电集成 28–55nm 新线、8 寸 SiN 硅光损耗<0.1dB/cm 卡位高增长赛道、管理层与供应商管理市场化升级。" },
    { t:"我方定位", h:"Power + IC + 硅光 整合优势", ic:"puzzle_t", col:TEAL, tint:CARDT,
      b:"对位奕斯伟有 Power、对位金瑞泓/中欣有 IC，且具 SOI/硅光新材料——直接匹配燕东“功率+逻辑+光”三平台。" },
    { t:"目标与路径", h:"三阶段 · 锁定战略客户", ic:"target_c", col:COP, tint:CARDC,
      b:"Power 带 IC → 提质提量 → 齐头并进；阶段一月均 1000 万、阶段二月均 2000 万，进入核心供应链。" },
  ];
  const cw = 5.85, chh = 1.62, gx = 0.42, gy = 0.32;
  const x0 = MX, y0 = 1.78;
  cards.forEach((c, i) => {
    const x = x0 + (i%2)*(cw+gx), y = y0 + Math.floor(i/2)*(chh+gy);
    card(s, x, y, cw, chh, c.tint);
    iconChip(s, x+0.28, y+0.28, 0.66, c.ic, c.col);
    s.addText(c.t, { x: x+1.12, y: y+0.24, w: cw-1.3, h: 0.28, fontFace: FONT, fontSize: 11,
      color: c.col, bold: true, charSpacing: 1, margin: 0 });
    s.addText(c.h, { x: x+1.12, y: y+0.5, w: cw-1.3, h: 0.34, fontFace: FONT, fontSize: 15.5,
      color: INK, bold: true, margin: 0 });
    s.addText(c.b, { x: x+0.28, y: y+0.94, w: cw-0.56, h: 0.58, fontFace: FONT, fontSize: 10.8,
      color: SLATE, margin: 0, lineSpacing: 14.5, valign: "top" });
  });

  // risk strip
  card(s, MX, 5.72, 12.13, 1.02, "FBF6EC");
  iconChip(s, MX+0.24, 5.94, 0.58, "warn_a", AMBER);
  s.addText("风险提示", { x: MX+1.0, y: 5.86, w: 2.0, h: 0.3, fontFace: FONT, fontSize: 11.5,
    color: "9A7420", bold: true, margin: 0 });
  s.addText("12 寸硅片价格仍在筑底、国产厂商普遍亏损/爬坡，良率与验证周期是最大障碍；中环领先同打“Power+IC”（力争 70 万片/月），我方须以硅光/SOI 新材料 + 服务响应做差异化。",
    { x: MX+1.0, y: 6.14, w: 11.0, h: 0.55, fontFace: FONT, fontSize: 10.6, color: SLATE, margin: 0, lineSpacing: 14, valign: "top" });

  foot(s, "数据来源：燕东微 2025 年年度报告、公司公告及公开行业资料；判断为我方分析口径。");
}

// ============================================================ SLIDE 3 — 现状(一) 地位
function status1(){
  const s = pres.addSlide(); bg(s, WHITE);
  kicker(s, "第一部分 · 客户现状（一）");
  title(s, "燕东在国内 Power / IC 版图中的位置");

  // left: positioning + stats
  const lx = MX, lw = 4.55;
  card(s, lx, 1.8, lw, 2.02, CARD);
  s.addText("定位判断", { x: lx+0.26, y: 1.96, w: lw-0.5, h: 0.28, fontFace: FONT, fontSize: 11,
    color: TEAL, bold: true, charSpacing: 1, margin: 0 });
  s.addText([
    { text:"北京电控旗下 IDM 平台，", options:{}},
    { text:"6+8+12 英寸全尺寸布局。", options:{ breakLine:true }},
    { text:"以功率器件 + 特色工艺代工为主，先进制程（≤28nm）尚在建设——属国内“特色工艺”梯队，非先进逻辑代工第一梯队。", options:{}},
  ], { x: lx+0.26, y: 2.26, w: lw-0.52, h: 1.5, fontFace: FONT, fontSize: 11.6, color: SLATE, lineSpacing: 16, margin: 0, valign: "top" });

  const stats = [
    { n:"18.33亿", l:"2025 营收（元）", c:TEAL },
    { n:"43.7%", l:"研发投入占比", c:COP },
    { n:"552人", l:"研发人员", c:TEAL },
  ];
  const sw = (lw-0.36)/3;
  stats.forEach((st, i) => {
    const x = lx + i*(sw+0.18);
    card(s, x, 3.98, sw, 1.18, i%2? CARDC:CARDT);
    s.addText(st.n, { x: x+0.04, y: 4.18, w: sw-0.08, h: 0.5, align:"center", fontFace: FONT,
      fontSize: 19, color: st.c, bold: true, margin: 0 });
    s.addText(st.l, { x: x+0.04, y: 4.72, w: sw-0.08, h: 0.4, align:"center", fontFace: FONT,
      fontSize: 9, color: MUTE, margin: 0, lineSpacing: 11 });
  });
  s.addText("研发投入占比远超行业均值，重资产 + 重研发并行。", { x: lx, y: 5.28, w: lw, h: 0.3,
    fontFace: FONT, fontSize: 9, color: MUTE, italic: true, margin: 0 });

  // right: capacity table
  const rx = 5.45;
  s.addText("产能矩阵（截至 2025 年末）", { x: rx, y: 1.8, w: 7.2, h: 0.32, fontFace: FONT,
    fontSize: 13, color: INK, bold: true, margin: 0 });
  const th = (t) => ({ text:t, options:{ fill:{color:INK}, color:WHITE, bold:true, fontSize:10.5, align:"center", valign:"middle" }});
  const tc = (t, o={}) => ({ text:t, options:{ fontSize:10, color:SLATE, valign:"middle", align: o.align||"left", ...o }});
  const rows = [
    [th("产线"), th("基地 / 制程"), th("月产能"), th("主力工艺平台")],
    [tc("6 英寸", {bold:true, align:"center"}), tc("四川遂宁", {align:"center"}), tc("65k", {align:"center", color:TEAL, bold:true}), tc("TVS · 模拟IC · 车规FRD · SiC")],
    [tc("8 英寸", {bold:true, align:"center"}), tc("北京", {align:"center"}), tc("60k", {align:"center", color:TEAL, bold:true}), tc("Trench MOS · IGBT · 700V BCD · SiN硅光")],
    [tc("12 英寸\n燕东科技", {bold:true, align:"center"}), tc("北京 · 65nm", {align:"center"}), tc("40k\n规划", {align:"center", color:COP, bold:true}), tc("功率器件 · SOI硅光 · 0.18μm CMOS")],
    [tc("12 英寸\n北电集成", {bold:true, align:"center"}), tc("北京亦庄\n28–55nm", {align:"center"}), tc("50k\n规划", {align:"center", color:COP, bold:true}), tc("显示驱动 · 数模混合 · MCU · PD/FD-SOI")],
  ];
  s.addTable(rows, { x: rx, y: 2.2, w: 7.28, colW: [1.32, 1.62, 1.0, 3.34], rowH: [0.4, 0.62, 0.62, 0.72, 0.72],
    border: { pt: 0.5, color: LINE }, fill: { color: WHITE }, valign: "middle", fontFace: FONT, autoPage: false });

  card(s, rx, 5.62, 7.28, 1.02, CARDT, true);
  iconChip(s, rx+0.24, 5.84, 0.56, "light_a", AMBER);
  s.addText([
    { text:"两条 12 寸合计规划 90k/月。", options:{ bold:true, color:TEAL }},
    { text:" 12 寸尚在爬坡（燕东科技一期单月最高 2 万片），产能利用率仍难评估——“铺产能”阶段。", options:{ color:SLATE }},
  ], { x: rx+0.98, y: 5.78, w: 6.1, h: 0.72, fontFace: FONT, fontSize: 10.6, lineSpacing: 14, margin: 0, valign: "middle" });

  foot(s, "来源：燕东微 2025 年年度报告（产能、营收、研发数据）；北电集成规划产能 5 万片/月，2026 年底量产、2030 年满产。");
}

// ============================================================ SLIDE 4 — 现状(二) 短板
function status2(){
  const s = pres.addSlide(); bg(s, WHITE);
  kicker(s, "第一部分 · 客户现状（二）", COP);
  title(s, "产品接受度与结构性短板：“现在的燕东不算强”");

  // left col: acceptance (green)
  const lx = MX, lw = 5.85, ly = 1.82, lh = 4.5;
  card(s, lx, ly, lw, lh, CARDT);
  iconChip(s, lx+0.3, ly+0.28, 0.6, "check_t", TEAL);
  s.addText("已有市场接受度", { x: lx+1.05, y: ly+0.34, w: lw-1.2, h: 0.4, fontFace: FONT,
    fontSize: 16, color: TEALD, bold: true, margin: 0, valign:"middle" });
  const acc = [
